insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jr',37,9,'crampon1923','Ainsi parle Yahweh: Ne vous faites pas illusion en disant: Les Chaldéens s''en iront sûrement loin de nous. Car ils ne s''en iront pas.'),
('jr',37,10,'crampon1923','Et même quand vous auriez battu toute l''armée des Chaldéens qui combattent contre vous, et qu''il ne resterait d''eux que des blessés, ils se lèveraient chacun dans sa tente et brûleraient cette ville par le feu.'),
('jr',37,11,'crampon1923','Pendant que l''armée des Chaldéens s''était éloignée de Jérusalem, à cause de l''armée de Pharaon,'),
('jr',37,12,'crampon1923','Jérémie sortit de Jérusalem pour aller au pays de Benjamin, afin de retirer de là sa portion au milieu du peuple.'),
('jr',37,13,'crampon1923','Mais pendant qu''il était à la porte de Benjamin, le capitaine de la garde, nommé Jérias, fils de Sélémias, fils de Hananias, arrêta Jérémie le prophète, en disant: " Tu passes aux Chaldéens! "'),
('jr',37,14,'crampon1923','Jérémie répondit: " C''est, faux, je ne passe pas aux Chaldéens! " Mais Jérias ne l''écouta point; il arrêta Jérémie et l''amena aux chefs.'),
('jr',37,15,'crampon1923','Et les chefs s''emportèrent contre Jérémie; ils le battirent et le mirent en prison, dans la maison de Jonathan, le secrétaire; car ils en avaient fait une prison.'),
('jr',37,16,'crampon1923','Lorsque Jérémie eut pénétré dans la basse-fosse, sous les voûtes, et que Jérémie y fut resté bien des jours,'),
('jr',37,17,'crampon1923','Sédécias l''envoya tirer de là. Il l''interrogea secrètement dans sa maison, et lui dit: " Y a-t-il une parole de la part de Yahweh? " Et Jérémie répondit: " Oui! " et il ajouta: " Tu seras livré entre les mains du roi de Babylone. "'),
('jr',37,18,'crampon1923','Jérémie dit encore au roi Sédécias: " Quelle offense ai-je commise contre toi, contre tes serviteurs et contre ce peuple, que vous m’ayez mis en prison?'),
('jr',37,19,'crampon1923','Et où sont vos prophètes qui vous prophétisaient en disant: Le roi de Babylone ne viendra pas contre vous, ni contre ce pays?'),
('jr',37,20,'crampon1923','Et maintenant écoute, je te prie, ô roi, mon seigneur! Que ma supplication arrive devant toi: Ne me renvoie pas dans la maison de Jonathan, le secrétaire, pour y mourir. "'),
('jr',37,21,'crampon1923','Le roi Sédécias donna l’ordre de garder Jérémie dans la cour de la prison et de lui donner chaque jour une miche de pain, de la rue des boulangers, jusqu’à ce que tout le pain fût consommé dans la ville. Ainsi Jérémie demeura dans la cour de la prison.'),
('jr',38,1,'crampon1923','Alors Saphatias, fils de Mathan, Gédélias, fils de Phassur, Juchal, fils de Sélémias, et Phassur, fils de Melchias, entendirent les paroles que Jérémie adressait à tout le peuple, en disant:'),
('jr',38,2,'crampon1923','" Ainsi parle Yahweh: Celui qui restera dans cette ville mourra par l''épée, par la famine ou par la peste; mais celui qui sortira pour se rendre aux Chaldéens vivra; il aura la vie pour butin, et il vivra.'),
('jr',38,3,'crampon1923','Ainsi parle Yahweh: Cette ville sera livrée à l''armée du roi de Babylone, et il la prendra. "'),
('jr',38,4,'crampon1923','Et les chefs dirent au roi: " Qu’on fasse donc mourir cet homme! Car il décourage les hommes de guerre qui restent dans la ville, et tout le peuple, en leur tenant ces discours. Car cet homme ne cherche pas le bien de ce peuple, mais son malheur. "'),
('jr',38,5,'crampon1923','Et le roi Sédécias dit: " Il est en votre pouvoir, car le roi ne peut rien contre vous. "'),
('jr',38,6,'crampon1923','Alors ils prirent Jérémie et le descendirent dans la citerne de Melchias, fils du roi, dans la cour de garde; ils descendirent Jérémie avec des cordes dans la citerne; il n''y avait pas d''eau, mais de la boue. Et Jérémie enfonça dans la boue.'),
('jr',38,7,'crampon1923','Abdémélech, l''Ethiopien, eunuque de la maison du roi, apprit qu''on avait mis Jérémie dans la citerne. — Or le roi était assis à la porte de Benjamin. —'),
('jr',38,8,'crampon1923','Abdémélech sortit de la maison du roi, et il parla au roi en ces termes:'),
('jr',38,9,'crampon1923','" O roi, mon seigneur, ces hommes ont mal agi en traitant ainsi Jérémie, le prophète; ils l''ont descendu dans la citerne; il mourra de faim sur place, car il n''y a plus de pain dans la ville."'),
('jr',38,10,'crampon1923','Et le roi donna cet ordre à Abdémélech, l''Ethiopien: " Prends ici trente hommes avec toi, et fais remonter de la citerne Jérémie le prophète, avant qu''il ne meure. "'),
('jr',38,11,'crampon1923','Abdémélech prit donc avec lui ces hommes et entra dans la maison du roi, au-dessous de la trésorerie. Il y prit des linges usés et de vieilles hardes, et il les fit passer avec des cordes à Jérémie dans la citerne.'),
('jr',38,12,'crampon1923','Et Abdémélech, l''Ethiopien, dit à Jérémie: " Mets ces linges usés et ces hardes sous tes aisselles, par-dessous les cordes. " Jérémie fit ainsi.'),
('jr',38,13,'crampon1923','Et ils le tirèrent avec des cordes, et le firent remonter de la citerne. Et Jérémie demeura dans la cour de garde.'),
('jr',38,14,'crampon1923','Alors le roi Sédécias envoya prendre Jérémie, le prophète, et le fit venir vers lui à la troisième entrée de la maison de Yahweh. Et le roi dit à Jérémie: " J''ai une chose à te demander; ne me cache rien! "'),
('jr',38,15,'crampon1923','Et Jérémie dit à Sédécias: " Si je te la dis, ne me feras-tu pas sûrement mourir? Et si je te donne un conseil, tu ne m''écouteras pas. "'),
('jr',38,16,'crampon1923','Le roi Sédécias fit en secret ce serment à Jérémie: " Yahweh est vivant, lui qui nous a donné cette vie! Je ne te ferai point mourir, et je ne te livrerai point aux mains de ces hommes qui en veulent à ta vie. "'),
('jr',38,17,'crampon1923','Alors Jérémie dit à Sédécias: " Ainsi parle Yahweh des armées, Dieu d''Israël: Si tu sors pour te rendre aux chefs du roi de Babylone, tu auras la vie sauve, et cette ville ne sera pas brûlée; tu vivras, toi et ta maison.'),
('jr',38,18,'crampon1923','Mais si tu ne sors pas vers les chefs du roi de Babylone, cette ville sera livrée aux mains des Chaldéens, qui la brûleront; et toi tu ne leur échapperas point. "'),
('jr',38,19,'crampon1923','Et le roi Sédécias dit à Jérémie: " Je crains les Judéens qui ont passé aux Chaldéens; on me livrera à eux, et ils se joueront de moi. "'),
('jr',38,20,'crampon1923','Jérémie répondit: " On ne te livrera pas. Ecoute donc la voix de Yahweh dans ce que je te dis; tu t''en trouveras bien, et tu auras la vie sauve.'),
('jr',38,21,'crampon1923','Mais si tu refuses de sortir, voici ce que Yahweh m’a révélé:'),
('jr',38,22,'crampon1923','Voici que toutes les femmes qui sont restées de la maison du roi de Juda, seront menées aux chefs du roi de Babylone, et elles te diront: Tes amis t’ont séduit et dominé; tes pieds se sont enfoncés dans la boue, et eux se sont esquivés.'),
('jr',38,23,'crampon1923','Et on mènera toutes tes femmes et tes enfants aux Chaldéens, et toi-même tu ne leur échapperas pas; mais tu seras pris par le roi de Babylone, et tu auras brûlé cette ville. "'),
('jr',38,24,'crampon1923','Et Sédécias dit à Jérémie: " Que personne ne sache rien de cet entretien, et tu ne mourras point.'),
('jr',38,25,'crampon1923','Si les chefs apprennent que j''ai parlé avec toi, et qu''ils viennent te dire: Déclare-nous ce que tu as dit au roi et ce que le roi t''a dit; ne nous cache rien, et nous ne te ferons pas mourir,'),
('jr',38,26,'crampon1923','tu leur répondras: J''ai présenté ma supplication au roi pour qu''il ne me fasse pas retourner dans la maison de Jonathan, où je mourrais. "'),
('jr',38,27,'crampon1923','Tous les chefs vinrent en effet vers Jérémie et le questionnèrent; il leur répondit entièrement selon ces paroles que le roi lui avait prescrites; et ils le laissèrent en repos, car l''entretien n''avait pas été entendu.'),
('jr',38,28,'crampon1923','Ainsi Jérémie resta dans la cour de garde jusqu''à la prise de Jérusalem, et il y était lorsque Jérusalem fut prise.'),
('jr',39,1,'crampon1923','La neuvième année de Sédécias, roi de Juda, le dixième mois, Nabuchodonosor, roi de Babylone, vint avec toute son armée devant Jérusalem; et ils l''assiégèrent.'),
('jr',39,2,'crampon1923','La onzième année de Sédécias, au quatrième mois, le neuvième jour du mois, une brèche fut faite à la ville.'),
('jr',39,3,'crampon1923','Tous les chefs du roi de Babylone entrèrent et s''établirent à la porte du milieu; Nergal-Séréser, gardien du trésor, Nabu-Sarsakim, chef des eunuques, Nergal-Séréser, chef des mages, et tout le reste des chefs du roi de Babylone.'),
('jr',39,4,'crampon1923','Lorsque Sédécias, roi de Juda, et tous les gens de guerre les eurent vus, ils s''enfuirent et sortirent de la ville pendant la nuit vers le chemin du jardin du roi, par la porte entre les deux murs, et ils prirent le chemin de la plaine.'),
('jr',39,5,'crampon1923','Mais l''armée des Chaldéens les poursuivit et atteignit Sédécias dans les plaines de Jéricho. L''ayant pris, ils le firent monter vers Nabuchodonosor, roi de Babylone, à Ribla, au pays d''Emath, et il prononça sur lui des sentences.'),
('jr',39,6,'crampon1923','Le roi de Babylone égorgea à Ribla les fils de Sédécias sous ses yeux; le roi de Babylone égorgea aussi tous les grands de Juda.'),
('jr',39,7,'crampon1923','Puis il creva les yeux à Sédécias, et le lia avec deux chaînes d''airain, pour l''emmener à Babylone.'),
('jr',39,8,'crampon1923','Puis les Chaldéens brûlèrent la maison du roi et les maisons du peuple, et démolirent les murailles de Jérusalem.'),
('jr',39,9,'crampon1923','Nabuzardan, capitaine des gardes, emmena captifs à Babylone le reste du peuple qui était demeuré dans la ville, les transfuges qui s''étaient rendus à lui, et le reste du peuple du pays qui était demeuré là.'),
('jr',39,10,'crampon1923','Nabuzardan, capitaine des gardes, laissa dans le pays de Juda quelques-uns des gens pauvres qui ne possédaient rien; et il leur donna des vignes et des champs, en ce jour-là.'),
('jr',39,11,'crampon1923','Nabuchodonosor, roi de Babylone, donna un ordre à Nabuzardan, chef des gardes, au sujet de Jérémie en ces termes:'),
('jr',39,12,'crampon1923','" Prends-le, aie les yeux sur lui, et ne lui fais point de mal; mais agis avec lui comme il te le dira. "'),
('jr',39,13,'crampon1923','Nabuzardan, chef des gardes, Nabusezban, chef des eunuques, et Nergal-Séréser, chef des mages, et tous les chefs du roi de Babylone'),
('jr',39,14,'crampon1923','envoyèrent prendre Jérémie dans la cour de garde, et ils le remirent à Godolias, fils d''Ahicam, fils de Saphan, pour le conduire dans sa maison. Et il demeura au milieu du peuple.'),
('jr',39,15,'crampon1923','La parole de Yahweh fut adressée à Jérémie, pendant qu''il était enfermé dans la cour de garde, en ces termes:'),
('jr',39,16,'crampon1923','Va, parle à Abdémélech, l''Ethiopien, et dis-lui: Ainsi parle Yahweh des armées, Dieu d''Israël: Voici que je vais exécuter mes paroles sur cette ville, pour le mal, et non pour le bien, et ces choses seront en ce jour-là sous tes yeux.'),
('jr',39,17,'crampon1923','Mais je te délivrerai en ce jour-là, — oracle de Yahweh, — et tu ne seras pas livré aux mains des hommes que tu crains.'),
('jr',39,18,'crampon1923','Je te ferai sûrement échapper, et tu ne tomberas pas sous l''épée; tu auras ta vie pour butin, parce que tu t’es confié en moi, — oracle de Yahweh.'),
('jr',40,1,'crampon1923','La parole qui fut adressée à Jérémie de la part de Yahweh, après que Nabuzardan, chef des gardes, l''eut envoyé de Rama, l''ayant fait prendre quand il était lié de chaînes au milieu de tous les captifs de Jérusalem et de Juda qu''on déportait à Babylone.'),
('jr',40,2,'crampon1923','Le chef des gardes prit Jérémie et lui dit: " Yahweh, ton Dieu, avait annoncé ce malheur contre ce lieu,'),
('jr',40,3,'crampon1923','et il l''a fait venir; et Yahweh a fait comme il avait dit; parce que vous avez péché contre Yahweh et que vous n''avez point obéi à sa voix, cette chose vous est arrivée.'),
('jr',40,4,'crampon1923','Et maintenant, voici que je te délie aujourd''hui des chaînes que tu avais aux mains. S''il paraît bon à tes yeux de venir avec moi à Babylone, viens, et j''aurai mes yeux sur toi; mais s''il paraît mauvais à tes yeux de venir avec moi à Babylone, laisse cela. Regarde, tout le pays est devant toi; là où il paraîtra bon et convenable à tes yeux d''aller, vas-y. "'),
('jr',40,5,'crampon1923','Comme Jérémie tardait à s''en aller: " Retourne, ajouta-t-il, vers Godolias, fils d''Ahicam, fils de Saphan, que le roi de Babylone a établi sur les villes de Juda, et demeure avec lui au milieu du peuple; ou bien va où il te plaira. " Et le chef des gardes lui donna des vivres et des présents, et le congédia.'),
('jr',40,6,'crampon1923','Et Jérémie se rendit auprès de Godolias à Maspha, et il demeura avec lui au milieu du peuple laissé dans le pays.'),
('jr',40,7,'crampon1923','Lorsque tous les chefs de troupes qui étaient dans la campagne, eux et leurs hommes, eurent appris que le roi de Babylone avait établi Godolias, fils d''Ahicam, gouverneur du pays, et qu''il lui avait confié les hommes, les femmes et les enfants, et ceux des pauvres du pays qui n''étaient pas déportés à Babylone,'),
('jr',40,8,'crampon1923','ils vinrent vers Godolias, à Maspha, savoir: Ismaël, fils de Nathanias, Johanan et Jonathan, fils de Carée, Saraïas, fils de Tanéhumeth, les fils d''Ephoï, de Nétopha, et Jézonias, fils du Maahathien, eux et leurs hommes.'),
('jr',40,9,'crampon1923','Godolias, fils d''Ahicam, fils de Saphan, leur dit avec serment, à eux et à leurs hommes: " Ne craignez point de servir les Chaldéens; demeurez dans le pays, servez le roi de Babylone, et vous vous en trouverez bien.'),
('jr',40,10,'crampon1923','Pour, moi, voici que je reste à Maspha pour être aux ordres des Chaldéens qui viendront vers vous. Et vous, faites la récolte du vin, des fruits et de l''huile; mettez-les dans vos vases, et habitez vos villes que vous occupez. "'),
('jr',40,11,'crampon1923','Tous les Judéens qui étaient dans le pays de Moab, chez les fils d''Ammon et dans Edom, et qui apprirent dans tous ces pays-là que le roi de Babylone avait laissé un reste à Juda, et qu''il leur avait donné pour gouverneur Godolias, fils d''Ahicam, fils de Saphan.'),
('jr',40,12,'crampon1923','Alors tous les Judéens revinrent de tous les lieux où ils avaient été chassés, et se rendirent au pays de Juda auprès de Godolias, à Maspha; et ils récoltèrent du vin et des fruits en abondance.'),
('jr',40,13,'crampon1923','Mais Johanan, fils de Carée, et tous les chefs des troupes qui étaient dans la campagne, vinrent trouver Godolias à Maspha,'),
('jr',40,14,'crampon1923','et lui dirent: " Sais-tu que Baalis, roi des fils d’Ammon, a envoyé Ismaël, fils de Nathanias, pour t''ôter la vie? " Mais Godolias, fils d’Ahicam, ne les crut point.'),
('jr',40,15,'crampon1923','Et Johanan, fils de Carée, parla en secret à Godolias à Maspha; en ces termes: " Que j''aille donc tuer Ismaël, fils de Nathanias, sans que personne le sache. Pourquoi t''ôterait-il la vie, et tous les Juifs qui se sont rassemblés vers toi seraient-ils dispersés, et le reste de Juda périrait-il? "'),
('jr',40,16,'crampon1923','Godolias, fils d’Ahicam, dit à Johanan, fils de Carée: " Ne fais point cela; car ce que tu dis au sujet d’Ismaël est faux. "'),
('jr',41,1,'crampon1923','Au septième mois, Ismaël, fils de Nathanias, fils d''Elisama, de la race royale, vint, accompagné de grands officiers du roi et de dix hommes, vers Godolias, fils d''Ahicam, à Maspha; et ils mangèrent ensemble à Maspha,'),
('jr',41,2,'crampon1923','Et Ismaël, fils de Nathanias, se leva, lui et les dix hommes qui étaient avec lui, et ils frappèrent avec l''épée Godolias, fils d''Ahicam, fils de Saphan, et ils le firent mourir — lui que le roi de Babylone avait établi gouverneur du pays,'),
('jr',41,3,'crampon1923','— ainsi que tous les judéens qui étaient avec lui, — avec Godolias, — à Maspha; Ismaël tua aussi les Chaldéens qui se trouvaient là, les gens de guerre.'),
('jr',41,4,'crampon1923','Le second jour après le meurtre de Godolias, avant que personne le sût,'),
('jr',41,5,'crampon1923','des hommes vinrent de Sichem, de Silo et de Samarie, au nombre de quatre-vingts, la barbe rasée, les vêtements déchirés et le corps couvert d''incisions; ils portaient des offrandes et de l''encens, pour les présenter à la maison de Yahweh.'),
('jr',41,6,'crampon1923','Ismaël, fils de Nathanias, sortit de Maspha à leur rencontre, tout en pleurant; et, quand il les eut atteints, il leur dit: " Venez vers Godolias, fils d''Ahicam. "'),
('jr',41,7,'crampon1923','Mais dès qu''ils furent entrés au milieu de la ville, Ismaël, fils de Nathanias, les égorgea et les jeta au milieu de la citerne, lui et les hommes qui étaient avec lui.'),
('jr',41,8,'crampon1923','Mais il se trouva parmi eux dix hommes qui dirent à Ismaël: " Ne nous fais pas mourir, car nous avons dans les champs des provisions cachées de froment, d''orge, d''huile et de miel. " Alors il s''arrêta et ne les fit pas mourir au milieu de leurs frères.'),
('jr',41,9,'crampon1923','La citerne dans laquelle Ismaël jeta les cadavres des hommes qu''il avait frappés à cause de Godolias, est celle que le roi Asa avait faite en vue de Baasa, roi d''Israël; c''est elle qu''Ismaël, fils de Nathanias, remplit de cadavres.'),
('jr',41,10,'crampon1923','Et Ismaël emmena prisonnier le reste du peuple qui était à Maspha, les filles du roi et tout le peuple qui était resté à Maspha, auxquels Nabuzardan, chef des gardes, avait donné pour chef Godolias, fils d''Ahicam; Ismaël, fils de Nathanias, les emmena prisonniers, et partit pour passer chez les fils d''Ammon.'),
('jr',41,11,'crampon1923','Johanan, fils de Carée, et tous les chefs de troupes qui étaient avec lui, ayant appris tout le mal qu''Ismaël, fils de Nathanias, avait fait,'),
('jr',41,12,'crampon1923','prirent tous leurs hommes et se mirent en marche pour combattre Ismaël, fils de Nathanias; ils l''atteignirent près du grand étang de Gabaon.'),
('jr',41,13,'crampon1923','Et quand tout le peuple qui était avec Ismaël, vit Johanan, fils de Carée, et tous les chefs des troupes qui étaient avec lui, il s''en réjouit.'),
('jr',41,14,'crampon1923','Et tout le peuple qu''Ismaël emmenait prisonnier de Maspha se retourna et vint se joindre à Johanan, fils de Carée.'),
('jr',41,15,'crampon1923','Mais Ismaël, fils de Nathanias, s''échappa avec huit hommes devant Johanan, et alla chez les fils d''Ammon.'),
('jr',41,16,'crampon1923','Et Johanan, fils de Carée, et tous les chefs des troupes qui étaient avec lui, prirent tout le reste du peuple qu''Ismaël, fils de Nathanias, avait emmené de Maspha, après avoir tué Godolias, fils d''Ahicam, hommes de guerre, femmes, enfants et eunuques, et ils les ramenèrent de Gabaon.'),
('jr',41,17,'crampon1923','Ils allèrent et s''arrêtèrent au caravansérail de Chamaam, près de Bethléem, pour se retirer ensuite en Egypte,'),
('jr',41,18,'crampon1923','loin des Chaldéens qu''ils craignaient, parce qu''Ismaël, fils de Nathanias, avait tué Godolias, fils d''Ahicam, que le roi de Babylone avait établi gouverneur du pays.'),
('jr',42,1,'crampon1923','Alors tous les chefs de troupes, ainsi que Johanan, fils de Carée, Jezonias, fils d''Osaïas, et tout le peuple, petits et grands, s''approchèrent'),
('jr',42,2,'crampon1923','et dirent à Jérémie, le prophète: " Que notre supplication arrive devant toi; intercède pour nous auprès de Yahweh, ton Dieu, pour tout ce reste de Juda; car, de beaucoup que nous étions, nous sommes réduits à un petit nombre, comme tes yeux nous voient.'),
('jr',42,3,'crampon1923','Que Yahweh, ton Dieu, nous indique le chemin que nous devons suivre, et ce que nous avons à faire. "'),
('jr',42,4,'crampon1923','Jérémie, le prophète, leur répondit: " J''ai entendu; voici que je vais prier Yahweh, votre Dieu, selon vos paroles, et tout ce que Yahweh vous répondra, je vous le ferai connaître, sans rien vous cacher. "'),
('jr',42,5,'crampon1923','Ils dirent à Jérémie: " Que Yahweh soit un témoin véridique et fidèle contre nous, si nous n''agissons pas en tout selon la parole que Yahweh, ton Dieu, t''aura envoyé nous communiquer.'),
('jr',42,6,'crampon1923','Que ce soit du bien ou du mal, nous obéirons à la voix de Yahweh, notre Dieu, vers qui nous t''envoyons, afin qu''il nous arrive du bien, en obéissant à la voix de Yahweh, notre Dieu. "'),
('jr',42,7,'crampon1923','Et au bout de dix jours, la parole de Yahweh fut adressée à Jérémie,.'),
('jr',42,8,'crampon1923','Et il appela Johanan, fils de Carée, tous les chefs des troupes qui étaient avec lui, et tout le peuple, petits et grands;'),
('jr',42,9,'crampon1923','et il leur dit: Ainsi, parle Yahweh, Dieu d''Israël, vers qui vous m''avez envoyé pour présenter devant lui votre supplication:'),
('jr',42,10,'crampon1923','Si vous continuez à demeurer dans ce pays, je vous établirai et ne vous détruirai point, je vous planterai et ne vous arracherai point; car je me repens du mal que je vous ai fait.'),
('jr',42,11,'crampon1923','Ne craignez pas le roi de Babylone, dont vous avez peur; ne le craignez point, — oracle de Yahweh, — car je suis avec vous pour vous sauver et vous délivrer de sa main.'),
('jr',42,12,'crampon1923','Je vous ferai obtenir compassion, et il aura compassion de vous, et il vous fera retourner dans votre pays.'),
('jr',42,13,'crampon1923','Que si vous dites: Nous ne demeurerons pas dans ce pays, de telle sorte que vous n''obéissiez pas à la voix de Yahweh, votre Dieu;'),
('jr',42,14,'crampon1923','si vous dites: Non! mais nous irons au pays d''Egypte, où nous ne verrons point de guerre, où nous n''entendrons pas le son de la trompette, où nous ne sentirons pas la faim, et c''est là que nous habiterons, —'),
('jr',42,15,'crampon1923','alors entendez la parole de Yahweh, vous, les restes de Juda: Ainsi parle Yahweh des armées, Dieu d''Israël: Si vous tournez vos regards vers l''Egypte pour y aller, et que vous y entriez pour y habiter,'),
('jr',42,16,'crampon1923','l''épée que vous craignez vous atteindra là, au pays d''Egypte, et la famine que vous redoutez s''attachera à vous là, en Egypte; et là vous mourrez.'),
('jr',42,17,'crampon1923','Tous ceux qui auront tourné leurs regards vers l''Egypte pour y aller et pour y habiter mourront par l''épée, par la famine et la peste, et il n''y en aura point parmi eux qui survive et qui échappe au mal que je ferai venir sur eux.'),
('jr',42,18,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: Comme ma colère et ma fureur ont fondu sur les habitants de Jérusalem, ainsi ma fureur fondra sur vous quand vous serez entrés en Egypte; vous serez un objet d''exécration, de stupéfaction, de malédiction et d''outrages, et vous ne reverrez plus ce lieu-ci.'),
('jr',42,19,'crampon1923','Restes de Juda, Yahweh vous dit: N''entrez point en Egypte; sachez bien que je vous avertis solennellement aujourd''hui.'),
('jr',42,20,'crampon1923','Car vous vous abusiez vous-mêmes, lorsque vous m''avez envoyé vers Yahweh, notre Dieu, en disant: Intercède pour nous auprès de Yahweh, notre Dieu, et tout ce que Yahweh, notre Dieu, dira, déclare-le-nous, et nous le ferons.'),
('jr',42,21,'crampon1923','Je vous l''ai déclaré aujourd''hui; mais vous n''avez point écouté la voix de Yahweh, votre Dieu, ni rien de ce qu''il m''a envoyé vous communiquer.'),
('jr',42,22,'crampon1923','Sachez donc bien maintenant que vous mourrez par l''épée, par la famine et par la peste, au lieu où il vous a plu d''aller pour y habiter. "'),
('jr',43,1,'crampon1923','Et lorsque Jérémie eut achevé de dire à tout le peuple toutes les paroles de Yahweh, leur Dieu, toutes ces paroles que Yahweh, leur Dieu, l’avait envoyé leur communiquer,'),
('jr',43,2,'crampon1923','Azarias, fils d’Osaïas, Johanan, fils de Carée, et tous les hommes orgueilleux dirent à Jérémie: " Tu dis un mensonge; Yahweh, notre Dieu, ne t’a pas envoyé pour nous dire: N’entrez point en Egypte pour y habiter.'),
('jr',43,3,'crampon1923','Mais c’est Baruch, fils de Nérias, qui t’excite contre nous, afin de nous livrer aux mains des Chaldéens, pour nous faire mourir et pour nous faire transporter à Babylone. "'),
('jr',43,4,'crampon1923','Ainsi Johanan, fils de Carée, tous les chefs de troupes et tout le peuple n''écoutèrent pas la voix de Yahweh qui leur ordonnait de demeurer au pays de Juda.'),
('jr',43,5,'crampon1923','Mais Johanan, fils de Carée, et tous les chefs des troupes prirent tout le reste de Juda, ceux qui étaient revenus de toutes les nations où ils avaient été dispersés, pour habiter le pays de Juda,'),
('jr',43,6,'crampon1923','hommes, femmes et enfants, les filles du roi et toutes les personnes que Nabuzardan, chef des gardes, avait laissées avec Godolias, fils d''Ahicam, fils de Saphan, ainsi que Jérémie, le prophète, et Baruch, fils de Nérias.'),
('jr',43,7,'crampon1923','Ils entrèrent au pays d''Egypte, car ils n''écoutèrent pas la voix de Yahweh; et ils vinrent jusqu’à Taphnès.'),
('jr',43,8,'crampon1923','Et la parole de Yahweh fut adressée à Jérémie, à Taphnès, en ces termes:'),
('jr',43,9,'crampon1923','Prends dans ta main de grosses pierres et cache-les, en présence des hommes de Juda, dans le ciment de la plate-forme en briques qui est à l''entrée de la maison de Pharaon à Taphnès,'),
('jr',43,10,'crampon1923','et dis-leur: Ainsi parle Yahweh des armées, Dieu d''Israël: Voici que je vais envoyer prendre Nabuchodonosor, roi de Babylone, mon serviteur, et je placerai son trône sur ces pierres que j''ai cachées; il étendra son tapis sur elles.'),
('jr',43,11,'crampon1923','Il viendra et frappera le pays d''Egypte: qui est pour la mort, à la mort! qui est pour la captivité, en captivité! qui est pour l''épée, à l''épée.'),
('jr',43,12,'crampon1923','Et je mettrai le feu aux maisons des dieux d''Egypte; il les brûlera et emmènera les dieux captifs; il s''enveloppera du pays d''Egypte, comme un berger s''enveloppe de son vêtement, et il en sortira paisiblement.'),
('jr',43,13,'crampon1923','Il brisera les stèles de la maison du Soleil qui est dans le pays d''Egypte, et il brûlera les maisons des dieux d''Egypte!'),
('jr',44,1,'crampon1923','La parole qui fut adressée à Jérémie pour tous les Judéens demeurant dans le pays d''Egypte, demeurant à Migdol, à Taphnès, à Noph et au pays de Phaturès, en ces termes:'),
('jr',44,2,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Vous avez vu tout le mal que j''ai fait venir sur Jérusalem et sur toutes les villes de Juda: les voilà aujourd''hui dévastées et sans habitants,'),
('jr',44,3,'crampon1923','à cause du mal qu''ils ont fait pour m''irriter, en allant offrir de l''encens et des hommages à des dieux étrangers qu''ils ne connaissaient pas, ni eux, ni vous, ni vos vos pères.'),
('jr',44,4,'crampon1923','Je vous ai envoyé tous mes serviteurs les prophètes, les envoyant dès le matin, pour vous dire: Ne faites donc pas cette abomination que je hais.'),
('jr',44,5,'crampon1923','Mais ils n''ont pas écouté, ils n''ont pas prêté l''oreille pour revenir de leur méchanceté et n''offrir plus d''encens à des dieux étrangers.'),
('jr',44,6,'crampon1923','Aussi mon indignation et ma colère ont fondu sur eux et se sont allumées contre les villes de Juda et les rues de Jérusalem, qui sont devenues un lieu dévasté et désert, comme cela se voit aujourd''hui.'),
('jr',44,7,'crampon1923','Et maintenant, ainsi parle Yahweh, Dieu des armées, Dieu d''Israël: Pourquoi vous faites-vous ce grand mal à vous-mêmes, de vous faire exterminer du milieu de Juda, vos hommes et vos femmes, vos enfants et vos nourrissons, sans qu''on vous laisse aucun reste,'),
('jr',44,8,'crampon1923','de m''irriter par les œuvres de vos mains, en offrant de l''encens à des dieux étrangers dans le pays d''Egypte, où vous êtes entrés pour y habiter, afin de vous faire exterminer, et afin de devenir un objet de malédiction et d’opprobre parmi tous les peuples de la terre?'),
('jr',44,9,'crampon1923','Avez-vous, oublié les crimes de vos pères, les crimes des rois de Juda, les crimes des femmes de Juda, vos crimes et les crimes de vos femmes, qu''elles ont commis dans le pays de Juda et dans les rues de Jérusalem?'),
('jr',44,10,'crampon1923','Ils n''ont pas été contrits jusqu''à ce jour, ils n''ont pas eu de crainte, ils n''ont pas marché dans ma loi ni dans mes commandements que j''avais mis devant vous et devant vos pères.'),
('jr',44,11,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées, Dieu d''Israël: Voici que je vais tourner ma face contre vous, pour votre malheur, et pour exterminer tout Juda.'),
('jr',44,12,'crampon1923','Je prendrai le reste de Juda, qui a tourné ses regards vers le pays d''Egypte pour y venir habiter. Ils seront tous consumés dans le pays d''Egypte et ils tomberont; ils seront consumés par l''épée, par la famine; petits et grands, ils mourront par l''épée et par la famine, et ils seront un objet d''exécration, de stupéfaction, de malédiction et d''opprobre.'),
('jr',44,13,'crampon1923','Je visiterai ceux qui demeurent dans le pays d''Egypte, comme j''ai visité Jérusalem, par l''épée, par la famine et par la peste.'),
('jr',44,14,'crampon1923','Nul ne réchappera ni ne survivra du reste de Juda, de ceux qui sont venus pour demeurer ici, au pays d''Egypte, et pour retourner au pays de Juda, où leur désir les pousse à revenir pour y demeurer. Car ils n''y retourneront pas, sauf quelques réchappés.'),
('jr',44,15,'crampon1923','Alors tous les hommes qui savaient que leurs femmes offraient de l''encens à des dieux étrangers, et toutes les femmes rassemblées là, en grande assemblée, et tout le peuple qui demeurait dans le pays d''Egypte, à Pathurès, répondirent, à Jérémie en ces termes:'),
('jr',44,16,'crampon1923','" Quant à la parole que tu nous as dite au nom de Yahweh, nous ne t''écoutons pas.'),
('jr',44,17,'crampon1923','Mais nous accomplirons certainement toute parole sortie de notre bouche, en offrant de l''encens à la Reine du ciel, en lui versant des libations, comme nous avons fait, nous et nos pères, nos rois et nos chefs, dans les villes de Juda et dans les rues de Jérusalem. Nous avions alors du pain à satiété, nous étions heureux et nous ne voyions pas le malheur.'),
('jr',44,18,'crampon1923','Mais depuis que nous avons cessé d''offrir de l''encens à la Reine du ciel et de lui verser des libations, nous avons manqué de tout et nous avons été consumés par l''épée et par la famine.'),
('jr',44,19,'crampon1923','Et quand nous offrions de l''encens à la Reine du ciel et que nous lui versions des libations, est-ce en dehors de nos maris que nous lui faisions des gâteaux pour la représenter et que nous lui versions des libations?'),
('jr',44,20,'crampon1923','Alors Jérémie parla à tout le peuple contre les hommes, contre les femmes et contre ceux qui lui avaient ainsi répondu, et il leur dit:'),
('jr',44,21,'crampon1923','" N''est-ce pas l''encens que vous avez brûlé dans les villes de Juda et dans les rues de Jérusalem, vous et vos pères, vos rois et vos chefs, et le peuple du pays, que Yahweh s''est rappelé et qui lui est monté au cœur?'),
('jr',44,22,'crampon1923','Yahweh n''a pu le supporter plus longtemps, à cause de la méchanceté de vos actions et des abominations que vous avez commises; et votre pays est devenu un lieu désert, dévasté et maudit, où personne n''habite, comme on le voit aujourd''hui.'),
('jr',44,23,'crampon1923','C''est parce que vous avez offert de l''encens et péché contre Yahweh et que vous n''avez pas écouté la voix de Yahweh, ses lois, ses ordonnances et ses préceptes, c''est pour cela que ce malheur vous est arrivé, comme cela se voit aujourd''hui. "'),
('jr',44,24,'crampon1923','Et Jérémie dit à tout le peuple et à toutes les femmes: " Ecoutez la parole de Yahweh, vous tous, hommes de Juda qui êtes dans le pays d''Egypte.'),
('jr',44,25,'crampon1923','Ainsi parle Yahweh des armées, Dieu d''Israël: Vous et vos femmes, vous l''avez déclaré de vos bouches et exécuté de vos mains, en disant: Oui, nous accomplirons les vœux que nous avons faits, d''offrir de l''encens à la Reine du ciel et de lui verser des libations. Eh bien, acquittez vos vœux, ne manquez pas d''accomplir vos vœux!'),
('jr',44,26,'crampon1923','Ecoutez donc la parole de Yahweh, vous tous, hommes de Juda qui demeurez dans le pays d''Egypte. Voici que je le jure par mon grand nom, dit Yahweh: Mon nom ne sera plus prononcé dans tout le pays d''Egypte par la bouche d''aucun homme de Juda disant: Le Seigneur Yahweh est vivant!'),
('jr',44,27,'crampon1923','Voici que je veille sur eux, pour leur mal et non pour leur bien, et tous les hommes de Juda qui sont dans le pays d''Egypte seront consumés par l''épée et par la famine, jusqu''à leur extermination.'),
('jr',44,28,'crampon1923','Et ceux qui échapperont à l''épée, en petit nombre, retourneront du pays d''Egypte au pays de Juda. Et tout le reste de Juda, ceux qui sont venus en Egypte pour y habiter, sauront de qui la parole sera réalisée, la mienne ou la leur.'),
('jr',44,29,'crampon1923','Et ceci sera pour vous, — oracle de Yahweh, — le signe que je vous visiterai en ce lieu, afin que vous sachiez que mes paroles s''accompliront certainement pour votre malheur:'),
('jr',44,30,'crampon1923','Ainsi parle Yahweh: Voici que je livre le Pharaon Hophra, roi d''Egypte, aux mains de ses ennemis et aux mains de ceux qui en veulent à sa vie, comme j''ai livré Sédécias, roi de Juda, aux mains de Nabuchodonosor, roi de Babylone, son ennemi, qui en voulait à sa vie. "'),
('jr',45,1,'crampon1923','La parole que Jérémie, le prophète, dit à Baruch, fils de Nérias, lorsqu’il écrivit ces paroles dans le livre sous la dictée de Jérémie, la quatrième année de Joakim, fils de Josias, roi de Juda, — en ces termes:'),
('jr',45,2,'crampon1923','" Ainsi parle Yahweh, roi d’Israël, à ton sujet, Baruch:'),
('jr',45,3,'crampon1923','Tu dis: Malheur à moi! car Yahweh ajoute à mon chagrin la douleur; je m’épuise dans mon gémissement, et je ne trouve point de repos.'),
('jr',45,4,'crampon1923','Ainsi tu lui diras: Ainsi parle Yahweh: Voici que ce que j''avais bâti, je le détruis; ce que j''avais planté, je l''arrache, et c''est toute cette terre.'),
('jr',45,5,'crampon1923','Et toi, tu chercherais pour toi de grandes choses! Ne les cherche point! Car voici que j''amène un malheur sur toute chair, — oracle de Yahweh; — mais je te donnerai la vie pour butin dans tous les lieux où tu iras. "'),
('jr',46,1,'crampon1923','Parole de Yahweh qui fut adressée à Jérémie, le prophète, au sujet des nations païennes.'),
('jr',46,2,'crampon1923','Sur l''Egypte. — Contre l’armée du Pharaon Néchao, roi d’Egypte, qui était près du fleuve de l’Euphrate, à Carchémis, et que battit Nabuchodonosor, roi de Babylone, la quatrième année de Joakim, fils de Josias, roi de Juda.'),
('jr',46,3,'crampon1923','Préparez l''écu et le bouclier, et marchez au combat!'),
('jr',46,4,'crampon1923','Attelez les chevaux; montez, cavaliers! A vos rangs, vous qui portez le casque! Fourbissez les lances, endossez la cuirasse!'),
('jr',46,5,'crampon1923','Que vois-je? Ils sont frappés d’épouvante, ils tournent le dos! Leurs guerriers sont battus, ils fuient sans se retourner! Terreur de toutes parts! — oracle de Yahweh.'),
('jr',46,6,'crampon1923','Que l''homme agile ne fuie pas, que le vaillant n''échappe pas! Au septentrion, sur les rives du fleuve de l''Euphrate, ils ont chancelé, ils sont tombés!'),
('jr',46,7,'crampon1923','Qui est-ce qui monte, pareil au Nil, dont les flots bouillonnent, pareils à des fleuves?'),
('jr',46,8,'crampon1923','C''est l''Egypte qui monte, pareille au Nil, dont les flots bouillonnent, pareils à des fleuves. Elle a dit: Je monterai, je couvrirai la terre, je détruirai les villes et leurs habitants.'),
('jr',46,9,'crampon1923','Montez, chevaux! Chars, précipitez-vous! En marche, guerriers! Ethiopiens et Lybiens qui manient le bouclier, Lydiens qui manient et bandent l''arc!'),
('jr',46,10,'crampon1923','Mais ce jour est au Seigneur Yahweh des armées; jour de vengeance pour se venger de ses ennemis! L’épée dévore et se rassasie, elle s''abreuve de leur sang. Car c''est une immolation pour le Seigneur Yahweh des armées, au pays du septentrion, sur le fleuve de l''Euphrate.'),
('jr',46,11,'crampon1923','Monte à Galaad et prends du baume, vierge, fille de l''Egypte. En vain tu multiplies les remèdes; il n''y a point de guérison pour toi.'),
('jr',46,12,'crampon1923','Les nations ont appris ta honte, et tes cris de détresse remplissent la terre. Car le guerrier se heurte au guerrier; ils tombent tous deux.'),
('jr',46,13,'crampon1923','La parole qu’adressa Yahweh à Jérémie, le prophète, sur la venue de Nabuchodonosor, roi de Babylone, pour frapper le pays d''Egypte.'),
('jr',46,14,'crampon1923','Publiez-le en Egypte, faites-le entendre à Migdol, faites-le entendre à Noph et à Taphnès; dites: A vos rangs, tenez-vous prêts; déjà l''épée dévore autour de vous!'),
('jr',46,15,'crampon1923','Quoi! ton héros est renversé! Il ne s''est pas tenu debout, car Yahweh l''a jeté par terre.'),
('jr',46,16,'crampon1923','Il multiplie ceux qui trébuchent; ils tombent les uns sur les autres, et ils disent: Levons-nous, retournons vers notre peuple et dans notre pays natal, loin de l''épée homicide.'),
('jr',46,17,'crampon1923','Là ils crient: Pharaon, roi d''Egypte est perdu; il a laissé passer le temps favorable.'),
('jr',46,18,'crampon1923','Je suis vivant! — oracle du roi dont le nom est Yahweh des armées: Comme le Thabor parmi les montagnes, comme le Carmel au-dessus de la mer, il vient.'),
('jr',46,19,'crampon1923','Prépare ton bagage de captive, habitante, fille de l''Egypte; car Noph va devenir un désert; elle sera brûlée et sans habitants.'),
('jr',46,20,'crampon1923','L''Egypte est une génisse très belle; un taon vient, vient du septentrion.'),
('jr',46,21,'crampon1923','Ses mercenaires au milieu d''elle sont comme des veaux engraissés. Eux aussi, ils tournent le dos, ils fuient tous ensemble; ils ne résistent point; car il est venu sur eux le jour de leur calamité, le temps de leur châtiment.'),
('jr',46,22,'crampon1923','Sa voix est comme le bruit du serpent qui s''en va; car ils sont venus en force, ils sont arrivés chez elle avec des haches, pareils à des bûcherons.'),
('jr',46,23,'crampon1923','Ils ont abattu sa forêt, — oracle de Yahweh, alors qu''elle était impénétrable; car ils sont plus nombreux que les sauterelles, et on ne peut les compter.'),
('jr',46,24,'crampon1923','Elle est confuse, la fille de l''Egypte; elle a été livrée aux mains d''un peuple du septentrion!'),
('jr',46,25,'crampon1923','Yahweh des armées, Dieu d''Israël, a dit: Voici que je vais visiter Amon de No, et Pharaon, et l''Egypte, et ses dieux, et ses rois, et Pharaon, et ceux qui se fient à lui.'),
('jr',46,26,'crampon1923','Et je les livrerai aux mains de ceux qui en veulent à leur vie, aux mains de Nabuchodonosor, roi de Babylone, et aux mains de ses serviteurs. Et après cela, elle sera habitée, comme aux jours d''autrefois, — oracle de Yahweh.'),
('jr',46,27,'crampon1923','Toi donc, ne crains pas, mon serviteur Jacob; ne t''effraie pas, Israël. Car voici que je vais te tirer de la terre lointaine, et ta postérité du pays de son exil; Jacob reviendra, il sera tranquille, en sécurité, sans que personne l''épouvante.'),
('jr',46,28,'crampon1923','Et toi, ne crains pas, mon serviteur Jacob, — oracle de Yahweh, — car je suis avec toi! Je ferai une extermination dans toutes les nations où je t''ai chassé. Pour toi, je ne t''exterminerai pas. Mais je te châtierai selon la justice, et je ne te laisserai pas impuni.'),
('jr',47,1,'crampon1923','Parole de Yahweh qui fut adressée à Jérémie, le prophète, au sujet des Philistins, avant que Pharaon frappât Gaza.'),
('jr',47,2,'crampon1923','Ainsi parle Yahweh: Voici que des eaux montent du septentrion; elles deviennent comme un torrent qui déborde, et elles submergeront le pays et ce qu''il contient, la ville et habitants. Les hommes poussent des cris, et tous les habitants du pays se lamentent.'),
('jr',47,3,'crampon1923','Au retentissement du sabot de ses coursiers, au fracas de ses chars, au bruit de ses roues, les pères ne se tournent plus vers leurs enfants, tant les mains sont sans force!'),
('jr',47,4,'crampon1923','C''est à cause du jour qui est venu, où seront détruits tous les Philistins, exterminés tous les derniers alliés de Tyr et de Sidon; car Yahweh va détruire les Philistins, les restes de l''île de Caphtor.'),
('jr',47,5,'crampon1923','Gaza est devenue chauve, Ascalon est ruinée, avec la vallée qui les entoure; jusques à quand te feras-tu des incisions?'),
('jr',47,6,'crampon1923','Ah! épée de Yahweh, jusques à quand n''auras-tu pas de repos? Rentre dans ton fourreau, arrête et sois tranquille! —'),
('jr',47,7,'crampon1923','Comment te reposerais-tu, quand Yahweh t’a donné ses ordres? Vers Ascalon et la côte de la mer, c''est là qu’il la dirige.'),
('jr',48,1,'crampon1923','A Moab. Ainsi parle Yahweh des armées, Dieu d''Israël: Malheur à Nabo, car elle est ravagée; Cariathaïm est couverte de honte, elle est prise; la forteresse est couverte de honte, elle est abattue;'),
('jr',48,2,'crampon1923','elle n''est plus, la gloire de Moab! A Hésebon on médite contre lui le mal: Allons et exterminons-le d''entre les nations! Toi aussi, Madmen, tu seras réduite au silence, l''épée marche derrière toi.'),
('jr',48,3,'crampon1923','Des cris partent de Horonaïm; dévastation et grande ruine!'),
('jr',48,4,'crampon1923','Moab est brisé; ses petits enfants font entendre des cris.'),
('jr',48,5,'crampon1923','Oui! à la montée de Luith il y a des pleurs, on la gravit en pleurant; oui! à la descente de Horonaïm, on entend les cris de détresse.'),
('jr',48,6,'crampon1923','Fuyez, sauvez vos vies! Qu’elles soient comme une bruyère dans la lande!'),
('jr',48,7,'crampon1923','Car, puisque tu as mis ta confiance en tes ouvrages et en tes trésors, toi aussi tu seras conquis; et Chamos ira en exil, avec ses prêtres et ses princes, tous ensemble.'),
('jr',48,8,'crampon1923','Le dévastateur viendra contre toutes les villes, et pas une ville n''échappera; la vallées sera ruinée, et le plateau saccagé, comme l''a dit Yahweh.'),
('jr',48,9,'crampon1923','Donnez des ailes à Moab, car il faut qu''il s''envole; ses villes seront dévastées, sans qu''il y ait d''habitant.'),
('jr',48,10,'crampon1923','Maudit soit celui qui fait mollement l''œuvre du Seigneur! Maudit celui qui refuse le sang à son épée!'),
('jr',48,11,'crampon1923','Moab a été tranquille depuis sa jeunesse; il a reposé sur sa lie; il n''a pas été vidé d''un vase dans un autre, et il n''est pas allé en captivité. Aussi son goût lui est-il resté, et son parfum ne s''est pas altéré.'),
('jr',48,12,'crampon1923','C’est pourquoi voici que des jours viennent, — oracle Yahweh, où je lui enverrai des transvaseurs qui le transvaseront; ils videront ses vases, et ils briseront ses cruches.'),
('jr',48,13,'crampon1923','Et Moab aura honte de Chamos, comme la maison d''Israël a eu honte de Béthel, en qui était sa confiance.'),
('jr',48,14,'crampon1923','Comment pouvez-vous dire: " Nous sommes des guerriers, des hommes vaillants au combat? "'),
('jr',48,15,'crampon1923','Moab est ravagé, ses villes montent en fumée, l''élite de ses jeunes gens descend pour la boucherie; — oracle du roi, dont le nom est Yahweh des armées.'),
('jr',48,16,'crampon1923','La ruine de Moab approche, son malheur vient en grande hâte.'),
('jr',48,17,'crampon1923','Consolez-le, vous tous, ses voisins, et vous tous qui connaissez son nom, dites: " Comment a été brisé un bâton si fort, un sceptre si magnifique? "'),
('jr',48,18,'crampon1923','Descends de ta gloire et assieds-toi sur la terre aride, habitante, fille de Dibon; car le dévastateur de Moab est monté contre toi, il a renversé tes remparts.'),
('jr',48,19,'crampon1923','Tiens-toi sur le chemin, et observe, habitante d''Aroër; interroge celui qui fuit et celle qui s''échappe; dis: " Qu''est-il arrivé? —'),
('jr',48,20,'crampon1923','" Moab est confus, car il est renversé. Poussez des gémissements et des cris! Annoncez sur l''Arnon que Moab est ravagé! "'),
('jr',48,21,'crampon1923','Un jugement est venu sur le pays de la plaine, sur Hélon, sur Jasa, sur Méphaath,'),
('jr',48,22,'crampon1923','sur Dibon, sur Nabo, sur Beth-Deblathaïm,'),
('jr',48,23,'crampon1923','sur Cariathaïm, sur Beth-Gamul, sur Beth-Maon,'),
('jr',48,24,'crampon1923','sur Carioth, sur Bosra et sur toutes les villes du pays de Moab, éloignées et proches.'),
('jr',48,25,'crampon1923','La corne de Moab est abattue, et son bras est brisé, — oracle de Yahweh.'),
('jr',48,26,'crampon1923','Enivrez-le; car il s''est élevé contre Yahweh! que Moab se vautre dans son vomissement, et qu''il devienne un objet de risée, lui aussi!'),
('jr',48,27,'crampon1923','Israël n''a-t-il pas été pour toi un objet de risée? L''a-t-on surpris avec des voleurs, pour que, chaque fois que tu parlés de lui, tu hoches la tête?'),
('jr',48,28,'crampon1923','Abandonnez les villes; demeurez dans les rochers, habitants de Moab, et soyez comme la colombe qui fait son nid au-dessus du précipice béant.'),
('jr',48,29,'crampon1923','Nous avons entendu l''orgueil de Moab, le très orgueilleux, sa hauteur, son orgueil, sa fierté, et la fierté de son cœur.'),
('jr',48,30,'crampon1923','Moi aussi je connais, — oracle de Yahweh, sa jactance, et ses vains discours, et ses œuvres vaines.'),
('jr',48,31,'crampon1923','C''est pourquoi je me lamente sur Moab; sur tout Moab je pousse des cris; on gémit sur les gens de Qir-Hérès.'),
('jr',48,32,'crampon1923','Plus encore que sur Jazer, je pleure sur toi, vigne de Sabama. Tes sarments dépassaient la mer, ils touchaient à la mer de Jazer. Sur ta récolte et sur ta vendange le dévastateur s''est jeté.'),
('jr',48,33,'crampon1923','La joie et l''allégresse ont disparu des vergers et de la terre de Moab; j''ai fait tarir le vin des cuves; on ne le foule plus au bruit des hourrahs; le hourrah n''est plus le hourrah.'),
('jr',48,34,'crampon1923','A cause du cri de Hésébon jusqu''à Eléalé; jusqu''à Jasa, ils font entendre leur cri; de Segor jusqu''à Horonaïm, jusqu''à Eglath-Sélisia; Car même les eaux de Nemrim seront taries.'),
('jr',48,35,'crampon1923','Je veux, en finir avec Moab, — oracle de Yahweh, avec celui qui monte à son haut-lieu et offre de l’encens à son dieu.'),
('jr',48,36,'crampon1923','C''est pourquoi mon cœur au sujet de Moab, gémit comme une flûte, oui, mon cœur au sujet des gens de Qir-Hérès, gémit comme une flûte. C''est pourquoi le gain qu''ils avaient fait est perdu.'),
('jr',48,37,'crampon1923','Car toute tête est rasée, et toute barbe coupée; sur toutes les mains il y a des incisions; et sur les reins des sacs.'),
('jr',48,38,'crampon1923','Sur tous les toits de Moab et sur ses places, ce ne sont que lamentations; car j''ai brisé Moab comme un vase dont on ne veut plus, — oracle de Yahweh.'),
('jr',48,39,'crampon1923','Comme il est brisé! Gémissez! Comme Moab a honteusement tourné le dos! Moab est devenu un objet de risée, et d''épouvante pour tous ses voisins.'),
('jr',48,40,'crampon1923','Car ainsi parle Yahweh: Voici qu''il prend son vol comme l''aigle, il étend ses ailes sur Moab.'),
('jr',48,41,'crampon1923','Carioth est prise, les forteresses sont emportées, et le cœur des guerriers de Moab est, en ce jour, comme le cœur d''une femme en travail.'),
('jr',48,42,'crampon1923','Moab est exterminé du rang des peuples, parce qu''il s''est élevé contre Yahweh.'),
('jr',48,43,'crampon1923','Epouvante, fosse et filet, sont sur toi, habitant de Moab! — oracle de Yahweh.'),
('jr',48,44,'crampon1923','Celui qui fuit devant l''objet d''épouvante tombera dans la fosse, et celui qui remontera de la fosse sera pris au filet; car je vais faire venir sur lui, sur Moab, l''année de sa visitation, — oracle de Yahweh.'),
('jr',48,45,'crampon1923','A l''ombre de Hésébon ils s''arrêtent, les fuyards à bout de forces; mais il est sorti un feu de Hésébon, et une flamme du milieu de Séhon; elle a dévoré les flancs de Moab et le crâne des fils du tumulte.'),
('jr',48,46,'crampon1923','Malheur à toi, Moab! Il est perdu, le peuple de Chamos; car tes fils sont emmenés en exil, et tes filles en captivité.'),
('jr',48,47,'crampon1923','Mais je ramènerai les captifs de Moab; à la fin des jours, — oracle de Yahweh. Jusqu''ici le jugement de Moab.'),
('jr',49,1,'crampon1923','Contre les enfants d''Ammon. Ainsi parle Yahweh: Israël n''a-t-il pas de fils, n''a-t-il pas d''héritier? Pourquoi Melchom a-t-il pris possession de Gad, et son peuple s''est-il installé dans ses villes?'),
('jr',49,2,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où je ferai retentir à Rabba des enfants d''Ammon le cri de guerre. Elle deviendra un monceau de ruines, et ses filles seront livrées au feu, et Israël héritera de ceux qui ont hérité de lui, — oracle de Yahweh.'),
('jr',49,3,'crampon1923','Lamente-toi, Hésébon, car Haï a été saccagée; poussez des cris, filles de Rabbah, ceignez-vous de sacs, lamentez-vous; errez le long des clôtures; car Melchom s''en va en exil, et avec lui, ses prêtres et ses chefs.'),
('jr',49,4,'crampon1923','Pourquoi te glorifier de tes vallées? — elle est riche, ta vallée! — fille rebelle, toi qui te confies dans tes trésors, disant: " Qui oserait venir contre moi? "'),
('jr',49,5,'crampon1923','Voici que j''amène contre toi la terreur, — oracle du Seigneur Yahweh des armées, de tous les alentours; vous serez chassés, chacun droit devant soi, et personne ne ralliera les fuyards.'),
('jr',49,6,'crampon1923','Mais après cela, je ramènerai les captifs des enfants d''Ammon, — oracle de Yahweh.'),
('jr',49,7,'crampon1923','Contre Edom. Ainsi parle Yahweh, des armées: N''y a-t-il plus de sagesse en Théman? Les avisés sont-ils à bout de conseils? Leur sagesse s''est-elle évanouie?'),
('jr',49,8,'crampon1923','Fuyez, retournez sur vos pas, blottissez-vous, habitants de Dédan car j''amènerai sur Esaü la ruine, au temps où je le visite.'),
('jr',49,9,'crampon1923','Si des vendangeurs viennent chez toi, ils ne laissent rien à grappiller; si ce sont des voleurs de nuit, ils pillent tout leur soûl.'),
('jr',49,10,'crampon1923','Car c''est moi qui ai mis à nu Esaü et découvert ses retraites, et il ne peut plus se cacher; sa race est ravagé, ses frères, ses voisins, — et il n''est plus.'),
('jr',49,11,'crampon1923','Abandonne tes orphelins, c''est moi qui les ferai vivre, et que tes veuves se confient en moi!'),
('jr',49,12,'crampon1923','Car ainsi parle Yahweh: Voici que ceux qui ne devaient pas boire cette coupe la boiront sûrement; et toi, tu en serais tenu quitte? Non, tu n''en seras pas tenu quitte, tu la boiras sûrement!'),
('jr',49,13,'crampon1923','Car je l''ai juré par moi-même, — oracle de Yahweh: Bosra sera un sujet d''étonnement et d''opprobre, un lieu désert et maudit, et toutes ses villes seront des ruines à jamais.'),
('jr',49,14,'crampon1923','J''en ai appris de Yahweh la nouvelle, et un messager a été envoyé parmi les nations: " Rassemblez-vous et marchez contre lui! Levez-vous pour le combat! "'),
('jr',49,15,'crampon1923','Car voici que je t''ai rendu petit parmi les nations, méprisé parmi les hommes.'),
('jr',49,16,'crampon1923','La terreur que tu inspirais t''a égaré, ainsi que la fierté de ton cœur, toi qui habites le creux des rochers, qui occupes le sommet de la colline. Mais quand tu élèverais ton aire comme l''aigle, de là je te ferai descendre, — oracle de Yahweh.'),
('jr',49,17,'crampon1923','Edom sera un sujet d''étonnement; tous les passants s''étonneront, et siffleront à la vue de toutes ses plaies.'),
('jr',49,18,'crampon1923','Ce sera comme la catastrophe de Sodome, de Gomorrhe et des villes voisines, dit Yahweh; personne n''y habitera, aucun fils de l''homme n''y séjournera.'),
('jr',49,19,'crampon1923','Pareil à un lion, voici qu''il monte des halliers du Jourdain au pâturage perpétuel; soudain j''en ferai fuir Edom, et j''y établirai celui que j''ai choisi. Car qui est semblable à moi? Qui me provoquerait, et quel est le berger qui me tiendrait tête?'),
('jr',49,20,'crampon1923','Ecoutez donc la résolution qu''a prise Yahweh contre Edom, et les desseins qu''il a médités contre les habitants de Théman: Oui, on les entraînera comme de faibles brebis; oui, leur pâturage en sera dans la stupeur.'),
('jr',49,21,'crampon1923','Au bruit de leur chute, la terre tremble; le bruit de leur voix se fait entendre jusqu''à la mer Rouge.'),
('jr',49,22,'crampon1923','Voici qu''il monte et prend son vol comme l''aigle, il étend ses ailes sur Bosra; et le cœur des guerriers d''Edom est en ce jour comme le cœur d''une femme en travail.'),
('jr',49,23,'crampon1923','Contre Damas. Hamath et Arphad sont dans la confusion, parce qu''elles ont reçu une mauvaise nouvelle; elles se fondent de peur; c''est la mer en tourmente, qui ne peut s''apaiser.'),
('jr',49,24,'crampon1923','Damas est sans force, elle se tourne pour fuir, et l''effroi s''empare d''elle; l''angoisse et les douleurs la saisissent, comme une femme qui enfante.'),
('jr',49,25,'crampon1923','A quel point n''est-elle pas abandonnée, la ville glorieuse, la cité de délices, de joie!'),
('jr',49,26,'crampon1923','Aussi ses jeunes gens tomberont sur ses places, ainsi que tous ses hommes de guerre; ils périront en ce jour-là, — oracle de Yahweh des armées.'),
('jr',49,27,'crampon1923','J''allumerai un feu dans les murs de Damas, et il dévorera les palais de Ben-Hadad.'),
('jr',49,28,'crampon1923','Contre Cédar et les royaumes de Hasor, que frappa Nabuchodonosor, roi de Babylone. Ainsi parle Yahweh: Debout! Marchez contre Cédar, exterminez les fils de l''Orient!'),
('jr',49,29,'crampon1923','Qu''on prenne leurs tentes et leurs troupeaux! Qu''on leur enlève leurs tentures, tous leurs bagages et leurs chameaux! Et qu''on leur crie: Terreur de toutes parts!'),
('jr',49,30,'crampon1923','Sauvez-vous, fuyez de toutes vos forces, blottissez-vous, habitants de Hasor! — oracle de Yahweh. Car Nabuchodonosor, roi de Babylone, a formé contre vous un dessein, il a conçu un projet contre vous.'),
('jr',49,31,'crampon1923','Debout! Marchez contre un peuple tranquille, en assurance dans sa demeure, — oracle de Yahweh, qui n''a ni portes ni barres, qui vit à l''écart.'),
('jr',49,32,'crampon1923','Leurs chameaux seront votre butin, et la multitude de leurs troupeaux vos dépouilles. Je les disperserai à tous les vents, ces hommes aux tempes rasées, et de tous côtés je ferai venir sur leur ruine, — oracle de Yahweh.'),
('jr',49,33,'crampon1923','Et Hasor deviendra un repaire de chacals, une solitude pour toujours; personne n''y demeurera, aucun fils d''homme n''y séjournera.'),
('jr',49,34,'crampon1923','La parole de Yahweh qui fut adressée à Jérémie, le prophète, pour Élam, au commencement du règne de Sédécias, roi de Juda, en ces termes:'),
('jr',49,35,'crampon1923','Ainsi parle Yahweh des armées: Voici que je vais briser l''arc d''Élam, principe de sa force.'),
('jr',49,36,'crampon1923','Je ferai venir sur Élam quatre vents, des quatre coins du ciel, et je le disperserai à tous ces vents; et il n''y aura pas une nation où n''arrivent pas des fugitifs d''Élam.'),
('jr',49,37,'crampon1923','Je ferai trembler Élam devant ses ennemis, et devant ceux qui en veulent à sa vie. Et j''amènerai sur eux des malheurs, le feu de mon ardente colère, — oracle de Yahweh. Et j''enverrai après eux l''épée, jusqu''à ce que je les aie anéantis.'),
('jr',49,38,'crampon1923','Je placerai mon trône en Élam, et j''en exterminerai roi et chefs, — oracle de Yahweh.'),
('jr',49,39,'crampon1923','Mais à la fin des jours, je ramènerai les captifs d''Élam, — oracle de Yahweh.'),
('jr',50,1,'crampon1923','La parole que Yahweh prononça sur Babylone, sur le pays des Chaldéens, par l''intermédiaire de Jérémie, le prophète.'),
('jr',50,2,'crampon1923','Annoncez-le parmi les nations, publiez-le; élevez un étendard, publiez-le; ne le cachez pas, dites: Babel est prise! Bel est confondu, Mérodach est abattu; ses idoles sont confondues, ses faux dieux sont abattus.'),
('jr',50,3,'crampon1923','Car du septentrion un peuple monte contre elle; il fera de son pays une solitude, il n''y aura plus d''habitant; hommes et bêtes ont fuit, se sont en allés.'),
('jr',50,4,'crampon1923','En ces jours-là et en ce temps-là, — oracle de Yahweh, les enfants d''Israël reviendront, eux et les enfants de Juda avec eux; ils marcheront en pleurant, et chercheront Yahweh, leur Dieu.'),
('jr',50,5,'crampon1923','Ils demanderont Sion, et tourneront leur face vers elle. " Venez et attachons-nous à Yahweh par une alliance éternelle, qui ne soit jamais oubliée. "'),
('jr',50,6,'crampon1923','Mon peuple était un troupeau de brebis qui se perdaient; leurs bergers les égaraient sur des montagnes perfides; elles allaient de montagne en colline, oubliant leur bercail.'),
('jr',50,7,'crampon1923','Tous ceux qui les trouvaient les dévoraient, et leurs ennemis disaient: " Nous ne sommes pas coupables! " Parce qu''elles avaient péché contre Yahweh, la demeure de justice, contre Yahweh, l''espérance de leurs pères.'),
('jr',50,8,'crampon1923','Fuyez du milieu de Babylone, et sortez du pays des Chaldéens; soyez comme les boucs, à la tête du troupeau.'),
('jr',50,9,'crampon1923','Car voici que je vais susciter et faire marcher contre Babel une réunion de grands peuples; venant du pays du septentrion. Ils se rangeront contre elle, et de ce côté-là elle sera prise; leurs flèches sont celles d''un guerrier habile, qui ne revient pas à vide.'),
('jr',50,10,'crampon1923','Et la Chaldée sera mise au pillage, tous ceux qui la pilleront se rassasieront, — oracle de Yahweh.'),
('jr',50,11,'crampon1923','Oui, réjouissez-vous; oui, livrez-vous à l''allégresse, pillards de mon héritage; oui, bondissez comme une génisse dans la prairie, hennissez comme des étalons!'),
('jr',50,12,'crampon1923','Votre mère est couverte de confusion; celle qui vous a enfantés rougit de honte. Voici qu''elle est la dernière des nations, un désert, une steppe, une terre aride.'),
('jr',50,13,'crampon1923','A cause de la colère de Yahweh, elle ne sera plus habitée, ce ne sera plus qu''une solitude; quiconque passera près de Babel s''étonnera et sifflera à la vue de ses plaies.'),
('jr',50,14,'crampon1923','Rangez-vous contre Babel, tout autour, vous tous, archers! Tirez contre elle, n''épargnez pas les flèches, car elle a péché contre Yahweh.'),
('jr',50,15,'crampon1923','Poussez de tous côtés contre elle un cri de guerre; elle tend les mains; ses tours s''écroulent, ses murs sont renversés. Car c''est la vengeance de Yahweh: vengez-vous sur elle; faites-lui comme elle a fait!'),
('jr',50,16,'crampon1923','Exterminez de Babel celui qui sème, et celui qui manie la faucille au jour de la moisson. Devant le glaive destructeur, que chacun se tourne vers son peuple, que chacun fuie vers son pays.'),
('jr',50,17,'crampon1923','Israël est une brebis égarée a qui les lions ont fait la chasse; le premier l''a dévorée: le roi d''Assyrie; puis cet autre lui a brisé les os: Nabuchodonosor, roi de Babel.'),
('jr',50,18,'crampon1923','C''est pourquoi ainsi parle Yahweh des armées, Dieu d''Israël: Voici que je vais visiter le roi de Babel et son pays, comme j''ai visité le roi d''Assyrie.'),
('jr',50,19,'crampon1923','Et je ramènerai Israël dans sa demeure; et il paîtra au Carmel et en Basan; et sur la montagne d''Ephraïm et de Galaad, il ira se rassasier.'),
('jr',50,20,'crampon1923','En ces jours-là et en ce temps-là, — oracle de Yahweh, on cherchera l''iniquité d''Israël, et elle ne sera plus; le péché de Juda, et on ne le trouvera plus; car je pardonnerai au reste que j''aurai laissé.'),
('jr',50,21,'crampon1923','Monte contre le pays de Rébellion et contre les habitants de Punition; détruis, extermine-les, les uns après les autres, — oracle de Yahweh, et fais-leur tout ce que je t''ai ordonné.'),
('jr',50,22,'crampon1923','Bruit de bataille dans le pays et grand massacre!'),
('jr',50,23,'crampon1923','Comment a été rompu et brisé, le marteau de toute la terre? Comment Babel, est-elle devenue un objet d''horreur, au milieu des nations?'),
('jr',50,24,'crampon1923','J''ai tendu des lacets, et tu as été prise, Babel, sans t''en douter; tu as été trouvée et saisie, parce que tu t''es mise en guerre contre Yahweh.'),
('jr',50,25,'crampon1923','Yahweh a ouvert son arsenal, et il en a tiré les armes de sa colère; car le Seigneur Yahweh des armées, a affaire au pays des Chaldéens.'),
('jr',50,26,'crampon1923','Arrivez contre elle de toutes parts, ouvrez ses greniers, entassez tout comme des gerbes, et exterminez; qu''il n''en reste rien!'),
('jr',50,27,'crampon1923','Tuez tous les taureaux, qu''ils descendent à la boucherie! Malheur à eux car leur jour est arrivé, le temps où ils seront visités.'),
('jr',50,28,'crampon1923','Cris des fuyards et de ceux qui se sauvent du pays de Babel! ils annoncent en Sion la vengeance de Yahweh, notre Dieu, la vengeance de son temple.'),
('jr',50,29,'crampon1923','Appelez contre Babel des archers, tous ceux qui bandent l''arc; campez autour d''elle: que personne n''échappe! Rendez-lui selon ses œuvres, tout ce qu''elle a fait, faites-le lui; car elle s''est élevée contre Yahweh, contre le Saint d’Israël.'),
('jr',50,30,'crampon1923','C''est pourquoi ses jeunes gens tomberont sur ses places, et tous ses hommes de guerre périront en ce jour, — oracle de Yahweh.'),
('jr',50,31,'crampon1923','Me voici contre toi, insolente! — oracle du Seigneur Yahweh des armées; car ton jour est venu, le temps où je visite.'),
('jr',50,32,'crampon1923','Elle chancellera, l''insolente, elle tombera, et personne ne la relèvera; je mettrai le feu à ses villes, et il dévorera tous ses alentours.'),
('jr',50,33,'crampon1923','Ainsi parle Yahweh des armées: Les enfants d''Israël sont opprimés et avec eux les enfants de Juda; tous ceux qui les ont emmenés captifs les retiennent; et refusent de les lâcher.'),
('jr',50,34,'crampon1923','Mais leur vengeur est fort; Yahweh des armées est son nom; il défendra puissamment leur cause, pour donner le repos à la terre, et faire trembler les habitants de Babel.'),
('jr',50,35,'crampon1923','Epée contre les Chaldéens, — oracle de Yahweh, et contre les habitants de Babel, et contre ses chefs et contre ses sages!'),
('jr',50,36,'crampon1923','Epée contre les imposteurs, et qu''ils perdent le sens! Epée contre ses braves, et qu''ils tremblent!'),
('jr',50,37,'crampon1923','Epée contre ses chevaux et ses chars, et contre toute la tourbe des gens qui sont au milieu d''elle, et qu''ils soient comme des femmes! Epée contre ses trésors, et qu''ils soient pillés!'),
('jr',50,38,'crampon1923','Sécheresse sur ses eaux, et qu''elles tarissent! Car c''est un pays d''idoles, et devant ces épouvantails ils délirent.'),
('jr',50,39,'crampon1923','Aussi les animaux du désert s''y établiront avec les chacals; les autruches y feront leur demeure; elle ne sera jamais plus peuplée; elle ne sera plus habitée d''âge en âge.'),
('jr',50,40,'crampon1923','Comme lorsque Dieu détruisit Sodome, Gomorrhe et les villes voisines, — oracle de Yahweh, personne n''y demeurera, aucun fils d''homme n''y séjournera.'),
('jr',50,41,'crampon1923','Voici qu''un peuple arrive du Septentrion; une grande nation et des rois nombreux se lèvent des extrémités de la terre.'),
('jr',50,42,'crampon1923','Ils tiennent à la main l''arc et le javelot; ils sont cruels et sans pitié. Leur voix gronde comme la mer; ils sont montés sur des chevaux, rangés comme un seul homme pour la guerre, contre toi, fille de Babel.'),
('jr',50,43,'crampon1923','Le roi de Babel a appris la nouvelle, et ses mains ont défailli; l''angoisse l''a saisi, les douleurs d''une femme qui enfante.'),
('jr',50,44,'crampon1923','Pareil à un lion, voici qu’il monte des halliers du Jourdain au pâturage perpétuel; et soudain je les en ferai fuir, et j''y établirai celui que j''ai choisi. Car qui est semblable à moi? Qui me provoquerait, et quel est le berger qui me tiendrait tête?'),
('jr',50,45,'crampon1923','Ecoutez donc la résolution de Yahweh qu''il a prise contre Babel, et les desseins qu''il a médités contre le pays des Chaldéens: Oui, on les entraînera comme de faibles brebis; oui, le pâturage en sera dans la stupeur!'),
('jr',50,46,'crampon1923','Au bruit de la prise de Babel, la terre tremble, un cri se fait entendre chez les nations!'),
('jr',51,1,'crampon1923','Ainsi parle Yahweh: Voici que je vais soulever contre Babel, et contre les habitants de la Chaldée l''esprit d''un destructeur.'),
('jr',51,2,'crampon1923','Et j''enverrai à Babel des vanneurs qui la vanneront; et ils videront son pays, car ils fondront de toutes parts sur elle, au jour du malheur.'),
('jr',51,3,'crampon1923','Que l''archer tende son arc contre l''archer et contre celui qui se pavane dans sa cuirasse! N''épargnez pas ses jeunes gens, exterminez toute son armée.'),
('jr',51,4,'crampon1923','Que des blessés à mort tombent sur la terre des Chaldéens, et des transpercés dans les rues de Babel!'),
('jr',51,5,'crampon1923','Car Israël et Juda ne sont pas veuves de leur Dieu, de Yahweh des armées, et le pays des Chaldéens est rempli d''iniquités contre le Saint d''Israël.'),
('jr',51,6,'crampon1923','Fuyez du milieu de Babylone, et que chacun de vous sauve sa vie! Ne périssez pas pour son crime; car c''est le temps de la vengeance pour Yahweh; il va lui rendre ce qu''elle a mérité.'),
('jr',51,7,'crampon1923','Babel était une coupe d''or dans la main de Yahweh; elle enivrait toute la terre; les nations ont bu de son vin, c''est pourquoi les nations sont en délire.'),
('jr',51,8,'crampon1923','Soudain Babel est tombée, et s''est brisée; hurlez sur elle; prenez du baume pour sa plaie; peut-être guérira-t-elle!'),
('jr',51,9,'crampon1923','" Nous avons voulu guérir Babel, mais elle n''a pas guéri; laissez-la! allons chacun dans notre pays! Car son jugement atteint jusqu''aux cieux, et s''élève jusqu''aux nues. "'),
('jr',51,10,'crampon1923','Yahweh a manifesté la justice de notre cause; venez et racontons en Sion l''œuvre de Yahweh notre Dieu.'),
('jr',51,11,'crampon1923','Aiguisez les flèches, couvrez-vous de vos boucliers! Yahweh a excité l''esprit des rois de Médie; car son dessein sur Babel est de la détruire. Car c''est là la vengeance de Yahweh, la vengeance de son temple.'),
('jr',51,12,'crampon1923','Elevez l''étendard contre les murs de Babylone; renforcez le blocus, posez des sentinelles, dressez des embuscades! Car Yahweh a formé un dessein, il exécute ce qu''il a dit contre les habitants de Babel.'),
('jr',51,13,'crampon1923','Toi qui habites au bord des grandes eaux, riche en trésors, ta fin est venue, le terme de tes rapines!'),
('jr',51,14,'crampon1923','Yahweh des armées l''a juré par lui-même: Je te remplirai d''hommes, comme de sauterelles, et ils pousseront sur toi le cri du triomphe.'),
('jr',51,15,'crampon1923','Il a fait la terre par sa force, affermi le monde par sa sagesse, et par son intelligence il a étendu les cieux.'),
('jr',51,16,'crampon1923','A sa voix, les eaux s''amassent dans les cieux; il fait monter les nuages des extrémités de la terre; il fait briller les éclairs d''où jaillit l''averse, et tire le vent de ses réservoirs.'),
('jr',51,17,'crampon1923','Tout homme est stupide, hors de sens; tout artisan a honte de son idole, car ses idoles ne sont que mensonge; il n''y a point de souffle en elles.'),
('jr',51,18,'crampon1923','Elles sont une vanité, une œuvre de tromperie; au jour du châtiment, elles périront.'),
('jr',51,19,'crampon1923','Telle n''est point la part de Jacob; lui, il a formé l''univers; sa part d''héritage est celui qui se nomme Yahweh des armées.'),
('jr',51,20,'crampon1923','Tu me sers de marteau, d''arme de guerre: par toi je broie des peuples; par toi je détruis des royaumes;'),
('jr',51,21,'crampon1923','par toi je broie le cheval et son cavalier; par toi je broie le char et celui qui le monte;'),
('jr',51,22,'crampon1923','par toi je broie homme et femme; par toi je broie vieillard et enfant; par toi je broie jeune homme et jeune fille;'),
('jr',51,23,'crampon1923','par toi je broie le berger et son troupeau; par toi je broie le laboureur et son attelage; par toi je broie les gouverneurs et les chefs.'),
('jr',51,24,'crampon1923','Mais je rendrai à Babylone et à tous les habitants de la Chaldée tout le mal qu''ils ont fait dans Sion, sous vos yeux, — oracle de Yahweh.'),
('jr',51,25,'crampon1923','Me voici contre toi, montagne de destruction, — oracle de Yahweh qui détruis toute la terre; j''étends ma main sur toi, je te roule du haut des rochers et je fais de toi une montagne brûlée.'),
('jr',51,26,'crampon1923','On ne tirera de toi ni pierres d''angle, ni pierres pour les fondements, car tu seras à jamais une ruine, — oracle de Yahweh.'),
('jr',51,27,'crampon1923','Elevez un étendard sur la terre; sonnez de la trompette parmi les nations, consacrez les nations contre elle; appelez contre elle les royaumes d''Ararat, de Menni et d''Ascenez! Etablissez contre elle un chef d''armée; lancez les chevaux comme des sauterelles hérissées.'),
('jr',51,28,'crampon1923','Consacrez contre elle les nations, les rois de Médie, ses capitaines et ses chefs, et tout le pays sur lequel ils commandent.'),
('jr',51,29,'crampon1923','La terre tremble, elle s''agite; car le dessein de Yahweh s''accomplit contre Babel, pour changer le pays de Babel en un lieu de terreur, sans habitants.'),
('jr',51,30,'crampon1923','Les vaillants de Babel ont cessé de combattre; ils se tiennent dans les forteresses; leur vigueur est à bout, ils sont devenus comme des femmes. On a mis le feu à ses habitations, on a brisé les barres de ses portes.'),
('jr',51,31,'crampon1923','Les courriers courrent à la rencontre des courriers, les messagers à la rencontre des messagers, pour annonçer au roi de Babel que sa ville est prise de tous côtés.'),
('jr',51,32,'crampon1923','Les passages sont occupés, on brûle au feu les marais, et les hommes de guerre sont consternés!'),
('jr',51,33,'crampon1923','Car ainsi parle Yahweh des armées, Dieu d''Israël: La fille de Babel est comme une aire, au temps où on la foule; encore un peu, et viendra pour elle le temps de la moisson.'),
('jr',51,34,'crampon1923','Il m''a dévorée, il m''a consumée, Nabuchodonosor, roi de Babel; il m''a posée là comme un vase vide; tel qu''un dragon, il m''a engloutie; il a rempli son ventre de mes meilleurs mets: il m''a chassée.'),
('jr',51,35,'crampon1923','Que ma chair déchirée soit sur Babel! dira le peuple de Sion; et mon sang sur les habitants de la Chaldée! dira Jérusalem.'),
('jr',51,36,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je prends en main ta cause, et que j''exécute ta vengeance; je dessécherai sa mer et ferai tarir sa source.'),
('jr',51,37,'crampon1923','Et Babel sera un monceau de pierres, un repaire de chacals, un sujet de terreur et de moquerie, sans habitants.'),
('jr',51,38,'crampon1923','Ils rugissent tous ensemble comme des lions; ils grondent comme les petits des lionnes.'),
('jr',51,39,'crampon1923','Tandis qu''ils sont en fièvre, je leur verserai un breuvage, et je les enivrerai pour qu''ils se livrent à la joie; et ils s''endormiront d''un sommeil éternel et ils ne se réveilleront plus, — oracle de Yahweh.'),
('jr',51,40,'crampon1923','Je les ferai descendre comme des agneaux à la boucherie, comme des béliers et des boucs.'),
('jr',51,41,'crampon1923','Comment a été prise Sésac, a été conquise la gloire de toute la terre? Comment est-elle devenue un objet de terreur, Babel, parmi les nations?'),
('jr',51,42,'crampon1923','La mer est montée sur Babel, elle l''a couverte du bruit de ses flots.'),
('jr',51,43,'crampon1923','Ses villes sont devenues un objet de terreur, une terre désolée et déserte, une terre où personne ne demeure, où ne passe aucun fils d''homme.'),
('jr',51,44,'crampon1923','Je visiterai Bel à Babel; et je tirerai de sa bouche ce qu''il a englouti; et les nations n''afflueront plus vers lui. La muraille même de Babel est tombée:'),
('jr',51,45,'crampon1923','Sortez du milieu d''elle, ô mon peuple; et que chacun de vous sauve sa vie, devant l''ardente colère de Yahweh.'),
('jr',51,46,'crampon1923','Que votre cœur ne défaille point, ne vous effrayez pas des bruits qu''on entendra dans le pays! Car une année surviendra un bruit, et une année après un autre bruit: il y aura violence dans le pays, tyran contre tyran.'),
('jr',51,47,'crampon1923','C''est pourquoi voici que des jours viennent où je visiterai les idoles de Babel, et tout son pays sera confus, et tous ses tués tomberont au milieu d''elle.'),
('jr',51,48,'crampon1923','Le ciel et la terre et tout ce qu''ils renferment pousseront des cris de joie sur Babel; car du septentrion viendront sur elle les dévastateurs, — oracle de Yahweh.'),
('jr',51,49,'crampon1923','Babel doit tomber, ô tués d''Israël, comme pour Babel sont tombés les tués de toute la terre.'),
('jr',51,50,'crampon1923','Echappés du glaive, partez, ne vous arrêtez pas! De la terre lointaine souvenez-vous de Yahweh, et que Jérusalem soit présente à votre cœur!'),
('jr',51,51,'crampon1923','Nous étions confus, car nous avions appris l''outrage; la honte couvrait nos visages, car des étrangers étaient venus contre le sanctuaire de la maison de Yahweh.'),
('jr',51,52,'crampon1923','C''est pourquoi voici que des jours viennent, — oracle de Yahweh, où je visiterai ses idoles, et dans tout son pays gémiront ceux qu''on égorge.'),
('jr',51,53,'crampon1923','Quand Babel s''élèverait jusqu''aux cieux, quand elle rendrait inaccessible sa haute forteresse; par mon ordre lui viendraient des dévastateurs, — oracle de Yahweh.'),
('jr',51,54,'crampon1923','Une clameur retentit du côté de Babel: grand désastre au pays des Chaldéens!'),
('jr',51,55,'crampon1923','Car Yahweh dévaste Babel, et il fait cesser son grand bruit; leurs flots mugissent comme les grandes eaux; et font entendre leur fracas.'),
('jr',51,56,'crampon1923','Car il est venu contre elle, le dévastateur, — contre Babel; ses guerriers sont pris, leurs arcs sont brisés; car Yahweh est le Dieu des rétributions, il paiera sûrement!'),
('jr',51,57,'crampon1923','J''enivrerai ses princes et ses sages, ses gouverneurs, ses magistrats et ses guerriers, et ils s''endormiront d''un sommeil éternel, et ne se réveilleront plus, — oracle du Roi, dont le nom est Yahweh des armées.'),
('jr',51,58,'crampon1923','Ainsi parle Yahweh des armées: Les murailles de Babel, si larges, seront complètement rasées, et ses hautes portes seront brûlées. Ainsi les peuples travaillent pour le néant; et les nations au profit du feu, et ils s''y épuisent.'),
('jr',51,59,'crampon1923','L''ordre que donna Jérémie, le prophète, à Saraïas, fils de Nérias, fils de Maasias, lorsqu''il se rendit à Babylone avec Sédécias, roi de Juda, la quatrième année de son règne. Saraïas était grand chambellan.'),
('jr',51,60,'crampon1923','Jérémie écrivit dans un livre tous les malheurs qui devaient arriver à Babylone, toutes ces paroles écrites sur Babylone.'),
('jr',51,61,'crampon1923','Et Jérémie dit à Saraïas: " Quand tu seras arrivé à Babylone, tu auras soin de lire toutes ces paroles,'),
('jr',51,62,'crampon1923','et tu diras: " Yahweh, toi-même tu as dit au sujet de ce lieu qu''on le détruirait, de telle sorte qu''il n''y aurait plus d''habitant, ni homme, ni bête, mais qu''il serait une solitude pour toujours. "'),
('jr',51,63,'crampon1923','Et quand tu auras achevé de lire ce livre, tu y attacheras une pierre et tu le jetteras au milieu de l''Euphrate,'),
('jr',51,64,'crampon1923','et tu diras: Ainsi s''abîmera Babylone, et elle ne se relèvera pas du malheur que j''amènerai sur elle, et ils tomberont épuisés. " Jusqu''ici les paroles de Jérémie.'),
('jr',52,1,'crampon1923','Sédécias était âgé de vingt et un ans lorsqu''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''appelait Amital, fille de Jérémie, de Lobna.'),
('jr',52,2,'crampon1923','Il fit ce qui est mal aux yeux de Yahweh, imitant tout ce qu''avait fait Joakim.'),
('jr',52,3,'crampon1923','Cela arriva à Jérusalem et en Juda, à cause de la colère de Yahweh, jusqu''à ce qu''il les rejette de devant sa face. Et Sédécias se révolta contre le roi de Babylone.'),
('jr',52,4,'crampon1923','La neuvième année du règne de Sédécias, le dixième mois, le dixième jour du mois, Nabuchodonosor, roi de Babylone, vint avec toute son armée contre Jérusalem; ils campèrent devant elle et construisirent tout autour des murs d''approche.'),
('jr',52,5,'crampon1923','La ville fut assiégée jusqu''à la onzième année du roi Sédécias.'),
('jr',52,6,'crampon1923','Au quatrième mois, le neuvième jour du mois, comme la famine était grande dans la ville, et qu''il n''y avait plus de pain pour le peuple du pays,'),
('jr',52,7,'crampon1923','une brèche fut faite à la ville, et tous les gens de guerre s''enfuirent et sortirent de la ville pendant la nuit, par la porte entre les deux murs, près du jardin du roi, pendant que les Chaldéens environnaient la ville; et ils prirent le chemin de la plaine.'),
('jr',52,8,'crampon1923','Mais l''armée des chaldéens poursuivit le roi; ils atteignirent Sédécias dans les plaines de Jéricho, et toute son armée se dispersa loin de lui.'),
('jr',52,9,'crampon1923','Ayant saisi roi, ils le firent monter vers le roi de Babylone, à Rébla, dans le pays de d''Émath, et il prononça sur lui des sentences.'),
('jr',52,10,'crampon1923','Le roi de Babylone égorgea les fils de Sédécias sous les yeux de leur père; il égorgea aussi tous les chefs de Juda à Rébla.'),
('jr',52,11,'crampon1923','Puis il creva les yeux à Sédécias et le lia avec deux chaînes d''airain; et le roi de Babylone le mena à Babylone, et le tint en prison jusqu''au jour de sa mort.'),
('jr',52,12,'crampon1923','Le cinquième mois, le dixième jour du mois, — c''était la dix-neuvième année du règne de Nabuchodonosor, roi de Babylone, — Nabuzardan, capitaine des gardes, qui était ministre du roi de Babylone, vint à Jérusalem.'),
('jr',52,13,'crampon1923','Il brûla la maison de Yahweh, la maison du roi, et toutes les maisons de Jérusalem; il livra au feu toutes les grandes maisons.'),
('jr',52,14,'crampon1923','Toute l''armée des chaldéens qui était avec le capitaine des gardes démolit les murailles formant l''enceinte de Jérusalem.'),
('jr',52,15,'crampon1923','Nabuzardan, capitaine des gardes, emmena captifs une partie des plus pauvres du peuple, avec le reste du peuple qui était demeuré dans la ville, les transfuges qui s''étaient rendus au roi de Babylone, et le reste des artisans.'),
('jr',52,16,'crampon1923','Mais Nabuzardan, capitaine des gardes, laissa comme vignerons et comme laboureurs quelques-uns des pauvres du pays.'),
('jr',52,17,'crampon1923','Les Chaldéens brisèrent les colonnes d''airain qui appartenaient à la maison de Yahweh, ainsi que les bases et la mer d''airain qui étaient dans la maison de Yahweh, et ils en emportèrent l''airain à Babylone.'),
('jr',52,18,'crampon1923','Ils prirent les pots, les pelles, les couteaux, les tasses, les coupes et tous les ustensiles d''airain avec lesquels on faisait le service.'),
('jr',52,19,'crampon1923','Le capitaine des gardes prit encore les bassins, les encensoirs, les tasses, les pots, les chandeliers, les cuillers et les urnes, ce qui était d''or et ce qui était d''argent.'),
('jr',52,20,'crampon1923','Quant aux deux colonnes, à la mer et aux douze bœufs d''airain qui étaient dessous, et aux bases que le roi Salomon avait faites dans la maison de Yahweh, il n''y avait pas à peser l''airain de tous ces ustensiles.'),
('jr',52,21,'crampon1923','Quant aux colonnes, la hauteur d''une colonne était de dix-huit coudées, et un cordon de douze coudées en mesurait le tour; son épaisseur était de quatre doigts, et elle était creuse.'),
('jr',52,22,'crampon1923','Il y avait au-dessus un chapiteau d''airain, et la hauteur d''un chapiteau était de cinq coudées; et il y avait tout autour du chapiteaux un treillis et des grenades, le tout d''airain. Il en était de même de la seconde colonne; avec les grenades.'),
('jr',52,23,'crampon1923','Il y avait quatre-vingt-seize grenades sur les faces, et toutes les grenades étaient au nombre de cent sur le treillis, tout autour.'),
('jr',52,24,'crampon1923','Le capitaine des gardes prit Saraïas, le grand-prêtre, Sophonie, prêtre de second ordre, et les trois gardiens de la porte.'),
('jr',52,25,'crampon1923','De la ville il prit un officier qui commandait aux gens de guerre, sept hommes faisant partie du conseil privé du roi et qui furent trouvés dans la ville, le secrétaire du chef de l''armée chargé d''enrôler le peuple du pays, et soixante hommes du peuple du pays qui se trouvaient dans la ville.'),
('jr',52,26,'crampon1923','Les ayant pris, Nabuzardan, capitaine des gardes, les conduisit vers le roi de Babylone à Rébla.'),
('jr',52,27,'crampon1923','Et le roi de Babylone les frappa et les fit mourir à Rébla, dans le pays de d''Emath. Ainsi Juda fut emmené captif loin de sa patrie.'),
('jr',52,28,'crampon1923','Voici le nombre des hommes que Nabuchodonosor emmena captifs: la septième année, trois mille vingt-trois hommes de Juda;'),
('jr',52,29,'crampon1923','la dix-huitième année de Nabuchodonosor, huit cent trente-deux personnes de la population de Jérusalem;'),
('jr',52,30,'crampon1923','la vingt-troisième année de Nabuchodonosor, Nabuzardan, capitaine des gardes, emmena encore captifs sept cent quarante-cinq hommes de Juda; en tout quatre mille six cents personnes.'),
('jr',52,31,'crampon1923','La trente-septième année de la captivité de Joachin, roi de Juda, le douzième mois, le vingt-cinquième jour du mois, Evil-Mérodach, roi de Babylone, en l''année de son avènement, releva la tête de Joachin, roi de Juda, et le fit sortir de prison.'),
('jr',52,32,'crampon1923','Il lui parla avec bonté et mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone.'),
('jr',52,33,'crampon1923','Il lui fit changer ses vêtements de prison, et Joachin mangea en sa présence, toujours, tous les jours de sa vie.'),
('jr',52,34,'crampon1923','Quant à son entretien, son entretien perpétuel, le roi de Babylone y pourvut chaque jour, jusqu''au jour de sa mort, tous les jours de sa vie.'),
('lm',1,1,'crampon1923','Comment est-elle assise solitaire, la cité populeuse! Elle est devenue comme une veuve, celle qui était grande parmi les nations. Celle qui était reine parmi les provinces a été soumise au tribut. BETH.'),
('lm',1,2,'crampon1923','Elle pleure amèrement durant la nuit, et les larmes couvrent ses joues; pas un ne la console, de tous ses amants; tous ses compagnons l''ont trahie, ils sont devenus ses ennemis. GHIMEL.'),
('lm',1,3,'crampon1923','Juda s''en est allé en exil, misérable et condamné à un rude travail; il habite chez les nations, sans trouver le repos; ses persécuteurs l’ont atteint dans d''étroits défilés. DALETH.'),
('lm',1,4,'crampon1923','Les chemins de Sion sont dans le deuil, parce que nul ne vient plus à ses fêtes; Toutes ses portes sont en ruines, ses prêtres gémissent, ses vierges se désolent, et elle-même est dans l''amertume. HÉ.'),
('lm',1,5,'crampon1923','Ses oppresseurs ont le dessus, ses ennemis prospèrent; car Yahweh l''a affligée, à cause de la multitude de ses offenses; ses petits enfants s''en sont allés captifs, devant l''oppresseur. VAV.'),
('lm',1,6,'crampon1923','Et la fille de Sion a perdu toute sa gloire; ses princes sont comme des cerfs qui ne trouvent pas de pâture, et qui s''en vont sans force devant celui qui les poursuit. ZAÏN.'),
('lm',1,7,'crampon1923','Jérusalem se souvient, aux jours de son affliction et de sa vie errante, de tous ses biens précieux qu''elle possédait, dès les jours anciens. Maintenant que son peuple est tombé sous la main de l''oppresseur, et que personne ne vient a son aide, ses ennemis la voient, et ils rient de son chômage. HETH.'),
('lm',1,8,'crampon1923','Jérusalem a multiplié ses péchés; c''est pourquoi elle est devenue une chose souillée; tous ceux qui l''honoraient la méprisent, car ils ont vu sa nudité; elle-même pousse des gémissements, et détourne la face. TETH.'),
('lm',1,9,'crampon1923','Sa souillure apparaît sous les pans de sa robe; elle ne songeait pas à sa fin. Et elle est tombée d''une manière étrange, et personne ne la console! " Vois, Yahweh, ma misère, car l''ennemi triomphe! " JOD.'),
('lm',1,10,'crampon1923','L''oppresseur a étendu la main sur tous ses trésors; car elle a vu les nations entrer dans son sanctuaire, les nations au sujet desquelles tu avais donné cet ordre: " Elles n''entreront pas dans ton assemblée. " CAPH.'),
('lm',1,11,'crampon1923','Tout son peuple gémit, cherchant du pain; ils donnent leurs joyaux pour des aliments, qui leur rendent la vie. " Vois Yahweh et considère l''abjection où je suis tombée! " LAMED.'),
('lm',1,12,'crampon1923','" O vous tous, qui passez par le chemin, regardez et voyez s''il y a une douleur pareille à la douleur qui pèse sur moi, moi que Yahweh a frappée, au jour de son ardente colère! MEM.'),
('lm',1,13,'crampon1923','" D''en haut il a lancé dans mes os un feu qui les dévore; il a étendu un filet devant mes pieds, il m''a fait reculer; il m''a jeté dans la désolation, je languis tout le jour. NUN.'),
('lm',1,14,'crampon1923','" Le joug de mes iniquités a été lié dans sa main; unies en faisceau, elles pèsent sur mon cou; il a fait chanceler ma force. Le Seigneur m’a livré à des mains auxquelles je ne puis résister. SAMECH.'),
('lm',1,15,'crampon1923','" Le Seigneur a enlevé tous les guerriers qui étaient au milieu de moi; il a appelé contre moi une armée, pour écraser mes jeunes hommes; le Seigneur a foulé au pressoir la vierge, fille de Juda. AÏN.'),
('lm',1,16,'crampon1923','" C''est pour cela que je pleure, que mon œil, mon œil se fond en larmes; car il n''y a près de moi personne qui me console, qui me rende la vie; mes fils sont dans la désolation, car l''ennemi l''emporte. " PHÉ.'),
('lm',1,17,'crampon1923','Sion a tendu les mains... Personne qui la console! Yahweh a mandé contre Jacob ses ennemis qui l''enveloppent; Jérusalem est devenue au milieu d''eux comme une chose souillée. TSADÉ.'),
('lm',1,18,'crampon1923','" Yahweh est vraiment juste, car j''ai été rebelle à ses ordres. Oh! écoutez tous, peuples, et voyez ma douleur: mes vierges et mes jeunes gens sont allés en exil! QOPH.'),
('lm',1,19,'crampon1923','J''ai appelé mes amants, ils m''ont trompée; mes prêtres et mes anciens ont péri dans la ville, en cherchant de la nourriture, pour ranimer leur vie. RESCH.'),
('lm',1,20,'crampon1923','" Regarde, Yahweh, quelle est mon angoisse! Mes entrailles sont émues; mon cœur est bouleversé au dedans de moi, parce que j''ai été bien rebelle. Au dehors l''épée tue mes enfants; au dedans, c''est la mort! SIN.'),
('lm',1,21,'crampon1923','" On entend mes gémissements; personne qui me console! Tous mes ennemis, en apprenant mon malheur, se réjouissent de ce que tu as agi. Tu feras venir le jour que tu as annoncé, et ils deviendront tels que moi! THAV.'),
('lm',1,22,'crampon1923','" Que toute leur méchanceté soit présente devant toi, pour que tu les traites comme tu m''as traitée moi-même, à cause de toutes mes offenses! Car mes gémissements sont nombreux, et mon cœur est malade! "'),
('lm',2,1,'crampon1923','Comment le Seigneur, dans sa colère, a-t-il couvert d''un nuage la fille de Sion? Il a précipité du ciel sur la terre la magnificence d''Israël; il ne s''est plus souvenu de l''escabeau de ses pieds, au jour de sa colère. BETH.'),
('lm',2,2,'crampon1923','Le Seigneur a détruit sans pitié toutes les demeures de Jacob; il a renversé dans sa fureur les forteresses de la fille de Juda; il les a jetées par terre; il a profané la royauté et ses princes. GHIMEL.'),
('lm',2,3,'crampon1923','Dans l''ardeur de sa colère, il a brisé toute force d''Israël; il a ramené sa droite en arrière, devant l''ennemi; il a allumé dans Jacob comme un feu ardent qui dévore de tous côtés. DALETH.'),
('lm',2,4,'crampon1923','Il a bandé son arc comme fait un ennemi; sa droite s''est levée comme celle d''un assaillant; et il a égorgé tout ce qui charmait les yeux; dans la tente de la fille de Sion, il a versé son courroux comme un feu. HÉ.'),
('lm',2,5,'crampon1923','Le Seigneur a été comme un ennemi, il a détruit Israël; il a détruit tous ses palais, abattu ses citadelles; il a amoncelé sur la fille de Sion douleur sur douleur. VAV.'),
('lm',2,6,'crampon1923','Il a forcé son enclos, comme un jardin; il a détruit son sanctuaire. Yahweh a fait cesser dans Sion solennités et sabbats; dans l''ardeur de sa colère, il a rejeté avec dédain roi et prêtre. ZAÏN.'),
('lm',2,7,'crampon1923','Le Seigneur a pris en dégoût son autel, en abomination son sanctuaire; il a livré aux mains de l''ennemi les murs de ses citadelles; on a poussé des cris dans la maison de Yahweh, comme en un jour de fête. HETH.'),
('lm',2,8,'crampon1923','Yahweh a médité de renverser les murs de la fille de Sion; il a étendu le cordeau, il n''a pas retiré sa main qu''il ne les eût détruits; il a mis en deuil le mur et l''avant-mur; ils gisent tristement ensemble. TETH.'),
('lm',2,9,'crampon1923','Ses portes sont enfoncées en terre, il en a rompu, brisé les barres; son roi et ses princes sont parmi les nations, il n’y a plus de loi; même ses prophètes ne reçoivent plus de vision de Yahweh. JOD.'),
('lm',2,10,'crampon1923','Ils sont assis par terre, en silence, les anciens de la fille de Sion; ils ont jeté de la poussière sur leur tête, ils sont vêtus de sacs; elles inclinent leur tête vers la terre, les vierges de Jérusalem. CAPH.'),
('lm',2,11,'crampon1923','Mes yeux se consument dans les larmes, mes entrailles sont émues; mon foie se répand sur la terre, à cause de la blessure de la fille de mon peuple, lorsque enfants et nourrissons tombent en défaillance, sur les places de la ville. LAMED.'),
('lm',2,12,'crampon1923','Ils disent à leurs mères: " Où y a-t-il du pain et du vin? " et ils tombent comme frappés du glaive, sur les places de la ville; et leur âme expire sur le sein de leurs mères. MEM.'),
('lm',2,13,'crampon1923','Que puis-je te dire? Qui trouver de semblable à toi, fille de Jérusalem? A qui te comparer pour te consoler, vierge, fille de Sion? Car ta plaie est grande comme la mer: qui te guérirait? NUN.'),
('lm',2,14,'crampon1923','Tes prophètes ont eu pour toi de vaines et folles visions; ils ne t''ont pas dévoilé ton iniquité, afin de détourner de toi l''exil; mais ils t''ont donné pour visions des oracles de mensonge et de séduction. SAMECH.'),
('lm',2,15,'crampon1923','Ils battent des mains à ton sujet, tous ceux qui passent sur le chemin; ils sifflent, ils branlent la tête sur la fille de Jérusalem; " Est-ce là cette ville qu''on appelait la parfaite en beauté la joie de toute la terre? " PHÉ.'),
('lm',2,16,'crampon1923','Ils ouvrent la bouche contre toi, tous tes ennemis; ils sifflent, ils grincent des dents, ils disent: " Nous l''avons engloutie! C''est là le jour que nous attendions, nous y sommes arrivés, nous le voyons! " AÏN.'),
('lm',2,17,'crampon1923','Yahweh a exécuté ce qu''il avait résolu; il a accompli sa parole, qu''il avait prononcée dès les jours anciens; il a détruit sans pitié; il a réjoui l''ennemi à ton sujet, il a élevé la corne de tes oppresseurs. TSADÉ.'),
('lm',2,18,'crampon1923','Leur cœur crie vers le Seigneur! O muraille de la fille de Sion, laisse couler, comme un torrent, tes larmes, le jour et la nuit; ne te donne aucune relâche, que ta prunelle n''ait point de repos! QOPH.'),
('lm',2,19,'crampon1923','Lève-toi, pousse des cris pendant la nuit, au commencement des veilles; épanche ton cœur comme de l''eau, devant la face du Seigneur! Lève tes mains vers lui pour la vie de tes petits enfants, qui tombent en défaillance à cause de la faim, aux coins de toutes les rues! RESCH.'),
('lm',2,20,'crampon1923','" Vois, Yahweh et considère: qui as-tu jamais traité ainsi? Quoi! des femmes mangent le fruit de leurs entrailles, les petits enfants qu''elles chérissent? SIN. Quoi! Ils sont égorgés dans le sanctuaire du Seigneur, le prêtre et le prophète!'),
('lm',2,21,'crampon1923','" Ils sont couchés par terre dans les rues, l''enfant et le vieillard; mes vierges et mes jeunes hommes sont tombés par l''épée; tu as égorgé au jour de ta colère, tu as immolé sans pitié. THAV.'),
('lm',2,22,'crampon1923','" Tu as convoqué, comme à un jour de fête, mes terreurs de toutes parts; au jour de la colère de Yahweh, il n''y a eu ni échappé ni fugitif: ceux que j''avais chéris et élevés, mon ennemi les a exterminés! "'),
('lm',3,1,'crampon1923','Je suis l''homme qui a vu l''affliction sous la verge de sa fureur.'),
('lm',3,2,'crampon1923','Il m''a conduit et m''a fait marcher dans les ténèbres et non dans la lumière;'),
('lm',3,3,'crampon1923','contre moi seul il tourne et retourne sa main tout le jour. BETH.'),
('lm',3,4,'crampon1923','Il a usé ma chair et ma peau, il a brisé mes os;'),
('lm',3,5,'crampon1923','Il a bâti contre moi, il m''a environné d''amertume et d''ennui.'),
('lm',3,6,'crampon1923','Il m''a fait habiter dans les ténèbres, comme ceux qui sont morts depuis longtemps. GHIMEL.'),
('lm',3,7,'crampon1923','Il m’a entouré d’un mur pour que je ne puisse sortir, il a rendu lourdes mes chaînes.'),
('lm',3,8,'crampon1923','Lors même que je crie et que j''implore, il ferme tout accès à ma prière.'),
('lm',3,9,'crampon1923','Il a muré mes chemins avec des pierres de taille, il a bouleversé mes sentiers. DALETH.'),
('lm',3,10,'crampon1923','Il a été pour moi comme un ours aux aguets, comme un lion dans les embuscades;'),
('lm',3,11,'crampon1923','il a détourné mes voies et m''a mis en pièces, il m''a réduit à l''abandon;'),
('lm',3,12,'crampon1923','il a bandé son arc et m''a placé comme but à ses flèches. HÉ.'),
('lm',3,13,'crampon1923','Il a fait pénétrer dans mes reins les fils de son carquois;'),
('lm',3,14,'crampon1923','je suis la risée de tout mon peuple, leur chanson tout le jour;'),
('lm',3,15,'crampon1923','il m''a rassasié d''amertume, il m''a abreuvé d''absinthe. VAV.'),
('lm',3,16,'crampon1923','Et il a fait broyer du gravier à mes dents, il m''a enfoncé dans la cendre;'),
('lm',3,17,'crampon1923','et mon âme est violemment écartée de la sécurité; j''ai oublié le bonheur;'),
('lm',3,18,'crampon1923','et j''ai dit: " Ma force est perdue, ainsi que mon espérance en Yahweh! " ZAÏN.'),
('lm',3,19,'crampon1923','Souviens-toi de mon affliction et de ma souffrance, de l''absinthe et de l''amertume!'),
('lm',3,20,'crampon1923','Mon âme s''en souvient sans cesse, et elle est abattue en moi.'),
('lm',3,21,'crampon1923','Voici ce que je me rappelerai en mon cœur, et ce pourquoi j''espérerai: HETH.'),
('lm',3,22,'crampon1923','C''est une grâce de Yahweh que nous ne soyons pas anéantis, car ses miséricordes ne sont pas épuisées!'),
('lm',3,23,'crampon1923','Elles se renouvellent chaque matin; grande est ta fidélité!'),
('lm',3,24,'crampon1923','" Yahweh est mon partage, a dit mon âme; c''est pourquoi j''espérerai en lui. " TETH.'),
('lm',3,25,'crampon1923','Yahweh est bon pour qui espère en lui, pour l''âme qui le cherche.'),
('lm',3,26,'crampon1923','Il est bon d''attendre en silence la délivrance de Yahweh.'),
('lm',3,27,'crampon1923','Il est bon à l''homme de porter le joug dès sa jeunesse. JOD.'),
('lm',3,28,'crampon1923','Qu''il s''asseye à l''écart, en silence, si Dieu le lui impose!')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('lm',3,29,'crampon1923','Qu''il mette sa bouche dans la poussière: peut-être y a-t-il de l''espérance!'),
('lm',3,30,'crampon1923','Qu''il tende la joue à celui qui le frappe; qu''il se rassasie d''opprobre! CAPH.'),
('lm',3,31,'crampon1923','Car le Seigneur ne rejette pas à toujours;'),
('lm',3,32,'crampon1923','mais, s''il afflige, il a compassion, selon sa grande miséricorde;'),
('lm',3,33,'crampon1923','car ce n''est pas de bon cœur qu''il humilie, et qu''il afflige les enfants des hommes. LAMED.'),
('lm',3,34,'crampon1923','Quand on foule aux pieds tous les captifs du pays,'),
('lm',3,35,'crampon1923','quand on fait fléchir le droit d''un homme, à la face du Très-Haut,'),
('lm',3,36,'crampon1923','quand on fait tort à quelqu''un dans sa cause, le Seigneur ne le verrait donc pas! MEM.'),
('lm',3,37,'crampon1923','Qui a parlé, et la chose s''est faite, sans que le Seigneur l''ait commandé?'),
('lm',3,38,'crampon1923','N''est-ce pas de la bouche du Très-Haut que procèdent les maux et les biens?'),
('lm',3,39,'crampon1923','Pourquoi l''homme se plaindrait-il tant qu''il vit? Que chacun se plaigne de ses péchés! NUN.'),
('lm',3,40,'crampon1923','Examinons nos voies et scrutons-les, et retournons à Yahweh.'),
('lm',3,41,'crampon1923','Elevons nos cœurs, avec nos mains, vers Dieu dans les cieux:'),
('lm',3,42,'crampon1923','" Nous, nous avons péché, nous avons été rebelles; toi, tu n''as pas pardonné. " SAMECH.'),
('lm',3,43,'crampon1923','" Tu t''es enveloppé dans ta colère, et tu nous as poursuivis; tu as tué sans épargner;'),
('lm',3,44,'crampon1923','Tu t''es couvert d''une nuée, afin que la prière ne passe point;'),
('lm',3,45,'crampon1923','tu as fait de nous des balayures et un rebut, au milieu des peuples. " PHÉ.'),
('lm',3,46,'crampon1923','Ils ouvrent la bouche contre nous, tous nos ennemis.'),
('lm',3,47,'crampon1923','La frayeur et la fosse ont été notre part, ainsi que la dévastation et la ruine.'),
('lm',3,48,'crampon1923','Mon œil se fond en un ruisseau de larmes, à cause de la ruine de la fille de mon peuple. AÏN.'),
('lm',3,49,'crampon1923','Mon œil pleure et ne cesse point, parce qu''il n''y a pas de répit,'),
('lm',3,50,'crampon1923','jusqu''à ce qu''il regarde et voie, Yahweh, du haut des cieux.'),
('lm',3,51,'crampon1923','Mon œil fait mal à mon âme, à cause de toutes les filles de ma ville. TSADÉ.'),
('lm',3,52,'crampon1923','Ils m’ont donné la chasse comme a un passereau, ceux qui me haïssent sans cause.'),
('lm',3,53,'crampon1923','Ils ont voulu anéantir ma vie dans la fosse, et ils ont jeté une pierre sur moi.'),
('lm',3,54,'crampon1923','Les eaux montaient au-dessus de ma tête; je disais: " Je suis perdu! " QOPH.'),
('lm',3,55,'crampon1923','J''ai invoqué ton nom, Yahweh, de la fosse profonde;'),
('lm',3,56,'crampon1923','tu as entendu ma voix: " Ne ferme point ton oreille à mes soupirs, à mes cris! "'),
('lm',3,57,'crampon1923','Tu t''es approché, au jour où je t''ai invoqué, et tu as dit: " Ne crains point! " RESCH.'),
('lm',3,58,'crampon1923','Seigneur tu as pris en main ma cause, tu m''as sauvé la vie.'),
('lm',3,59,'crampon1923','Tu as vu, Yahweh, la violence qu''ils me font; fais-moi justice!'),
('lm',3,60,'crampon1923','Tu as vu toute leur rancune, tous leurs complots contre moi. SIN.'),
('lm',3,61,'crampon1923','Tu as entendu leurs outrages, Yahweh, tous leurs complots contre moi,'),
('lm',3,62,'crampon1923','les propos de mes adversaires et ce qu''ils méditent, contre moi tout le jour.'),
('lm',3,63,'crampon1923','Quand ils s''asseyent ou qu''ils se lèvent, regarde: je suis l''objet de leurs chansons. THAV.'),
('lm',3,64,'crampon1923','Tu leur rendras, Yahweh, ce qu''ils méritent, selon l''œuvre de leurs mains;'),
('lm',3,65,'crampon1923','Tu leur donneras l''aveuglement du cœur; ta malédiction sera pour eux.'),
('lm',3,66,'crampon1923','Tu les poursuivras avec colère et tu les extermineras, de dessous les cieux de Yahweh!'),
('lm',4,1,'crampon1923','Comment l''or s''est-il terni, l’or pur s''est-il altéré, les pierres sacrées ont-elles été dispersées au coin de toutes les rues? BETH.'),
('lm',4,2,'crampon1923','Les plus nobles fils de Sion, estimés au poids de l''or fin, comment ont-ils été comptés pour des vases de terre, ouvrage des mains d''un potier? GHIMEL.'),
('lm',4,3,'crampon1923','Même les chacals présentent les mamelles, et allaitent leurs petits; la fille de mon peuple est devenue cruelle, comme les autruches dans le désert. DALETH.'),
('lm',4,4,'crampon1923','La langue du nourrisson s''attache à son palais, à cause de la soif; les petits enfants demandent du pain, et personne ne leur en donne. HÉ.'),
('lm',4,5,'crampon1923','Ceux qui se nourrissaient de mets délicats tombent d''inanition dans les rues; ceux qu''on portait sur la pourpre embrassent le fumier. VAV.'),
('lm',4,6,'crampon1923','Et l''iniquité de la fille de mon peuple a été plus grande que le péché de Sodome, qui fut renversée en un instant, sans que des mains se levassent contre elle. ZAÏN.'),
('lm',4,7,'crampon1923','Ses princes surpassaient la neige en éclat, le lait en blancheur; leur corps était plus vermeil que le corail, leur figure était un saphir. HETH.'),
('lm',4,8,'crampon1923','Leur aspect est plus sombre que le noir même; on ne les reconnaît plus dans les rues; leur peau est collée à leurs os, elle est sèche comme du bois. TETH.'),
('lm',4,9,'crampon1923','Plus heureuses sont les victimes de l''épée que les victimes de la faim, qui s''épuisent lentement, blessées, faute des produits des champs! JOD.'),
('lm',4,10,'crampon1923','Des femmes compatissantes ont de leurs mains fait cuire leurs enfants; ils leur ont servi de nourriture, dans le désastre de la fille de mon peuple. CAPH.'),
('lm',4,11,'crampon1923','Yahweh a épuisé sa fureur; il a répandu l''ardeur de sa colère, et a allumé dans Sion un feu qui en a dévoré les fondements. LAMED.'),
('lm',4,12,'crampon1923','Ils ne croyaient pas, les rois de la terre, ni tous les habitants du monde, que l''adversaire, l''ennemi entrerait dans les portes de Jérusalem. MEM.'),
('lm',4,13,'crampon1923','C''est à cause des péchés de ses prophètes, des iniquités de ses prêtres, qui répandaient dans son enceinte le sang des justes. NUN.'),
('lm',4,14,'crampon1923','Ils erraient comme des aveugles dans les rues, souillés de sang, de sorte qu''on ne pouvait toucher leurs vêtements. SAMECH.'),
('lm',4,15,'crampon1923','" Ecartez-vous! Un impur! " leur criait-on. "Ecartez-vous! Ecartez-vous! Ne le touchez pas! " Ils erraient, et l''on disait parmi les nations: " Qu''ils ne séjournent point ici! " PHÉ.'),
('lm',4,16,'crampon1923','La face irritée de Yahweh les a dispersés; il ne les regarde plus. L''ennemi n''a eu ni respect pour les prêtres, ni pitié pour les vieillards. AÏN.'),
('lm',4,17,'crampon1923','Et nous, nos yeux se consumaient encore à attendre un vain secours; du haut de nos tours, nous regardions vers une nation qui ne peut sauver. TSADÉ.'),
('lm',4,18,'crampon1923','Ils épiaient nos pas, nous empêchant de marcher dans nos places. Notre fin approche, nos jours sont accomplis; oui, notre fin est arrivée! QOPH.'),
('lm',4,19,'crampon1923','Ceux qui nous poursuivaient ont été plus légers que les aigles du ciel; ils nous ont pourchassés sur les montagnes; ils nous ont dressé des embûches dans le désert. RESCH.'),
('lm',4,20,'crampon1923','Le souffle de nos narines, l''oint de Yahweh, a été pris dans leurs fosses, lui dont nous disions: " A son ombre nous vivrons parmi les nations. " SIN.'),
('lm',4,21,'crampon1923','Réjouis-toi et sois dans l''allégresse, fille d''Edom, qui habite au pays de Hus! A toi aussi passera la coupe; tu t''enivreras et tu te mettras à nu. THAV.'),
('lm',4,22,'crampon1923','Ton iniquité a pris fin, fille de Sion, il ne t''enverra plus en exil. Il visite ton iniquité, fille d''Edom; il met à découvert tes péchés.'),
('lm',5,1,'crampon1923','Souviens-toi, Yahweh, de ce qui nous est arrivé, regarde et vois notre opprobre.'),
('lm',5,2,'crampon1923','Notre héritage a passé à des étrangers, nos maisons à des inconnus.'),
('lm',5,3,'crampon1923','Nous sommes orphelins, sans père; nos mères sont comme des veuves.'),
('lm',5,4,'crampon1923','Nous buvons notre eau à prix d''argent, le bois ne nous vient que pour un salaire.'),
('lm',5,5,'crampon1923','Nos persécuteurs nous pressent par derrière; nous sommes épuisés; plus de repos pour nous.'),
('lm',5,6,'crampon1923','Nous tendons la main vers l''Egypte, et vers l''Assyrie, pour nous rassasier de pain.'),
('lm',5,7,'crampon1923','Nos pères ont péché, ils ne sont plus; et nous, nous portons leurs iniquités!'),
('lm',5,8,'crampon1923','Des esclaves dominent sur nous; personne ne nous délivre de leurs mains.'),
('lm',5,9,'crampon1923','Nous acquérons notre pain au péril de notre vie; devant l''épée du désert.'),
('lm',5,10,'crampon1923','Notre peau est brûlante comme un four, par suite des ardeurs de la faim.'),
('lm',5,11,'crampon1923','Ils ont déshonoré les femmes dans Sion, les vierges dans les villes de Juda.'),
('lm',5,12,'crampon1923','Des chefs ont été pendus par leurs mains; la face des vieillards n''a pas été respectée.'),
('lm',5,13,'crampon1923','Des adolescents ont porté la meule; des enfants ont chancelé, chargés de bois.'),
('lm',5,14,'crampon1923','Les vieillards ont cessé d''aller à la porte; les jeunes gens, de jouer de leur lyre.'),
('lm',5,15,'crampon1923','La joie de nos cœurs a cessé, nos danses sont changées en deuil.'),
('lm',5,16,'crampon1923','La couronne de notre tête est tombée; oui, malheur à nous, car nous avons péché!'),
('lm',5,17,'crampon1923','Voici pourquoi notre cœur est malade, pourquoi nos yeux sont obscurcis:'),
('lm',5,18,'crampon1923','c''est parce que la montagne de Sion est désolée, et que les chacals s''y promènent.'),
('lm',5,19,'crampon1923','Toi, Yahweh, tu sièges éternellement; ton trône subsiste d''âge en âge!'),
('lm',5,20,'crampon1923','Pourquoi nous oublierais-tu à jamais, nous abandonnerais-tu pour de si longs jours?'),
('lm',5,21,'crampon1923','Fais-nous revenir à toi, Yahweh, et nous reviendrons; renouvelle nos jours comme autrefois.'),
('lm',5,22,'crampon1923','Car nous aurais-tu entièrement rejetés, serais-tu irrité contre nous sans mesure?'),
('ba',1,1,'crampon1923','Voici les paroles du livre qu''écrivit Baruch, fils de Nérias, fils de Maasias, fils de Sédécias, fils de Sédéï, fils de Helcias, à Babylone,'),
('ba',1,2,'crampon1923','la cinquième année, le septième jour du mois, au temps où les Chaldéens avaient pris Jérusalem et l''avaient brûlée.'),
('ba',1,3,'crampon1923','Baruch lut les paroles de ce livre aux oreilles de Jéchonias, fils de Joakim, roi de Juda, et aux oreilles de tout le peuple qui était venu pour entendre ce livre,'),
('ba',1,4,'crampon1923','aux oreilles des grands et des fils des rois, et aux oreilles des anciens, et aux oreilles de tout le peuple, du plus petit jusqu''au plus grand, de tous ceux qui habitent à Babylone, près du fleuve Sodi.'),
('ba',1,5,'crampon1923','En l''entendant, ils pleuraient, jeûnaient et priaient le Seigneur.'),
('ba',1,6,'crampon1923','Et ils recueillirent de l''argent, selon que chacun put en donner suivant ses moyens.'),
('ba',1,7,'crampon1923','Et ils l''envoyèrent à Jérusalem, à Joakim, fils de Helcias, fils de Salom, le prêtre, aux autres prêtres et à tout le peuple qui se trouvait avec lui à Jérusalem.'),
('ba',1,8,'crampon1923','Baruch avait alors recouvré les ustensiles de la maison du Seigneur qui avaient été emportés du Temple, pour les renvoyer au pays de Juda, le dixième jour du mois de Sivan, ustensiles en argent qu''avait fait faire Sédécias, fils de Josias, roi de Juda,'),
('ba',1,9,'crampon1923','après que Nabuchodonosor, roi de Babylone, eut enlevé de Jérusalem Jéchonias, les princes, les otages, les grands et le peuple du pays, et les eut emmenés à Babylone.'),
('ba',1,10,'crampon1923','Ils dirent: " Voici que nous vous envoyons de l''argent; achetez avec cet argent des victimes pour les holocaustes et les sacrifices d''expiation, et de l''encens; faites aussi des oblations, et offrez-les sur l''autel du Seigneur, notre Dieu.'),
('ba',1,11,'crampon1923','Priez pour la vie de Nabuchodonosor, roi de Babylone, et pour la vie de Baltassar, son fils, afin que leurs jours sur la terre soient comme les jours du ciel;'),
('ba',1,12,'crampon1923','et le Seigneur nous donnera la force; il fera briller la lumière à nos yeux; nous vivrons à l''ombre de Nabuchodonosor, roi de Babylone, et à l''ombre de Baltassar, son fils; nous les servirons de longs jours et nous trouverons grâce devant eux.'),
('ba',1,13,'crampon1923','Priez aussi pour nous le Seigneur notre Dieu, parce que nous avons péché contre le Seigneur notre Dieu, et que la colère du Seigneur et son courroux ne se sont pas détournés de nous jusqu''à ce jour.'),
('ba',1,14,'crampon1923','Lisez ce livre que nous vous envoyons pour qu''on en fasse la lecture publique dans la maison du Seigneur, les jours de fête et les jours d''assemblée.'),
('ba',1,15,'crampon1923','Et vous direz: Au Seigneur notre Dieu appartient la justice, à nous la confusion du visage, comme on le voit aujourd''hui, pour les hommes de Juda, et les habitants de Jérusalem,'),
('ba',1,16,'crampon1923','pour nos rois et nos princes, pour nos prêtres et nos prophètes, et pour nos pères.'),
('ba',1,17,'crampon1923','Nous avons péché devant le Seigneur'),
('ba',1,18,'crampon1923','et nous lui avons désobéi. Nous n''avons pas écouté la voix du Seigneur notre Dieu, en suivant les commandements du Seigneur, qu''il a donnés devant nous.'),
('ba',1,19,'crampon1923','Depuis le jour où le Seigneur a tiré nos pères du pays d''Egypte jusqu''aujourd''hui, nous avons été indociles envers le Seigneur notre Dieu, et, dans notre folie nous nous sommes détournés, pour ne pas entendre sa voix.'),
('ba',1,20,'crampon1923','Aussi, comme on le voit en ce jour, de grands malheurs se sont attaches à nous, ainsi que la malédiction que le Seigneur a prononcée, par l''intermédiaire de Moïse, son serviteur, qui a fait sortir nos pères du pays d''Egypte, pour nous donner un pays où coulent le lait et le miel.'),
('ba',1,21,'crampon1923','Nous n''avons pas écouté la voix du Seigneur notre Dieu, selon toutes les paroles des prophètes qu''il a envoyés vers nous.'),
('ba',1,22,'crampon1923','Et nous sommes allés, chacun selon l''inclination de son cœur méchant, servir des dieux étrangers, faire le mal sous les yeux du Seigneur notre Dieu.'),
('ba',2,1,'crampon1923','C’est pourquoi le Seigneur, notre Dieu, a accompli sa parole, qu''il avait prononcée contre nous, contre nos juges qui ont jugé Israël, contre nos rois, contre nos chefs, et contre tous les hommes d''Israël et de Juda,'),
('ba',2,2,'crampon1923','nous menaçant de faire venir sur nous de grandes calamités, telles qu''il n''en a pas existé sous tout le ciel comme il en a existé à Jérusalem, selon ce qui est écrit dans la loi de Moïse,'),
('ba',2,3,'crampon1923','savoir, que nous mangerions chacun la chair de son fils, et chacun la chair de sa fille.'),
('ba',2,4,'crampon1923','Et il les a mis sous la main de tous les rois qui nous entourent, pour être un objet d''opprobre et de stupéfaction, pour tous les peuples au milieu desquels le Seigneur nous a dispersés.'),
('ba',2,5,'crampon1923','Et nous avons été assujettis au lieu de commander, parce que nous avons péché contre le Seigneur, notre Dieu, en n’obéissant pas à sa voix.'),
('ba',2,6,'crampon1923','Au Seigneur, notre Dieu, appartient la justice, à nous et à nos pères la confusion du visage, comme on le voit en ce jour.'),
('ba',2,7,'crampon1923','Tous ces maux dont le Seigneur nous avait parlé à notre sujet sont venus sur nous.'),
('ba',2,8,'crampon1923','Et nous n''avons pas prié la face du Seigneur de faire revenir chacun de nous des pensées de son cœur mauvais.'),
('ba',2,9,'crampon1923','Aussi le Seigneur a veillé sur le mal, et le Seigneur l''a fait venir sur nous; car le Seigneur est juste dans toutes les œuvres qu''il nous a commandées.'),
('ba',2,10,'crampon1923','Et nous n’avons pas écouté sa voix, en observant les préceptes du Seigneur, qu''Il a mis devant nous.'),
('ba',2,11,'crampon1923','Et maintenant, Seigneur, Dieu d’Israël, qui avez fait sortir votre peuple du pays d''Egypte par une main forte, par des miracles et des prodiges, avec une grande puissance et un bras élevé, et qui vous êtes fait un nom, comme on le voit en ce jour,'),
('ba',2,12,'crampon1923','nous avons péché, nous avons fait des actes impies, nous avons commis l''iniquité, Seigneur notre Dieu, à propos de tous vos préceptes.'),
('ba',2,13,'crampon1923','Que votre colère se détourne de nous, puisque nous ne sommes plus qu''un faible reste parmi les nations, où vous nous avez dispersés!'),
('ba',2,14,'crampon1923','Exaucez, Seigneur, notre prière et notre supplication; délivrez-nous à cause de vous-même, et faites-nous trouver faveur devant ceux qui nous ont déportés:'),
('ba',2,15,'crampon1923','afin que toute la terre sache que vous êtes le Seigneur notre Dieu, puisque votre nom a été invoqué sur Israël et sur sa race.'),
('ba',2,16,'crampon1923','Regardez, Seigneur, de votre demeure sainte, songez à nous, inclinez votre oreille et écoutez,'),
('ba',2,17,'crampon1923','ouvrez les yeux et considérez: ce ne sont pas les morts, dans le schéol, dont l''esprit est sorti de leurs entrailles, qui rendent gloire et justice au Seigneur.'),
('ba',2,18,'crampon1923','Mais le vivant, attristé de la grandeur de ses maux, qui marche courbé et sans force, dont les yeux sont languissants, dont l''âme est affamée, c''est lui qui vous rend gloire et justice, Seigneur.'),
('ba',2,19,'crampon1923','Car ce n''est pas à cause de la justice de nos pères et de nos rois que nous répandons notre prière devant vous, Seigneur, notre Dieu.'),
('ba',2,20,'crampon1923','Car vous avez envoyé sur nous votre colère et votre indignation, comme vous l''aviez proclamé par vos serviteurs les prophètes,'),
('ba',2,21,'crampon1923','en disant: Ainsi parle le Seigneur: " Inclinez vos épaules et votre cou et servez le roi de Babylone, et vous demeurerez dans le pays que j''ai donné à vos pères.'),
('ba',2,22,'crampon1923','Que si vous n''écoutez pas la voix du Seigneur, votre Dieu, en servant le roi de Babylone,'),
('ba',2,23,'crampon1923','je ferai cesser, dans les villes de Juda et hors de Jérusalem, le chant de joie et le chant d''allégresse, le chant du fiancé et le chant de la fiancée, et tout le pays deviendra un désert, sans habitants. "'),
('ba',2,24,'crampon1923','Nous n''avons pas écouté votre voix, en servant le roi de Babylone, et vous avez accompli vos paroles, prononcées par l''organe de vos serviteurs les prophètes, annonçant que les ossements de nos rois et les ossements de nos pères seraient ôtés de leurs sépulcres.'),
('ba',2,25,'crampon1923','Et voici qu''ils ont été, en effet, jetés sur le sol, exposés aux ardeurs du soleil et au froid de la nuit; et nos pères sont morts dans de cruelles souffrances, par la faim, par le glaive et par la peste.'),
('ba',2,26,'crampon1923','Vous avez réduit la maison sur laquelle votre nom était invoqué, dans l''état où elle est aujourd''hui, à cause de la méchanceté de la maison d''Israël et de la maison de Juda.'),
('ba',2,27,'crampon1923','Vous avez agi envers nous, Seigneur, notre Dieu, selon toute votre bonté, et selon toute votre grande miséricorde,'),
('ba',2,28,'crampon1923','comme vous l''aviez déclaré par l''organe de votre serviteur Moïse, au jour où vous lui ordonnâtes d''écrire votre loi, en présence des enfants d''Israël,'),
('ba',2,29,'crampon1923','en disant: " Si vous n''écoutez pas ma voix, cette grande et vaste multitude sera réduite à un très petit nombre, parmi les nations où je les disperserai.'),
('ba',2,30,'crampon1923','Car je sais bien qu''ils ne m''écouteront pas, parce que c''est un peuple à la tête dure; mais ils rentreront en eux-mêmes, dans le pays de leur exil;'),
('ba',2,31,'crampon1923','et ils sauront que je suis le Seigneur, leur Dieu, et je leur donnerai un cœur qui comprenne, et des oreilles qui entendent.'),
('ba',2,32,'crampon1923','Et ils me loueront dans le pays de leur exil, et ils se souviendront de mon nom.'),
('ba',2,33,'crampon1923','Ils renonceront à leur cou raide, et à leurs maximes perverses, parce qu''ils se souviendront du sort de leurs pères, qui ont péché devant le Seigneur.'),
('ba',2,34,'crampon1923','Et je les ramènerai dans le pays que j''ai promis par serment à leurs pères, à Abraham, à Isaac et à Jacob, et ils en seront les maîtres, et je les multiplierai, et ils ne diminueront point.'),
('ba',2,35,'crampon1923','Je ferai avec eux une alliance éternelle, afin que je sois leur Dieu, et qu’ils soient mon peuple; et je ne chasserai plus mon peuple d''Israël du pays que je leur ai donné.'),
('ba',3,1,'crampon1923','Seigneur tout-puissant, Dieu d''Israël, une âme dans l''angoisse et un esprit inquiet crie vers vous.'),
('ba',3,2,'crampon1923','Écoutez, Seigneur, et ayez pitié, parce que nous avons péché devant vous;'),
('ba',3,3,'crampon1923','car vous êtes assis sur un trône éternel, et nous, nous périssons sans retour.'),
('ba',3,4,'crampon1923','Seigneur tout-puissant, Dieu d''Israël, écoutez la prière des morts d''Israël, et des fils de ceux qui ont péché devant vous, eux qui n''ont pas écouté la voix de leur Dieu, et sont cause que ces malheurs se sont attachés à nous.'),
('ba',3,5,'crampon1923','Ne vous souvenez plus des iniquités de nos pères, mais souvenez-vous, à cette heure, de votre puissance et de votre nom.'),
('ba',3,6,'crampon1923','Car vous êtes le Seigneur, notre Dieu, et nous vous louerons, Seigneur.'),
('ba',3,7,'crampon1923','C''est pour cela que vous avez mis votre crainte dans nos cœurs, pour que nous invoquions votre nom; et nous vous louerons dans notre exil; car nous avons écarté de nos cœurs l''iniquité de nos pères, qui ont péché devant vous.'),
('ba',3,8,'crampon1923','Voici que nous sommes aujourd''hui dans notre terre d''exil, où vous nous avez dispersés pour l''opprobre, la malédiction et l''expiation, selon toutes les iniquités de nos pères, qui se sont détournés du Seigneur, notre Dieu.'),
('ba',3,9,'crampon1923','Écoute, Israël, les commandements de vie; prête l''oreille pour apprendre la prudence.'),
('ba',3,10,'crampon1923','D''où vient, Israël, d''où vient que tu es dans le pays de tes ennemis, que tu languis sur une terre étrangère, que tu te souilles avec les morts,'),
('ba',3,11,'crampon1923','et que tu es compté parmi ceux qui sont descendus au schéol?'),
('ba',3,12,'crampon1923','Tu as abandonné la source de la sagesse.'),
('ba',3,13,'crampon1923','Car si tu avais marché dans la voie de Dieu, tu habiterais à jamais dans la paix.'),
('ba',3,14,'crampon1923','Apprends où est la prudence, où est la force, où est l''intelligence, afin que tu saches en même temps où est la longueur des jours et la vie, où est la lumière des yeux et la paix.'),
('ba',3,15,'crampon1923','Qui a trouvé le lieu de la sagesse, et qui est entré dans ses trésors?'),
('ba',3,16,'crampon1923','Où sont les chefs des nations, et ceux qui domptent les bêtes de la terre,'),
('ba',3,17,'crampon1923','qui se jouent des oiseaux du ciel,'),
('ba',3,18,'crampon1923','qui amassent l''argent et l''or, dans lesquels les hommes mettent leur confiance, et dont les possessions n''ont pas de fin? Car ces hommes qui amassent de l''argent et en font leur souci, on ne trouverait plus trace de leurs œuvres.'),
('ba',3,19,'crampon1923','Ils ont disparu et sont descendus au schéol, et d''autres se sont élevés à leur place.'),
('ba',3,20,'crampon1923','Des jeunes gens ont vu la lumière, et ont habité sur la terre; mais ils n''ont pas connu le chemin de la sagesse;'),
('ba',3,21,'crampon1923','ils n''ont pas connu ses sentiers; leurs fils non plus ne l''ont pas saisie; ils étaient loin de sa voie!'),
('ba',3,22,'crampon1923','On n''a pas entendu parler d''elle au pays de Chanaan, et elle n''a pas été vue dans Théman.'),
('ba',3,23,'crampon1923','Et les fils d''Agar qui cherchent la prudence qui est de la terre; les marchands de Merrha et de Théman, les interprètes de paraboles et les chercheurs de prudence n''ont pas connu la voie de la sagesse, et ne se sont pas souvenus de ses sentiers.'),
('ba',3,24,'crampon1923','O Israël, qu''elle est grande la maison de Dieu, qu''il est vaste le lieu de son domaine!'),
('ba',3,25,'crampon1923','Il est vaste et n''a point de bornes, il est élevé et immense.'),
('ba',3,26,'crampon1923','Là vécurent dès l''origine les géants fameux, à la haute stature et habiles dans la guerre.'),
('ba',3,27,'crampon1923','Ce n''est pas eux que Dieu a choisis, et il ne leur a pas appris le chemin de la sagesse.'),
('ba',3,28,'crampon1923','Et ils ont péri parce qu''ils n''avaient pas la vraie science, ils ont péri à cause de leur folie.'),
('ba',3,29,'crampon1923','Qui est monté au ciel et a saisi la sagesse, et l''a fait descendre des nuées?'),
('ba',3,30,'crampon1923','Qui a passé la mer, et, l''ayant trouvée, l''a rapportée au prix de l''or le plus pur?'),
('ba',3,31,'crampon1923','Il n''y a personne qui connaisse ses voies, ni qui observe ses sentiers.'),
('ba',3,32,'crampon1923','Mais celui qui sait toutes choses la connaît, il la découvre par sa prudence, celui qui a affermi la terre à jamais, et qui l''a remplie d''animaux à quatre pieds,'),
('ba',3,33,'crampon1923','qui envoie la lumière, et elle part, qui l''appelle, et elle lui obéit en tremblant.'),
('ba',3,34,'crampon1923','Les étoiles brillent à leurs postes, et elles sont dans la joie;'),
('ba',3,35,'crampon1923','il les appelle, et elles disent: " Nous voici! " et elles brillent joyeusement pour celui qui les a créées.'),
('ba',3,36,'crampon1923','C''est lui qui est notre Dieu, et nul autre ne lui est comparable.'),
('ba',3,37,'crampon1923','Il a trouvé toutes les voies de la sagesse, et il l''a donnée à Jacob, son serviteur, et à Israël son bien-aimé.'),
('ba',3,38,'crampon1923','Après cela il a apparu sur la terre, et il a conversé parmi les hommes.'),
('ba',4,1,'crampon1923','La sagesse, c''est le livre des commandements de Dieu, et la loi qui subsiste à jamais; tous ceux qui s''y attacheront arriveront à la vie, mais ceux qui l''abandonneront iront à la mort.'),
('ba',4,2,'crampon1923','Reviens, ô Jacob, et embrasse-la; marche à la splendeur de sa lumière.'),
('ba',4,3,'crampon1923','Ne donne pas ta gloire à un autre, ni tes avantages à une nation étrangère.'),
('ba',4,4,'crampon1923','Heureux sommes-nous, ô Israël, parce que ce qui plaît à Dieu nous a été révélé.'),
('ba',4,5,'crampon1923','Prends Courage, ô mon peuple, souvenir d''Israël!'),
('ba',4,6,'crampon1923','Vous avez été vendus aux nations, non pour la ruine; mais parce que vous avez excité la colère de Dieu, vous avez été livrés aux oppresseurs.'),
('ba',4,7,'crampon1923','Car vous avez irrité Celui qui vous a faits, en offrant des sacrifices aux démons, et non à Dieu.'),
('ba',4,8,'crampon1923','Vous avez oublié Celui qui vous a nourris, Dieu éternel, et vous avez contristé celle qui vous a élevés, Jérusalem.'),
('ba',4,9,'crampon1923','Car elle a vu fondre sur vous la colère de Dieu, et elle a dit: Écoutez, voisines de Sion, car Dieu m''a envoyé un grand deuil.'),
('ba',4,10,'crampon1923','J''ai vu la captivité de mes fils et de mes filles, que l''Éternel a fait venir sur eux.'),
('ba',4,11,'crampon1923','Je les avais nourris dans la joie, et je les ai laissés partir dans les larmes et le deuil.'),
('ba',4,12,'crampon1923','Que nul ne se réjouisse en me voyant veuve, et délaissée d''un grand nombre! Je suis déserte à cause des péchés de mes fils, parce qu''ils se sont détournés de la loi de Dieu,'),
('ba',4,13,'crampon1923','qu''ils ont méconnu ses commandements, qu''ils n''ont pas marché dans la voie des préceptes de Dieu, et n''ont pas suivi les sentiers de la discipline, selon sa justice.'),
('ba',4,14,'crampon1923','Qu''elles viennent, les voisines de Sion! Souvenez-vous de la captivité de mes fils et de mes filles, que l''Éternel a amenée sur eux.'),
('ba',4,15,'crampon1923','Car il a fait venir contre eux une nation lointaine, une nation cruelle, au langage barbare,'),
('ba',4,16,'crampon1923','qui n''a eu ni respect pour le vieillard, ni compassion pour l''enfant, qui a emmené les bien-aimés de la veuve, et m''a laissée seule, privée de mes filles.'),
('ba',4,17,'crampon1923','Et moi comment pourrais-je vous secourir?'),
('ba',4,18,'crampon1923','Celui qui a fait venir ces maux sur vous, c''est lui qui vous tirera de la main de vos ennemis.'),
('ba',4,19,'crampon1923','Allez, mes fils, allez; pour moi, je reste seule!'),
('ba',4,20,'crampon1923','J''ai quitté la robe des jours heureux; j''ai revêtu le sac de ma supplication; je crierai au Très-Haut tous les jours de ma vie.'),
('ba',4,21,'crampon1923','Courage, mes fils; criez au Seigneur, et il vous arrachera à la puissance, aux mains de vos ennemis.'),
('ba',4,22,'crampon1923','J''attends de l''Éternel votre délivrance, et la joie me vient, de la part du Saint, pour la miséricorde qui vous viendra bientôt de l''Éternel, votre Sauveur.'),
('ba',4,23,'crampon1923','Je vous ai laissés partir dans les larmes et le deuil; mais Dieu vous ramènera à moi dans la joie et l''allégresse, pour toujours.'),
('ba',4,24,'crampon1923','Comme les voisines de Sion ont vu votre captivité, ainsi elles verront bientôt votre délivrance de la part de Dieu, laquelle vous viendra avec une grande gloire et un grand éclat de l''Éternel.'),
('ba',4,25,'crampon1923','Mes fils, supportez avec patience la colère de Dieu qui est venue sur vous; votre ennemi vous a persécutés; mais bientôt vous verrez sa ruine, et mettrez le pied sur son cou.'),
('ba',4,26,'crampon1923','Mes fils les plus délicats ont marché par d''âpres chemins; ils ont été enlevés comme un troupeau volé par l''ennemi.'),
('ba',4,27,'crampon1923','Courage, mes fils, et criez au Seigneur: car Celui qui a fait venir sur vous ces maux se souviendra de vous.'),
('ba',4,28,'crampon1923','Car, comme votre pensée a été de vous éloigner de Dieu, revenus à lui, vous mettrez dix fois plus d''ardeur à le chercher.'),
('ba',4,29,'crampon1923','Car Celui qui a fait venir sur vous le malheur, vous amènera, en vous sauvant, une joie éternelle.'),
('ba',4,30,'crampon1923','Courage, Jérusalem; celui qui t''a donné son nom, te consolera.'),
('ba',4,31,'crampon1923','Malheureux ceux qui t''ont maltraitée, et se sont réjouis de ta chute!'),
('ba',4,32,'crampon1923','Malheureuses les villes où tes fils ont été esclaves! Malheureuse celle qui les a reçus!'),
('ba',4,33,'crampon1923','De même qu''elle s''est réjouie de ta ruine et qu''elle a triomphé de ta chute, ainsi elle s''attristera de sa propre dévastation.'),
('ba',4,34,'crampon1923','Je lui ôterai la joie que lui causaient ses nombreux habitants, et sa jactance sera changée en deuil.'),
('ba',4,35,'crampon1923','Un feu viendra sur elle de la part de l''Éternel, pour de longs jours, et elle sera pendant longtemps le séjour des esprits mauvais.'),
('ba',4,36,'crampon1923','Regarde du côté de l''Orient, ô Jérusalem, et vois la joie qui te vient de la part de Dieu.'),
('ba',4,37,'crampon1923','Car voici qu''ils reviennent, tes fils que tu as vus partir, ils viennent rassemblés de l''Orient à l''Occident à la voix du Saint, se réjouissant de la gloire de Dieu.'),
('ba',5,1,'crampon1923','Quitte, Jérusalem, la robe de ton deuil et de ton affliction, et revêts les ornements de la gloire qui te vient de Dieu pour toujours;'),
('ba',5,2,'crampon1923','enveloppe-toi du manteau de la justice qui te vient de Dieu; mets sur ta tête la mitre de la gloire de l''Éternel.'),
('ba',5,3,'crampon1923','Car Dieu montrera ta splendeur à tout pays qui est sous le ciel.'),
('ba',5,4,'crampon1923','Ton nom sera prononcé par Dieu pour jamais: " Paix-de-la-justice " et " Splendeur-de-la-piété ".'),
('ba',5,5,'crampon1923','Lève-toi, Jérusalem, tiens-toi sur ta hauteur, et regarde vers l''Orient; et vois tes enfants rassemblés du couchant au levant, par la parole du Saint, se réjouissant de ce que Dieu s''est souvenu d''eux.'),
('ba',5,6,'crampon1923','Ils t''avaient quittée à pied, emmenés par les ennemis; Dieu te les ramène portés avec honneur, comme un trône royal.'),
('ba',5,7,'crampon1923','Car Dieu a ordonné de s''abaisser à toute montagne élevée et aux roches éternelles, et aux vallées, de se combler pour aplanir la terre, afin qu''Israël marche sans péril, pour la gloire de Dieu.'),
('ba',5,8,'crampon1923','Les forêts elles-mêmes et tous les arbres odoriférants ont prêté leur ombre à Israël, par l''ordre de Dieu.'),
('ba',5,9,'crampon1923','Car Dieu conduira Israël avec joie à la lumière de sa gloire, avec une miséricorde et une justice qui viennent de lui-même.'),
('ba',6,1,'crampon1923','A cause des péchés que vous avez commis devant Dieu, vous allez être emmenés captifs à Babylone par Nabuchodonosor, roi des Babyloniens.'),
('ba',6,2,'crampon1923','Étant donc arrivés à Babylone, vous y resterez de nombreuses années et un long temps, jusqu''à sept générations; et après cela je vous en ferai sortir en paix.'),
('ba',6,3,'crampon1923','Or vous verrez à Babylone des dieux d''argent, d''or et de bois, que l''on porte sur les épaules et qui inspirent la crainte aux nations.'),
('ba',6,4,'crampon1923','Prenez donc garde de ne pas imiter, vous aussi, ces étrangers, et de ne pas vous laisser saisir par la crainte de ces dieux.'),
('ba',6,5,'crampon1923','Quand vous verrez une foule se presser par devant et par derrière eux, et leur rendre ses hommages, dites en votre cœur: " C''est vous, Maître, qu''il faut adorer. "'),
('ba',6,6,'crampon1923','Car mon ange est avec vous, et il prend soin de votre vie.'),
('ba',6,7,'crampon1923','Car la langue de ces dieux a été polie par un ouvrier; on la recouvre d''or et d''argent, mais ils ne sont que mensonge, et ne peuvent parler.'),
('ba',6,8,'crampon1923','Comme pour une fille qui aime la parure, on a pris de l''or, et l''on a préparé des couronnes pour les poser sur la tête de ces dieux.'),
('ba',6,9,'crampon1923','Les prêtres vont jusqu''à dérober à leurs dieux de l''or et de l''argent, qu’ils font servir à leurs propres usages;'),
('ba',6,10,'crampon1923','ils en donneront même aux prostituées dans leur maison. Ils les parent de riches vêtements, comme des hommes, ces dieux d''argent, d''or et de bois;'),
('ba',6,11,'crampon1923','mais ceux-ci ne peuvent se défendre ni de la rouille, ni des vers.'),
('ba',6,12,'crampon1923','Quand on les a revêtus d''habits de pourpre, il faut encore essuyer leur visage, à cause de la poussière de la maison qui les couvre d''une couche épaisse.'),
('ba',6,13,'crampon1923','En voici un qui tient un sceptre, comme un gouverneur de province: il ne fera pas mourir celui qui l''aura offensé.'),
('ba',6,14,'crampon1923','Cet autre porte à la main une épée ou une hache, mais il ne peut se défendre contre l''ennemi ou les voleurs. Par où l''on voit bien que ce ne sont pas des dieux;'),
('ba',6,15,'crampon1923','ne les craignez donc point. Comme le vase qu''un homme possède, lorsqu''il est brisé, devient inutile: ainsi en est-il de leurs dieux.'),
('ba',6,16,'crampon1923','Si vous les placez dans une maison, leurs yeux se remplissent de la poussière des pieds de ceux qui entrent.'),
('ba',6,17,'crampon1923','De même que les portes de la prison sont fermées avec soin sur un homme qui a offensé le roi, ou sur un homme qu''on va conduire à la mort, ainsi les prêtres défendent la demeure de leurs dieux par des portes solides, par des serrures et des verrous, de peur qu''ils ne soient dépouillés par les voleurs.'),
('ba',6,18,'crampon1923','Ils allument des lampes, et même en plus grand nombre que pour eux-mêmes, et ces dieux n''en peuvent voir aucune.'),
('ba',6,19,'crampon1923','Ils sont comme une des poutres de la maison, et l''on dit que leur cœur est rongé par la vermine qui sort de terre, et qui les dévore ainsi que leurs vêtements, sans qu''ils le sentent.'),
('ba',6,20,'crampon1923','Leur visage devient noir par la fumée qui s''élève de la maison.'),
('ba',6,21,'crampon1923','Sur leur corps et sur leur tête voltigent les hiboux, les hirondelles et les autres oiseaux; et pareillement s''ébattent les chats eux-mêmes.'),
('ba',6,22,'crampon1923','Par là vous reconnaîtrez que ce ne sont pas des dieux; ne les craignez donc point.'),
('ba',6,23,'crampon1923','L''or dont on les recouvre pour les embellir, si quelqu''un n''en ôte pas la rouille, ils ne le feront pas briller; car ils n''ont même rien senti lorsqu''on les fondait.'),
('ba',6,24,'crampon1923','Ces idoles ont été achetées au plus haut prix, et il n''y a point en elle de souffle de vie.'),
('ba',6,25,'crampon1923','N''ayant pas de pieds, elles sont portées sur les épaules, montrant ainsi aux hommes leur honteuse impuissance. Qu''ils soient confondus avec elles ceux qui les servent!'),
('ba',6,26,'crampon1923','Si elles tombent à terre, elles ne se relèveront pas d''elles-mêmes; et si quelqu''un les pose debout, elles ne se mettront pas d''elles-mêmes en mouvement; et si elles penchent, elles ne se redresseront pas. C''est comme devant des morts qu''on met devant elles des offrandes.'),
('ba',6,27,'crampon1923','Les prêtres vendent les victimes qu''on leur offre et en font leur profit; leurs femmes en font des salaisons, et ne donnent rien ni au pauvre, ni à l''infirme.'),
('ba',6,28,'crampon1923','Les femmes en couches ou dans un état impur touchent à leurs sacrifices. Sachant donc par ces choses que ce ne sont pas des dieux, ne les craignez point.'),
('ba',6,29,'crampon1923','Et pourquoi les appeler des dieux? Car ce sont des femmes qui viennent apporter leurs offrandes à ces dieux d''argent, d''or et de bois.'),
('ba',6,30,'crampon1923','Et, dans leurs temples, les prêtres sont assis, la tunique déchirée, la tête et le visage rasés, et la tête découverte.'),
('ba',6,31,'crampon1923','Ils rugissent en criant devant leurs dieux, comme dans un festin mortuaire.'),
('ba',6,32,'crampon1923','Leurs prêtres leur enlèvent leurs vêtements, et ils en habillent leurs femmes et leurs enfants.'),
('ba',6,33,'crampon1923','Qu''on leur fasse du mal ou qu''on leur fasse du bien, ils ne pourront rendre ni l''un ni l''autre; ils sont incapables d''établir un roi ou de le renverser.'),
('ba',6,34,'crampon1923','Ils ne peuvent pas davantage donner la richesse, ni même une pièce de monnaie. Si quelqu''un, leur ayant fait un vœu, ne s''en acquitte pas, ils ne réclament pas.'),
('ba',6,35,'crampon1923','Ils ne sauveront pas un homme de la mort, ils n''arracheront point le faible de la main d''un puissant.'),
('ba',6,36,'crampon1923','Ils ne rendront pas la vue à un aveugle, et ne délivreront pas celui qui est dans la détresse.'),
('ba',6,37,'crampon1923','Ils n''auront pas pitié de la veuve, et ne feront pas de bien à l''orphelin.'),
('ba',6,38,'crampon1923','Elles ressemblent aux rochers détachés de la montagne, ces idoles de bois, recouvertes d''or et d''argent, et ceux qui les servent seront confondus.'),
('ba',6,39,'crampon1923','Comment croire ou dire que ce sont des dieux?'),
('ba',6,40,'crampon1923','Les Chaldéens eux-mêmes les déshonorent, lorsque, voyant un homme qui ne peut parler, ils le présentent à Bel demandant que le muet parle, comme si le dieu pouvait entendre quelque chose.'),
('ba',6,41,'crampon1923','Et quoiqu''ils s''en rendent compte, ils ne peuvent abandonner ces idoles; car elles n''ont pas le sentiment.'),
('ba',6,42,'crampon1923','Les femmes, entourées d''une corde, vont s''asseoir sur les chemins, brûlant de la farine grossière;'),
('ba',6,43,'crampon1923','et, quand l''une d''elles, entraînée par quelque passant, a dormi avec lui, elle reproche à sa voisine de n''avoir pas été jugée digne du même honneur, et de n''avoir pas vu rompre sa tresse de jonc.'),
('ba',6,44,'crampon1923','Tout ce qui se fait à l''égard des idoles est mensonge. Comment donc croire ou dire que ce sont des dieux?'),
('ba',6,45,'crampon1923','Ils ont été façonnés par des artisans et des orfèvres; ils ne sauraient être autrement que les ouvriers veulent qu''ils soient.'),
('ba',6,46,'crampon1923','Et les ouvriers qui les ont façonnés n''ont pas longtemps à vivre: comment donc leurs ouvrages seraient-ils de longue durée?'),
('ba',6,47,'crampon1923','Ils n''ont laissé que mensonge et opprobre à la postérité.'),
('ba',6,48,'crampon1923','Que survienne une guerre, ou quelque autre calamité, les prêtres délibèrent entre eux pour savoir où ils se cacheront avec leurs dieux:'),
('ba',6,49,'crampon1923','comment donc ne comprend-on pas que ceux-là ne sont pas des dieux, qui ne peuvent se sauver de la guerre ou d''une autre calamité?'),
('ba',6,50,'crampon1923','Ces idoles de bois, recouvertes d''or et d''argent, seront reconnues plus tard comme n''étant que mensonge; pour toutes les nations et pour tous les rois il sera évident qu''elles ne sont pas des dieux, mais des ouvrages de mains d''hommes, et qu''il n''y a en elles aucune œuvre divine.'),
('ba',6,51,'crampon1923','Pour qui donc ne serait-il pas évident que ce ne sont pas des dieux?'),
('ba',6,52,'crampon1923','Ils n''établiront jamais un roi sur un pays, et ne donneront pas la pluie aux hommes.'),
('ba',6,53,'crampon1923','Ils ne sauront pas juger leurs propres affaires, et ils ne protégeront pas contre l''injustice, puisqu''ils ne peuvent rien, semblables à des corneilles qui se tiennent entre le ciel et ta terre.'),
('ba',6,54,'crampon1923','Et lorsque le feu tombera sur la maison de ces dieux de bois, recouverts d''or et d''argent, leurs prêtres prendront la fuite et seront sauvés; mais eux seront consumés comme des poutres au milieu des flammes.'),
('ba',6,55,'crampon1923','Ils ne résisteront ni à un roi, ni à une armée ennemie. Comment admettre ou penser que ce sont des dieux?'),
('ba',6,56,'crampon1923','Ils n''échapperont pas aux voleurs et aux brigands, ces dieux de bois, recouverts d''argent et d''or.'),
('ba',6,57,'crampon1923','Des hommes plus puissants qu''eux enlèveront l''argent et l''or, et s''en iront avec les riches vêtements dont on les a couverts, et ces dieux ne pourront se secourir eux-mêmes.'),
('ba',6,58,'crampon1923','Aussi vaut-il mieux être un roi déployant sa force, ou un vase utile dans la maison, dont le maître se sert, que d''être ces faux dieux; ou bien une porte à une maison, qui garde ce qui s''y trouve, que d''être ces faux dieux; ou encore une colonne de bois dans la maison d''un roi, que d''être ces faux dieux.'),
('ba',6,59,'crampon1923','Le soleil, la lumière et les astres, qui sont brillants et envoyés pour l''utilité des hommes, obéissent à Dieu.'),
('ba',6,60,'crampon1923','De même encore l''éclair, lorsqu''il paraît, est beau à voir; le vent aussi souffle sur tous le pays;'),
('ba',6,61,'crampon1923','et les nuées, lorsque Dieu leur commande de parcourir toute la terre, exécutent ce qui leur est ordonné.'),
('ba',6,62,'crampon1923','Le feu également, lorsqu''il est envoyé d''en haut pour consumer les montagnes et les forêts, fait ce qui lui a été commandé. Mais les idoles ne sont pas comparables, ni en beauté ni en puissance, à toutes ces choses.'),
('ba',6,63,'crampon1923','Il ne faut donc ni penser ni dire que ce sont des dieux, puisqu''elles ne peuvent ni discerner ce qui est juste, ni faire du bien aux hommes.'),
('ba',6,64,'crampon1923','Sachant donc que ce ne sont pas des dieux, ne les craignez point.'),
('ba',6,65,'crampon1923','Ils sont incapables de maudire ou de bénir les rois.'),
('ba',6,66,'crampon1923','Ils ne font pas voir aux nations des signes dans le ciel; ils ne brillent pas comme le soleil, ils n''éclairent pas comme la lune.'),
('ba',6,67,'crampon1923','Les bêtes valent mieux qu''eux, puisqu''elles peuvent en fuyant trouver un abri et être utiles à elles-mêmes.'),
('ba',6,68,'crampon1923','Ainsi d''aucune manière il n''est évident pour nous que ce sont des dieux; ne les craignez donc pas.'),
('ba',6,69,'crampon1923','De même qu''un épouvantail dans un champ de concombres ne préserve de rien, ainsi en est-il de leurs dieux de bois, recouverts d''or et d''argent.'),
('ba',6,70,'crampon1923','Tout semblables à un buisson d''épines dans un jardin, sur lequel tous les oiseaux se posent, ou à un mort jeté dans un lieu obscur, tels sont leurs dieux de bois, recouverts d''or et d''argent.'),
('ba',6,71,'crampon1923','La pourpre elle-même et l''écarlate qui se gâtent sur eux font voir que ce ne sont pas des dieux. Eux-mêmes finiront par être dévorés et deviendront une honte dans le pays.'),
('ba',6,72,'crampon1923','Mieux vaut l''homme juste qui n''a pas d''idoles; il n''aura pas à craindre la confusion.'),
('ez',1,1,'crampon1923','Et la trentième année, au quatrième mois, le cinquième jour du mois, comme j''étais parmi les captifs, près du fleuve Chobar, les cieux s''ouvrirent et je vis des visions de Dieu.'),
('ez',1,2,'crampon1923','Le cinquième jour du mois, — c''était la cinquième année de la captivité du roi Joachin, —'),
('ez',1,3,'crampon1923','la parole de Yahweh fut adressée à Ezéchiel, fils de Buzi, prêtre, dans le pays des Chaldéens, prés du fleuve Chobar, et là, la main de Yahweh fut sur lui.'),
('ez',1,4,'crampon1923','Je vis, et voici qu''un vent de tempête venait du septentrion, et une grande nuée, et une masse de feu qui resplendissait alentour; et au milieu d''elle on voyait comme l''aspect d''un métal plongé dans le feu.'),
('ez',1,5,'crampon1923','Et au milieu, je vis la ressemblance de quatre êtres vivants, et voici quel était leur aspect: ils avaient une ressemblance humaine.'),
('ez',1,6,'crampon1923','Chacun avait quatre faces, et chacun avait quatre ailes.'),
('ez',1,7,'crampon1923','Leurs pieds étaient des pieds droits, et la plante de leurs pieds était comme la plante du pied d''un veau; ils étincelaient comme l''aspect de l''airain poli.'),
('ez',1,8,'crampon1923','Des mains d''hommes sortaient de dessous leurs ailes, sur leurs quatre côtés; et tous les quatre avaient leurs faces et leurs ailes.'),
('ez',1,9,'crampon1923','Leurs ailes étaient jointes l''une à l''autre; ils ne tournaient point en marchant; chacun allait devant soi.'),
('ez',1,10,'crampon1923','Et voici quelle était la ressemblance de leurs faces: une face d''homme par devant, une face de lion à droite à tous les quatre, une face de taureau à gauche à tous les quatre, et une face d''aigle à tous les quatre.'),
('ez',1,11,'crampon1923','Et telles étaient leurs faces. Leurs ailes se déployaient au-dessus d''eux; chacun avait deux ailes qui rejoignaient celles de l''autre, et deux ailes qui couvraient son corps.'),
('ez',1,12,'crampon1923','Chacun allait devant soi; là où l''esprit les faisait aller, ils allaient; ils ne tournaient pas en allant.'),
('ez',1,13,'crampon1923','L''aspect de ces êtres vivants ressemblait à des charbons ardents; c''était comme l''aspect des lampes; le feu circulait entre les êtres, le feu était éblouissant, et du feu sortaient des éclairs.'),
('ez',1,14,'crampon1923','Et les êtres vivants couraient en tous sens, comme l''aspect de la foudre.'),
('ez',1,15,'crampon1923','Et je regardai les êtres vivants, et voici une roue à terre auprès d''eux, devant leurs quatre faces.'),
('ez',1,16,'crampon1923','L''aspect des roues et leur forme étaient ceux de la pierre de Tharsis, et toutes quatre étaient semblables; leur aspect et leur forme étaient comme si une roue était au milieu d''une autre roue.'),
('ez',1,17,'crampon1923','En avançant, elles allaient sur leurs quatre côtés et ne se retournaient pas dans leur marche.'),
('ez',1,18,'crampon1923','Leurs jantes étaient d''une hauteur effrayante, et les jantes des quatre roues étaient remplies d''yeux tout autour.'),
('ez',1,19,'crampon1923','Quand les êtres allaient, les roues allaient aussi à côté d''eux, et quand les êtres s''élevaient de terre, les roues s''élevaient aussi.'),
('ez',1,20,'crampon1923','Là où l''esprit les poussait à aller, ils y allaient, l''esprit les y poussant, et les roues s''élevaient avec eux; car l''esprit de l''être vivant était dans les roues.'),
('ez',1,21,'crampon1923','Quand ils allaient, elles allaient; quand ils s''arrêtaient, elles s''arrêtaient; et quand ils s''élevaient de terre, les roues s''élevaient avec eux; car l''esprit de l''être vivant était dans les roues.'),
('ez',1,22,'crampon1923','Au-dessus des têtes des êtres vivants, était la ressemblance d''un firmament, pareil à un cristal éblouissant; il était étendu au-dessus de leurs têtes.'),
('ez',1,23,'crampon1923','Et sous le firmament se dressaient leurs ailes, l''une vers l''autre, et chacun en avait deux qui lui couvraient le corps de chaque côté.'),
('ez',1,24,'crampon1923','Et j''entendis le bruit de leurs ailes, quand ils allaient, comme le bruit des grandes eaux, comme la voix du Tout-Puissant, un bruit tumultueux comme celui d''un camp; quand ils s''arrêtaient, ils laissaient retomber leurs ailes.'),
('ez',1,25,'crampon1923','Et il se faisait un bruit, partant du firmament étendu sur leurs têtes; quand ils s''arrêtaient, ils laissaient retomber leurs ailes.'),
('ez',1,26,'crampon1923','Au-dessus du firmament qui était sur leurs têtes, il y avait comme l''aspect d''une pierre de saphir, en forme de trône; et sur cette ressemblance de trône, il semblait y avoir comme une figure d''homme au-dessus.'),
('ez',1,27,'crampon1923','Au-dedans et alentour, je vis comme une forme de métal, comme un aspect de feu, depuis ce qui paraissait ses reins et au-dessus; et depuis ce qui paraissait ses reins et au-dessous, je vis comme l''aspect du feu, et il y avait de l''éclat tout autour de lui.'),
('ez',1,28,'crampon1923','Comme l''aspect de l''arc qui est dans la nuée en un jour de pluie, tel était l''aspect de l''éclat tout autour de lui. Tel était l''aspect de la ressemblance de la gloire de Yahweh. A cette vue, je tombai sur ma face, et j''entendis la voix de quelqu''un qui parlait.'),
('ez',2,1,'crampon1923','Il me dit: " Fils de l''homme, tiens-toi sur tes pieds, et je te parlerai. "'),
('ez',2,2,'crampon1923','Et comme il me parlait, l''Esprit entra en moi et me fit tenir sur mes pieds, et j''entendis celui qui me parlait.'),
('ez',2,3,'crampon1923','Il me dit: " Fils de l''homme, je t''envoie vers les enfants d''Israël, vers les peuples rebelles qui se sont révoltés contre moi; eux et leurs pères ont péché contre moi, même jusqu''à ce jour.'),
('ez',2,4,'crampon1923','Ces fils à la face impudente et au cœur endurci, c''est vers eux que je t''envoie. Et tu leur diras: Ainsi a parlé le Seigneur Yahweh.'),
('ez',2,5,'crampon1923','Pour eux, qu''ils écoutent ou n''écoutent point — car c''est une maison de rebelles, — ils sauront qu''il y a eu un prophète au milieu d''eux.'),
('ez',2,6,'crampon1923','Et toi, fils de l''homme, ne les crains pas et n''aie pas peur de leurs paroles, car tu es avec des chardons et des épines, et tu habites avec des scorpions. N''aie pas peur de leurs paroles et ne redoute pas leurs faces, car c''est une maison de rebelles.'),
('ez',2,7,'crampon1923','Et tu leur diras mes paroles, qu''ils écoutent ou n''écoutent pas, car ce sont des rebelles.'),
('ez',2,8,'crampon1923','Et toi, fils de l''homme, écoute ce que je te dis: Ne sois pas rebelle comme la maison rebelle. Ouvre ta bouche et mange ce que je te donne. "'),
('ez',2,9,'crampon1923','Je regardai, et voici qu''une main était tendue vers moi, et voici qu''elle tenait un livre roulé.'),
('ez',2,10,'crampon1923','Il le déroula devant moi, et il était écrit en dedans et en dehors; et ce qui y était écrit était des chants de deuil, des lamentations et des plaintes.'),
('ez',3,1,'crampon1923','Et il me dit: " Fils de l''homme, ce que tu trouves devant toi, mange-le; mange ce livre; puis va, parle à la maison d''Israël. "'),
('ez',3,2,'crampon1923','J''ouvris la bouche, et il me fit manger ce livre;'),
('ez',3,3,'crampon1923','et il me dit: " Fils de l''homme, repais ton ventre et remplis tes entrailles de ce livre que je te donne. " Je le mangeai, et il fut dans ma bouche doux comme du miel.'),
('ez',3,4,'crampon1923','Et il me dit: " Fils de l''homme, va vers la maison d''Israël, et tu leur diras mes paroles.'),
('ez',3,5,'crampon1923','Car ce n''est point vers un peuple au parler étrange et à la langue barbare que tu es envoyé; c''est vers la maison d''Israël.'),
('ez',3,6,'crampon1923','Ce n''est point vers des peuples nombreux au parler étrange et à la langue barbare, dont tu ne comprendrais pas les paroles, mais c''est vers eux que je t''envoie; eux peuvent te comprendre.'),
('ez',3,7,'crampon1923','Et la maison d''Israël ne voudra pas t''écouter, parce qu''ils ne veulent pas m''écouter; car toute la maison d''Israël a le front endurci et le cœur impudent.'),
('ez',3,8,'crampon1923','Mais voici que j''ai rendu ta face dure comme leur face, et ton front dur comme leur front.'),
('ez',3,9,'crampon1923','J''ai rendu ton front comme le diamant, plus dur que le roc. Ne les crains point, et ne tremble point devant eux, car c''est une maison rebelle ".'),
('ez',3,10,'crampon1923','Et il me dit: " Fils de l''homme toutes les paroles que je te dirai, reçois-les dans ton cœur et écoute-les de tes oreilles.'),
('ez',3,11,'crampon1923','Va, rends-toi auprès des captifs, vers les fils de ton peuple, et parle-leur en leur disant: Ainsi parle le Seigneur Yahweh, soit qu''ils écoutent, soit qu''ils n''écoutent pas. "'),
('ez',3,12,'crampon1923','L''Esprit m''enleva, et j''entendis derrière moi le bruit d''un grand fracas: " Bénie soit la gloire de Yahweh au lieu de sa demeure? "'),
('ez',3,13,'crampon1923','Et j''entendis le bruit des ailes des êtres vivants qui battaient l''une contre l''autre, et le bruit des roues à leurs côtés, et le bruit d''un grand fracas.'),
('ez',3,14,'crampon1923','Et l''Esprit m''enleva et m''emporta, et je m''en allai l''amertume et le courroux dans l''âme; et la main de Yahweh était fortement sur moi.'),
('ez',3,15,'crampon1923','Et j''arrivai à Tel-Abid, auprès des captifs qui demeuraient aux bords du fleuve Chobar et dans le lieu où ils demeuraient; là je demeurai sept jours dans la stupeur, au milieu d''eux.'),
('ez',3,16,'crampon1923','Au bout de sept jours, la parole de Yahweh me fut adressée en ces termes:'),
('ez',3,17,'crampon1923','" Fils de l''homme, je t''établis comme sentinelle pour la maison d''Israël; tu écouteras la parole qui sortira de ma bouche et tu les avertiras de ma part.'),
('ez',3,18,'crampon1923','Si je dis au méchant: Tu mourras certainement, et que tu ne l''avertisses pas, et que tu ne parles pas pour l''avertir de sa voie mauvaise, afin qu''il vive, ce méchant mourra dans son iniquité; et je redemanderai son sang de ta main.'),
('ez',3,19,'crampon1923','Mais si tu avertis le méchant, et qu''il ne se détourne pas de sa méchanceté et de sa mauvaise voie, il mourra dans son iniquité; mais toi, tu auras sauvé ton âme.'),
('ez',3,20,'crampon1923','Si un juste se détourne de sa justice et commet l''iniquité, et que je mette un piège devant lui, il mourra; parce que tu ne l''auras pas averti, il mourra dans son péché; on ne se souviendra plus de ses œuvres de justice qu''il aura faites; et je redemanderai son sang de ta main.'),
('ez',3,21,'crampon1923','Mais si tu as averti un juste pour que ce juste ne pèche pas, et qu''il n''ait pas péché, il vivra certainement, parce qu''il aura été averti; et toi tu auras sauvé ton âme.'),
('ez',3,22,'crampon1923','La main de Yahweh fut là sur moi, et il me dit: " Lève-toi, sors vers la plaine, et là je te parlerai. "'),
('ez',3,23,'crampon1923','M''étant levé, je sortis vers la plaine, et voici que la gloire de Yahweh se tenait là, telle que la gloire que j''avais vue près du fleuve Chobar; et je tombai sur ma face.'),
('ez',3,24,'crampon1923','L''Esprit entra en moi et me fit tenir sur mes pieds; et Yahweh me parla et me dit: " Va t''enfermer au milieu de ta maison.'),
('ez',3,25,'crampon1923','Et toi, fils de l''homme, voici qu''on va mettre sur toi des cordes et on t''en liera, et tu ne sortiras pas au milieu d''eux.'),
('ez',3,26,'crampon1923','Et j''attacherai ta langue à ton palais, tu seras muet, et tu ne seras pas pour eux un censeur; car ils sont une maison rebelle.'),
('ez',3,27,'crampon1923','Et quand je te parlerai, j''ouvrirai ta bouche, et tu leur diras: Ainsi parle le Seigneur Yahweh: Qui veut écouter, qu''il écoute, et qui veut s''en abstenir, qu''il s''en abstienne; car ils sont une maison rebelle.'),
('ez',4,1,'crampon1923','Toi, fils de l''homme, prends une brique, pose-la devant toi, et tu y dessineras une ville, Jérusalem.'),
('ez',4,2,'crampon1923','Mets le siège contre elle, construis contre elle une tour d''attaque, élève contre elle des terrasses: place contre elle des camps, et pose contre elle des béliers tout autour.'),
('ez',4,3,'crampon1923','Et toi, prends une poêle en fer et place-la comme un mur de fer entre toi et la ville, et dirige ta face contre elle; elle sera assiégée et tu l''assiégeras. Que ce soit un signe pour la maison d''Israël!'),
('ez',4,4,'crampon1923','Et toi, couche-toi sur ton côté gauche, et mets-y l''iniquité de la maison d''Israël; et le nombre de jours que tu resteras ainsi couché, tu porteras leur iniquité.'),
('ez',4,5,'crampon1923','Et moi, je t''ai compté les années de leur iniquité selon le nombre de jours: durant trois cent quatre-vingt-dix jours, tu porteras l''iniquité de la maison d''Israël.'),
('ez',4,6,'crampon1923','Et quand tu auras achevé ces jours, tu te coucheras sur ton côté droit une seconde fois, et tu porteras l''iniquité de la maison de Juda, quarante jours; je t''ai compté un jour pour une année.'),
('ez',4,7,'crampon1923','Et tu dirigeras ta face et ton bras nu contre Jérusalem assiégée, et tu prophétiseras contre elle.'),
('ez',4,8,'crampon1923','Et voici que j''ai mis sur toi des cordes, afin que tu ne puisses pas te tourner d''un côté sur l''autre, jusqu''à ce que tu aies accompli les jours de ton siège.'),
('ez',4,9,'crampon1923','Prends du froment, de l''orge, des fèves, des lentilles, du millet et de l''épeautre; mets-les dans un vase et fais-en du pain pour toi, selon le nombre de jours que tu seras couché sur ton côté; tu en mangeras trois cent quatre-vingt-dix jours.'),
('ez',4,10,'crampon1923','Et la nourriture que tu mangeras sera du poids de vingt sicles par jour; tu en mangeras de temps en temps.'),
('ez',4,11,'crampon1923','Tu boiras de l''eau par petite quantité, un sixième de hin; tu en boiras de temps en temps.'),
('ez',4,12,'crampon1923','Tu mangeras cela sous la forme de galettes d''orge, et tu le feras cuire sous leurs yeux avec des excréments d''homme. "'),
('ez',4,13,'crampon1923','Et Yahweh me dit: " C''est ainsi que les enfants d''Israël mangeront leur pain souillé chez les nations où je les chasserai. "'),
('ez',4,14,'crampon1923','Je dis: " Ah! Seigneur Yahweh, voici que mon âme n''a jamais été souillée; je n''ai pas mangé d''une bête morte ou déchirée depuis ma jeunesse jusqu''à présent, et aucune chair souillée n''est entrée dans ma bouche. "'),
('ez',4,15,'crampon1923','Il me dit: " Vois, je t''accorde de la fiente de bétail au lieu d''excréments d''homme, et tu feras cuire ton pain dessus. "'),
('ez',4,16,'crampon1923','Et il me dit: " Fils de l''homme, voici que je vais briser le bâton du pain dans Jérusalem; ils mangeront du pain au poids et dans l''angoisse; ils boiront de l''eau à la mesure et dans l''épouvante.'),
('ez',4,17,'crampon1923','Car ils manqueront de pain et d''eau; ils dépériront les uns et les autres, et se consumeront à cause de leur iniquité.'),
('ez',5,1,'crampon1923','Et toi, fils de l''homme, prends une lame tranchante, prends-la en guise de rasoir de barbier, et fais-la passer sur ta tête et sur ta barbe; puis tu prendras des balances à peser, et tu partageras ce que tu auras coupé.'),
('ez',5,2,'crampon1923','Tu en brûleras un tiers dans le feu, au milieu de la ville, lorsque les jours du siège seront accomplis; tu en prendras un tiers que tu frapperas avec l''épée autour de la ville; et l''autre tiers, tu le disperseras au vent, et je tirerai l''épée derrière eux.'),
('ez',5,3,'crampon1923','Et tu en prendras une petite quantité, que tu serreras dans les ailes de ton vêtement.'),
('ez',5,4,'crampon1923','De ce reste, tu en prendras encore pour le jeter au milieu du feu, et tu le brûleras dans le feu. De là sortira un feu pour toute la maison d''Israël.'),
('ez',5,5,'crampon1923','Ainsi parle le Seigneur Yahweh: C''est là cette Jérusalem que j''avais placée au milieu des nations, avec de vastes contrées autour d''elle!'),
('ez',5,6,'crampon1923','Mais, dans sa méchanceté, elle à résisté à mes décrets plus que les nations, et à mes lois plus que les pays qui l''entourent; car ils ont rejeté mes décrets et n''ont pas marché suivant mes lois.'),
('ez',5,7,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce que vous avez été plus rebelles que les nations qui vous entourent, que vous n''avez pas marché suivant mes lois, que vous n''avez pas observé mes décrets et que vous n''avez pas agi selon les coutumes des nations qui vous entourent,'),
('ez',5,8,'crampon1923','à cause de cela le Seigneur Yahweh parle ainsi: Voici que je viens contre toi à mon tour! Moi, j''exécuterai des décrets au milieu de toi sous les yeux des nations;'),
('ez',5,9,'crampon1923','et je ferai contre toi une chose telle que je n''en ai point fait et que je n''en ferai jamais plus de pareille, — à cause de toutes tes abominations.'),
('ez',5,10,'crampon1923','C''est pourquoi des pères dévoreront leurs fils au milieu de toi, et des fils dévoreront leurs pères. J''exécuterai contre toi des jugements, et je disperserai à tout vent tout ce qui restera de toi.'),
('ez',5,11,'crampon1923','C''est pourquoi, je suis vivant, oracle du Seigneur Yahweh: Parce que tu as souillé mon sanctuaire par toutes tes infamies et toutes tes abominations, moi aussi je briserai, et mon œil sera sans pitié, et je n''aurai point de compassion.'),
('ez',5,12,'crampon1923','Un tiers de tes enfants mourra par la peste et sera consumé par la famine au milieu de toi; un tiers tombera par l''épée tout autour de toi; et, pour l''autre tiers, je le disperserai à tout vent, et je tirerai l''épée derrière eux.'),
('ez',5,13,'crampon1923','Et ma colère s''assouvira, et j''apaiserai mon courroux sur eux et je serai satisfait; et ils sauront que moi, Yahweh, j''ai parlé dans ma jalousie, quand j''aurai assouvi sur eux mon courroux.'),
('ez',5,14,'crampon1923','Je te livrerai à l''opprobre et à la désolation parmi les nations qui t''entourent, aux yeux de tous les passants.'),
('ez',5,15,'crampon1923','Tu seras un opprobre et une honte, une leçon et un sujet de terreur pour les peuples qui t''entourent, quand j''exécuterai sur toi des jugements avec colère, avec courroux, et par les châtiments de mon courroux, — c''est moi, Yahweh, qui parle! —'),
('ez',5,16,'crampon1923','quand je décocherai sur eux les flèches funestes de la famine, qui servent à détruire et que je lancerai sur vous pour vous détruire; car j''augmenterai encore pour vous la famine, et je briserai pour vous le bâton du pain;'),
('ez',5,17,'crampon1923','et j''enverrai sur vous la famine et des bêtes malfaisantes, qui te priveront d''enfants; la peste et le sang passeront sur toi, et je ferai venir sur toi l''épée — moi, Yahweh, j''ai parlé!'),
('ez',6,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',6,2,'crampon1923','Fils de l''homme, tourne ta face vers les montagnes d''Israël et prophétise contre elles.'),
('ez',6,3,'crampon1923','Tu diras: Montagnes d''Israël, écoutez la parole du Seigneur Yahweh: Ainsi parle le Seigneur Yahweh aux montagnes et aux collines, aux ravins et vallées: Voici que je fais venir contre vous l''épée, et je détruirai vos hauts lieux.'),
('ez',6,4,'crampon1923','Et vos autels seront dévastés, et vos colonnes solaires seront brisées; et je ferai tomber vos hommes frappés à mort devant vos idoles.'),
('ez',6,5,'crampon1923','Je mettrai les cadavres des enfants d''Israël devant leurs idoles. Et je sèmerai vos ossements autour de vos autels.'),
('ez',6,6,'crampon1923','Partout où vous habitez, les villes seront désolées, et les hauts lieux dévastés, afin que vos autels soient désolés et détruits, vos idoles brisées et anéanties, vos colonnes solaires abattues, et vos ouvrages ruinés.'),
('ez',6,7,'crampon1923','Des blessés à mort tomberont au milieu de vous, et vous saurez que je suis Yahweh.'),
('ez',6,8,'crampon1923','Mais je vous laisserai un reste, des réchappés du glaive parmi les nations, quand vous serez dispersés dans les pays.'),
('ez',6,9,'crampon1923','Et vos réchappés se souviendront de moi chez les nations, où je les emmènerai captifs, quand j''aurai brisé leur cœur adultère, qui s''est détourné de moi, et leurs yeux adultères, qui se sont tournés vers leurs idoles; et ils se prendront eux-mêmes en dégoût, pour le mal qu''ils ont fait, en commettant toutes leurs abominations.'),
('ez',6,10,'crampon1923','Et ils sauront que je suis Yahweh; ce n''est pas en vain que j''ai parlé de faire venir sur eux ces maux.'),
('ez',6,11,'crampon1923','Ainsi parle le Seigneur Yahweh: Frappe dans ta main et bats du pied, et dis: Hélas! sur toutes les méchantes abominations de la maison d''Israël, qui va périr par l''épée, par la famine et par la peste.'),
('ez',6,12,'crampon1923','Celui qui sera loin mourra de la peste, et celui qui sera près tombera par l''épée; celui qui sera resté et sera conservé mourra de faim, et j''assouvirai sur eux mon courroux.'),
('ez',6,13,'crampon1923','Et vous saurez que je suis Yahweh quand leurs morts seront couchés au milieu de leurs idoles autour de leurs autels, sur toute colline élevée, sur tous les sommets des montagnes, sous tout arbre vert, et sous tout chêne au feuillage touffu, à l''endroit où ils ont offert un encens d''agréable odeur à toutes leurs idoles.'),
('ez',6,14,'crampon1923','J''étendrai ma main contre eux, et je rendrai le pays désolé et dévasté, depuis le désert jusqu''à Diblah, partout où ils habitent; et ils sauront que je suis Yahweh.'),
('ez',7,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',7,2,'crampon1923','Et toi, fils de l''homme, ainsi parle le Seigneur Yahweh au pays d''Israël: La fin! La fin vient sur les quatre coins de la terre!'),
('ez',7,3,'crampon1923','Maintenant la fin vient sur toi; je vais donner cours à ma colère contre toi; je te jugerai d''après tes œuvres; je ferai retomber sur toi toutes tes abominations.'),
('ez',7,4,'crampon1923','Mon œil ne t''épargnera pas, et je serai sans pitié; car je ferai retomber sur toi tes œuvres, et tes abominations seront au milieu de toi; et vous saurez que je suis Yahweh.'),
('ez',7,5,'crampon1923','Ainsi parle le Seigneur Yahweh: Un malheur unique! Un malheur! Voici qu''il arrive!'),
('ez',7,6,'crampon1923','Une fin vient! La fin arrive! Elle s''éveille contre toi; voici qu''elle arrive!'),
('ez',7,7,'crampon1923','Ton sort est venu, habitant du pays; le temps vient, le jour est proche! Du tumulte!... et non le cri de joie sur les montagnes.'),
('ez',7,8,'crampon1923','Maintenant, je vais sans tarder répandre mon courroux sur toi; j''assouvirai sur toi ma colère, je te jugerai selon tes voies, et je ferai retomber sur toi toutes tes abominations.'),
('ez',7,9,'crampon1923','Mon œil n''épargnera pas, et je serai sans pitié; je ferai retomber sur toi tes œuvres, tes abominations seront au milieu de toi; et vous saurez que c''est moi, Yahweh, qui frappe!'),
('ez',7,10,'crampon1923','Voici le jour; voici qu''il vient; ton sort est arrivé; la verge fleurit, l''orgueil éclôt.'),
('ez',7,11,'crampon1923','La violence s''élève, pour être la verge de l''impiété. Il ne restera rien d''eux, ni de leur multitude, ni de leur tumulte, et ils n''auront plus d''éclat.'),
('ez',7,12,'crampon1923','Le temps vient, le jour approche! Que l''acheteur ne se réjouisse pas, et que le vendeur ne s''afflige point; car la colère va éclater sur toute leur multitude.'),
('ez',7,13,'crampon1923','Le vendeur ne rentrera pas en possession de ce qu''il aura vendu, fût-il encore parmi les vivants; car la vision contre toute leur multitude ne sera point révoquée, et nul par son péché n''assurera sa vie.'),
('ez',7,14,'crampon1923','On sonne la trompette, et tout est prêt; mais personne ne marche au combat, car ma colère est contre toute leur multitude.'),
('ez',7,15,'crampon1923','Au dehors, l''épée; au dedans, la peste et la famine; celui qui est aux champs mourra par l''épée, et celui qui est dans la ville, la famine et la peste le dévoreront.'),
('ez',7,16,'crampon1923','Si des fugitifs parmi eux s''enfuient, ils erreront sur les montagnes comme les colombes des vallées, tous gémissant, chacun pour son péché.'),
('ez',7,17,'crampon1923','Toutes les mains sont défaillantes, et tous les genoux se fondent en eau.'),
('ez',7,18,'crampon1923','Ils se revêtent de sacs, et la terreur les enveloppe; la confusion est sur tous les visages, et toutes les têtes sont rasées.'),
('ez',7,19,'crampon1923','Ils jetteront leur argent dans les rues, et leur or sera pour eux de l''ordure; leur argent et leur or ne pourront les délivrer, au jour de la colère de Yahweh; ils n''en rassasieront pas leur âme, et n''en rempliront pas leurs entrailles; car c''est là ce qui les a fait tomber dans l''iniquité.'),
('ez',7,20,'crampon1923','Des joyaux dont ils se paraient, ils faisaient leur orgueil; ils en fabriquaient leurs abominations, leurs idoles. C''est pourquoi je changerai tout cela en ordure,'),
('ez',7,21,'crampon1923','et je le livrerai en pillage aux mains des étrangers, en proie aux impies de la terre, — et ils le souilleront.'),
('ez',7,22,'crampon1923','Je détournerai d''eux mon visage, et on souillera mon trésor; des hommes de violence y entreront et le souilleront.'),
('ez',7,23,'crampon1923','Prépare les chaînes; car le pays est rempli d''attentats, et la ville de violences.'),
('ez',7,24,'crampon1923','Et je ferai venir les plus méchants d''entre les peuples, et ils s''empareront de leurs maisons, et ils mettront fin à l''orgueil des puissants; et leurs lieux saints seront profanés.'),
('ez',7,25,'crampon1923','La ruine vient; ils chercheront la paix, et il n''y en aura point.'),
('ez',7,26,'crampon1923','Il arrivera malheur sur malheur, et nouvelle sur nouvelle; et ils chercheront des visions auprès des prophètes, et la loi fera défaut au prêtre, et le conseil aux anciens.'),
('ez',7,27,'crampon1923','Le roi sera dans le deuil, le prince se vêtira de tristesse, et les mains du peuple du pays trembleront. Je les traiterai d''après leurs œuvres, je les jugerai selon leurs mérites; et ils sauront que je suis Yahweh.'),
('ez',8,1,'crampon1923','La sixième année, au sixième mois, le cinquième jour du mois, comme j''étais assis dans ma maison, et que les anciens de Juda étaient assis devant moi, la main du Seigneur Yahweh tomba sur moi.'),
('ez',8,2,'crampon1923','Et je vis; et voici une figure qui avait l''aspect du feu; depuis ce qui paraissait ses reins jusqu''en bas, c''était du feu; et depuis ses reins jusqu''en haut, c''était comme l''aspect d''une clarté, comme l''aspect d''un métal.'),
('ez',8,3,'crampon1923','Et il étendit une forme de main, et il me saisit par les boucles de mes cheveux, et l''Esprit m''enleva entre la terre et le ciel; et il m''amena à Jérusalem, en des visions divines, à l''entrée de la porte intérieure qui regarde au septentrion, où était placée l''idole de jalousie qui provoque la jalousie.'),
('ez',8,4,'crampon1923','Et voici que là était la gloire du Dieu d''Israël selon l''aspect que j''avais vu dans la plaine.'),
('ez',8,5,'crampon1923','Il me dit: " Fils de l''homme, lève donc tes yeux dans la direction du septentrion. " Et je levai mes yeux dans la direction du septentrion, et voici qu''au nord de la porte de l''autel, il y avait cette idole de jalousie, à l''entrée.'),
('ez',8,6,'crampon1923','Et il me dit: " Fils de l''homme, vois-tu ce qu''ils font, les grandes abominations que la maison d''Israël commet ici, afin que je m''éloigne de mon sanctuaire. Et tu verras encore d''autres grandes abominations. "'),
('ez',8,7,'crampon1923','Et il me conduisit à l''entrée du parvis, et je vis: et voici qu''il y avait un trou dans le mur!'),
('ez',8,8,'crampon1923','et il me dit: " Fils de l''homme, perce donc la muraille. " Et je perçai la muraille, et voici qu''il y avait une porte.'),
('ez',8,9,'crampon1923','Et il me dit: " Viens et vois les horribles abominations qu''ils commettent ici. "'),
('ez',8,10,'crampon1923','Et je vins et je vis: et voici qu''il y avait toutes sortes de figures de reptiles et d''animaux immondes, et toutes les horreurs de la maison d''Israël dessinées sur la muraille tout autour.'),
('ez',8,11,'crampon1923','Et soixante-dix hommes d''entre les anciens de la maison d''Israël, parmi lesquels était Jézonias, fils de Saphan, se tenaient debout devant elles, et chacun avait à la main son encensoir, d''où s''élevait le parfum d''un nuage d''encens.'),
('ez',8,12,'crampon1923','Et il me dit: " As-tu vu, fils de l''homme, ce que les anciens de la maison d''Israël font dans les ténèbres, chacun dans ses appartements couverts de figures, car ils disent: Yahweh ne nous voit pas; Yahweh a abandonné le pays! "'),
('ez',8,13,'crampon1923','Et il me dit: " Tu verras encore d''autres grandes abominations qu''ils commettent. "'),
('ez',8,14,'crampon1923','Et il me conduisit à l''entrée de la porte de la maison de Yahweh qui regarde le septentrion; et voici que les femmes y étaient assises, pleurant le dieu Thammuz.'),
('ez',8,15,'crampon1923','Et il me dit: " As-tu vu, fils de l''homme? Tu verras encore d''autres abominations plus grandes que celles-là. "'),
('ez',8,16,'crampon1923','Et il me conduisit alors dans le parvis intérieur de la maison de Yahweh; et voici qu''à l''entrée de la maison de Yahweh, entre le portique et l''autel, il y avait environ vingt-cinq hommes, le dos tourné au temple de Yahweh, et le visage vers l''orient; et ils se prosternaient à l''orient devant le soleil.'),
('ez',8,17,'crampon1923','Et il me dit: " As-tu vu, fils de l''homme? Est-ce trop peu pour la maison de Juda de commettre les abominations qu''ils commettent ici? Faut-il qu''ils remplissent encore le pays de violence, et qu''ils recommencent toujours à m''irriter? Voici qu''ils portent le rameau à leur nez.'),
('ez',8,18,'crampon1923','Et moi aussi, j''agirai avec colère; mon œil n''épargnera point, et je serai sans pitié; ils crieront à haute voix à mes oreilles, et je ne les entendrai point. "'),
('ez',9,1,'crampon1923','Et il cria d''une voix forte à mes oreilles, en ces termes: " Approchez, vous qui veillez sur la ville, chacun son instrument de destruction à la main. "'),
('ez',9,2,'crampon1923','Et voici que six hommes arrivèrent par le chemin de la porte supérieure qui regarde le septentrion, chacun ayant en main son instrument pour frapper; et il y avait au milieu d''eux un homme vêtu de lin, portant une écritoire de scribe à la ceinture. Et ils entrèrent et ils se tinrent à côté de l''autel d''airain.'),
('ez',9,3,'crampon1923','Et la gloire du Dieu d''Israël s''éleva de dessus le Chérubin sur lequel elle se tenait, et vint vers le seuil de la maison. Et Yahweh appela l''homme vêtu de lin, qui portait une écritoire à la ceinture.'),
('ez',9,4,'crampon1923','Et Yahweh lui dit: " Passe par le milieu de la ville, par le milieu de Jérusalem, et marque d''un Thau le front des hommes qui soupirent et qui gémissent à cause de toutes les abominations qui s''y commettent. "'),
('ez',9,5,'crampon1923','Et il dit aux autres, à mes oreilles: " Passez dans la ville après lui et frappez; que votre œil n''épargne point, et soyez sans pitié.'),
('ez',9,6,'crampon1923','Vieillard, jeune homme, jeune fille, enfant, femme, tuez-les jusqu''à extermination; mais de quiconque porte sur lui le Thau, n''approchez pas. Et commencez par mon sanctuaire. " Et ils commencèrent par les vieillards qui étaient devant la maison.'),
('ez',9,7,'crampon1923','Et il leur dit: " Souillez la maison et remplissez de morts les parvis. Sortez! " Ils sortirent et frappèrent dans la ville.'),
('ez',9,8,'crampon1923','Et quand ils eurent frappé, comme je restais seul, je tombai sur ma face, je m''écriai et je dis: " Ah! Seigneur Yahweh, vas-tu détruire tout ce qui reste d''Israël, en répandant ta colère sur Jérusalem? "'),
('ez',9,9,'crampon1923','Il me dit: " L''iniquité de la maison d''Israël et de Juda est grande, très grande. Le pays est rempli de sang et la ville est pleine d''injustices, car ils disent: " Yahweh abandonne le pays, Yahweh ne voit rien!'),
('ez',9,10,'crampon1923','Moi aussi, mon œil n''épargnera point et je serai sans pitié; je ferai retomber leurs œuvres sur leurs têtes. "'),
('ez',9,11,'crampon1923','Et voici que l''homme vêtu de lin, qui portait une écritoire à sa ceinture, vint rendre compte en disant: " J''ai fait comme tu m''as commandé. "'),
('ez',10,1,'crampon1923','Et je vis, et voici que sur le firmament qui était au-dessus de la tête des Chérubins, il y avait comme une pierre de saphir; quelque chose paraissant ressembler à un trône apparut au-dessus d''eux.'),
('ez',10,2,'crampon1923','Et il dit à l''homme vêtu de lin: " Va dans les intervalles des roues, sous les Chérubins; remplis tes mains de charbons ardents pris d''entre les Chérubins, et répands-les sur la ville. " Et il y alla devant mes yeux.'),
('ez',10,3,'crampon1923','Or les Chérubins se tenaient à droite de la maison quand l''homme y alla, et la nuée remplit le parvis intérieur.'),
('ez',10,4,'crampon1923','Et la gloire de Yahweh s''éleva de dessus les Chérubins et vint sur le seuil de la maison; la maison fut remplie de la nuée, et le parvis était plein de l''éclat de la gloire de Yahweh.'),
('ez',10,5,'crampon1923','Le bruit des ailes des Chérubins se fit entendre jusqu''au parvis extérieur, comme la voix du Dieu tout-puissant quand il parle.'),
('ez',10,6,'crampon1923','Quand il eut donné cet ordre à l''homme vêtu de lin: " Prends du feu dans l''intervalle des roues, entre les Chérubins, " l''homme vint se tenir à côté des roues.'),
('ez',10,7,'crampon1923','Et le Chérubin avança la main entre les Chérubins, vers le feu qui était entre les Chérubins; il en prit et le mit dans les mains de l''homme vêtu de lin, qui le prit et sortit.'),
('ez',10,8,'crampon1923','Or on voyait aux Chérubins une forme de main d''homme sous leurs ailes.'),
('ez',10,9,'crampon1923','Et je vis, et voici quatre roues auprès des Chérubins, une roue à côté de chaque Chérubin, et l''aspect des roues était comme celui de la pierre de Tharsis.'),
('ez',10,10,'crampon1923','Et quant à leur aspect, toutes quatre étaient semblables, comme si une roue était au milieu d''une autre roue.'),
('ez',10,11,'crampon1923','En avançant, elles allaient sur leurs quatre côtés, et ne se retournaient pas dans leur marche; car vers le lieu où se tournait la tête elles allaient, et elles ne se retournaient pas dans leur marche.'),
('ez',10,12,'crampon1923','Et tout le corps des Chérubins, leur dos, leurs mains et leurs ailes, ainsi que les roues, étaient remplies d''yeux tout autour; tous les quatre avaient leurs roues.'),
('ez',10,13,'crampon1923','Quant aux roues, on les appelait " agiles. "'),
('ez',10,14,'crampon1923','Chacun des Chérubins avait quatre faces: la face du premier était la face de chérubin; la face du second était une face d''homme; celle du troisième, une face de taureau, et celle du quatrième, une face d''aigle.'),
('ez',10,15,'crampon1923','Et les chérubins s''élevèrent; c''était l''être vivant que j''avais vu au fleuve Chobar.'),
('ez',10,16,'crampon1923','Quand les Chérubins allaient, les roues allaient aussi à côté d''eux; et quand les Chérubins dressaient leurs ailes pour s''élever de terre, les roues ne se détournaient pas, elles non plus, d''à côté d''eux.'),
('ez',10,17,'crampon1923','Quand ils s''arrêtaient, elles s''arrêtaient; quand ils s''élevaient, elles s''élevaient avec eux; car l''Esprit de l''être vivant était en elles.'),
('ez',10,18,'crampon1923','La gloire de Yahweh se retira de dessus le seuil de la maison et s''arrêta sur les Chérubins.'),
('ez',10,19,'crampon1923','Les Chérubins dressèrent leurs ailes et s''élevèrent de terre à mes yeux, quand ils partirent et les roues avec eux. Ils s''arrêtèrent à l''entrée de la porte orientale de la maison de Yahweh; et la gloire du Dieu d''Israël reposait sur eux par-dessus.'),
('ez',10,20,'crampon1923','C''était l''être vivant que j''avais vu au-dessous du Dieu d''Israël, au fleuve Chobar; et je sus que c''étaient des Chérubins.'),
('ez',10,21,'crampon1923','Chacun avait quatre faces et chacun avait quatre ailes, et une ressemblance de mains d''hommes était sous leurs ailes.'),
('ez',10,22,'crampon1923','Et quant à la ressemblance de leurs faces, c''étaient les faces que j''avais vues près du fleuve Chobar; c''était le même aspect, c''étaient eux-mêmes. Chacun allait droit devant soi.'),
('ez',11,1,'crampon1923','L''Esprit m''enleva et m''amena à la porte orientale de la maison de Yahweh, celle qui regarde l''orient. Et voici qu''à l''entrée de la porte, il y avait vingt-cinq hommes, et je vis au milieu d''eux Jézonias, fils d''Azzur, et Pheltias, fils de Banaïas, chefs du peuple.'),
('ez',11,2,'crampon1923','Et Yahweh me dit: " Fils de l''homme, ce sont là les hommes qui méditent l''iniquité, et qui donnent de mauvais conseils dans cette ville;'),
('ez',11,3,'crampon1923','qui disent: Le malheur n''est pas si proche! Bâtissons des maisons! Cette ville est la chaudière, et nous sommes la viande.'),
('ez',11,4,'crampon1923','C''est pourquoi prophétise contre eux, prophétise, fils de l''homme. "'),
('ez',11,5,'crampon1923','Et l''Esprit de Yahweh tomba sur moi, et il me dit: " Dis: Ainsi parle Yahweh: C''est ainsi que vous parlez, maison d''Israël! Ce qui monte à votre esprit, moi je le connais.'),
('ez',11,6,'crampon1923','Vous avez multiplié vos meurtres dans cette ville et rempli ses rues de cadavres.'),
('ez',11,7,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Vos morts, que vous avez étendus au milieu de la ville, c''est la chair, et la ville est la chaudière; mais on vous fera sortir du milieu d''elle.'),
('ez',11,8,'crampon1923','Vous craignez l''épée, et je ferai venir sur vous l''épée, — oracle du Seigneur Yahweh.'),
('ez',11,9,'crampon1923','Je vous ferai sortir du milieu de la ville, je vous livrerai à la main des étrangers et j''exercerai sur vous mes jugements.'),
('ez',11,10,'crampon1923','Vous tomberez par l''épée; je vous jugerai à la frontière d''Israël, et vous saurez que je suis Yahweh.'),
('ez',11,11,'crampon1923','Cette ville ne sera pas pour vous la chaudière, et vous ne serez pas la viande au milieu d''elle; c''est à la frontière d''Israël que je vous jugerai.'),
('ez',11,12,'crampon1923','Et vous saurez que je suis Yahweh dont vous n''avez pas suivi les ordonnances, ni pratiqué les lois; mais vous avez agi selon les lois des nations qui vous entourent. "'),
('ez',11,13,'crampon1923','Comme je prophétisais, Pheltias, fils de Banaïas, mourut; et je tombai sur ma face, et je criai à haute voix, et je dis: " Ah! Seigneur, Yahweh, vas-tu anéantir ce qui reste d''Israël? "'),
('ez',11,14,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ez',11,15,'crampon1923','" Fils de l''homme, tes frères, tes frères, hommes de ta parenté, et toute la maison d''Israël, ce sont tous ceux à qui les habitants de Jérusalem disent: Restez loin de Yahweh, c''est à nous que le pays a été donné en possession.'),
('ez',11,16,'crampon1923','C''est pourquoi dis-leur: Ainsi parle le Seigneur Yahweh: Oui, je les ai éloignés parmi les nations, je les ai dispersés dans les pays; mais je serai pour eux un sanctuaire pendant un peu de temps, dans les pays où ils sont allés.'),
('ez',11,17,'crampon1923','C''est pourquoi dis-leur: Ainsi parle le Seigneur Yahweh: je vous rassemblerai du milieu des peuples, je vous recueillerai des pays où vous avez été dispersés, et je vous donnerai la terre d''Israël.'),
('ez',11,18,'crampon1923','Ils y entreront et en ôteront toutes ses infamies et toutes ses abominations.'),
('ez',11,19,'crampon1923','Et je leur donnerai un seul cœur; je mettrai au-dedans d''eux un esprit nouveau; et j''ôterai de leur chair le cœur de pierre, et je leur donnerai un cœur de chair,'),
('ez',11,20,'crampon1923','afin qu''ils suivent mes ordonnances, et qu''ils gardent mes lois et les pratiquent; et ils seront mon peuple, et moi je serai leur Dieu.'),
('ez',11,21,'crampon1923','Quant à ceux dont le cœur suit le cœur de leurs idoles abominables, je ferai retomber leurs œuvres sur leurs têtes, — oracle du Seigneur Yahweh.'),
('ez',11,22,'crampon1923','Alors les Chérubins dressèrent leurs ailes, et les roues se mirent en mouvement avec eux, et la gloire du Dieu d''Israël reposait au-dessus d''eux.'),
('ez',11,23,'crampon1923','Et la gloire de Yahweh, s''élevant de dessus le milieu de la ville, s''arrêta sur la montagne qui est à l''orient de la ville.'),
('ez',11,24,'crampon1923','Et l''Esprit m''enleva et m''emmena en Chaldée auprès des captifs, en vision, dans l''esprit de Dieu; et la vision que j''avais eue disparut de devant moi.'),
('ez',11,25,'crampon1923','Et je racontai aux captifs toutes les choses que Yahweh m''avait fait voir.'),
('ez',12,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',12,2,'crampon1923','Fils de l''homme, tu habites au milieu d''une maison de rebelles, qui ont des yeux pour voir et qui ne voient point, qui ont des oreilles pour entendre et n''entendent point; car ils sont une maison de rebelles.'),
('ez',12,3,'crampon1923','Et toi, fils de l''homme, fais-toi un bagage d''émigrant, et émigre de jour, à leurs yeux; émigre, à leurs yeux, du lieu où tu es dans un autre lieu: peut-être verront-ils qu''ils sont une maison de rebelles.'),
('ez',12,4,'crampon1923','Sors ton bagage, comme un bagage d''émigrant, de jour, à leurs yeux; et toi, pars le soir, à leurs yeux, comme on part pour émigrer.'),
('ez',12,5,'crampon1923','A leurs yeux, creuse un trou dans la muraille et sors par là ton bagage.'),
('ez',12,6,'crampon1923','A leurs yeux, mets-le sur ton épaule, emporte-le dans l''obscurité; voile-toi le visage, en sorte que tu ne voies pas la terre; car je t''ai établi comme un signe pour la maison d''Israël. "'),
('ez',12,7,'crampon1923','Je fis ainsi, selon que j''en avais reçu l''ordre; je sortis de jour mon bagage, comme un bagage d''émigrant; le soir, je perçai de ma main un trou dans la muraille; et je fis sortir le bagage dans l''obscurité, je le portai sur mes épaules, à leurs yeux.'),
('ez',12,8,'crampon1923','Le matin, la parole de Yahweh me fut adressée en ces termes:'),
('ez',12,9,'crampon1923','" Fils de l''homme, la maison d''Israël, la maison de rebelles, ne t''a-t-elle pas dit: Que fais-tu?'),
('ez',12,10,'crampon1923','Dis-leur: Ainsi parle le Seigneur Yahweh: Cet oracle est pour le prince qui est à Jérusalem, et pour toute la maison d''Israël qui se trouve dans cette ville.'),
('ez',12,11,'crampon1923','Dis: Je suis pour vous un emblème: comme j''ai fait, ainsi il leur sera fait, ils iront en exil, en captivité.'),
('ez',12,12,'crampon1923','Le prince qui est au milieu d''eux mettra son bagage sur son épaule dans l''obscurité et partira; on creusera un trou dans la muraille pour le faire sortir; il se voilera le visage, en sorte qu''il ne voie pas de ses yeux la terre.'),
('ez',12,13,'crampon1923','J''étendrai mon filet sur lui, et il sera pris dans mes rets; je l''emmènerai à Babylone, au pays des Chaldéens; mais il ne le verra point, et là il mourra.'),
('ez',12,14,'crampon1923','Tous ceux qui l''entourent, ses auxiliaires et tous ses bataillons, je les disperserai à tout vent, et je les poursuivrai l''épée nue.'),
('ez',12,15,'crampon1923','Et ils sauront que je suis Yahweh, quand je les aurai répandus parmi les nations; et dispersés dans les pays.'),
('ez',12,16,'crampon1923','Et je laisserai d''entre eux un petit nombre d''hommes qui échapperont à l''épée, à la famine et à la peste, pour qu''ils racontent leurs abominations parmi les nations où ils iront; et ils sauront que je suis Yahweh. "'),
('ez',12,17,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',12,18,'crampon1923','" Fils de l''homme, tu mangeras ton pain dans l''agitation, et tu boiras ton eau dans l''inquiétude et l''angoisse.'),
('ez',12,19,'crampon1923','Et tu diras au peuple du pays: Ainsi parle le Seigneur Yahweh pour les habitants de Jérusalem, pour la terre d''Israël: Ils mangeront leur pain dans l''angoisse, et ils boiront leur eau dans la désolation, parce que le pays sera dépeuplé de tout ce qu''il contient, à cause de la violence de tous ceux qui l''habitent.'),
('ez',12,20,'crampon1923','Les villes qui sont habitées seront désertes, le pays sera désolé, et vous saurez que je suis Yahweh. "'),
('ez',12,21,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',12,22,'crampon1923','" Fils de l''homme, qu''est-ce que ce dicton que vous répétez sur la terre d''Israël: Les jours se prolongent; toute vision reste sans effet?'),
('ez',12,23,'crampon1923','C''est pourquoi dis-leur: Ainsi parle le Seigneur Yahweh je ferai cesser ce dicton, et on ne le prononcera plus en Israël. Dis-leur au contraire: Les jours sont proches ainsi que la réalisation de toute parole de vision.'),
('ez',12,24,'crampon1923','Car il n''y aura plus de vision de mensonge, ni de divination trompeuse, au milieu de la maison d''Israël.'),
('ez',12,25,'crampon1923','Car moi, Yahweh, je parlerai; la parole que je dirai s''accomplira; elle ne sera plus différée. Oui, c''est en vos jours, maison rebelle, que je dirai la parole et que je l''exécuterai. — oracle du Seigneur Yahweh. "'),
('ez',12,26,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',12,27,'crampon1923','" Fils de l''homme, voici que la maison d''Israël dit: La vision qu''il voit est pour des jours lointains, et c''est pour des temps éloignés qu''il prophétise.'),
('ez',12,28,'crampon1923','C''est pourquoi dis-leur: Ainsi parle le Seigneur Yahweh: Aucune de mes paroles ne sera plus différée; la parole que je dis va s''accomplir, — oracle du Seigneur Yahweh. "'),
('ez',13,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',13,2,'crampon1923','" Fils de l''homme, prophétise contre les prophètes d''Israël, qui prophétisent, et dis à ceux qui prophétisent de leur chef: Ecoutez la parole de Yahweh:'),
('ez',13,3,'crampon1923','Ainsi parle le Seigneur Yahweh: Malheur aux prophètes insensés, qui suivent leur propre esprit, sans rien voir!'),
('ez',13,4,'crampon1923','Comme des renards dans des ruines, tels sont tes prophètes, ô Israël.'),
('ez',13,5,'crampon1923','Vous n''êtes pas montés aux brèches, et vous n''avez pas élevé de muraille autour de la maison d''Israël, pour tenir ferme dans la bataille, au jour de Yahweh.'),
('ez',13,6,'crampon1923','Ils ont des visions vaines, et des divinations de mensonge, ceux qui disent: Oracle de Yahweh, sans que Yahweh les ait envoyés, et qu''ils puissent espérer l''accomplissement de leur parole.'),
('ez',13,7,'crampon1923','N''est-ce pas des visions vaines que vous voyez, des divinations mensongères que vous prononcez, quand vous dites: Oracle de Yahweh! et moi, je n''ai point parlé?'),
('ez',13,8,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce que vous proférez la vanité, et que vous avez des visions de mensonge, voici que je viens à vous, — oracle du Seigneur Yahweh.'),
('ez',13,9,'crampon1923','Ma main sera sur les prophètes qui ont des visions vaines et des divinations de mensonge: ils ne seront pas dans le conseil de mon peuple; ils ne seront pas inscrits dans le livre de la maison d''Israël, et ils n''entreront pas dans la terre d''Israël, — et vous saurez que je suis le Seigneur Yahweh, —'),
('ez',13,10,'crampon1923','attendu qu''ils ont égaré mon peuple en disant: Paix! quand il n''y avait pas de paix. Mon peuple construit un mur et voici qu''ils le couvrent de plâtre!'),
('ez',13,11,'crampon1923','Dis à ceux qui enduisent de plâtre, que le mur tombera. Viendra une pluie violente: Tombez, pierres de grêle! Vent des tempêtes, éclate!'),
('ez',13,12,'crampon1923','Voici que le mur est tombé! Ne vous dira-t-on pas: Où est le plâtre dont vous l''aviez couvert?'),
('ez',13,13,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Dans mon courroux, je déchaînerai un vent de tempêtes; dans ma colère, je ferai venir une pluie violente, et, dans mon courroux, des pierres de grêle pour exterminer.'),
('ez',13,14,'crampon1923','J''abattrai le mur que vous avez couvert de plâtre, je le renverserai par terre, et le fondement en sera mis à nu; il tombera, et vous périrez au milieu de ses décombres, et vous saurez que je suis Yahweh.'),
('ez',13,15,'crampon1923','J''assouvirai ma colère contre le mur, et contre ceux qui l''ont couvert de plâtre, et je vous dirai: Plus de mur! Plus de ces gens qui le replâtraient,'),
('ez',13,16,'crampon1923','de ces prophètes d''Israël qui prophétisaient sur Jérusalem et qui voyaient pour elle des visions de paix, quand il n''y avait point de paix, — oracle du Seigneur Yahweh! "'),
('ez',13,17,'crampon1923','" Et toi, fils de l''homme, tourne ta face contre les filles de ton peuple qui prophétisent de leur propre chef, et prophétise contre elles,'),
('ez',13,18,'crampon1923','et dis: Ainsi parle le Seigneur Yahweh: Malheur à celles qui cousent des coussins pour toutes les jointures des mains, et qui font des oreillers pour toutes les têtes de toute taille, pour prendre les âmes au piège. Vous prendriez au piège les âmes de mon peuple, et vos âmes, à vous, vivraient!'),
('ez',13,19,'crampon1923','Vous m''avez déshonoré auprès de mon peuple, pour une poignée d''orge et pour un morceau de pain, faisant mourir des âmes qui ne doivent point mourir, et faisant vivre des âmes qui ne doivent point vivre, trompant ainsi mon peuple qui écoute le mensonge.'),
('ez',13,20,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que j''en veux à vos coussins, par lesquels vous prenez les âmes au piège, et je les ferai s''envoler; ces coussins, je les déchirerai de dessus vos bras, et je délivrerai les âmes que vous prenez au piège, afin qu''elles s''envolent.'),
('ez',13,21,'crampon1923','Je déchirerai vos oreillers, et j''arracherai mon peuple de vos mains, et ils ne seront plus une proie dans vos mains, et vous saurez que je suis Yahweh.'),
('ez',13,22,'crampon1923','Parce que vous affligez le cœur du juste par des mensonges, quand moi-même je ne l''ai pas affligé, et que vous affermissez les mains du méchant, en sorte qu''il ne revienne pas de sa voie mauvaise, pour vivre,'),
('ez',13,23,'crampon1923','à cause de cela, vous n''aurez plus de visions vaines, et vous n''aurez plus de divinations; j''arracherai mon peuple de vos mains, et vous saurez que je suis Yahweh. "'),
('ez',14,1,'crampon1923','Quelques-uns des anciens d''Israël vinrent auprès de moi et s''assirent devant moi.'),
('ez',14,2,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('ez',14,3,'crampon1923','" Fils de l''homme, ces gens-là ont dressé dans leur cœur leurs infâmes idoles, et ils mettent devant leur face le scandale qui les fait pécher: me laisserai-je interroger par eux?'),
('ez',14,4,'crampon1923','C''est pourquoi parle-leur et dis-leur: Ainsi parle le Seigneur Yahweh: Quiconque de la maison d''Israël dresse en son cœur ses infâmes idoles et met devant sa face le scandale qui le fait pécher, s''il vient vers le prophète, moi, Yahweh, je lui répondrai par moi-même, comme le mérite la multitude de ses idoles,'),
('ez',14,5,'crampon1923','afin de prendre la maison d''Israël par son propre cœur, elle qui, avec toutes ses idoles infâmes, s''est détournée de moi.'),
('ez',14,6,'crampon1923','C''est pourquoi dis à la maison d''Israël: Ainsi parle le Seigneur Yahweh: Revenez et détournez-vous de vos idoles infâmes, et détournez votre face de toutes vos abominations.'),
('ez',14,7,'crampon1923','Car quiconque de la maison d''Israël ou des étrangers séjournant en Israël se détourne de moi, dresse dans son cœur ses infâmes idoles et met devant sa face le scandale qui le fait pécher, s''il vient vers le prophète afin qu''il m''interroge pour lui, moi Yahweh je lui répondrai moi-même.'),
('ez',14,8,'crampon1923','Je dirigerai ma face contre cet homme, je le détruirai pour faire de lui un signe et un proverbe; je le retrancherai du milieu de mon peuple, et vous saurez que je suis Yahweh.'),
('ez',14,9,'crampon1923','Et si le prophète se laisse séduire et qu''il prononce quelque parole, c''est moi, Yahweh, qui aurai séduit ce prophète; et j''étendrai ma main sur lui, et je l''exterminerai du milieu de mon peuple d''Israël.'),
('ez',14,10,'crampon1923','Ils porteront ainsi la peine de leur iniquité, — telle l''iniquité de celui qui interroge, telle l''iniquité du prophète, —'),
('ez',14,11,'crampon1923','afin que la maison d''Israël ne s''égare plus loin de moi, et qu''elle ne se souille plus par toutes ses transgressions. Alors ils seront mon peuple, et moi je serai leur Dieu, — oracle du Seigneur Yahweh. "'),
('ez',14,12,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',14,13,'crampon1923','" Fils de l''homme, si un pays péchait contre moi par révolte, et si j''étendais ma main sur lui en brisant pour lui le bâton du pain, et si je lui envoyais la famine, en exterminant hommes et bêtes,'),
('ez',14,14,'crampon1923','et qu''il y eut ces trois hommes au milieu de ce pays, Noé, Daniel et Job,... eux sauveraient leur âme par leur justice, — oracle du Seigneur Yahweh.'),
('ez',14,15,'crampon1923','Si je faisais passer dans le pays des bêtes malfaisantes, et qu''il fût dépeuplé, et qu''il devint un désert où personne ne passerait à cause des bêtes,'),
('ez',14,16,'crampon1923','et qu''il y eût ces trois hommes au milieu de ce pays, je suis vivant, — oracle du Seigneur Yahweh: Ils ne sauveraient ni fils ni filles; eux seuls seraient sauvés, mais le pays serait dévasté.'),
('ez',14,17,'crampon1923','Ou si je faisais venir l''épée sur ce pays, et que je dise: Que l''épée passe sur le pays!... en exterminant hommes et bêtes,'),
('ez',14,18,'crampon1923','et qu''il y eût ces trois hommes au milieu de ce pays, je suis vivant, — oracle du Seigneur Yahweh: Ils ne sauveraient ni fils, ni filles; eux seuls seraient sauvés.'),
('ez',14,19,'crampon1923','Ou si j''envoyais la peste sur ce pays, et que je répandisse sur lui mon courroux dans le sang, en exterminant hommes et bêtes,'),
('ez',14,20,'crampon1923','et que Noé, Daniel et Job fussent au milieu de ce pays, je suis vivant, — oracle du Seigneur Yahweh: Ils ne sauveraient ni fils, ni filles, mais eux sauveraient leur âme par leur justice.'),
('ez',14,21,'crampon1923','Car ainsi parle le Seigneur Yahweh: Même quand j''aurai envoyé contre Jérusalem mes quatre châtiments terribles, l''épée, la famine, les bêtes malfaisantes et la peste, en exterminant hommes et bêtes,'),
('ez',14,22,'crampon1923','voici qu''il y aura un reste qui échappera, qui sortira de la ville, des fils et des filles. Voici qu''ils viendront vers vous; vous verrez leur conduite et leurs œuvres, et vous vous consolerez du mal que j''aurai fait venir sur Jérusalem, de tout ce que j''aurai fait venir sur elle.'),
('ez',14,23,'crampon1923','Ils vous consoleront, quand vous verrez leur conduite et leurs œuvres, et vous saurez que ce n''est pas sans cause que j''aurai fait tout ce que je lui aurai fait, — oracle du Seigneur Yahweh. "'),
('ez',15,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',15,2,'crampon1923','" Fils de l''homme, en quoi le bois de la vigne vaut-il plus que tout autre bois, que le rameau qui est parmi les arbres de la forêt?'),
('ez',15,3,'crampon1923','En prend-on du bois, pour en fabriquer un ouvrage? En tire-t-on une cheville, pour y suspendre quelque objet?'),
('ez',15,4,'crampon1923','Voici qu''on le livre au feu pour qu''il le consume; le feu en dévore les deux bouts, et le milieu brûle: sera-t-il bon a quelque usage?'),
('ez',15,5,'crampon1923','Voici que, lorsqu''il était entier, il n''était employé à aucun ouvrage: combien moins, quand le feu l''a consumé et brûlé, pourrait-on l''employer à quelque usage?'),
('ez',15,6,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Tel que le bois de la vigne parmi les bois de la forêt, ce bois que je livre au feu pour le consumer, tels je livrerai les habitants de Jérusalem.'),
('ez',15,7,'crampon1923','Je dirigerai ma face contre eux; ils ont échappé au feu, et le feu les consumera, et vous saurez que je suis Yahweh, quand je tournerai ma face contre eux.'),
('ez',15,8,'crampon1923','Et je ferai du pays un désert, parce qu''ils ont été infidèles, — oracle du Seigneur Yahweh. "'),
('ez',16,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',16,2,'crampon1923','" Fils de l''homme, fais connaître à Jérusalem ses abominations'),
('ez',16,3,'crampon1923','et dis: Ainsi parle le Seigneur Yahweh, à Jérusalem: Par ton origine et ta naissance, tu es de la terre du Chananéen; ton père était l''Amorrhéen et ta mère une Héthéenne.'),
('ez',16,4,'crampon1923','Quant à ta naissance, le jour où tu naquis, ton cordon n''a pas été coupé, et tu n''as pas été baignée dans l''eau pour être purifiée; tu n''as pas été frottée de sel, ni enveloppée de langes.'),
('ez',16,5,'crampon1923','Aucun œil n''eut pitié du toi pour te rendre un seul de ces soins, par compassion pour toi; mais on te jeta, par dégoût de toi, sur la face des champs, le jour de ta naissance.'),
('ez',16,6,'crampon1923','Je passai près de toi et je te vis te débattant dans ton sang, et je te dis: Vis dans ton sang.'),
('ez',16,7,'crampon1923','Je te fis multiplier comme l''herbe des champs; tu te multiplias et tu grandis; tu acquis une beauté parfaite; tes seins se formèrent et tu arrivas à la puberté; mais tu étais nue, entièrement nue.'),
('ez',16,8,'crampon1923','Et je passai près de toi et je te vis; et voici que ton temps était venu, le temps des amours; j''étendis sur toi le pan de mon manteau et je couvris ta nudité; je te fis un serment et j''entrai en alliance avec toi, — oracle du Seigneur Yahweh, — et tu fus à moi.'),
('ez',16,9,'crampon1923','Je te baignai dans l''eau, et je lavai ton sang de dessus toi, et je t''oignis d''huile.'),
('ez',16,10,'crampon1923','Je te vêtis de broderie, et je te chaussai de peau de veau marin; je ceignis ta tête d''un voile de lin, et je te couvris de soie.'),
('ez',16,11,'crampon1923','Je t''ornai d''une parure: je mis des bracelets à tes mains, et un collier à ton cou;'),
('ez',16,12,'crampon1923','je mis à ton nez un anneau, des boucles à tes oreilles, et sur ta tête un magnifique diadème.'),
('ez',16,13,'crampon1923','Tu t''ornas d''or et d''argent, et tu fus vêtue de lin, de soie et de broderie; la fleur de froment, le miel et l''huile étaient ta nourriture; tu devins extraordinairement belle, et tu arrivas à la dignité royale.'),
('ez',16,14,'crampon1923','Ton nom se répandit parmi les nations à cause de ta beauté; car elle était parfaite, grâce à ma splendeur que j''avais répandue sur toi, — oracle du Seigneur Yahweh.'),
('ez',16,15,'crampon1923','Mais tu mis ta confiance en ta beauté, et tu te prostituas à la faveur de ton nom; tu prodiguas tes amours à tout passant, te livrant à lui.'),
('ez',16,16,'crampon1923','Et tu as pris de tes vêtements, et tu t''en es fait des hauts lieux aux couleurs variées, et tu t''es prostituée dessus: ce qui ne s''était jamais fait et ne se fera jamais.'),
('ez',16,17,'crampon1923','Tu as pris tes bijoux, faits de mon or et de mon argent que je t''avais donnés, et tu t''en es fait des images d''hommes, auxquelles tu t''es prostituée.'),
('ez',16,18,'crampon1923','Tu as pris tes vêtements brodés et tu les en as couvertes, et tu as mis devant elles mon huile et mon encens.'),
('ez',16,19,'crampon1923','Mon pain que je t''avais donné, la fleur de froment, l''huile et le miel dont je te nourrissais, tu les as mis devant elles en offrande d''agréable odeur. Voilà ce qui s''est fait, — oracle du Seigneur Yahweh.'),
('ez',16,20,'crampon1923','Tu as pris tes fils et tes filles que tu m''avais enfantés; tu les leur a offerts en sacrifice pour qu''ils les dévorassent. Etait-ce trop peu de tes prostitutions,'),
('ez',16,21,'crampon1923','que tu aies égorgé mes fils, et que tu les leur aies livrés, en les faisant passer par le feu en leur honneur?'),
('ez',16,22,'crampon1923','Et au milieu de toutes tes abominations et de tes prostitutions, tu ne t''es pas souvenue des jours de ta jeunesse, quand tu étais nue, complètement nue, te débattant dans ton sang.'),
('ez',16,23,'crampon1923','Après toutes tes méchantes actions, — malheur, malheur à toi! oracle du Seigneur Yahweh —'),
('ez',16,24,'crampon1923','tu t''es construit une voûte et tu t''es fait un tertre sur toutes les places.'),
('ez',16,25,'crampon1923','A chaque carrefour tu as élevé ton tertre; tu as souillé ta beauté; tu t''es livrée à tout passant, tu as multiplié tes prostitutions.'),
('ez',16,26,'crampon1923','Tu t''es prostituée aux fils de l''Egypte, tes voisins, aux membres vigoureux, et tu as multiplié tes prostitutions pour m''irriter.'),
('ez',16,27,'crampon1923','Et voici que j''ai étendu ma main sur toi; j''ai diminué ta portion; je t''ai livrée au bon plaisir de tes ennemies, les filles des Philistins, qui ont rougi de ta conduite criminelle.'),
('ez',16,28,'crampon1923','Et tu t''es prostituée aux fils d''Assur, parce que tu n''étais pas rassasiée; et, après t''être prostituée à eux, tu n''as pas encore été rassasiée.'),
('ez',16,29,'crampon1923','Et tu as multiplié tes prostitutions dans le pays de Chanaan jusqu''en Chaldée, et avec cela tu n''as pas encore été rassasiée.'),
('ez',16,30,'crampon1923','Oh! que ton cœur est faible, — oracle du Seigneur Yahweh, — pour que tu aies fait toutes ces choses, ce que fait la prostituée la plus dévergondée!'),
('ez',16,31,'crampon1923','Quand tu construisais ta voûte à chaque carrefour et que tu faisais ton tertre à chaque place, tu n''étais pas comme la prostituée, car tu dédaignais le salaire;'),
('ez',16,32,'crampon1923','tu étais la femme adultère, qui prend des étrangers à la place de son mari.'),
('ez',16,33,'crampon1923','A toutes les prostituées on donne des présents; mais toi, tu as donné tes présents à tous tes amants, tu les as payés, pour qu''ils viennent vers toi, de toutes parts, pour tes prostitutions.'),
('ez',16,34,'crampon1923','Il t''est arrivé, dans tes prostitutions, le contraire de ce qui arrive aux autres femmes: personne ne te recherchait. En donnant des présents alors qu''on ne t''en faisait pas, tu as été au rebours des autres.'),
('ez',16,35,'crampon1923','C''est pourquoi, prostituée, écoute la parole de Yahweh:'),
('ez',16,36,'crampon1923','Ainsi parle le Seigneur Yahweh: Parce que ton airain a été répandu et que ta nudité a été découverte, dans tes prostitutions avec tes amants et avec toutes tes abominables idoles, et à cause du sang de tes enfants que tu leur as donnés,'),
('ez',16,37,'crampon1923','à cause de cela voici que je rassemblerai tous tes amants avec lesquels tu as eu commerce, tous ceux que tu as aimés, avec tous ceux que tu as haïs; je vais les rassembler contre toi de toutes parts; je découvrirai ta nudité devant eux, et ils verront toute ta nudité.'),
('ez',16,38,'crampon1923','Je te jugerai selon le droit des femmes adultères et de celles qui répandent le sang; et je ferai de toi une victime sanglante de fureur et de jalousie.'),
('ez',16,39,'crampon1923','Je te livrerai entre leurs mains; ils abattront ta voûte et démoliront tes hauts lieux; ils te dépouilleront de tes vêtements, prendront tes bijoux et te laisseront nue, complètement nue.'),
('ez',16,40,'crampon1923','Ils feront monter contre toi une assemblée; ils te lapideront et te perceront de leurs épées.'),
('ez',16,41,'crampon1923','Ils brûleront tes maisons par le feu et ils exécuteront contre toi des jugements, sous les yeux de beaucoup de femmes; je ferai cesser tes prostitutions, et tu ne feras plus de présents.'),
('ez',16,42,'crampon1923','J''assouvirai sur toi mon courroux, et ma jalousie s''éloignera de toi; je m''apaiserai et ne serai plus irrité.'),
('ez',16,43,'crampon1923','Parce que tu ne t''es pas souvenue des jours de ta jeunesse et que tu m''as irrité par tous ces excès, voici que moi, à mon tour, je ferai retomber ta conduite sur ta tête, — oracle du Seigneur Yahweh; et tu ne commettras plus l''impudicité avec toutes tes abominations.'),
('ez',16,44,'crampon1923','Voici que tous ceux qui disent des proverbes en feront à ton sujet en disant:'),
('ez',16,45,'crampon1923','Telle mère, telle fille! Tu es bien la fille de ta mère qui a rejeté son mari et ses enfants, et tu es la sœur de tes sœurs qui ont rejeté leurs maris et leurs enfants; votre mère est une Héthéenne, et votre père un Amorrhéen.'),
('ez',16,46,'crampon1923','Ta grande sœur, qui demeure à ta gauche, c''est Samarie avec ses filles; et ta petite sœur, qui demeure à ta droite, c''est Sodome avec ses filles.'),
('ez',16,47,'crampon1923','Tu n''as pas seulement marché dans leurs voies et agi selon leurs abominations: c''était trop peu; tu t''es corrompue plus qu''elles dans toutes tes voies.'),
('ez',16,48,'crampon1923','Je suis vivant, — oracle du Seigneur Yahweh: Sodome, ta sœur, elle et ses filles, n''ont pas fait ce que tu as fait, toi, et tes filles.'),
('ez',16,49,'crampon1923','Voici quel fut le crime de Sodome, ta sœur: l''orgueil, l''abondance et l''insouciant repos où elle vivait avec ses filles, et elle ne soutenait pas la main du malheureux et de l''indigent.'),
('ez',16,50,'crampon1923','Elles sont devenues orgueilleuses, et elles ont commis l''abomination devant moi, et je les ai fait disparaître quand j''ai vu cela.'),
('ez',16,51,'crampon1923','Samarie n''a pas commis la moitié de tes péchés; tu as multiplié tes abominations plus qu''elles ne l''avaient fait, et tu as justifié tes sœurs par toutes tes abominations que tu as commises.'),
('ez',16,52,'crampon1923','Porte donc, toi aussi, ton opprobre, que tu rejetais sur tes sœurs, à cause de tes péchés par lesquels tu t''es rendue plus abominable qu''elles; elles sont plus justes que toi. Toi aussi, sois couverte de confusion et porte ton opprobre, puisque tu as justifié tes sœurs.'),
('ez',16,53,'crampon1923','Je ramènerai leurs captifs, les captifs de Sodome et de ses filles, les captifs de Samarie et de ses filles, et tes captifs parmi les leurs,'),
('ez',16,54,'crampon1923','afin que tu portes ton opprobre et que tu sois confuse de tout ce que tu as fait pour les consoler.'),
('ez',16,55,'crampon1923','Ta sœur Sodome et ses filles reviendront à leur premier état, Samarie et ses filles reviendront à leur premier état; et toi et tes filles, vous reviendrez à votre premier état.'),
('ez',16,56,'crampon1923','Ta sœur Sodome n''était pas nommée par ta bouche aux jours de ton orgueil,'),
('ez',16,57,'crampon1923','avant que ta perversité fut mise à nu, comme au temps où tu fus outragée par les filles de la Syrie et de tous ses alentours, par les filles des Philistins qui t''insultaient autour de toi.'),
('ez',16,58,'crampon1923','Ton crime et tes abominations, tu en as porté la peine, — oracle de Yahweh.'),
('ez',16,59,'crampon1923','Car ainsi parle le Seigneur Yahweh: J''agirai avec toi comme tu as agi, toi qui as méprisé ton serment en rompant l''alliance.'),
('ez',16,60,'crampon1923','Mais moi, je me souviendrai de mon alliance que j''ai contractée avec toi aux jours de ta jeunesse, et j''établirai avec toi une alliance éternelle.'),
('ez',16,61,'crampon1923','Tu te souviendras de ta conduite et tu en auras honte, quand tu recevras tes sœurs, celles qui sont plus grandes que toi avec celles qui sont plus petites que toi, et que je te les donnerai pour filles, mais non en vertu de ton alliance.'),
('ez',16,62,'crampon1923','J''établirai mon alliance avec toi, et tu sauras que je suis Yahweh,'),
('ez',16,63,'crampon1923','afin que tu te souviennes et que tu rougisses, afin que tu n''ouvres plus la bouche à cause de ta confusion, quand je ferai l''expiation pour toi, pour tout ce que tu as fait, — oracle du Seigneur Yahweh. "'),
('ez',17,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',17,2,'crampon1923','" Fils de l''homme, propose une énigme et raconte une parabole à la maison d''Israël,'),
('ez',17,3,'crampon1923','et dis: Ainsi parle le Seigneur Yahweh: Le grand aigle, aux grandes ailes, à la large envergure, et couvert d''un plumage aux couleurs variées, vint vers le Liban et enleva la cime du cèdre.'),
('ez',17,4,'crampon1923','Il arracha le plus élevé de ses rameaux, l''emporta dans un pays de Chanaan et le plaça dans une ville de marchands.'),
('ez',17,5,'crampon1923','Puis il prit du plant du pays et le plaça dans un sol fertile; il le mit près d''une eau abondante et le planta comme un saule.'),
('ez',17,6,'crampon1923','Ce rejeton poussa et devint un cep de vigne étendu, peu élevé; ses rameaux étaient tournés vers l''aigle et ses racines étaient sous lui; il devint un cep, donna des jets et poussa des branches.'),
('ez',17,7,'crampon1923','Il y avait un autre grand aigle, aux grandes ailes, au plumage abondant; et voici que cette vigne étendit avidement ses racines vers lui, et que, du parterre où elle était plantée, elle poussa vers lui ses rameaux pour qu''il l''arrosât.'),
('ez',17,8,'crampon1923','Elle était plantée dans une bonne terre, auprès d''eaux abondantes, de manière à pousser du feuillage et à porter du fruit, pour devenir une vigne magnifique.'),
('ez',17,9,'crampon1923','Dis: Ainsi parle le Seigneur Yahweh: Prospérera-t-elle? N''arrachera-t-on pas ses racines et n''abattra-t-on pas son fruit pour qu''elle sèche? Toutes les jeunes feuilles qu''elle poussait se dessécheront. Il ne faudra ni un bras puissant ni beaucoup de gens pour l''enlever de ses racines.'),
('ez',17,10,'crampon1923','Et voici qu''elle est plantée; mais prospérera-t-elle? Dès que le vent d''Orient l''aura touchée, ne séchera-t-elle pas? Dans le parterre où elle a poussé, elle séchera. "'),
('ez',17,11,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',17,12,'crampon1923','" Dis donc à la maison rebelle: Ne savez-vous pas ce que cela signifie? Dis: Voici que le roi de Babylone est allé à Jérusalem, qu''il a pris son roi et ses chefs et les a fait venir auprès de lui à Babylone.'),
('ez',17,13,'crampon1923','Puis il a pris un homme de la race royale, il a conclu une alliance avec lui et lui a fait prêter serment. Il avait pris les hommes puissants du pays,'),
('ez',17,14,'crampon1923','pour que le royaume fût dans l''abaissement, sans pouvoir s''élever, observant son alliance pour subsister.'),
('ez',17,15,'crampon1923','Mais il s''est révolté contre lui, envoyant ses messagers en Egypte pour qu''on lui donnât des chevaux et beaucoup d''hommes. Réussira-t-il? Echappera-t-il, celui qui fait de telles choses? Il a rompu l''alliance, et il échapperait!'),
('ez',17,16,'crampon1923','Je suis vivant, — oracle du Seigneur Yahweh: C''est dans la ville du roi qui l''a fait régner, dont il a méprisé le serment et dont il a rompu l''alliance, c''est chez lui, dans Babylone, qu''il mourra.'),
('ez',17,17,'crampon1923','Et le pharaon n''agira pas pour lui, dans la guerre, avec une grande armée et un peuple nombreux, quand on élèvera des terrasses et qu''on construira des murs pour faire périr beaucoup d''hommes!'),
('ez',17,18,'crampon1923','Il a méprisé le serment en rompant l''alliance, et voilà qu''il avait donné sa main! Il a fait tout cela, il n''échappera pas.'),
('ez',17,19,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Je suis vivant: c''est mon serment qu''il a méprisé, et mon alliance qu''il a rompue; je ferai retomber cela sur sa tête.'),
('ez',17,20,'crampon1923','J''étendrai sur lui mon rets, et il sera pris dans mon filet; je le ferai venir à Babylone, et là je le mettrai en cause pour sa perfidie qu''il a montrée envers moi.'),
('ez',17,21,'crampon1923','Tous ses fuyards de toutes ses troupes tomberont par l''épée, et ceux qui resteront seront dispersés à tout vent; et vous saurez que moi, Yahweh, j''ai parlé.'),
('ez',17,22,'crampon1923','Ainsi parle le Seigneur Yahweh: Je prendrai, moi, un rameau de la cime du cèdre élevé et je le placerai; de l''extrémité de ses branches je couperai un tendre rameau, et je le planterai sur une montagne haute et élevée.'),
('ez',17,23,'crampon1923','Je le planterai sur la haute montagne d''Israël; il poussera des branches et portera du fruit, et il deviendra un cèdre majestueux; tout passereau, tout oiseau habitera sous lui; ils habiteront à l''ombre de ses rameaux.'),
('ez',17,24,'crampon1923','Et tous les arbres des champs sauront que moi, Yahweh, j''ai abaissé l''arbre qui était élevé, et élevé l''arbre qui était abaissé, que j''ai fait sécher l''arbre vert et fait verdir l''arbre sec. Moi, Yahweh, j''ai parlé et j''agirai. "'),
('ez',18,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',18,2,'crampon1923','" Pourquoi donc proférez-vous ce proverbe, au sujet du pays d''Israël: " Les pères mangent du verjus, et les dents des fils en sont agacées? "'),
('ez',18,3,'crampon1923','Je suis vivant, — oracle du Seigneur Yahweh: Vous n''aurez plus lieu de proférer ce proverbe en Israël.'),
('ez',18,4,'crampon1923','Voici que toutes les âmes sont à moi: l''âme du fils comme l''âme du père est à moi; l''âme qui pèche sera celle qui mourra.'),
('ez',18,5,'crampon1923','Si un homme est juste et pratique le droit et la justice;'),
('ez',18,6,'crampon1923','s''il ne mange pas sur les montagnes et n''élève pas les yeux vers les idoles infâmes de la maison d''Israël; s''il ne déshonore pas la femme de son prochain et ne s''approche pas d''une femme pendant sa souillure;'),
('ez',18,7,'crampon1923','s''il n''opprime personne, s''il rend au débiteur son gage, s''il ne commet pas de rapines, s''il donne son pain à celui qui a faim et couvre d''un vêtement celui qui est nu;'),
('ez',18,8,'crampon1923','s''il ne prête pas à usure et ne prend pas d''intérêt; s''il détourne sa main de l''iniquité; s''il juge selon la vérité entre un homme et un autre;'),
('ez',18,9,'crampon1923','s''il suit mes préceptes et observe mes lois, en agissant avec fidélité, celui-là est juste; il vivra — oracle du Seigneur Yahweh.'),
('ez',18,10,'crampon1923','Mais cet homme engendre un fils violent, qui verse le sang et qui fait à son frère quelqu''une de ces choses,'),
('ez',18,11,'crampon1923','— mais lui-même n''a pas fait toutes ces choses; — il mange sur les montagnes, il déshonore la femme de son prochain, il opprime le pauvre et le malheureux;'),
('ez',18,12,'crampon1923','il commet des rapines, il ne rend pas le gage, il lève les yeux vers les idoles, il commet une abomination;'),
('ez',18,13,'crampon1923','il prête à usure et prend un intérêt, et il vivrait!... Il ne vivra pas; il a commis toutes ces abominations, il doit mourir; son sang sera sur lui.'),
('ez',18,14,'crampon1923','Mais voici qu''un homme a engendré un fils; ce fils a vu tous les péchés qu''a commis son père; il les a vus et n''a rien fait de semblable.'),
('ez',18,15,'crampon1923','Il n''a pas mangé sur les montagnes, il n''a pas levé les yeux vers les idoles infâmes de la maison d''Israël; il n''a pas déshonoré la femme de son prochain;'),
('ez',18,16,'crampon1923','il n''a opprimé personne et n''a pas pris de gage, il n''a pas commis de rapines; il a donné son pain à l''affamé, il a couvert d''un vêtement celui qui était nu;'),
('ez',18,17,'crampon1923','il n''a pas fait peser sa main sur le pauvre, il n''a pris ni usure, ni intérêt; il a observé mes lois et suivi mes préceptes, — celui-là ne mourra point pour l''iniquité de son père; il vivra certainement.'),
('ez',18,18,'crampon1923','Son père qui a multiplié la violence, qui a pratiqué la rapine envers son frère et qui a fait ce qui n''était pas bien au milieu de son peuple, voici que lui, il mourra pour son iniquité.'),
('ez',18,19,'crampon1923','Et vous dites: " Pourquoi le fils ne porte-t-il pas l''iniquité de son père? " Mais le fils a agi suivant le droit et la justice, il a observé tous mes préceptes et les a mis en pratique: il vivra certainement.'),
('ez',18,20,'crampon1923','L''âme qui pèche, c''est elle qui mourra; le fils ne portera pas l''iniquité du père, et le père ne portera pas l''iniquité du fils; la justice du juste sera sur lui, et la méchanceté du méchant sera sur lui.'),
('ez',18,21,'crampon1923','Quant au méchant, s''il se détourne de tous ses péchés qu''il commis, s''il observe tous mes préceptes et agit selon le droit et la justice, il vivra, il ne mourra pas.'),
('ez',18,22,'crampon1923','De toutes les transgressions qu''il a commises, on ne se souviendra plus; à cause de la justice qu''il a pratiquée, il vivra.'),
('ez',18,23,'crampon1923','Prendrai-je plaisir à la mort du méchant, — oracle du Seigneur Yahweh? N''est-ce pas plutôt à ce qu''il se détourne de ses voies et qu''il vive?'),
('ez',18,24,'crampon1923','Et si le juste se détourne de sa justice et qu''il commette l''iniquité, selon toutes les abominations que le méchant commet, — il les ferait et il vivrait!... — de toutes ses œuvres de justice qu''il a pratiquées, on ne se souviendra plus; à cause de la transgression dont il s''est rendu coupable et de son péché qu''il a commis, à cause de cela il mourra.'),
('ez',18,25,'crampon1923','Vous dites: " La voie du Seigneur n''est pas droite? " Ecoutez donc, maison d''Israël: Est-ce ma voie qui n''est pas droite? Ne sont-ce pas vos voies qui ne sont pas droites?'),
('ez',18,26,'crampon1923','Quand le juste se détourne de sa justice et commet l''iniquité, et que là-dessus il meurt, c''est à cause de l''iniquité qu''il à commise qu''il meurt.'),
('ez',18,27,'crampon1923','Et si le méchant se détourne de sa méchanceté qu''il a pratiquée et qu''il agisse suivant le droit et la justice, il fera vivre son âme.'),
('ez',18,28,'crampon1923','S''il ouvre les yeux et se détourne de toutes ses transgressions qu''il a commises, il vivra certainement, et il ne mourra point.'),
('ez',18,29,'crampon1923','Mais la maison d''Israël dit: " La voie du Seigneur n''est pas droite. " Sont-ce mes voies qui ne sont pas droites, maison d''Israël? Ne sont-ce pas vos voies qui ne sont pas droites?'),
('ez',18,30,'crampon1923','C''est pourquoi je vous jugerai chacun selon ses voies, maison d''Israël, — oracle du Seigneur Yahweh. Détournez-vous et convertissez-vous de toutes vos transgressions, et l''iniquité ne deviendra pas votre ruine.'),
('ez',18,31,'crampon1923','Rejetez loin de vous toutes les transgressions que vous avez commises; faites-vous un cœur nouveau et un esprit nouveau. Pourquoi mourriez-vous, maison d''Israël?'),
('ez',18,32,'crampon1923','Car je ne prends point plaisir à la mort de celui qui meurt, — oracle du Seigneur Yahweh; convertissez-vous donc et vivez. "'),
('ez',19,1,'crampon1923','Et toi, prononce une lamentation sur les princes d''Israël, et dis:'),
('ez',19,2,'crampon1923','" Pourquoi ta mère, comme une lionne, s''est-elle couchée entre des lions? Au milieu des jeunes lions elle a nourri ses petits.'),
('ez',19,3,'crampon1923','Elle éleva l''un de ses petits, et ce fut un jeune lion; il apprit à déchirer sa proie, il dévorait des hommes.'),
('ez',19,4,'crampon1923','Les nations entendirent parler de lui; il fut pris dans leur fosse. Elles le conduisirent, avec des crochets aux mâchoires, au pays de l''Egypte.'),
('ez',19,5,'crampon1923','Et la lionne vit qu''elle attendait en vain, et que son espoir était perdu; elle prit un autre de ses petits, et en fit un lion.'),
('ez',19,6,'crampon1923','Il marcha au milieu des lions, et ce fut un jeune lion; il apprit à déchirer sa proie; il dévorait des hommes.'),
('ez',19,7,'crampon1923','Il connut leurs veuves, et il ravagea leurs villes; le pays et ce qu''il contenait fut épouvanté du bruit de son rugissement.'),
('ez',19,8,'crampon1923','Alors les peuples des contrées d''alentour dressèrent contre lui et étendirent sur lui leurs filets, et il fut pris dans leur fosse.'),
('ez',19,9,'crampon1923','Ils le mirent dans une cage, avec des crochets aux mâchoires, et le conduisirent au roi de Babylone; et ils le conduisirent dans des forteresses, afin qu''on n''entendît plus sa voix sur les montagnes d''Israël.'),
('ez',19,10,'crampon1923','Ta mère était comme une vigne, au temps de ta prospérité; elle était plantée au bord de, eaux; elle donna du fruit et poussa du feuillage, à cause des eaux abondantes.'),
('ez',19,11,'crampon1923','Elle avait des branches vigoureuses, pour des sceptres de souverains, et sa taille était élevée parmi les rameaux touffus. Elle apparut dans sa grandeur, avec la multitude de ses sarments.'),
('ez',19,12,'crampon1923','Mais elle a été arrachée avec fureur, et elle a été jetée par terre; et le vent d''orient a desséché son fruit. Ses branches vigoureuses ont été rompues et desséchées; le feu les a dévorées.'),
('ez',19,13,'crampon1923','Et maintenant, elle est plantée dans le désert, dans une terre sèche et aride.'),
('ez',19,14,'crampon1923','Un feu est sorti d''un de ses rameaux, il a dévoré son fruit; elle n''a plus de rameaux puissants, de sceptre pour dominer. " C''est là une lamentation, et elle deviendra une lamentation.'),
('ez',20,1,'crampon1923','La septième année, au cinquième mois, le dix du mois, quelques-uns des anciens d''Israël vinrent consulter Yahweh et s''assirent devant moi.'),
('ez',20,2,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('ez',20,3,'crampon1923','" Fils de l''homme, parle aux anciens d''Israël et dis-leur: Ainsi parle le Seigneur Yahweh: Est-ce pour me consulter que vous êtes venus? Je suis vivant: je ne me laisserai point consulter par vous, — oracle du Seigneur Yahweh.'),
('ez',20,4,'crampon1923','Les jugeras-tu, les jugeras-tu, fils de l''homme? Fais-leur connaître les abominations de leurs pères,'),
('ez',20,5,'crampon1923','et dis-leur: Ainsi parle le Seigneur Yahweh: Le jour où j''ai choisi Israël et où j''ai levé ma main pour la postérité de Jacob, où je me suis fait connaître à eux dans le pays d''Egypte, et où j''ai élevé ma main pour eux en disant: Je suis Yahweh, votre Dieu,'),
('ez',20,6,'crampon1923','en ce jour-là j''ai levé ma main pour eux en leur jurant de les faire sortir du pays d''Egypte et de les amener dans un pays que j''avais exploré pour eux, où coulent le lait et le miel; c''était le joyau de tous les pays.'),
('ez',20,7,'crampon1923','Et je leur dis: Rejetez chacun les idoles infâmes de vos yeux, ne vous souillez pas par les abominations de l''Egypte. Je suis Yahweh, votre Dieu.'),
('ez',20,8,'crampon1923','Mais ils se révoltèrent contre moi et ne voulurent pas m''écouter. Ils ne rejetèrent pas chacun les idoles infâmes de leurs yeux, et ils n''abandonnèrent pas les abominations de l''Egypte. Je pensai à répandre sur eux mon courroux, à épuiser sur eux ma colère au milieu du pays d''Egypte.'),
('ez',20,9,'crampon1923','Mais j''agis à cause de mon nom, afin qu''il ne fût pas profané aux yeux des nations parmi lesquelles ils se trouvaient, à la vue desquelles je m''étais fait connaître à eux, pour les faire sortir du pays d''Egypte.'),
('ez',20,10,'crampon1923','Je les fis sortir du pays d''Egypte et je les conduisis au désert.'),
('ez',20,11,'crampon1923','Je leur donnai mes préceptes et leur fis connaître mes ordonnances, par lesquelles l''homme qui les pratique aura la vie.'),
('ez',20,12,'crampon1923','Je leur donnai aussi mes sabbats pour servir de signe entre moi et eux, pour qu''ils connussent que je suis Yahweh qui les sanctifie.'),
('ez',20,13,'crampon1923','Mais la maison d''Israël se révolta contre moi dans le désert; ils ne suivirent pas mes lois et rejetèrent mes ordonnances, par lesquelles l''homme qui les pratique vivra, et ils profanèrent extrêmement mes sabbats. Je pensai à répandre sur eux mon courroux dans le désert, pour les exterminer.'),
('ez',20,14,'crampon1923','Mais j''agis à cause de mon nom, afin qu''il ne fût pas profané aux yeux des nations à la vue desquelles je les avais fait sortir.'),
('ez',20,15,'crampon1923','Et même je levai ma main contre eux dans le désert, leur jurant de ne pas les faire entrer dans le pays que je leur avais donné, où coulent le lait et le miel, — c''est le joyau de tous les pays —'),
('ez',20,16,'crampon1923','parce qu’ils avaient rejeté mes ordonnances et n''avaient pas suivi mes lois, et parce qu''ils avaient profané mes sabbats; car leur cœur suivait leurs idoles infâmes.'),
('ez',20,17,'crampon1923','Mais mon œil eut pitié d''eux, pour ne pas les détruire; et je ne les exterminai pas dans le désert.'),
('ez',20,18,'crampon1923','Je dis à leurs fils dans le désert: Ne suivez pas les observances de vos pères, ne gardez pas leurs coutumes et ne vous souillez pas par leurs infâmes idoles.'),
('ez',20,19,'crampon1923','Je suis Yahweh, votre Dieu; suivez mes préceptes, observez mes ordonnances et pratiquez-les;'),
('ez',20,20,'crampon1923','et sanctifiez mes sabbats, pour qu''ils soient un signe entre moi et vous, afin que vous sachiez que je suis Yahweh, votre Dieu.'),
('ez',20,21,'crampon1923','Mais les fils se révoltèrent contre moi; ils ne suivirent pas mes préceptes et n''observèrent pas, en les mettant en pratique, mes ordonnances, par lesquelles l''homme qui les pratique vivra; et ils profanèrent mes sabbats. Je pensai à répandre mon courroux sur eux, à épuiser sur eux ma colère dans le désert.'),
('ez',20,22,'crampon1923','Mais j''ai détourné ma main et j''ai agi à cause de mon nom, afin qu''il ne fut pas profané aux yeux des nations à la vue desquelles je les avais fait sortir.'),
('ez',20,23,'crampon1923','Même je levai ma main contre eux dans le dessert, leur jurant de les disperser parmi les nations et de les répandre dans les pays,'),
('ez',20,24,'crampon1923','parce qu''ils n''avaient pas pratiqué mes ordonnances, qu''ils avaient rejeté mes préceptes et profané mes sabbats, et que leurs yeux avaient suivi les idoles infâmes de leurs pères.'),
('ez',20,25,'crampon1923','Et même je leur donnai des préceptes qui n''étaient pas bons, et des ordonnances par lesquelles ils ne pouvaient pas vivre.'),
('ez',20,26,'crampon1923','Et je les souillai par leurs offrandes, quand ils faisaient passer par le feu tout premier-né, et cela pour les ravager, afin qu''ils connussent que je suis Yahweh.'),
('ez',20,27,'crampon1923','C''est pourquoi parle à la maison d''Israël, fils de l''homme, et dis-leur: Ainsi parle le Seigneur Yahweh: Encore en ceci vos pères m''ont outragé; en ce qu''ils ont été infidèles envers moi.'),
('ez',20,28,'crampon1923','Quand je les eus fait entrer dans le pays que j''avais juré, la main levée, de leur donner, partout où ils ont vu une colline élevée et un arbre touffu, ils y ont offert leurs sacrifices et présenté leurs offrandes qui excitaient ma colère; ils y ont apporté leurs parfums d''agréable odeur et y ont répandu leurs libations.'),
('ez',20,29,'crampon1923','Et je leur dis: qu''est ce que le haut lieu où vous allez? Et il fut appelé haut lieu, jusqu''à ce jour.'),
('ez',20,30,'crampon1923','C''est pourquoi dis à la maison d''Israël: Ainsi parle le Seigneur Yahweh: Quoi! Vous vous souillez à la manière de vos pères, et vous vous prostituez après leurs abominations!'),
('ez',20,31,'crampon1923','En présentant vos offrandes, en faisant passer vos enfants par le feu, vous vous souillez avec toutes vos infâmes idoles jusqu''à aujourd''hui, et moi, je me laisserai consulter par vous, maison d''Israël? Je suis vivant, — oracle du Seigneur Yahweh: je ne me laisserai pas consulter par vous.'),
('ez',20,32,'crampon1923','Et elle ne se réalisera pas la pensée qui monte à votre esprit, quand vous dites: Nous serons comme les nations, comme les autres familles des pays, servant le bois et la pierre.'),
('ez',20,33,'crampon1923','Je suis vivant, — oracle du Seigneur Yahweh: à main forte, à bras étendu, à courroux répandu je régnerai sur vous!'),
('ez',20,34,'crampon1923','Je vous ferai sortir du milieu des peuples, et je vous rassemblerai des pays où vous avez été dispersés à main forte, à bras étendu et à courroux répandu.'),
('ez',20,35,'crampon1923','Et je vous mènerai au désert des peuples, et là j''entrerai en jugement avec vous face à face.'),
('ez',20,36,'crampon1923','Comme je suis entré en jugement avec vos pères dans le désert du pays d''Egypte, ainsi j''entrerai en jugement avec vous, — oracle du Seigneur Yahweh.'),
('ez',20,37,'crampon1923','Et je vous ferai passer sous la houlette et je vous amènerai sous la discipline de l''alliance.'),
('ez',20,38,'crampon1923','Et je séparerai d''avec vous les rebelles et ceux qui se sont détachés de moi; je les tirerai du pays où ils sont étrangers, mais ils ne viendront pas au pays d''Israël, et vous saurez que je suis Yahweh.'),
('ez',20,39,'crampon1923','Et vous, maison d''Israël, ainsi parle le Seigneur Yahweh: Allez servir chacun vos idoles! Mais, après cela, certainement vous m''écouterez et vous ne profanerez plus mon saint nom par vos offrandes et vos infâmes idoles.'),
('ez',20,40,'crampon1923','Car sur ma montagne sainte, sur la haute montagne d''Israël, — oracle du Seigneur Yahweh, — là toute la maison d''Israël, tout ce qu''il y a dans le pays me servira. Là je prendrai plaisir en eux; là je rechercherai vos offrandes et les prémices de vos dons en tout ce que vous me consacrerez.'),
('ez',20,41,'crampon1923','Je prendrai plaisir en vous comme en un parfum d''agréable odeur, quand je vous aurai fait sortir d''entre les peuples et que je vous aurai rassemblés des pays où vous êtes dispersés; et je me sanctifierai en vous aux yeux des nations.'),
('ez',20,42,'crampon1923','Et vous saurez que je suis Yahweh, quand je vous aurai amenés dans la terre d''Israël, au pays que j''ai juré, la main levée, de donner à vos pères.'),
('ez',20,43,'crampon1923','Là vous vous souviendrez de vos voies et de tous les crimes par lesquels vous vous êtes souillés; et vous vous prendrez vous mêmes en dégoût pour toutes les mauvaises actions que vous avez commises.'),
('ez',20,44,'crampon1923','Et vous saurez que je suis Yahweh quand j''agirai envers vous à cause de mon nom, et non selon vos voies mauvaises et vos crimes détestables, maison d''Israël, — oracle du Seigneur Yahweh. "'),
('ez',21,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',21,2,'crampon1923','" Fils de l''homme, tourne ta face dans la direction de Théman; fais découler ta parole vers le sud, et prophétise contre la forêt de la campagne du midi;'),
('ez',21,3,'crampon1923','et dis à la forêt du midi: Ecoute la parole de Yahweh! Ainsi parle le Seigneur Yahweh: Voici que je vais allumer au milieu de toi un feu, et il dévorera en toi tout arbre vert et tout arbre sec; la flamme dévorante ne s''éteindra point, et toute face sera brûlée par elle, du midi au septentrion.'),
('ez',21,4,'crampon1923','Et toute chair verra que c''est moi, Yahweh, qui l''ai allumée, et elle ne s''éteindra pas.'),
('ez',21,5,'crampon1923','Et je dis: " Ah! Seigneur Yahweh, ils disent de moi: Est-ce qu''il ne parle pas en paraboles? "'),
('ez',21,6,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('ez',21,7,'crampon1923','" Fils de l''homme, tourne ta face vers Jérusalem, et fais découler ta parole vers les lieux saints, et prophétise contre la terre d''Israël.'),
('ez',21,8,'crampon1923','Dis à la terre d''Israël: Ainsi parle Yahweh: Voici que je viens à toi; je tirerai mon épée de son fourreau, et j''exterminerai de ton sein juste et méchant.'),
('ez',21,9,'crampon1923','Et parce que je vais exterminer de ton sein juste et méchant, à cause de cela, mon épée sortira de son fourreau contre toute chair, du midi au septentrion.'),
('ez',21,10,'crampon1923','Et toute chair saura que c''est moi, Yahweh, qui ai tiré mon épée du fourreau; elle n''y rentrera plus.'),
('ez',21,11,'crampon1923','Et toi, fils de l''homme, gémis; jusqu''à te rompre les reins avec amertume, gémis devant eux.'),
('ez',21,12,'crampon1923','Et quand ils te diront: pourquoi gémis-tu? Tu répondras: A cause d''une nouvelle qui arrive. Et tout cœur se fondra, toute main faiblira, tout esprit sera dans le trouble, tout genou s''en ira en eau. Voici qu''elle arrive; c''est fait, — oracle du Seigneur Yahweh. "'),
('ez',21,13,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('ez',21,14,'crampon1923','" Fils de l''homme, prophétise et dis: Ainsi parle Yahweh: Dis: L''épée, l''épée est aiguisée et fourbie:'),
('ez',21,15,'crampon1923','c''est pour faire un massacre qu''elle est aiguisée, pour faire briller l''éclair qu''elle est fourbie. Ou bien nous réjouirons-nous en disant: " Le sceptre de mon fils méprise tout bois? "'),
('ez',21,16,'crampon1923','On l''a donnée à fourbir pour qu''on la prenne en main; c''est une épée aiguisée, et elle est fourbie, pour qu''on la mette dans la main de l''égorgeur.'),
('ez',21,17,'crampon1923','Crie et hurle, fils de l''homme, car elle est pour mon peuple, elle est pour tous les princes d''Israël. Ils sont livrés à l''épée avec mon peuple; frappe donc sur ta cuisse!'),
('ez',21,18,'crampon1923','Car l''épreuve est faite: et quoi donc? Si ce sceptre continue de mépriser, mes menaces ne se réaliseraient pas, — oracle du Seigneur Yahweh!'),
('ez',21,19,'crampon1923','Et toi, fils de l''homme, prophétise et frappe main contre main: Que l''épée double, triple ses coups! C''est l''épée du carnage, l''épée du grand carnage, qui les encercle.'),
('ez',21,20,'crampon1923','Pour que les cœurs se fondent, et pour multiplier les victimes, j''ai mis à toutes les portes l''épée meurtrière. Ah! elle est préparée pour lancer l''éclair, elle est aiguisée pour le carnage!'),
('ez',21,21,'crampon1923','En position à droite! En place à gauche! Fais face de tous côtés.'),
('ez',21,22,'crampon1923','Moi aussi, je frapperai main contre main; et j''assouvirai mon courroux. Moi, Yahweh, j''ai parlé. "'),
('ez',21,23,'crampon1923','Et la parole de Yahweh me fut adressée en ces termes:'),
('ez',21,24,'crampon1923','" Toi, fils de l''homme, trace deux chemins par où puisse aller l''épée du roi de Babylone; que tous deux partent du même pays, et grave un signe, grave-le à l''entrée du chemin d''une ville.'),
('ez',21,25,'crampon1923','Tu traceras un chemin à l''épée pour aller à Rabbath, capitale des fils d''Ammon, ou en Juda, contre Jérusalem, ville forte.'),
('ez',21,26,'crampon1923','Car le roi de Babylone s''est arrêté au carrefour, à la tête des deux chemins, pour tirer des présages: il secoue les flèches, il interroge les théraphim, il examine le foie.'),
('ez',21,27,'crampon1923','Dans sa droite est le présage " Jérusalem ", pour dresser des béliers contre les murailles, pour ouvrir une entrée par une brèche, pour pousser à haute voix le cri de guerre, pour dresser des béliers contre les portes, pour élever des terrasses, pour construire des murs.'),
('ez',21,28,'crampon1923','A leurs yeux, ce n''est qu''une divination mensongère; ils ont pour eux les serments les plus sacrés; mais lui les fera souvenir de leurs iniquités lorsqu''ils seront pris.'),
('ez',21,29,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce que vous avez rappelé votre iniquité en manifestant vos transgressions, en faisant voir vos péchés dans toutes vos actions, parce que vous vous êtes rappelés au souvenir, vous serez pris avec la main.'),
('ez',21,30,'crampon1923','Et toi, profane, méchant prince d''Israël, dont le jour est venu, maintenant que l''iniquité est à son terme,'),
('ez',21,31,'crampon1923','ainsi parle le Seigneur Yahweh: La tiare va être ôtée et la couronne enlevée; tout sera bouleversé; ce qui est bas sera élevé, ce qui est haut sera abaissé.'),
('ez',21,32,'crampon1923','J''en ferai une ruine, une ruine, une ruine; cela ne sera plus, jusqu''à ce que vienne celui à qui appartient le jugement et à qui je le remettrai.'),
('ez',21,33,'crampon1923','Et toi, fils de l''homme, prophétise et dis: Ainsi parle le Seigneur Yahweh, contre les fils d''Ammon et au sujet de leurs outrages. Dis: L''épée, l''épée est tirée pour massacrer; elle est fourbie pour dévorer, pour lancer l''éclair.'),
('ez',21,34,'crampon1923','— pendant qu''on a pour toi des visions vaines, et des présages menteurs, — pour te placer avec les cadavres des méchants livrés au glaive, dont le jour est venu au temps où l''iniquité est à son terme.'),
('ez',21,35,'crampon1923','Rentre ton épée dans son fourreau; c''est dans le lieu ou tu as été créé, sur la terre où tu as pris naissance que je te jugerai.'),
('ez',21,36,'crampon1923','Je répandrai sur toi mon courroux; avec le feu de ma fureur je soufflerai sur toi, et je te livrerai aux mains d''hommes insensés, à des artisans de destruction.'),
('ez',21,37,'crampon1923','Tu seras la pâture du feu, ton sang sera au milieu du pays, on ne se souviendra pas de toi; car moi, Yahweh, j''ai parlé. "'),
('ez',22,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',22,2,'crampon1923','" Et toi, fils de l''homme, jugeras-tu, jugeras-tu la ville de sang? Fais-lui connaître toutes ses abominations,'),
('ez',22,3,'crampon1923','et dis: Ainsi parle le Seigneur Yahweh: Ville qui répand le sang au dedans d''elle, pour que son temps vienne, et qui se couvre d''idoles infâmes pour se souiller!'),
('ez',22,4,'crampon1923','Par le sang que tu as répandu, tu t''es rendue criminelle; par les idoles infâmes que tu as faites, tu t''es souillée; et tu as ainsi avancé tes jours, et tu es parvenue au terme de tes années. C''est pourquoi je t''ai rendue un objet d''opprobre pour les nations et une risée dans tous les pays.'),
('ez',22,5,'crampon1923','Ceux qui sont près et ceux qui sont loin de toi se moqueront de toi, souillée de réputation, grande en désordre!'),
('ez',22,6,'crampon1923','Voici que les princes d''Israël, chacun selon ses forces, sont occupés chez toi à répandre le sang.'),
('ez',22,7,'crampon1923','Chez toi, on méprise père et mère; au milieu de toi, on maltraite l''étranger; chez toi, on opprime l''orphelin et la veuve.'),
('ez',22,8,'crampon1923','Tu méprises mon sanctuaire et tu profanes mes sabbats.'),
('ez',22,9,'crampon1923','Il y a chez toi des gens qui calomnient pour répandre le sang; chez toi, on mange sur les montagnes; on commet des énormités au milieu de toi.'),
('ez',22,10,'crampon1923','Chez toi, on découvre la nudité de son père; chez toi, on fait violence à la femme pendant sa souillure.'),
('ez',22,11,'crampon1923','L''un commet l''abomination avec la femme de son prochain, un autre souille par l''impureté sa belle-fille chez toi, un autre fait violence à sa sœur, fille de son père.'),
('ez',22,12,'crampon1923','Chez toi, ou reçoit des présents pour répandre le sang; tu prends l''usure et un intérêt; tu dépouilles par la violence ton prochain; et moi, tu m''oublies, — oracle du Seigneur Yahweh.'),
('ez',22,13,'crampon1923','Mais voici que je frappe dans ma main à cause du gain déshonnête que tu as fait, et à cause du sang qui est au milieu de toi.'),
('ez',22,14,'crampon1923','Ton cœur tiendra-t-il bon, tes mains seront-elles fermes aux jours où j''agirai contre toi? Moi, Yahweh, j''ai dit et j''agirai.'),
('ez',22,15,'crampon1923','Je te disperserai parmi les nations, je te sèmerai dans les pays, et j''ôterai de toi toute ta souillure,'),
('ez',22,16,'crampon1923','et tu seras profanée chez toi aux yeux des nations; et tu sauras que je suis Yahweh. "'),
('ez',22,17,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',22,18,'crampon1923','" Fils de l''homme, la maison d''Israël s''est changée pour moi en scories; eux tous sont de l''airain, de l''étain, du fer et du plomb au milieu du fourneau; ils sont devenus les scories de l''argent.'),
('ez',22,19,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce que vous êtes tous devenus des scories, à cause de cela, voici que je vais vous rassembler au milieu de Jérusalem.'),
('ez',22,20,'crampon1923','Comme ou met ensemble l''argent, l''airain, le fer, le plomb et l''étain au milieu d''un fourneau et qu''on souffle le feu sur le fourneau pour les fondre, ainsi je vous rassemblerai dans ma colère et mon courroux; je vous mettrai là et je vous fondrai.'),
('ez',22,21,'crampon1923','Je vous rassemblerai et je soufflerai sur vous, avec le feu de ma fureur, et vous serez fondus au milieu de Jérusalem.'),
('ez',22,22,'crampon1923','Comme on fond l''argent au milieu d''un fourneau, ainsi vous serez fondus au milieu d''elle; et vous saurez que moi, Yahweh, j''ai répandu mon courroux sur vous. "'),
('ez',22,23,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',22,24,'crampon1923','" Fils de l''homme, dis-lui: Tu es une terre qui n''a pas été purifiée, qui n''a pas été lavée par la pluie, en un jour de colère.'),
('ez',22,25,'crampon1923','Il y a au milieu d''elle une conspiration de ses prophètes. Comme un lion rugissant qui déchire sa proie, ils dévorent les âmes, ils s''emparent des biens et des trésors, ils multiplient ses veuves au milieu d''elle.'),
('ez',22,26,'crampon1923','Ses prêtres ont violé ma loi et profané mon sanctuaire; ils ne distinguent pas entre le saint et le profane; ils n''enseignent pas la différence entre celui qui est souillé et celui qui est pur; ils ferment leurs yeux sur mes sabbats, et je suis profané au milieu d''eux.'),
('ez',22,27,'crampon1923','Ses chefs sont au milieu d''elle comme des loups qui déchirent leur proie, répandant le sang, perdant des âmes pour faire des gains.'),
('ez',22,28,'crampon1923','Et ses prophètes leur plâtrent tous ces crimes; ils ont des visions vaines et des oracles menteurs; ils disent: " Ainsi parle le Seigneur Yahweh "; et Yahweh n''a point parlé.'),
('ez',22,29,'crampon1923','Le peuple du pays commet des violences et s''adonne à la rapine; ils foulent le malheureux et l''indigent, et font violence à l''étranger sans motif.'),
('ez',22,30,'crampon1923','J''ai cherché parmi eux un homme qui fit une clôture et qui se tint à la brèche devant moi pour le pays, afin que je ne détruise pas; et je ne l''ai pas trouvé.'),
('ez',22,31,'crampon1923','Et j''ai répandu sur eux mon courroux, et je les ai consumés par le feu de ma fureur, et j''ai fait retomber leurs œuvres sur leur tête, — oracle du Seigneur Yahweh. "'),
('ez',23,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',23,2,'crampon1923','" Fils de l''homme, il y avait deux femmes, filles d''une même mère.'),
('ez',23,3,'crampon1923','Elles se prostituèrent en Egypte, elles se prostituèrent dans leur jeunesse. Là on a saisi leurs mamelles, là on a pressé leur sein virginal.'),
('ez',23,4,'crampon1923','Voici leurs noms: Oolla, la plus grande, et Ooliba, sa sœur. Elles furent à moi, et elles enfantèrent des fils et des filles. Voici leurs noms: Oolla, c''est Samarie; Ooliba, c''est Jérusalem.'),
('ez',23,5,'crampon1923','Oolla me fut infidèle; elle brûla d''amour pour ses amants, les Assyriens, ses voisins.'),
('ez',23,6,'crampon1923','Vêtus de pourpre, gouverneurs et magistrats, tous beaux jeunes hommes, cavaliers montés sur des chevaux.'),
('ez',23,7,'crampon1923','C''est vers eux qu''elle dirigea ses prostitutions, vers toute l''élite des fils de l''Assyrie; et près de tous ceux pour qui elle brûlait d''amour, elle se souilla avec toutes leurs infâmes idoles.'),
('ez',23,8,'crampon1923','Et elle n''abandonna pas ses prostitutions de l''Egypte; car ils l''avaient déshonorée dans sa jeunesse; ils avaient pressé son sein virginal, et répandu sur elle leur impudicité.'),
('ez',23,9,'crampon1923','C''est pourquoi je l''ai livrée aux mains de ses amants, aux mains des fils de l''Assyrie, pour qui elle avait brûlé d''amour.'),
('ez',23,10,'crampon1923','Ils ont découvert sa nudité; ils ont pris ses fils et ses filles; ils l''ont égorgée avec l''épée. Et elle devint en renom parmi les femmes; car justice en avait été faite.'),
('ez',23,11,'crampon1923','Et sa sœur Ooliba l''a vu, et plus qu''elle elle a rendu pervers ses amours; et ses prostitutions ont surpassé celles de sa sœur.'),
('ez',23,12,'crampon1923','Elle a brûlé d''amour pour les fils de l''Assyrie, gouverneurs et chefs, ses voisins richement vêtus, cavaliers montés sur des chevaux, tous beaux jeunes hommes.'),
('ez',23,13,'crampon1923','Je vis qu''elle aussi se souillait; toutes deux suivaient la même voie.'),
('ez',23,14,'crampon1923','Elle ajouta encore à ses prostitutions: elle vit des hommes peints sur le mur, des images de Chaldéens peintes au vermillon;'),
('ez',23,15,'crampon1923','ils portaient des ceintures sur leurs reins, ils avaient sur leurs têtes d''amples turbans; tous paraissaient de grands seigneurs. C''étaient les figures des fils de Babylone, dont la Chaldée était la terre d''origine.'),
('ez',23,16,'crampon1923','Elle brûla pour eux dès que ses yeux les virent, et elle envoya des messagers vers eux en Chaldée;'),
('ez',23,17,'crampon1923','et les fils de Babylone vinrent vers elle au lit des amours et ils la souillèrent par leurs prostitutions, et elle se souilla avec eux; puis son âme se dégoûta d''eux.'),
('ez',23,18,'crampon1923','Elle fit voir à découvert ses prostitutions, elle découvrit sa nudité; et mon âme se dégoûta d''elle, comme mon âme s''était dégoûtée de sa sœur.'),
('ez',23,19,'crampon1923','Elle a multiplié ses prostitutions, se rappelant les jours de sa jeunesse, lorsqu''elle se prostituait au pays d''Egypte.'),
('ez',23,20,'crampon1923','Elle a brûlé pour ses impudiques, dont les membres sont des membres d''âne, et l''ardeur lubrique celle des étalons.'),
('ez',23,21,'crampon1923','Tu es revenue aux crimes de ta jeunesse, quand les Egyptiens pressaient tes mamelles, à cause de ton sein virginal.'),
('ez',23,22,'crampon1923','C''est pourquoi, Ooliba, ainsi parle le Seigneur Yahweh: Voici que je vais exciter contre toi tes amants, ceux dont ton âme s''est dégoûtée, et je les ferai venir contre toi de toute part,'),
('ez',23,23,'crampon1923','les fils de Babylone et tous les Chaldéens, princes, chefs et seigneurs, et avec eux tous les fils de l''Assyrie, beaux jeunes hommes, tous gouverneurs et magistrats, dignitaires et personnages illustres, tous montés sur des chevaux.'),
('ez',23,24,'crampon1923','Contre toi s''avancent armes, chars et roues, avec une multitude de peuples; ils disposent contre toi boucliers, écus et casques; je remets devant eux le jugement, et ils te jugeront selon leurs lois.'),
('ez',23,25,'crampon1923','Je dirigerai ma jalousie contre toi; et ils te traiteront avec fureur; ils te couperont le nez et les oreilles, et ce qui restera de toi tombera par l''épée; ils prendront tes fils et tes filles, et ce qui restera de toi sera dévoré par le feu.'),
('ez',23,26,'crampon1923','Ils te dépouilleront de tes vêtements, et ils enlèveront tes bijoux.'),
('ez',23,27,'crampon1923','Je mettrai un terme à ton crime, et à tes prostitutions du pays d''Egypte; tu ne lèveras plus les yeux vers eux, et tu ne te souviendras plus de l''Egypte.'),
('ez',23,28,'crampon1923','Car ainsi parle le Seigneur Yahweh: Voici que je vais te livrer aux mains de ceux que tu hais, aux mains de ceux dont ton âme s''est dégoûtée.'),
('ez',23,29,'crampon1923','Ils te traiteront avec haine, ils emporteront tout ce que tu as gagné, et te laisseront nue, complètement nue; et ta nudité impudique, ton impureté et tes prostitutions seront découvertes.'),
('ez',23,30,'crampon1923','On te traitera ainsi parce que tu t''es prostituée aux nations, parce que tu t''es souillée avec leurs idoles infâmes.'),
('ez',23,31,'crampon1923','Tu as marché dans la voie de ta sœur; je mettrai sa coupe dans ta main.'),
('ez',23,32,'crampon1923','Ainsi parle le Seigneur Yahweh: Tu boiras la coupe de ta sœur, coupe profonde et large; elle donnera à rire et à se moquer de toi, tant est grande sa capacité.'),
('ez',23,33,'crampon1923','Tu seras remplie d''ivresse et de douleur; c''est une coupe de désolation et de dévastation que la coupe de ta sœur, Samarie.'),
('ez',23,34,'crampon1923','Tu la boiras et la videras, tu en mordras les morceaux et t''en déchireras le sein; car moi j''ai parlé, — oracle du Seigneur Yahweh.'),
('ez',23,35,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce que tu m''as oublié, et que tu m''as rejeté derrière ton dos, porte donc, toi aussi, la peine de ton impureté et de tes prostitutions! "'),
('ez',23,36,'crampon1923','Et Yahweh me dit: " Fils de l''homme, jugeras-tu Oolla et Ooliba? Déclare-leur leurs abominations.'),
('ez',23,37,'crampon1923','Car elles ont été adultères, et il y a du sang dans leurs mains; elles ont commis l''adultère avec leurs idoles infâmes, et même leurs fils qu''elles m''avaient enfantés, elles les ont fait passer par le feu, pour qu''ils les mangent.'),
('ez',23,38,'crampon1923','Voici encore ce qu''elles ont fait: Elles ont souillé mon sanctuaire en ce jour-là, et elles ont profané mes sabbats.'),
('ez',23,39,'crampon1923','Et lorsqu''elles immolaient leurs fils à leurs idoles infâmes, elles entraient le même jour dans mon sanctuaire, pour le profaner: Voilà ce qu''elles ont fait au milieu de ma maison.'),
('ez',23,40,'crampon1923','Et même elles ont envoyé chercher des hommes venant de loin; et ceux à qui avait été envoyé un messager, voici qu''ils sont venus,... ceux pour qui tu t''es lavée, tu as mis du fard à tes yeux, tu t''es ornée de parures!'),
('ez',23,41,'crampon1923','Et tu t''es assise sur un lit d''apparat, devant lequel une table était dressée, où tu as posé mon encens et mon huile.'),
('ez',23,42,'crampon1923','On y entendait le bruit d''une foule à l''aise; aux gens venus des grands amas d''hommes, se sont joints les buveurs du désert, qui ont mis des bracelets aux mains des deux sœurs, et des couronnes magnifiques sur leurs têtes.'),
('ez',23,43,'crampon1923','Et je dis à cette femme usée dans les adultères: Va-t-elle maintenant continuer ses prostitutions, elle aussi?'),
('ez',23,44,'crampon1923','On va vers elle comme on va chez une prostituée. C''est ainsi qu''on est allé chez Oolla et Ooliba, ces femmes criminelles.'),
('ez',23,45,'crampon1923','Mais des hommes justes les condamneront à la peine des femmes adultères, et à la peine de celles qui répandent le sang; car elles sont adultères, et il y a du sang dans leurs mains.'),
('ez',23,46,'crampon1923','Car ainsi parle le Seigneur Yahweh: Fais monter contre elles une assemblée, et qu''on les livre à la terreur et au pillage;'),
('ez',23,47,'crampon1923','et que l''assemblée les accable sous les pierres, et les taille en pièces avec ses épées; qu''on tue leurs fils et leurs filles, et qu''on brûle au feu leurs maisons!'),
('ez',23,48,'crampon1923','Et je ferai cesser l''impureté dans le pays, et toutes les femmes en recevront une leçon, et ne commettront point des impuretés pareilles aux vôtres,'),
('ez',23,49,'crampon1923','On fera retomber votre impureté sur vous, et vous porterez la peine de votre idolâtrie; et vous saurez que je suis le Seigneur Yahweh. "'),
('ez',24,1,'crampon1923','La parole de Yahweh me fut adressée la neuvième année, au dixième mois, le dix du mois, en ces termes:'),
('ez',24,2,'crampon1923','" Fils de l''homme, mets par écrit le nom de ce jour, de ce propre jour-ci: le roi de Babylone s''est jeté sur Jérusalem en ce jour même.'),
('ez',24,3,'crampon1923','Propose une parabole à la maison rebelle et dis-leur: Ainsi parle le Seigneur Yahweh: Dresse la chaudière, dresse-la et verses-y de l''eau.'),
('ez',24,4,'crampon1923','Amasses-y ses morceaux, tous les bons morceaux, la cuisse et l''épaule, remplis-la des meilleurs os.'),
('ez',24,5,'crampon1923','Prends ce qu''il y a de mieux dans le troupeau, entasse aussi les os sous la chaudière; fais-la bouillir à gros bouillons, et que les os qui sont dedans cuisent aussi.'),
('ez',24,6,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Malheur à la ville de sang, chaudière dans laquelle il y a du vert-de-gris, et de laquelle le vert-de-gris n''est pas sorti! Vide-la morceaux par morceaux, sans tirer au sort.'),
('ez',24,7,'crampon1923','Car le sang qu''elle a versé est au milieu d''elle; elle l''a mis sur la roche nue; elle ne l''a pas répandu sur la terre, pour le couvrir de poussière.'),
('ez',24,8,'crampon1923','Afin d''exciter le courroux, afin de tirer vengeance, j''ai fait verser le sang qu''elle a répandu sur la roche nue, pour qu''il ne fût pas couvert.'),
('ez',24,9,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Malheur à la ville de sang! Moi aussi, je dresserai un grand monceau de bois.'),
('ez',24,10,'crampon1923','Amasse le bois, allume le feu, fais fondre la chair, fais bouillir la bouillie, et que les os soient consumés par le feu.'),
('ez',24,11,'crampon1923','Puis pose la chaudière vide sur ses charbons, afin qu''elle s''échauffe, que son airain s''embrase et que sa souillure se fonde au milieu d''elle, que son vert-de-gris soit consumé.'),
('ez',24,12,'crampon1923','Efforts inutiles! Sa masse de vert-de-gris ne s''en va pas, son vert-de-gris résiste au feu.'),
('ez',24,13,'crampon1923','Dans ta souillure il y a une énormité; puisque je t''ai purifiée et que tu n''es pas devenue pure, tu ne seras jamais plus purifiée de ta souillure, jusqu''à ce que j''aie fait reposer sur toi mon courroux.'),
('ez',24,14,'crampon1923','Moi, Yahweh, j''ai parlé; cela arrivera et je le ferai; je ne lâcherai point, je n''épargnerai point, je ne me repentirai point. On te jugera selon tes voies, et selon tes forfaits, — oracle du Seigneur Yahweh. "'),
('ez',24,15,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',24,16,'crampon1923','" Fils de l''homme, voici que je vais t''enlever par un coup soudain les délices de tes yeux; tu ne te lamenteras point, tu ne pleureras point, et tes larmes ne couleront pas.'),
('ez',24,17,'crampon1923','Soupire en silence; ne fais pas le deuil des morts; ceins ta tête de ton turban et mets ta chaussure à tes pieds; ne te voile pas la barbe et ne mange pas le pain de consolation. "'),
('ez',24,18,'crampon1923','Je parlai au peuple le matin, et ma femme mourut le soir; le lendemain matin, je fis ce qui m''avait été ordonné.'),
('ez',24,19,'crampon1923','Et le peuple me dit: " Ne nous expliqueras-tu pas ce que signifie pour nous ce que tu fais là? "'),
('ez',24,20,'crampon1923','Je leur dis: " La parole de Yahweh m''a été adressée en ces termes:'),
('ez',24,21,'crampon1923','Dis à la maison d''Israël: Ainsi parle le Seigneur Yahweh: Voici que je vais profaner mon sanctuaire, l''orgueil de votre force, les délices de vos yeux et l''amour de vos âmes; et vos fils et vos filles que vous avez quittés tomberont par l''épée.'),
('ez',24,22,'crampon1923','Vous ferez alors ce que j''ai fait: vous ne vous couvrirez pas la barbe et vous ne mangerez pas le pain de consolation.'),
('ez',24,23,'crampon1923','Vos turbans resteront sur vos têtes et vos chaussures à vos pieds; vous ne vous lamenterez pas et vous ne pleurerez pas; mais vous vous consumerez dans vos iniquités, et vous gémirez l''un auprès de l''autre.'),
('ez',24,24,'crampon1923','Ezéchiel sera pour vous un emblème: selon tout ce qu''il a fait vous agirez, quand cela arrivera, et vous saurez que je suis le Seigneur Yahweh. "'),
('ez',24,25,'crampon1923','" Et toi, fils de l''homme, le jour où je leur ôterai ce qui fait leur force, leur gloire et leur joie, les délices de leurs yeux et le désir de leurs âmes, — leurs fils et leurs filles, —'),
('ez',24,26,'crampon1923','en ce jour-là, un fugitif viendra vers toi pour en apporter la nouvelle.'),
('ez',24,27,'crampon1923','En ce jour-là, ta bouche s''ouvrira à l''arrivée du fugitif; tu parleras et ne seras plus muet, et tu seras pour eux un emblème; ils sauront que je suis le Seigneur Yahweh. "'),
('ez',25,1,'crampon1923','La parole de Dieu me fut adressée en ces termes:'),
('ez',25,2,'crampon1923','" Fils de l''homme, tourne ta face vers les enfants d''Ammon; et prophétise contre eux.'),
('ez',25,3,'crampon1923','Tu diras aux enfants d''Ammon: Ecoutez la parole du Seigneur Yahweh: Ainsi parle le Seigneur Yahweh: Puisque tu dis: Ha! Ha!, sur mon sanctuaire parce qu''il a été profané, et sur la terre d''Israël parce qu''elle a été dévastée, et sur la maison de Juda parce qu''ils sont allés en captivité,'),
('ez',25,4,'crampon1923','à cause de cela, voici que je vais te donner en possession aux fils de l''Orient; ils établiront chez toi leurs campements, et fixeront chez toi leurs demeures; ce sont eux qui mangeront tes fruits, eux qui boiront ton lait.'),
('ez',25,5,'crampon1923','Et je ferai de Rabbath un pâturage de chameaux, et du pays des enfants d''Ammon un bercail de brebis, et vous saurez que je suis Yahweh.'),
('ez',25,6,'crampon1923','Car ainsi parle le Seigneur Yahweh: Parce que tu as battu des mains, et que tu as frappé du pied, et que tu t''es réjouis dans ton âme avec tout ton dédain, au sujet de la terre d''Israël,'),
('ez',25,7,'crampon1923','à cause de cela, voici que je vais étendre ma main contre toi; je te donnerai en butin aux nations, je t''exterminerai d''entre les peuples, et je te retrancherai d''entre les pays; je t''anéantirai, et tu sauras que le suis Yahweh. "'),
('ez',25,8,'crampon1923','" Ainsi parle le Seigneur Yahweh: Parce que Moab et Séir disent: " Voici que la maison de Juda est comme toutes les nations, "'),
('ez',25,9,'crampon1923','à cause de cela, voici que je vais ouvrir le flanc de Moab, depuis les villes, depuis ses villes, depuis sa frontière, la gloire du pays, Bethjésimoth, Beelméon et Cariathain.'),
('ez',25,10,'crampon1923','Je vais l''ouvrir aux fils de l''Orient, aussi bien que le pays des enfants d''Ammon, et je le leur donnerai en possession, afin qu''on ne se souvienne plus des enfants d''Ammon parmi les nations.'),
('ez',25,11,'crampon1923','J''exercerai des jugements en Moab, et ils sauront que je suis Yahweh. "'),
('ez',25,12,'crampon1923','" Ainsi parle le Seigneur Yahweh: Parce qu''Edom a exercé cruellement la vengeance contre la maison de Juda, et qu''il s''est rendu grandement coupable en se vengeant d''eux,'),
('ez',25,13,'crampon1923','à cause de cela, ainsi parle le Seigneur Yahweh: J''étendrai ma main contre Edom et j''exterminerai du milieu de lui hommes et bêtes; j''en ferai un désert depuis Théman, et jusqu''à Dédan ils tomberont par l''épée.'),
('ez',25,14,'crampon1923','J''exercerai ma vengeance sur Edom, par la main de mon peuple d''Israël; il traitera Edom selon ma colère et ma fureur, et ils connaîtront ma vengeance, — oracle du Seigneur Yahweh. "'),
('ez',25,15,'crampon1923','" Ainsi parle le Seigneur Yahweh: Parce que les Philistins ont exercé la vengeance, et qu''ils se sont cruellement vengés, avec le dédain en leur âme, pour tout exterminer dans leur haine éternelle,'),
('ez',25,16,'crampon1923','à cause de cela, ainsi parle le Seigneur Yahweh: Voici que j''étendrai ma main contre les Philistins, j''exterminerai les Crétois, et je détruirai le reste qui habite sur le rivage de la mer.'),
('ez',25,17,'crampon1923','J''exercerai sur eux de grandes vengeances, les châtiant avec fureur, et ils sauront que je suis Yahweh, quand je ferai tomber sur eux ma vengeance. "'),
('ez',26,1,'crampon1923','La onzième année, le premier du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',26,2,'crampon1923','" Fils de l''homme, parce que Tyr a dit de Jérusalem: Ha! Ha! elle est brisée, la porte des peuples! on se tourne vers moi; je vais me remplir! elle est devenue un désert! —'),
('ez',26,3,'crampon1923','à cause de cela ainsi parle le Seigneur Yahweh: Voici que je viens contre toi, Tyr! Je vais faire monter contre toi des nations nombreuses, comme la mer fait monter ses flots.'),
('ez',26,4,'crampon1923','Elles détruiront les murs de Tyr, et abattront ses tours; je balaierai loin d''elle sa poussière, et je ferai d''elle un rocher nu.'),
('ez',26,5,'crampon1923','Elle sera, au milieu de la mer, un lieu où l''on étend les filets; car moi j''ai parlé, — oracle du Seigneur Yahweh; elle sera la proie des nations.'),
('ez',26,6,'crampon1923','Ses filles qui sont sur la terre ferme seront tuées par l''épée, et on saura que je suis Yahweh.'),
('ez',26,7,'crampon1923','Car ainsi parle le Seigneur Yahweh: Voici que je vais amener du septentrion contre Tyr, Nabuchodonosor, roi de Babylone, le roi des rois, avec des chevaux, des chars, des cavaliers, et une multitude de troupes et un peuple nombreux.'),
('ez',26,8,'crampon1923','Il tuera par l''épée tes filles sur la terre ferme, il construira contre toi des murs, il élèvera contre toi des terrasses, et dressera contre toi la tortue.'),
('ez',26,9,'crampon1923','Il dirigera contre tes murs le choc de ses béliers, et démolira tes tours avec ses crochets.'),
('ez',26,10,'crampon1923','Telle sera la multitude de ses chevaux que leur poussière te couvrira; au bruit des cavaliers, des roues et des chars, tes murs trembleront, quand il entrera dans tes portes, comme on entre dans une ville forcée.'),
('ez',26,11,'crampon1923','Du sabot de ses chevaux, il foulera toutes les rues; il tuera ton peuple par l''épée, et tes puissantes colonnes seront jetées par terre.'),
('ez',26,12,'crampon1923','Ils enlèveront tes richesses, pilleront tes marchandises, abattront tes murailles, renverseront tes beaux palais, et jetteront au milieu des eaux tes pierres, ton bois et ta poussière.'),
('ez',26,13,'crampon1923','Je ferai cesser le bruit de tes chansons, et le son de tes cithares ne se fera plus entendre.'),
('ez',26,14,'crampon1923','Je ferai de toi un rocher nu, tu seras un lieu où l''on étend les filets; tu ne seras plus rebâtie; car moi, Yahweh, j''ai parlé, — oracle du Seigneur Yahweh.'),
('ez',26,15,'crampon1923','Ainsi parle à Tyr le Seigneur Yahweh: Au bruit de ta chute, quand tes blessés pousseront des gémissements, quand le carnage sévira au milieu de toi, les îles ne trembleront-elles pas?'),
('ez',26,16,'crampon1923','Et ils descendront de leurs trônes, tous les princes de la mer; ils quitteront leurs manteaux, et déposeront leurs vêtements brodés; ils se vêtiront d''épouvante, ils s''assoieront sur la terre; ils trembleront à chaque moment, et seront dans la stupeur à cause de toi.'),
('ez',26,17,'crampon1923','Et ils prononceront sur toi une complainte, et ils te diront: " Comment as-tu péri, toi qui te dressais au sein des mers, ô toi ville célèbre, qui étais puissante sur la mer, toi et tes habitants, alors qu''ils inspiraient la terreur à tous les habitants de la mer. "'),
('ez',26,18,'crampon1923','Maintenant les îles trembleront au jour de ta chute, et les îles qui sont dans la mer seront épouvantées de ta fin.'),
('ez',26,19,'crampon1923','Car ainsi parle le Seigneur Yahweh: Quand j''aurai fait de toi une ville déserte, comme les villes qui n''ont point d''habitants; quand j''aurai fait monter sur toi l''abîme, et que les grandes eaux t''auront couverte,'),
('ez',26,20,'crampon1923','je te ferai descendre avec ceux qui sont descendus dans la fosse, vers les peuples d''autrefois; je te ferai habiter dans les profondeurs de la terre, dans les solitudes éternelles, avec ceux qui sont descendus dans la fosse, pour que tu ne sois plus habitée; et je mettrai un ornement sur la terre des vivants.'),
('ez',26,21,'crampon1923','Je ferai de toi un objet d''épouvante, et tu ne seras plus; on te cherchera, et on ne te trouvera plus jamais, — oracle du Seigneur Yahweh. "'),
('ez',27,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',27,2,'crampon1923','" Toi, fils de l''homme, prononce sur Tyr une lamentation,'),
('ez',27,3,'crampon1923','et dis à Tyr: O toi qui es assise aux entrées de la mer, qui trafiquais avec les peuples, vers des îles nombreuses, ainsi parle le Seigneur Yahweh: O Tyr, tu as dit: " Je suis parfaite en beauté! "'),
('ez',27,4,'crampon1923','ton domaine est au sein des mers; ceux qui t''ont bâtie ont rendu parfaite ta beauté.'),
('ez',27,5,'crampon1923','Ils ont construit en cyprès de Sanir toutes tes planches; ils ont pris un cèdre du Liban, pour t''en faire un mât.'),
('ez',27,6,'crampon1923','De chênes de Basant ils ont fait tes rames; ils ont fait tes bancs d''ivoire incrusté dans du buis provenant des îles de Kittim.'),
('ez',27,7,'crampon1923','Le fin lin d''Egypte, avec ses broderies, formait tes voiles, il te servait de pavillon; l''hyacinthe et l''écarlate des îles d''Elisa formaient tes tentures.'),
('ez',27,8,'crampon1923','Les habitants de Sidon et d''Arvad te servaient de rameurs; tes sages qui étaient chez toi, ô Tyr, étaient tes pilotes.'),
('ez',27,9,'crampon1923','Les anciens de Giblium et ses sages étaient chez toi, réparant tes fissures. Tous les vaisseaux de la mer et leurs marins étaient chez toi, pour échanger tes marchandises.'),
('ez',27,10,'crampon1923','Perses, Lydiens et Lybiens étaient dans ton armée, c''étaient tes hommes de guerre; ils suspendaient chez toi le casque et le bouclier, et te donnaient de la splendeur.'),
('ez',27,11,'crampon1923','Les fils d''Arvad et ton armée étaient sur tes murailles tout autour, et des hommes vaillants étaient sur tes forteresses; ils suspendaient leurs boucliers à tes murs tout autour; ils te rendaient parfaite en beauté.'),
('ez',27,12,'crampon1923','Tharsis trafiquait avec toi pour ses richesses de toutes sortes, argent, fer, étain et plomb, dont elle payait tes marchandises.'),
('ez',27,13,'crampon1923','Javan, Tubal et Mosoch faisaient commerce avec toi; avec des âmes d''hommes et des vases de cuivre, ils soldaient tes créances.'),
('ez',27,14,'crampon1923','Ceux de la maison de Thogorma, avec des chevaux de trait, des chevaux de course et des mulets, payaient tes marchandises.'),
('ez',27,15,'crampon1923','Les fils de Dédan faisaient commerce avec toi; le trafic d''îles nombreuses était dans ta main; elles te donnaient en paiement des cornes d''ivoires et de l''ébène.'),
('ez',27,16,'crampon1923','Aram trafiquait avec toi, pour la multitude de tes produits; avec des escarboucles, de la pourpre, des broderies, du fin lin, du corail et des rubis, il soldait tes créances.'),
('ez',27,17,'crampon1923','Juda et le pays d''Israël faisaient commerce avec toi, pour le froment de Minnith, les parfums, le miel, l''huile et le baume.'),
('ez',27,18,'crampon1923','Damas trafiquait avec toi, pour la multitude de tes produits, pour la multitude de tes biens, qu''elle échangeait avec du vin de Helbon et de la laine de Tsachar.'),
('ez',27,19,'crampon1923','Védan et Javan de Ouzzal, avec du fer fabriqué, payaient tes marchandises; la casse et le roseau odorant soldaient ta créance.'),
('ez',27,20,'crampon1923','Dédan faisait commerce avec toi, pour des housses servant à monter à cheval.'),
('ez',27,21,'crampon1923','L''Arabie et tous les princes de Cédar trafiquaient avec toi; pour des moutons, des béliers et des boucs, ils trafiquaient avec toi.'),
('ez',27,22,'crampon1923','Les commerçants de Saba et de Rééma faisaient commerce avec toi; avec tous les meilleurs aromates, avec toute espèce de pierres précieuses et avec de l''or ils payaient tes marchandises.'),
('ez',27,23,'crampon1923','Haran, Chéné et Eden, les commerçants de Saba, Assur et Chelmad faisaient commerce avec toi;'),
('ez',27,24,'crampon1923','ils faisaient avec toi commerce d''objets de luxe; manteaux de pourpre violette et de brocart, coffres à vêtements, cordes tressées et fortes, planches de cèdre pour tes expéditions.'),
('ez',27,25,'crampon1923','Les vaisseaux de Tharsis étaient tes caravanes, pour transporter tes marchandises. Tu es devenue tout à fait opulente et glorieuse, au sein des mers.'),
('ez',27,26,'crampon1923','Mais sur les grandes eaux où te conduisaient ceux qui maniaient tes rames, le vent d''Orient t''a brisée, au sein des mers.'),
('ez',27,27,'crampon1923','Tes richesses, ton trafic, tes marchandises, tes marins et tes pilotes, tes radoubeurs, les courtiers de ton commerce, tous tes hommes de guerre, qui sont chez toi, avec toute la multitude qui est au milieu de toi, tomberont au sein des mers, au jour de ta chute.'),
('ez',27,28,'crampon1923','Au bruit des cris de tes pilotes, les plages trembleront;'),
('ez',27,29,'crampon1923','Et ils descendront de leurs navires, tous ceux qui manient une rame, les marins, tous les pilotes de la mer, et ils se tiendront sur terre.'),
('ez',27,30,'crampon1923','Ils élèveront la voix sur toi, et pousseront des cris amers; ils jetteront de la poussière sur leurs têtes, et se rouleront dans la cendre.'),
('ez',27,31,'crampon1923','Pour toi ils se raseront la tête, ils se revêtiront de sacs, et, dans l''amertume de leur âme, ils verseront sur toi des larmes, des pleurs amers.'),
('ez',27,32,'crampon1923','Dans leur douleur, ils prononceront sur toi une lamentation, ils se lamenteront sur toi, en disant: Qui est comme Tyr, comme celle qui est devenue muette, au milieu de la mer?'),
('ez',27,33,'crampon1923','Quand tes marchandises sortaient des mers, tu rassasiais des peuples nombreux; par l''abondance de tes richesses et de ton trafic, tu enrichissais les rois de la terre.'),
('ez',27,34,'crampon1923','Maintenant que tu as été brisée par les mers, et jetée au fond des eaux, tes marchandises et toute ta multitude ont sombré avec toi.'),
('ez',27,35,'crampon1923','Tous les habitants des îles sont dans la stupeur à cause de toi; leurs rois sont saisis d''épouvante, leurs visages sont bouleversés.'),
('ez',27,36,'crampon1923','Les commerçants des peuples sifflent sur toi; tu es devenue un sujet d''effroi; et pour jamais tu n''es plus! "'),
('ez',28,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',28,2,'crampon1923','" Fils de l''homme, dis au prince de Tyr: Ainsi parle le Seigneur Yahweh: Parce que ton cœur s''est élevé, et que tu as dit: " Je suis un dieu, je siège sur un trône de dieu au milieu des mers ", alors que tu es un homme et non pas un dieu, quoique tu rendes ton cœur pareil au cœur d''un dieu:'),
('ez',28,3,'crampon1923','— Voici que tu es plus sage que Daniel; rien de secret ne t''est caché;'),
('ez',28,4,'crampon1923','par ta sagesse et ton intelligence, tu t''es acquis de la richesse, et tu as entassé de l''or et de l''argent, dans tes trésors;'),
('ez',28,5,'crampon1923','par la grandeur de ta sagesse, par ton commerce, tu as accru ta richesse, et, dans ta richesse, ton cœur s''est élevé, —'),
('ez',28,6,'crampon1923','à cause de cela, ainsi parle le Seigneur Yahweh: Parce que tu as rendu ton cœur pareil au cœur d''un dieu,'),
('ez',28,7,'crampon1923','à cause de cela, voici que je fais venir contre toi des étrangers, féroces entre tous les peuples; ils tireront l''épée contre les chefs-d''œuvre de ta sagesse, et ils profaneront ta splendeur.'),
('ez',28,8,'crampon1923','Ils te feront descendre dans la fosse, et tu mourras de la mort de ceux qui sont tués, au sein des mers.'),
('ez',28,9,'crampon1923','Diras-tu encore: " Je suis un dieu ", en présence de ton meurtrier, quand tu es un homme et non pas un dieu, dans la main de celui qui t''égorge?'),
('ez',28,10,'crampon1923','Tu mourras de la mort des incirconcis par la main des étrangers; car moi j''ai parlé, — oracle du Seigneur Yahweh. "'),
('ez',28,11,'crampon1923','La parole de Yahweh me fut adressée en ces termes: " Fils de l''homme, prononce une lamentation sur le roi de Tyr,'),
('ez',28,12,'crampon1923','et dis-lui: Ainsi parle le Seigneur Yahweh: Tu étais le sceau de la perfection, plein de sagesse et parfait en beauté.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ez',28,13,'crampon1923','Tu étais en Eden, dans un jardin de Dieu; tu étais couvert de pierres précieuses, sardoine, topaze et diamant, chrysolithe, onyx et jaspe, saphir, escarboucle, émeraude et or; tu avais à ton service des tambourins et des fifres, préparés le jour où tu fus créé.'),
('ez',28,14,'crampon1923','Tu étais le chérubin oint pour protéger; je t''avais placé sur la sainte montagne de Dieu; tu y étais; tu marchais au milieu des pierres de feu.'),
('ez',28,15,'crampon1923','Tu fus parfait dans tes voies depuis le jour où tu fus créé, jusqu''à ce que l''iniquité se trouva en toi.'),
('ez',28,16,'crampon1923','En multipliant ton trafic, ton intérieur s''est rempli de violence, et tu as péché, et je t''ai banni de la montagne de Dieu, et je t''ai fait périr, ô chérubin protecteur, au milieu des pierres de feu.'),
('ez',28,17,'crampon1923','Ton cœur s''est élevé à cause de ta beauté; tu as perverti ta sagesse par l''effet de ta splendeur. Je t''ai précipité par terre; je t''ai donné en spectacle aux rois.'),
('ez',28,18,'crampon1923','A force d''iniquité, par l''injustice de ton commerce, tu as profané tes sanctuaires; et j''ai fait sortir un feu du milieu de toi, c''est lui qui t''a dévoré; et je t''ai réduit en cendres sur la terre, aux yeux de tous ceux qui te voyaient.'),
('ez',28,19,'crampon1923','Tous ceux qui te connaissaient parmi les peuples sont dans la stupeur à cause de toi; tu es devenu un objet d''épouvante; et pour jamais tu n''es plus. "'),
('ez',28,20,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',28,21,'crampon1923','" Fils de l''homme, tourne ta face vers Sidon, prophétise sur elle,'),
('ez',28,22,'crampon1923','et dis: Ainsi parle le Seigneur Yahweh: Voici que je viens à toi, Sidon; je vais me glorifier au milieu de toi. On saura que je suis Yahweh quand j''exercerai des jugements contre elle, et que je me sanctifierai en elle.'),
('ez',28,23,'crampon1923','J''enverrai contre elle la peste, et il y aura du sang dans ses rues; il tombera au milieu d''elle des victimes de l''épée qui la frappera de toutes parts; et l''on saura que je suis Yahweh.'),
('ez',28,24,'crampon1923','Alors il n''y aura plus pour la maison d''Israël d''épine malfaisante ou de ronce douloureuse, parmi tous ses voisins qui la méprisent; et l''on saura que je suis le Seigneur Yahweh.'),
('ez',28,25,'crampon1923','Ainsi parle le Seigneur Yahweh: Lorsque je rassemblerai la maison d''Israël du milieu des peuples parmi lesquels elle est dispersée, je me sanctifierai en eux aux yeux des nations; et ils habiteront sur leur terre, que j''aie donnée à mon serviteur, à Jacob.'),
('ez',28,26,'crampon1923','Ils y habiteront en sûreté; ils bâtiront des maisons et planteront des vignes; ils l''habiteront en sûreté, quand j''aurai exercé des jugements sur tous leurs voisins qui les méprisent. Et l''on saura que je suis Yahweh leur Dieu. "'),
('ez',29,1,'crampon1923','La dixième année, au dixième mois, le douze du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',29,2,'crampon1923','" Fils de l''homme, tourne ta face contre Pharaon, roi d''Egypte, et prophétise sur lui et sur l''Egypte tout entière;'),
('ez',29,3,'crampon1923','parle et dis: Ainsi parle le Seigneur Yahweh: Voici que je viens à toi, Pharaon, roi d''Egypte, toi le grand crocodile, couché au milieu de tes fleuves, qui as dit: " Mon fleuve est à moi, et c''est moi qui me le suis fait. "'),
('ez',29,4,'crampon1923','Je mettrai des crochets dans tes mâchoires, et je ferai s''attacher à tes écailles les poissons de tes fleuves; et je te ferai monter du milieu de tes fleuves, toi et tous les poissons de tes fleuves, attachés à tes écailles;'),
('ez',29,5,'crampon1923','et je te jetterai au désert, toi et tous les poissons de tes fleuves; tu tomberas sur la face des champs, tu ne seras ni relevé, ni ramassé; je te donne en pâture aux bêtes de la terre et aux oiseaux du ciel;'),
('ez',29,6,'crampon1923','et tous les habitants de l''Egypte sauront que je suis Yahweh — parce qu''ils ont été un appui de roseau pour la maison d''Israël!'),
('ez',29,7,'crampon1923','Quand ils te prennent avec la main, tu casses, et tu leur déchires toute l''épaule; et quand ils s''appuient sur toi, tu te brises, tu les fais se tenir sur leurs reins à tous.'),
('ez',29,8,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que je ferai venir sur toi l''épée et j''exterminerai du milieu de toi hommes et bêtes;'),
('ez',29,9,'crampon1923','et la terre d''Egypte deviendra une désolation et un désert, et l''on saura que je suis Yahweh. Parce que Pharaon a dit: " Le fleuve est à moi, et c''est moi qui l''ai fait, "'),
('ez',29,10,'crampon1923','à cause de cela, voici que je viens à toi et à tes fleuves; et je ferai du pays d''Egypte des ruines désertes et désolées, de Migdol a Syène, et jusqu''à la frontière de l''Ethiopie.'),
('ez',29,11,'crampon1923','Il n''y passera nul pied d''homme, et nul pied de bête n''y passera, et il sera inhabité pendant quarante ans.'),
('ez',29,12,'crampon1923','Je ferai du pays d''Egypte une désolation, au milieu des pays désolés, et ses villes, au milieu des villes ruinées, seront une désolation, durant quarante ans; je disperserai les Egyptiens parmi les nations; et je les disséminerai en divers pays.'),
('ez',29,13,'crampon1923','Car ainsi parle le Seigneur Yahweh: Au bout de quarante ans, je rassemblerai les Egyptiens, d''entre les peuples chez lesquels ils auront été dispersés;'),
('ez',29,14,'crampon1923','je ferai revenir les captifs d''Egypte, et je les ramènerai dans le pays de Pathros, dans le pays de leur origine, et ils y seront un humble royaume.'),
('ez',29,15,'crampon1923','L''Egypte sera humble entre les royaumes, et elle ne s''élèvera plus au-dessus des nations; je réduirai leur nombre, afin qu''ils ne dominent pas sur les nations.'),
('ez',29,16,'crampon1923','Ils ne seront plus pour la maison d''Israël un objet de confiance; ils lui rappelleront l''iniquité qu''elle commettait en se tournant vers eux; et l''on saura que je suis le Seigneur Yahweh. "'),
('ez',29,17,'crampon1923','La vingt-septième année, au premier mois, le premier du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',29,18,'crampon1923','" Fils de l''homme, Nabuchodonosor, roi de Babylone, a fait faire à son armée un rude service contre Tyr; toute tête est devenue chauve, toute épaule meurtrie; et il n''a retiré de Tyr aucun salaire, ni pour lui, ni pour son armée, pour le service qu''il a fait contre elle.'),
('ez',29,19,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que je donne à Nabuchodonosor, roi de Babylone, le pays d''Egypte; il en emportera les richesses; il dépouillera ce qu''il y a à dépouiller, il pillera son butin et prendra ses dépouilles: et ce sera un salaire pour son armée.'),
('ez',29,20,'crampon1923','Pour prix du travail qu''il a fait contre Tyr, je lui donne le pays d''Egypte, parce qu''ils ont travaillé pour moi — oracle du Seigneur Yahweh.'),
('ez',29,21,'crampon1923','En ce jour-là, je ferai pousser une corne à la maison d''Israël, et je te donnerai d''ouvrir la bouche au milieu d''eux; et ils sauront que je suis Yahweh. "'),
('ez',30,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',30,2,'crampon1923','" Fils de l''homme prophétise et dis: Ainsi parle le Seigneur Yahweh: Hurlez! Ah! ce jour!'),
('ez',30,3,'crampon1923','Car le jour est proche, le jour est proche pour Yahweh! Jour de nuage! Ce sera le temps des nations!'),
('ez',30,4,'crampon1923','Une épée viendra sur l''Egypte, et il y aura de l''angoisse en Ethiopie, lorsque les blessés à mort tomberont en Egypte, quand on enlèvera ses richesses, et qu''on renversera ses fondements.'),
('ez',30,5,'crampon1923','Ethiopiens, Libyens et Lydiens, étrangers de toutes sortes, Chub et les fils du pays de l''alliance tomberont avec eux par l''épée.'),
('ez',30,6,'crampon1923','Ainsi parle Yahweh: ils tomberont les soutiens de l''Egypte, et l''orgueil de sa force sera abaissé. De Migdol à Syène on y tombera par l''épée; — oracle du Seigneur Yahweh.'),
('ez',30,7,'crampon1923','Elle sera désolée au milieu des pays désolés, et ses villes seront ruinées au milieu des villes ruinées;'),
('ez',30,8,'crampon1923','et l''on saura que je suis Yahweh, quand je mettrai le feu à l''Egypte et que tous ses auxiliaires seront brisés.'),
('ez',30,9,'crampon1923','En ce jour-là, des messagers s''en iront de ma part sur des barques, pour troubler l''Ethiopie dans sa sécurité, et il y aura chez elle de l''angoisse, comme dans le jour de l''Egypte, car voici qu''il arrive!'),
('ez',30,10,'crampon1923','Ainsi parle le Seigneur Yahweh: je ferai cesser tout le bruit de l''Egypte, par la main de Nabuchodonosor, roi de Babylone.'),
('ez',30,11,'crampon1923','Lui et son peuple avec lui, nation féroce entre toutes, seront amenés pour ravager le pays; ils tireront leurs épées contre l''Egypte, et rempliront de morts le pays.'),
('ez',30,12,'crampon1923','Je changerai les fleuves en lieux arides; je livrerai le pays aux mains d''hommes méchants, et je dévasterai le pays et tout ce qu''il contient, par la main des étrangers. Moi, Yahweh, j''ai parlé.'),
('ez',30,13,'crampon1923','Ainsi parle le Seigneur Yahweh: J''exterminerai les infâmes idoles, et je ferai disparaître de Noph les faux dieux, et il n''y aura plus de prince sorti du pays d''Egypte, et je répandrai la crainte dans le pays d''Egypte.'),
('ez',30,14,'crampon1923','Je désolerai Pathros, je mettrai le feu à Tsoan, j''exercerai des jugements sur No;'),
('ez',30,15,'crampon1923','je répandrai mon courroux sur Sin, la forteresse de l''Egypte, et j''exterminerai la multitude de No.'),
('ez',30,16,'crampon1923','Je mettrai le feu à l''Egypte; Sin se tordra de douleur, No sera forcée, et Noph se verra assaillie en plein jour.'),
('ez',30,17,'crampon1923','Les jeunes hommes d''Aven et de Bubaste tomberont par l''épée, et elles-mêmes iront en captivité.'),
('ez',30,18,'crampon1923','A Taphnés le jour s''obscurcira, quand je briserai là le joug de l''Egypte, et que l''orgueil de sa force y prendra fin. Un nuage la couvrira, et ses filles iront en captivité.'),
('ez',30,19,'crampon1923','J''exercerai des jugements sur l''Egypte, et l''on saura que je suis Yahweh. "'),
('ez',30,20,'crampon1923','La onzième année, au premier mois, le sept du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',30,21,'crampon1923','" Fils de l''homme, le bras de Pharaon, roi d''Egypte, je l''ai brisé, et voici qu''on ne l''a point pansé, en employant des remèdes, en appliquant des bandes, pour le panser et le rendre assez fort pour manier l''épée.'),
('ez',30,22,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici que je viens à Pharaon, roi d''Egypte; je lui briserai les deux bras, celui qui est valide et celui qui est déjà brisé, et je ferai tomber l''épée de sa main.'),
('ez',30,23,'crampon1923','Je disperserai les Egyptiens parmi les nations, et les disséminerai dans les pays.'),
('ez',30,24,'crampon1923','Je fortifierai les bras du roi de Babylone; et je mettrai mon épée dans sa main; je briserai les bras de Pharaon, et il gémira devant lui, comme gémit un homme blessé à mort.'),
('ez',30,25,'crampon1923','Je fortifierai les bras du roi de Babylone, et les bras de Pharaon tomberont. Et l''on saura que je suis Yahweh, quand je mettrai mon épée dans la main du roi de Bablylone, et qu''il la tournera contre le pays d''Egypte.'),
('ez',30,26,'crampon1923','Je disperserai les Egyptiens parmi les nations, et je les disséminerai dans les pays, et l''on saura que je suis Yahweh. "'),
('ez',31,1,'crampon1923','La onzième année, au troisième mois, le premier du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',31,2,'crampon1923','" Fils de l''homme, dis à Pharaon, roi d''Egypte, et à sa multitude: A qui ressembles-tu dans ta grandeur?'),
('ez',31,3,'crampon1923','Voilà qu''Assur était un cèdre sur le Liban, à la belle ramure, à l''ombrage épais, à la taille élevée, et ayant sa cime dans les nues.'),
('ez',31,4,'crampon1923','Les eaux l''avaient fait croître, l''abîme l''avait fait grandir, en faisant couler ses fleuves autour du lieu où il était planté et en envoyant ses ruisseaux à tous les arbres des champs.'),
('ez',31,5,'crampon1923','C''est pourquoi sa taille s''élevait, plus haute que les arbres des champs; ses branches avaient grandi, ses rameaux s''étaient allongés, grâce aux eaux abondantes du temps de sa croissance.'),
('ez',31,6,'crampon1923','Dans ses branches tous les oiseaux du ciel nichaient; sous ses rameaux mettaient bas tous les animaux des champs, et à son ombre étaient assises des nations nombreuses.'),
('ez',31,7,'crampon1923','Il était beau par sa grandeur, par la longueur de ses branches, car ses racines plongeaient dans des eaux abondantes.'),
('ez',31,8,'crampon1923','Les cèdres ne l''obscurcissaient pas dans le jardin de Dieu, les cyprès n''égalaient pas ses branches, et les platanes n''étaient pas comme ses rameaux; aucun arbre dans le jardin de Dieu ne l''égalait en beauté.'),
('ez',31,9,'crampon1923','Je l''avais rendu beau par la multitude de ses rameaux; tous les arbres d''Eden lui portaient envie, tous ceux qui sont dans le jardin de Dieu.'),
('ez',31,10,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Parce qu''il s''est élevé en hauteur, parce qu''il a porté sa cime jusque dans les nues; et que son cœur s''est enorgueilli de son élévation,'),
('ez',31,11,'crampon1923','je l''ai livré aux mains du dieu des nations, qui le traitera à sa guise; à cause de sa méchanceté, je l''ai chassé.'),
('ez',31,12,'crampon1923','Des étrangers l''ont coupé, — nation féroce entre toutes, — et laissé là; sur les montagnes et dans toutes les vallées, ses branches sont tombées; ses rameaux brisés gisent dans tous les ravins du pays; tous les peuples de la terre se sont éloignés de son ombre et l''ont abandonné.'),
('ez',31,13,'crampon1923','Sur ses débris tous les oiseaux du ciel viennent se poser, et dans ses rameaux se sont retirés tous les animaux des champs:'),
('ez',31,14,'crampon1923','afin qu''aucun arbre planté sur les eaux ne s''élève en hauteur et ne porte sa cime jusque dans les nues, et qu''aucun de ceux qui s''abreuvent d''eau ne s''appuie sur lui-même dans son orgueil. Car ils sont tous voués à la mort, aux profondeurs de la terre, mêlés aux enfants des hommes, à ceux qui descendent dans la fosse.'),
('ez',31,15,'crampon1923','Ainsi parle le Seigneur Yahweh: Le jour où il descendit au schéol, j''ai fait mener le deuil; à cause de lui j''ai voilé l''abîme, j''ai retenu le cours de ses fleuves, et les grandes eaux se sont arrêtées; à cause de lui, j''ai assombri le Liban, et à cause de lui, tous les arbres des champs ont langui.'),
('ez',31,16,'crampon1923','Au bruit de sa chute, j''ai fait trembler les nations, quand je l''ai fait descendre au schéol, avec ceux qui descendent dans la fosse. Ils se sont consolés dans les profondeurs de la terre, tous les arbres d''Eden, les plus beaux et les plus magnifiques du Liban, tous ceux que les eaux abreuvaient.'),
('ez',31,17,'crampon1923','Ceux-là aussi sont descendus avec lui au schéol, vers les victimes de l''épée, qui étaient son bras et étaient assises à son ombre au milieu des nations.'),
('ez',31,18,'crampon1923','Ainsi à qui ressembles-tu en gloire et en grandeur, parmi les arbres d''Eden? Tu seras précipité avec les arbres d''Eden, dans les profondeurs de la terre, pour être couché au milieu d''incirconcis, avec ceux que l''épée a transpercés. Tel sera le sort de Pharaon et de toute sa multitude; — oracle du Seigneur Yahweh. "'),
('ez',32,1,'crampon1923','La douzième année, au douzième mois, le premier du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',32,2,'crampon1923','" Fils de l''homme! prononce une lamentation sur Pharaon, roi d''Egypte, et dis-lui: Lion des nations, tu es anéanti! Tu étais comme le crocodile dans les mers; tu t''élançais dans tes fleuves; de tes pieds tu en remuais les eaux et tu troublais leurs canaux.'),
('ez',32,3,'crampon1923','Ainsi parle le Seigneur Yahweh: J''étendrai sur toi mon filet au moyen d''une assemblée de peuples nombreux, et ils te tireront dehors avec mes rets.'),
('ez',32,4,'crampon1923','Je t''abandonnerai sur le sol, je te jetterai sur la face des champs et je ferai se poser sur toi tous les oiseaux du ciel, et se rassasier de toi les bêtes de toute la terre.'),
('ez',32,5,'crampon1923','Je mettrai ta chair sur les montagnes, et je remplirai de tes débris les vallées.'),
('ez',32,6,'crampon1923','J''arroserai le pays des flots de ton sang jusqu''aux montagnes, et les ravins seront remplis de toi.'),
('ez',32,7,'crampon1923','En t''éteignant je voilerai les cieux, et j''obscurcirai leurs étoiles; je couvrirai de nuages le soleil, et la lune ne donnera plus sa lumière.'),
('ez',32,8,'crampon1923','Je vêtirai de deuil, à cause de toi, tous les astres qui brillent dans le ciel, et je répandrai des ténèbres sur ton pays; — oracle du Seigneur Yahweh.'),
('ez',32,9,'crampon1923','Je troublerai le cœur de beaucoup de peuples, quand je ferai parvenir la nouvelle de ta ruine chez les nations, en des pays que tu ne connaissais point.'),
('ez',32,10,'crampon1923','Je frapperai de stupeur à ton sujet beaucoup de peuples; à cause de toi, leurs rois seront pris de frisson, quand j''agiterai mon glaive devant eux; et ils trembleront à tout instant, chacun pour sa vie, au jour de ta ruine.'),
('ez',32,11,'crampon1923','Car ainsi parle le Seigneur Yahweh: L''épée du roi de Babylone viendra sur toi!'),
('ez',32,12,'crampon1923','Je ferai tomber ta multitude sous l''épée d''hommes vaillants, féroces entre tous les peuples; ils abattront l''orgueil de l''Egypte, et toute sa multitude sera exterminée.'),
('ez',32,13,'crampon1923','Je ferai disparaître tout son bétail, du bord des grandes eaux; le pied de l''homme ne les troublera plus, et le sabot des bestiaux ne les troublera plus.'),
('ez',32,14,'crampon1923','Alors je ferai reposer ses eaux, et couler ses fleuves comme l''huile, — oracle du Seigneur Yahweh,'),
('ez',32,15,'crampon1923','quand je réduirai la terre d''Egypte en solitude, et que le pays sera dépouillé de ce qu''il contient, quand je frapperai tous ceux qui y habitent; et ils sauront que je suis Yahweh.'),
('ez',32,16,'crampon1923','Telle est la lamentation, et on la prononcera, les filles des nations la prononceront; elles la prononceront sur l''Egypte et toute sa multitude; — oracle du Seigneur Yahweh. "'),
('ez',32,17,'crampon1923','La douzième année, le quinze du mois, la parole de Yahweh me fut adressée en ces termes:'),
('ez',32,18,'crampon1923','" Fils de l''homme, gémis sur la multitude de l''Egypte; fais-la descendre, elle et les filles des nations illustres, dans les profondeurs de la terre, avec ceux qui descendent dans la fosse.'),
('ez',32,19,'crampon1923','Qui surpassais-tu en beauté?... Descends, et couche-toi avec les incirconcis!'),
('ez',32,20,'crampon1923','Ils tomberont au milieu de ceux qu''a transpercés l''épée! L''épée est donnée; entraînez l''Egypte et toutes ses multitudes!'),
('ez',32,21,'crampon1923','Les plus puissants parmi les héros lui parleront, du milieu du schéol, avec ses soutiens: Ils sont descendus et sont couchés, les incirconcis transpercés par l''épée!'),
('ez',32,22,'crampon1923','Là est Assur avec tout son peuple, autour de lui sont ses sépulcres; tous ont été transpercés, tous sont tombés par l''épée.'),
('ez',32,23,'crampon1923','Ses sépulcres sont placés au plus profond de la fosse; son peuple est rangé autour de son sépulcre; tous ont été transpercés, tous sont tombés par l''épée; eux qui avaient répandu la terreur sur la terre des vivants!'),
('ez',32,24,'crampon1923','Là est Elam, et toute sa multitude, autour de son sépulcre; tous ont été transpercés, tous sont tombés par l''épée, ces incirconcis qui sont descendus dans les profondeurs de la terre, eux qui avaient répandu la terreur sur la terre des vivants; ils ont porté leur ignominie avec ceux qui sont descendus dans la fosse.'),
('ez',32,25,'crampon1923','Au milieu de ceux qui ont été transpercés, on prépare sa couche pour lui avec toute sa multitude; autour de lui sont ses sépulcres; tous sont des incirconcis, tous ont été transpercés par l''épée; car leur terreur s''était répandue sur la terre des vivants, et ils ont porté leur ignominie, avec ceux qui sont descendus dans la fosse; on les a placés parmi les égorgés.'),
('ez',32,26,'crampon1923','Là sont Mosoch, Thubal et toute sa multitude; autour de lui sont ses sépulcres; tous sont incirconcis, tous ont été transpercés par l''épée; car ils avaient répandu la terreur sur la terre des vivants.'),
('ez',32,27,'crampon1923','Ils ne se coucheront point avec les vaillants, qui sont tombés d''entre les incirconcis, qui sont descendus au schéol, avec leurs armes de guerre, et sous la tête desquels on a mis leur épée; mais leurs iniquités sont sur leurs os, car ils étaient la terreur des vaillants, sur la terre des vivants.'),
('ez',32,28,'crampon1923','Toi aussi, tu seras brisé au milieu des incirconcis, et tu seras couché avec ceux qui ont été transpercés par l''épée.'),
('ez',32,29,'crampon1923','Là est Edom, ses rois et tous ses princes, qui, malgré leur vaillance, ont été mis avec ceux qui ont été transpercés par l''épée; eux aussi sont couchés avec les incirconcis, et avec ceux qui sont descendus dans la fosse.'),
('ez',32,30,'crampon1923','Là sont les princes du septentrion, eux tous et tous les Sidoniens; ils sont descendus avec les transpercés, malgré la terreur qu''ils inspiraient; malgré leur vaillance, ils sont confondus! Ils sont couchés, ces incirconcis, avec ceux qui ont été transpercés par l''épée, et ils portent leur ignominie, avec ceux qui sont descendus dans la fosse.'),
('ez',32,31,'crampon1923','Pharaon les verra et se consolera, au sujet de toute sa multitude; Pharaon est transpercé par l''épée avec toute son armée, — oracle du Seigneur Yahweh!'),
('ez',32,32,'crampon1923','Car j''avais répandu sa terreur sur la terre des vivants, et le voilà couché au milieu des incirconcis, avec ceux qui ont été transpercés par l''épée, lui, Pharaon, et toute sa multitude, — oracle du Seigneur Yahweh! "'),
('ez',33,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',33,2,'crampon1923','" Fils de l''homme, parle aux enfants de ton peuple, et dis-leur: Quand je fais venir l''épée contre un pays et que les habitants de ce pays, prenant quelqu''un du milieu d''eux, l''établissent comme sentinelle,'),
('ez',33,3,'crampon1923','et que cet homme, voyant l''épée venir contre le pays, sonne de la trompette et avertit le peuple,'),
('ez',33,4,'crampon1923','si celui qui entend le son de la trompette ne se laisse pas avertir et que l''épée survienne et le surprenne, son sang sera sur sa tête:'),
('ez',33,5,'crampon1923','il a entendu le son de la trompette et ne s''est pas laissé avertir; son sang sera sur lui; mais s''il s''est laissé avertir, il aura sauvé sa vie.'),
('ez',33,6,'crampon1923','Que si la sentinelle, voyant venir l''épée, ne sonne pas de la trompette, et qu''ainsi le peuple ne soit pas averti, et que l''épée survienne et surprenne l''un d''entre eux, cet homme sera surpris dans son iniquité, mais je demanderai compte de son sang à la sentinelle.'),
('ez',33,7,'crampon1923','Et toi, fils de l''homme, je t''ai établi comme sentinelle pour la maison d''Israël: quand tu entendras de ma bouche une parole, tu les avertiras de ma part.'),
('ez',33,8,'crampon1923','Quand j''aurai dit au méchant: " Méchant, tu mourras certainement! " si tu ne parles pas pour avertir le méchant de quitter sa voie, celui-ci, étant méchant, mourra dans son iniquité; mais je te demanderai compte de son sang.'),
('ez',33,9,'crampon1923','Mais si tu avertis le méchant afin qu''il se détourne de sa voie, et qu''il ne se détourne pas de sa voie, il mourra dans son iniquité; mais toi, tu auras sauvé ton âme.'),
('ez',33,10,'crampon1923','Et toi, fils de l''homme, dis à la maison d''Israël: Voici que vous parlez en ces termes: " Nos transgressions et nos péchés sont sur nous, et c''est à cause d''eux que nous dépérissons; comment pourrions-nous vivre? "'),
('ez',33,11,'crampon1923','Dis-leur: Je suis vivant! — oracle du Seigneur Yahweh: je ne prends point plaisir à la mort du méchant, mais à ce que le méchant se détourne de sa voie et qu''il vive. Revenez, revenez de vos mauvaises voies! Et pourquoi mourriez-vous, maison d''Israël?'),
('ez',33,12,'crampon1923','Et toi, fils de l''homme, dis aux enfants de ton peuple: La justice du juste ne le sauvera point au jour de sa transgression; et le méchant ne tombera point pour sa méchanceté le jour où il se détournera de sa méchanceté, de même que le juste ne pourra pas vivre par sa justice le jour où il péchera.'),
('ez',33,13,'crampon1923','Quand j''aurai dit au juste qu''il vivra certainement, si, se confiant dans sa justice, il fait le mal, on ne se rappellera plus toutes ses œuvres justes, et, à cause du mal qu''il aura fait, à cause de lui il mourra.'),
('ez',33,14,'crampon1923','Et quand j''aurai dit au méchant: " Tu mourras certainement! " s''il se détourne de son péché et fait ce qui est juste et droit;'),
('ez',33,15,'crampon1923','si ce méchant rend le gage, s''il restitue ce qu''il a ravi, s''il suit les préceptes qui donnent la vie, sans faire le mal, certainement il vivra; il ne mourra pas!'),
('ez',33,16,'crampon1923','On ne se rappellera plus tous ses péchés qu''il a commis; il a fait ce qui est droit et juste; il vivra certainement.'),
('ez',33,17,'crampon1923','Les enfants de ton peuple ont dit: " La voie du Seigneur n''est pas droite. " C''est leur voie à eux qui n''est pas droite.'),
('ez',33,18,'crampon1923','Quand un juste se détourne de sa justice et fait le mal, il meurt à cause de cela;'),
('ez',33,19,'crampon1923','et quand un méchant se détourne de sa méchanceté et fait ce qui est droit et juste, à cause de cela il vit.'),
('ez',33,20,'crampon1923','Et vous dites: " La voie de Yahweh n''est pas droite! " Je vous jugerai chacun selon vos voies, maison d''Israël "'),
('ez',33,21,'crampon1923','La douzième année de notre captivité, au dixième mois, le cinq du mois, un fugitif de Jérusalem arriva vers moi en disant: " La ville a été prise. "'),
('ez',33,22,'crampon1923','Or la main de Yahweh avait été sur moi le soir avant l''arrivée du fugitif, et elle avait ouvert ma bouche avant qu''il vint vers moi le matin; et ainsi ma bouche fut ouverte, et je ne fus plus muet.'),
('ez',33,23,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',33,24,'crampon1923','" Fils de l''homme, ceux qui habitent ces ruines-là sur la terre d''Israël, parlent en ces termes: " Abraham était seul; et il a eu en partage le pays; nous, nous sommes nombreux, et la possession du pays nous a été donnée. "'),
('ez',33,25,'crampon1923','C''est pourquoi dis-leur: Ainsi parle le Seigneur Yahweh: Vous mangez la chair avec le sang, vous levez les yeux vers vos idoles infâmes, vous répandez le sang, et vous posséderiez le pays!'),
('ez',33,26,'crampon1923','Vous vous êtes appuyés sur votre épée, vous avez commis l''abomination; vous avez déshonoré chacun la femme de votre prochain, et vous posséderiez le pays!'),
('ez',33,27,'crampon1923','Voici ce que tu leur diras: Ainsi parle le Seigneur Yahweh: Je suis vivant! Ceux qui sont dans les ruines tomberont par l''épée; ceux qui sont dans la campagne, je les livrerai en nourriture aux bêtes féroces; et ceux qui sont dans les lieux forts et dans les cavernes mourront de la peste.'),
('ez',33,28,'crampon1923','Je ferai du pays une solitude et un désert, et l''orgueil de sa force prendra fin; et les montagnes du pays seront désolées, sans que personne y passe.'),
('ez',33,29,'crampon1923','Et l''on saura que je suis Yahweh, quand j''aurai fait du pays une solitude et un désert, à cause de toutes les abominations qu''ils ont commises. "'),
('ez',33,30,'crampon1923','" Et toi, fils de l''homme, les enfants de ton peuple s''entretiennent de toi le long des murs et aux portes des maisons; ils se parlent entre eux, l''un à l''autre, en ces termes: " Venez entendre quelle est la parole qui vient de Yahweh. "'),
('ez',33,31,'crampon1923','Et ils viennent vers toi comme vient la foule; mon peuple s''assied devant toi; ils écoutent tes paroles et ne les mettent point en pratique; ils font ce qui est agréable à leur bouche; leur cœur poursuit leur gain.'),
('ez',33,32,'crampon1923','Et voici que tu es pour eux un chanteur agréable, qui a une belle voix et joue bien de son instrument; ils entendent tes paroles et ne les mettent point en pratique.'),
('ez',33,33,'crampon1923','Quand ces choses arriveront, — et voici qu''elles arrivent, — ils sauront qu''il y avait un prophète au milieu d''eux. "'),
('ez',34,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',34,2,'crampon1923','" Fils de l''homme, prophétise sur les pasteurs d''Israël; prophétise et dis-leur, à ces pasteurs: Ainsi parle le Seigneur Yahweh: Malheur aux pasteurs d''Israël, qui n''ont fait que se paître eux-mêmes! N''est-ce pas le troupeau que les pasteurs doivent paître?'),
('ez',34,3,'crampon1923','Vous mangiez la graisse, vous vous revêtiez de la laine, vous tuiez ce qui était gras; vous ne paissiez pas le troupeau.'),
('ez',34,4,'crampon1923','Vous n''avez pas fortifié les brebis débiles, vous n''avez pas soigné celle qui était malade, vous n''avez pas pansé celle qui était blessée, vous n''avez pas ramené celle qui était égarée, vous n''avez pas cherché celle qui était perdue; mais vous avez dominé sur elles avec violence et cruauté.'),
('ez',34,5,'crampon1923','Et elles se sont dispersées, faute de pasteur; elles sont devenues la proie de toutes les bêtes des champs, et elles se sont dispersées.'),
('ez',34,6,'crampon1923','Mes brebis sont errantes sur toutes les montagnes, et sur toute colline élevée; sur toute la face du pays mes brebis ont été dispersées, et personne n''en a souci, et personne ne les recherche.'),
('ez',34,7,'crampon1923','C''est pourquoi, ô pasteurs, écoutez la parole de Yahweh:'),
('ez',34,8,'crampon1923','Je suis vivant, — oracle du Seigneur Yahweh: Parce que mes brebis ont été mises au pillage, et que mes brebis sont devenues la proie de toutes les bêtes sauvages, faute de pasteur, et parce que mes pasteurs ne prenaient pas souci de mes brebis, mais que ces pasteurs se paissaient eux-mêmes et ne paissaient pas mes brebis,'),
('ez',34,9,'crampon1923','à cause de cela, ô pasteurs, écoutez la parole de Yahweh:'),
('ez',34,10,'crampon1923','Ainsi parle le Seigneur Yahweh: Voici que je viens aux pasteurs; je redemanderai à leurs mains mes brebis; et je ne leur laisserai plus de troupeau à paître, et les pasteurs ne se paîtront plus eux-mêmes; j''arracherai mes brebis à leur bouche, et elles ne seront plus pour eux une proie à dévorer.'),
('ez',34,11,'crampon1923','Car ainsi parle le Seigneur Yahweh: Me voici; je veux moi-même prendre souci de mes brebis, et je les passerai en revue.'),
('ez',34,12,'crampon1923','Comme un pasteur passe en revue son troupeau, au jour où il se trouve au milieu de ses brebis éparses, ainsi je passerai en revue mes brebis, et je les retirerai de tous les lieux où elles ont été dispersées, en un jour de nuages et de ténèbres.'),
('ez',34,13,'crampon1923','Je les ferai sortir du milieu des peuples, et je les rassemblerai des divers pays; je les ramènerai sur leur sol, et je les ferai paître sur les montagnes d''Israël, dans les vallées et dans tous les lieux habités du pays.'),
('ez',34,14,'crampon1923','Je les ferai paître dans de bons pâturages, et leur bercail sera sur les hautes montagnes d''Israël; là elles reposeront dans un bon bercail, et elles paîtront dans un gras pâturage, sur les montagnes d''Israël.'),
('ez',34,15,'crampon1923','Moi je paîtrai mes brebis, moi, je les ferai reposer, — oracle du Seigneur Yahweh.'),
('ez',34,16,'crampon1923','Je chercherai celle qui était perdue, je ramènerai celle qui était égarée, je panserai celle qui est blessée, et je fortifierai celle qui est malade; mais celle qui est grasse et celle qui est forte, je les détruirai; je les paîtrai avec justice.'),
('ez',34,17,'crampon1923','Et vous, mes brebis, ainsi parle le Seigneur Yahweh: Voici que je vais juger entre brebis et brebis, entre les béliers et les boucs.'),
('ez',34,18,'crampon1923','Est-ce trop peu pour vous de paître un bon pâturage, que vous fouliez de vos pieds le reste de votre pâture; ou de boire des eaux limpides, que vous troubliez le reste avec vos pieds?'),
('ez',34,19,'crampon1923','Et mes brebis devraient paître ce que vos pieds ont foulé, et boire ce que vos pieds ont troublé!'),
('ez',34,20,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Me voici; je vais juger entre la brebis grasse et la brebis maigre.'),
('ez',34,21,'crampon1923','Parce que vous avez heurté du flanc et de l''épaule, et frappé de vos cornes toutes les brebis débiles jusqu''à ce que vous les eussiez chassées dehors,'),
('ez',34,22,'crampon1923','je sauverai mes brebis, et elles ne seront plus au pillage, et je jugerai entre brebis et brebis.'),
('ez',34,23,'crampon1923','Je leur susciterai un seul pasteur, — et il les fera paître, — mon serviteur David; c''est lui qui les paîtra, et c''est lui qui sera pour elles un pasteur.'),
('ez',34,24,'crampon1923','Moi, Yahweh, je serai leur Dieu, et mon serviteur David sera prince au milieu d''elles; moi, Yahweh, j''ai parlé.'),
('ez',34,25,'crampon1923','Je conclurai avec elles une alliance de paix; je ferai disparaître du pays les bêtes féroces, et ils habiteront en sécurité dans le désert, et ils dormiront dans les forêts.'),
('ez',34,26,'crampon1923','Je ferai d''eux et des environs de ma colline une bénédiction; je ferai tomber la pluie en sa saison, ce seront des pluies de bénédiction.'),
('ez',34,27,'crampon1923','Et l''arbre des champs donnera son fruit, et la terre donnera ses produits; ils seront en sécurité sur leur terre, et ils sauront que je suis Yahweh, quand je briserai les barres de leur joug, et que je les délivrerai de la main de ceux qui les asservissent.'),
('ez',34,28,'crampon1923','Ils ne seront plus un butin pour les nations, les bêtes de la terre ne les dévoreront plus, et ils habiteront en sécurité, sans que personne les effraie.'),
('ez',34,29,'crampon1923','Je ferai pousser pour eux une végétation de renom; ils ne seront plus enlevés par la famine dans le pays, et ils ne porteront plus l''opprobre des nations.'),
('ez',34,30,'crampon1923','Et ils sauront que moi, Yahweh, leur Dieu, je suis avec eux, et que eux, la maison d''Israël, ils sont mon peuple, — oracle du Seigneur Yahweh.'),
('ez',34,31,'crampon1923','Et vous mes brebis, troupeau que je pais, vous êtes hommes; et moi, je suis votre Dieu, — oracle du Seigneur Yahweh. "'),
('ez',35,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',35,2,'crampon1923','" Fils de l''homme, tourne ta face vers la montagne de Séir et prophétise contre elle, et dis-lui:'),
('ez',35,3,'crampon1923','Ainsi parle le Seigneur Yahweh: Voici que je viens à toi, montagne de Séir, je vais étendre ma main sur toi, et faire de toi une solitude et un désert.'),
('ez',35,4,'crampon1923','Je réduirai tes villes en ruines, tu seras une solitude; et tu sauras que je suis Yahweh.'),
('ez',35,5,'crampon1923','Parce que tu as une haine éternelle et que tu as livré au glaive les enfants d''Israël, au temps de leur calamité, au temps de l''iniquité finale,'),
('ez',35,6,'crampon1923','à cause de cela, je suis vivant, — oracle du Seigneur Yahweh: Je te mettrai à sang, et le sang te poursuivra; parce que tu n''as pas haï le sang, le sang te poursuivra.'),
('ez',35,7,'crampon1923','Et je ferai de la montagne de Séir une solitude et un désert, et j''en retrancherai tout allant et venant.'),
('ez',35,8,'crampon1923','Je remplirai ses monts de ses blessés à mort; sur tes collines, dans tes vallées et dans tous tes ravins tomberont les hommes égorgés par l''épée.'),
('ez',35,9,'crampon1923','Je te réduirai en solitudes éternelles, et tes villes ne seront plus habitées; et vous saurez que je suis Yahweh.'),
('ez',35,10,'crampon1923','Parce que tu as dit: " Les deux nations et les deux pays seront à moi, et nous en prendrons possession! " — et Yahweh était là! —'),
('ez',35,11,'crampon1923','à cause de cela, je suis vivant, — oracle du Seigneur Yahweh: j''agirai selon ta colère, et selon ta jalousie, que tu as montrées dans ta haine contre eux, et je me ferai connaître au milieu d''eux quand je te jugerai.'),
('ez',35,12,'crampon1923','Et tu sauras que moi, Yahweh, j''ai entendu tous tes outrages, que tu proférais contre les montagnes d''Israël, en disant: " Elles sont dévastées, elles nous sont données comme une proie à dévorer "'),
('ez',35,13,'crampon1923','Vous m''avez bravé par vos discours; et vous avez multiplié vos paroles contre moi; moi, j''ai entendu!'),
('ez',35,14,'crampon1923','Ainsi parle le Seigneur Yahweh: Quand toute la terre se réjouira, je ferai de toi une solitude.'),
('ez',35,15,'crampon1923','Comme tu t''es réjouie au sujet de l''héritage de la maison d''Israël parce qu''il était dévasté, je te ferai de même: tu seras dévastée, montagne de Séir, ainsi que l''Idumée tout entière. Et l''on saura que je suis Yahweh. "'),
('ez',36,1,'crampon1923','" Et toi, fils de l''homme, prophétise aux montagnes d''Israël et dis: Montagnes d''Israël, écoutez la parole de Yahweh:'),
('ez',36,2,'crampon1923','Ainsi parle le Seigneur Yahweh: Parce que l''ennemi a dit de vous: " Ha! Ha! les hauteurs éternelles sont devenues notre propriété! "'),
('ez',36,3,'crampon1923','à cause de cela prophétise et dis: Ainsi parle le Seigneur Yahweh: Attendu qu''on vous a dévastées et foulées aux pieds de toutes parts, pour que vous fussiez une propriété pour ce qui reste des nations, et attendu que vous avez été l''objet des discours des langues méchantes et des malins propos des gens,'),
('ez',36,4,'crampon1923','à cause de cela, montagnes d''Israël, écoutez la parole du Seigneur Yahweh: Ainsi parle le Seigneur Yahweh aux montagnes et aux collines, aux ravins et aux vallons, aux ruines désolées et aux villes abandonnées, qui ont été livrées au pillage et à la risée de ce qui reste des nations d''alentour;'),
('ez',36,5,'crampon1923','à cause de cela, ainsi parle le Seigneur Yahweh: Oui, dans le feu de ma jalousie, j''ai parlé contre ce qui reste des nations, et contre toute l''Idumée, qui se sont adjugé en possession mon pays, dans la joie de tout leur cœur, et dans le mépris de leur âme, pour le mettre au pillage;'),
('ez',36,6,'crampon1923','à cause de cela, prophétise touchant la terre d''Israël, et dis aux montagnes et aux collines, aux ravins et aux vallons: Ainsi parle le Seigneur Yahweh: Voici que j''ai parlé dans ma jalousie et dans ma fureur, parce que vous avez porté l''opprobre des nations.'),
('ez',36,7,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Moi, j''ai levé ma main! Les nations qui vous entourent porteront, elles aussi, leur opprobre.'),
('ez',36,8,'crampon1923','Et vous, montagnes d''Israël, vous pousserez vos rameaux, et vous porterez votre fruit, pour mon peuple d''Israël; car ils sont près de venir.'),
('ez',36,9,'crampon1923','Car voici que je viens à vous; et je tourne ma face vers vous; et vous serez cultivées et ensemencées.'),
('ez',36,10,'crampon1923','Je multiplierai sur vous les hommes, la maison d''Israël tout entière; les villes seront habitées, et les ruines seront rebâties.'),
('ez',36,11,'crampon1923','Je multiplierai sur vous hommes et bestiaux; ils seront nombreux et se multiplieront; je vous rendrai habitées comme autrefois; je vous ferai plus de bien que dans votre commencement, et vous saurez que je suis Yahweh.'),
('ez',36,12,'crampon1923','J''amènerai sur vous des hommes, mon peuple d''Israël, et ils te posséderont; tu seras leur héritage, et tu ne les priveras plus de leurs enfants.'),
('ez',36,13,'crampon1923','Ainsi parle le Seigneur Yahweh: Parce qu''ils vous disent: Tu as dévoré des hommes, et tu as privé ta nation de ses enfants,'),
('ez',36,14,'crampon1923','à cause de cela, tu ne dévoreras plus d''hommes, et tu ne priveras plus ta nation de ses enfants, — oracle du Seigneur Yahweh.'),
('ez',36,15,'crampon1923','Je ne te ferai plus entendre les outrages des nations, tu ne porteras plus l''opprobre des peuples, et tu ne feras plus broncher ta nation, — oracle du Seigneur Yahweh. "'),
('ez',36,16,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',36,17,'crampon1923','" Fils de l''homme, ceux de la maison d''Israël, quand ils habitaient sur leur terre, l''ont souillée par leur conduite et par leurs œuvres; leur conduite était devant moi comme la souillure d''une femme.'),
('ez',36,18,'crampon1923','Et j''ai versé sur eux mon courroux, à cause du sang qu''ils ont versé sur le pays, et parce qu''ils l''ont souillé par leurs infâmes idoles.'),
('ez',36,19,'crampon1923','Je les ai dispersés parmi les nations, et ils ont été disséminés dans les pays; je les ai jugés selon leur conduite et selon leurs œuvres.'),
('ez',36,20,'crampon1923','Arrivés chez les nations où ils sont allés, ils ont déshonoré mon saint nom, quand on disait d''eux: " C''est le peuple de Yahweh, c''est de son pays qu''ils sont sortis. "'),
('ez',36,21,'crampon1923','Et j''ai eu pitié de mon saint nom, que ceux de la maison d''Israël ont déshonoré parmi les nations chez lesquelles ils sont allés.'),
('ez',36,22,'crampon1923','C''est pourquoi dis à la maison d''Israël: Ainsi parle le Seigneur Yahweh: Ce n''est pas à cause de vous que je le fais, maison d''Israël; c''est pour mon saint nom que vous avez déshonoré, parmi les nations chez lesquelles vous êtes allés.'),
('ez',36,23,'crampon1923','Je sanctifierai mon grand nom qui est déshonoré, parmi les nations au milieu desquelles vous l''avez déshonoré, et les nations sauront que je suis le Seigneur Yahweh, — oracle du Seigneur Yahweh, quand je me sanctifierai en vous, à leurs yeux.'),
('ez',36,24,'crampon1923','Je vous tirerai d''entre les nations, je vous rassemblerai de tous les pays, et je vous ramènerai sur votre terre.'),
('ez',36,25,'crampon1923','Je ferai sur vous une aspersion d''eaux pures, et vous serez purs; de toutes vos souillures et de toutes vos abominations je vous purifierai.'),
('ez',36,26,'crampon1923','Et je vous donnerai un cœur nouveau, et je mettrai au dedans de vous un esprit nouveau; j''ôterai de votre chair le cœur de pierre; et je vous donnerai un cœur de chair.'),
('ez',36,27,'crampon1923','Je mettrai au dedans de vous mon Esprit, et je ferai que vous suivrez mes ordonnances, que vous observerez mes lois et les pratiquerez.'),
('ez',36,28,'crampon1923','Vous habiterez le pays que j''ai donné à vos pères, vous serez mon peuple, et moi, je serai votre Dieu.'),
('ez',36,29,'crampon1923','Je vous sauverai de toutes vos souillures; j''appellerai le froment et le ferai abonder, et je n''enverrai plus sur vous la famine.'),
('ez',36,30,'crampon1923','Je multiplierai les fruits des arbres, et le produit des champs, afin que vous ne portiez plus l''opprobre et la famine parmi les nations.'),
('ez',36,31,'crampon1923','Vous vous rappellerez vos voies mauvaises et vos œuvres qui n''étaient pas bonnes, et vous vous prendrez en dégoût, à cause de vos iniquités et de vos abominations.'),
('ez',36,32,'crampon1923','Ce n''est pas à cause de vous que je le fais, — oracle du Seigneur Yahweh, — sachez-le; ayez honte et rougissez de votre conduite, maison d''Israël.'),
('ez',36,33,'crampon1923','Ainsi parle le Seigneur Yahweh: Le jour où je vous purifierai de toutes vos iniquités, je rendrai aux villes leurs habitants, et ce qui est en ruine sera rebâti.'),
('ez',36,34,'crampon1923','La terre dévastée sera cultivée, elle qui n''était que désolation aux yeux de tous les passants.'),
('ez',36,35,'crampon1923','On dira: Cette terre, qui était dévastée, est devenue comme un jardin d''Eden, et les villes ruinées, désolées et renversées, sont habitées comme des places fortes.'),
('ez',36,36,'crampon1923','Et les nations qui seront restées autour de vous sauront que moi, Yahweh, j''ai rebâti ce qui était renversé, planté ce qui était ravagé. Moi, Yahweh, je dis et je fais!'),
('ez',36,37,'crampon1923','Ainsi parle le Seigneur Yahweh: Encore en ceci je me laisserai chercher par la maison d''Israël, pour le faire en leur faveur: je multiplierai les hommes comme des troupeaux.'),
('ez',36,38,'crampon1923','Tels que les troupeaux de brebis saintes, tels que les troupeaux de Jérusalem dans ses solennités, ainsi des troupeaux d''hommes rempliront les villes dévastées; et l''on saura que je suis Yahweh. "'),
('ez',37,1,'crampon1923','La main de Yahweh fut sur moi, et Yahweh me fit sortir en esprit et me plaça au milieu de la plaine, et elle était couverte d''ossements.'),
('ez',37,2,'crampon1923','Il me fit passer près d''eux, tout autour; ils étaient en très grand nombre sur la face de la plaine, et voici qu''ils étaient tout à fait desséchés.'),
('ez',37,3,'crampon1923','Et il me dit: " Fils de l''homme, ces ossements revivront-ils? " Je répondis: " Seigneur Yahweh, vous le savez. "'),
('ez',37,4,'crampon1923','Il me dit: " Prophétise sur ces ossements et dis-leur: Ossements desséchés, entendez la parole de Yahweh!'),
('ez',37,5,'crampon1923','Ainsi parle le Seigneur Yahweh à ces ossements: Voici que je vais faire entrer en vous l''esprit, et vous vivrez.'),
('ez',37,6,'crampon1923','Je mettrai sur vous des muscles, je ferai croître sur vous de la chair et j''étendrai sur vous de la peau; je mettrai en vous l''esprit, et vous vivrez; et vous saurez que je suis Yahweh. "'),
('ez',37,7,'crampon1923','Je prophétisai comme j''en avais reçu l''ordre. Et comme je prophétisais, il y eut un son; puis voici un bruit retentissant, et les os se rapprochèrent les uns des autres.'),
('ez',37,8,'crampon1923','Et je vis; et voici que des muscles et de la chair avaient crû au-dessus d''eux, et qu''une peau s''était étendue au-dessus d''eux; mais il n''y avait point d''esprit en eux.'),
('ez',37,9,'crampon1923','Et il me dit: " Prophétise à l''esprit, prophétise, fils de l''homme, et dis à l''esprit: Ainsi parle le Seigneur Yahweh: Viens des quatre vents, esprit, et souffle sur ces hommes tués, et qu''ils vivent. "'),
('ez',37,10,'crampon1923','Et je prophétisai comme il me l''avait ordonné; et l''esprit entra en eux, et ils prirent vie, et ils se tinrent sur leurs pieds: grande, très grande armée!'),
('ez',37,11,'crampon1923','Et il me dit: " Fils de l''homme, ces ossements, c''est toute la maison d''Israël. Voici qu''ils disent: Nos os sont desséchés, notre espérance est morte, nous sommes perdus!'),
('ez',37,12,'crampon1923','C''est pourquoi prophétise et dis-leur: Ainsi parle le Seigneur Yahweh: Voici que je vais ouvrir vos tombeaux, et je vous ferai remonter hors de vos tombeaux, ô mon peuple, et je vous ramènerai sur la terre d''Israël.'),
('ez',37,13,'crampon1923','Et vous saurez que je suis Yahweh, quand j''ouvrirai vos tombeaux et que je vous ferai remonter hors de vos tombeaux, ô mon peuple.'),
('ez',37,14,'crampon1923','Je mettrai mon Esprit en vous, et vous vivrez; et je vous donnerai du repos sur votre sol, et vous saurez que moi, Yahweh, je dis et j''exécute, — oracle de Yahweh! "'),
('ez',37,15,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',37,16,'crampon1923','" Et toi, fils de l''homme, prends un bois et écris dessus: " A Juda et aux enfants d''Israël qui lui sont unis. " Prends un autre bois et écris dessus: " A Joseph "; ce sera le bois d''Ephraïm et de toute la maison d''Israël qui lui est unie.'),
('ez',37,17,'crampon1923','Rapproche-les l''un de l''autre pour n''avoir qu''un seul bois, et qu''ils soient un dans ta main.'),
('ez',37,18,'crampon1923','Et quand les fils de ton peuple te parleront en ces termes: " Ne nous expliqueras-tu pas ce que signifient pour toi ces choses? "'),
('ez',37,19,'crampon1923','dis-leur: Ainsi parle le Seigneur Yahweh: Voici que je prendrai le bois de Joseph, qui est dans la main d''Ephraïm, et les tribus d''Ephraïm qui lui sont unies et je les joindrai au bois de Juda, et j''en ferai un seul bois, et ils seront un dans ma main.'),
('ez',37,20,'crampon1923','Les bois sur lesquels tu écriras seront dans ta main, à leurs yeux.'),
('ez',37,21,'crampon1923','Et dis-leur: Ainsi parle le Seigneur Yahweh: Voici que je vais prendre les enfants d''Israël du milieu des nations où ils sont allés; je les rassemblerai de toutes parts et je les ramènerai sur leur sol.'),
('ez',37,22,'crampon1923','Je ferai d''eux une seule nation dans le pays, sur les montagnes d''Israël; un seul roi régnera sur eux tous; ils ne seront plus deux nations, et ils ne seront plus séparés en deux royaumes.'),
('ez',37,23,'crampon1923','Ils ne se souilleront plus par leurs infâmes idoles, par leurs abominations et par tous leurs crimes; je les sauverai de toutes leurs rébellions par lesquelles ils ont péché, et je les purifierai; ils seront mon peuple, et je serai leur Dieu.'),
('ez',37,24,'crampon1923','Mon serviteur David sera leur roi, et il y aura un seul pasteur pour eux tous; ils suivront mes ordonnances, ils observeront mes commandements et les mettront en pratique.'),
('ez',37,25,'crampon1923','Et ils habiteront dans le pays que j''ai donné à mon serviteur Jacob et dans lequel ont habité leurs pères; ils y habiteront, eux et leurs enfants, et les enfants de leurs enfants, à jamais; et David, mon serviteur, sera leur prince pour toujours.'),
('ez',37,26,'crampon1923','Et je conclurai avec eux une alliance de paix; ce sera une alliance éternelle avec eux; et je les établirai et je les multiplierai; et j''érigerai mon sanctuaire au milieu d''eux pour toujours.'),
('ez',37,27,'crampon1923','Mon habitation sera au dessus d''eux; je serai leur Dieu, et ils seront mon peuple.'),
('ez',37,28,'crampon1923','Et les nations sauront que je suis Yahweh qui sanctifie Israël, quand mon sanctuaire sera au milieu d''eux pour toujours. "'),
('ez',38,1,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('ez',38,2,'crampon1923','Fils de l''homme, tourne ta face vers Gog, au pays de Magog, prince souverain de Mosoch et de Thubal, et prophétise sur lui, et dis:'),
('ez',38,3,'crampon1923','Ainsi parle le Seigneur Yahweh: Voici que je viens à toi, Gog, prince souverain de Mosoch et de Thubal.'),
('ez',38,4,'crampon1923','Je t''emmènerai; je mettrai des crocs à tes mâchoires, et je te ferai sortir, toi et toute ton armée, chevaux et cavaliers, tous magnifiquement équipés, troupe nombreuse, avec le bouclier et l''écu, tous maniant l''épée.'),
('ez',38,5,'crampon1923','Perses, Ethiopiens et Libyens seront avec eux, tous avec le bouclier et le casque.'),
('ez',38,6,'crampon1923','Gomer et tous ses bataillons, la maison de Thogorma, des confins du septentrion et tous ses bataillons, peuples nombreux, seront avec toi.'),
('ez',38,7,'crampon1923','Tiens-toi prêt, fais tes préparatifs, toi et toute la multitude qui s''est assemblée autour de toi; sois leur chef.'),
('ez',38,8,'crampon1923','Au bout de beaucoup de jours tu seras visité; à la fin des années tu viendras contre la nation soustraite à l''épée, rassemblée d''entre beaucoup de peuples sur les montagnes d''Israël, qui ont été longtemps désertes, la nation ramenée du milieu des peuples, et qui habite toute entière en sécurité.'),
('ez',38,9,'crampon1923','Tu monteras, tu arriveras comme l''ouragan, tu seras comme le nuage qui va couvrir la terre, toi et tous tes bataillons, et des peuples nombreux avec toi.'),
('ez',38,10,'crampon1923','Ainsi parle le Seigneur Yahweh: En ce jour-là, des pensées s''élèveront dans ton cœur, et tu concevras un mauvais dessein.'),
('ez',38,11,'crampon1923','Tu diras: Je monterai contre un pays ouvert; je viendrai vers ces gens tranquilles qui habitent en sécurité, qui ont tous des demeures sans murailles, qui n''ont ni verrous ni portes.'),
('ez',38,12,'crampon1923','Tu iras pour piller et faire du butin, pour porter ta main sur des ruines maintenant habitées, sur un peuple recueilli du milieu des nations, qui élève des troupeaux et acquiert des biens, et qui habite au centre de la terre.'),
('ez',38,13,'crampon1923','Saba, Dédan, les trafiquants de Tharsis et tous ses lionceaux te diront: " Est-ce pour piller que tu viens? Est-ce pour faire du butin que tu as assemblé tes troupes; pour emporter de l''argent et de l''or, pour prendre des troupeaux et des biens, pour ravir de grandes dépouilles? "'),
('ez',38,14,'crampon1923','C''est pourquoi prophétise, fils de l''homme, et dis à Gog: Ainsi parle le Seigneur Yahweh: N''est-ce pas? En ce jour-là, quand mon peuple habitera en sécurité, tu le sauras,'),
('ez',38,15,'crampon1923','et tu viendras de ton pays, des confins du septentrion, toi et des peuples nombreux avec toi, tous montés sur des chevaux, grande troupe et puissante armée.'),
('ez',38,16,'crampon1923','Et tu monteras contre mon peuple d''Israël; comme une nuée qui va couvrir le pays. Ce sera à la fin des jours que je te ferai venir contre mon pays, afin que les nations me connaissent, quand je me sanctifierai en toi à leurs yeux, ô Gog.'),
('ez',38,17,'crampon1923','Ainsi parle le Seigneur Yahweh: N''es-tu pas celui dont,j''ai parlé aux jours d''autrefois, par l''intermédiaire de mes serviteurs les prophètes d''Israël, qui ont prophétisé en ces jours-là, pendant des années, que je te ferais venir contre eux?'),
('ez',38,18,'crampon1923','Et il arrivera en ce jour-là, le jour où Gog entrera dans la terre d''Israël, — oracle du Seigneur Yahweh, mon courroux montera à mes narines,'),
('ez',38,19,'crampon1923','et dans ma jalousie, dans le feu de ma fureur, — je l''ai dit, — il y aura en ce jour-là un grand tremblement sur la terre d''Israël.'),
('ez',38,20,'crampon1923','Devant moi trembleront les poissons de la mer, les oiseaux du ciel, les bêtes des champs, tout reptile qui rampe sur la terre, et tout homme qui est sur la face de la terre; les montagnes s''écrouleront et les rochers tomberont, et toute muraille tombera sur le sol.'),
('ez',38,21,'crampon1923','Et j''appellerai contre lui l''épée sur toutes mes montagnes, — oracle du Seigneur Yahweh, et chacun tournera son épée contre son frère.'),
('ez',38,22,'crampon1923','J''exercerai mon jugement sur lui par la peste et par le sang; je ferai pleuvoir des torrents de pluie et des pierres de grêle, du feu et du soufre, sur lui et sur ses bataillons, et sur les peuples nombreux qui seront avec lui.'),
('ez',38,23,'crampon1923','Je me montrerai grand et saint, et je me ferai connaître aux yeux de beaucoup de nations, et elles sauront que je suis Yahweh. "'),
('ez',39,1,'crampon1923','" Et toi, fils de l''homme, prophétise contre Gog et dis: Ainsi parle le Seigneur Yahweh: Voici que je viens à toi, Gog, prince souverain de Mosoch et de Thubal.'),
('ez',39,2,'crampon1923','Je t''emmènerai, je te conduirai et je te ferai monter des confins du septentrion, et je t''amènerai sur les montagnes d''Israël.'),
('ez',39,3,'crampon1923','Là j''abattrai ton arc de ta main gauche, et je ferai tomber tes flèches de ta main droite.'),
('ez',39,4,'crampon1923','Tu tomberas sur les montagnes d''Israël, toi et tous tes bataillons, et les peuples qui seront avec toi; aux oiseaux de proie, aux oiseaux de toute sorte, et aux animaux des champs je t''ai donné en pâture.'),
('ez',39,5,'crampon1923','Tu tomberas sur la face des champs, car moi j''ai parlé, — oracle du Seigneur Yahweh.'),
('ez',39,6,'crampon1923','J''enverrai le feu dans le pays de Magog et chez ceux qui habitent en sécurité dans les îles, et ils sauront que je suis Yahweh.'),
('ez',39,7,'crampon1923','Et je ferai connaître mon saint nom au milieu de mon peuple d''Israël, et je ne profanerai plus mon saint nom; et les nations sauront que je suis Yahweh, saint en Israël.'),
('ez',39,8,'crampon1923','Ces choses viennent et elles s''accompliront, — oracle du Seigneur Yahweh; c''est là le jour dont j''ai parlé!'),
('ez',39,9,'crampon1923','Alors les habitants des villes d''Israël sortiront; ils brûleront et mettront en flammes les armes, l''écu, le bouclier, l''arc, les flèches, le bâton et le javelot; ils en feront du feu pendant sept ans.'),
('ez',39,10,'crampon1923','Ils n''apporteront plus le bois de la campagne, et ils n''en couperont point dans les forêts; car c''est avec les armes qu''ils feront du feu; ils dépouilleront ceux qui les dépouillaient, ils pilleront ceux qui les pillaient, — oracle du Seigneur Yahweh.'),
('ez',39,11,'crampon1923','Et il arrivera en ce jour-là: Je donnerai à Gog un lieu où sera son sépulcre en Israël, la vallée des Passants, à l''orient de la mer; et ce sépulcre fermera le chemin aux passants. C''est là qu''on enterrera Gog et toute sa multitude, et on appellera ce lieu la vallée d''Hamon-Gog.'),
('ez',39,12,'crampon1923','La maison d''Israël les enterrera, afin de purifier le pays, sept mois durant.'),
('ez',39,13,'crampon1923','Tout le peuple du pays enterrera, et ce sera pour eux un jour glorieux; celui où j''aurai fait éclater ma gloire, — oracle du Seigneur Yahweh.'),
('ez',39,14,'crampon1923','Et ils désigneront des hommes dont la charge sera de parcourir le pays, enterrant les passants, ceux qui seront restés sur la face de la terre, — pour la purifier; après sept mois ils feront leurs recherches.'),
('ez',39,15,'crampon1923','Et quand ces hommes parcourront le pays, si l''un d''eux voit des ossements humains, il dressera à coté un signal, jusqu''à ce que les enterreurs les aient mis en terre dans la vallée d''Hamon-Gog.'),
('ez',39,16,'crampon1923','Et Hamona sera même le nom d''une ville; et c''est ainsi qu''ils purifieront le pays.'),
('ez',39,17,'crampon1923','Et toi, fils de l''homme, ainsi parle le Seigneur Yahweh: Dis aux oiseaux de toute sorte, et à tous les animaux des champs: Assemblez-vous et venez! Réunissez-vous des alentours à mon sacrifice que je fais pour vous, un grand sacrifice sur les montagnes d''Israël; vous mangerez de la chair et vous boirez du sang.'),
('ez',39,18,'crampon1923','C''est de la chair de héros que vous mangerez, c''est du sang de princes de la terre que vous boirez, béliers, agneaux et boucs, jeunes taureaux, bœufs gras de Basan tous ensemble.'),
('ez',39,19,'crampon1923','Vous mangerez de la graisse à satiété, vous boirez du sang jusqu''à l''ivresse, à mon sacrifice que j''ai fait pour vous.'),
('ez',39,20,'crampon1923','Vous vous rassasierez à ma table de coursiers et de cavaliers, de héros et de guerriers de toute sorte, — oracle du Seigneur Yahweh.'),
('ez',39,21,'crampon1923','Je manifesterai ma gloire parmi les nations, et toutes les nations verront mon jugement que j''exécuterai; et ma main que j''étendrai sur eux.'),
('ez',39,22,'crampon1923','Et la maison d''Israël saura que je suis Yahweh, son Dieu, dès ce jour et à l''avenir:'),
('ez',39,23,'crampon1923','et les nations sauront que c''est à cause de son iniquité que la maison d''Israël a été menée en exil, parce qu''ils m''ont été infidèles; aussi je leur ai caché ma face, je les ai livrés aux mains de leurs ennemis, afin qu''ils tombassent tous par l''épée.'),
('ez',39,24,'crampon1923','C''est en raison de leur souillure et de leur prévarication que je les ai traités ainsi et que je leur ai caché ma face.'),
('ez',39,25,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Maintenant, je ramènerai les captifs de Jacob, j''aurai compassion de toute la maison d''Israël, et je me montrerai jaloux de mon nom.'),
('ez',39,26,'crampon1923','Ils porteront leur ignominie, et toutes les infidélités qu''ils ont commises envers moi, quand ils habiteront sur leur terre en sécurité, sans que personne les inquiète.'),
('ez',39,27,'crampon1923','Quand je les ramènerai d''entre les peuples, que je les rassemblerai des pays de leurs ennemis et que je me serai sanctifié en eux, aux yeux de beaucoup de nations,'),
('ez',39,28,'crampon1923','ils sauront que je suis Yahweh, leur Dieu, en ce que je les aurai emmenés captifs chez les nations, et rassemblés ensuite sur leur propre sol; et je ne laisserai plus aucun d''eux là-bas.'),
('ez',39,29,'crampon1923','Et je ne leur cacherai plus ma face, parce que j''aurai répandu mon Esprit sur la maison d''Israël, — oracle du Seigneur Yahweh. "'),
('ez',40,1,'crampon1923','La vingt-cinquième année de notre captivité, au commencement de l''année, le dixième jour du mois, la quatorzième année après que la ville eut été ruinée, ce jour-là même, la main de Yahweh fut sur moi, et il m''emmena en ce lieu-là.'),
('ez',40,2,'crampon1923','Dans des visions divines il m''emmena au pays d''Israël, et il me plaça sur une montagne très élevée; et sur cette montagne, il y avait comme une construction de ville au midi.'),
('ez',40,3,'crampon1923','Quand il m''eut amené là, je vis un homme dont l''aspect était comme l''aspect de l''airain; dans sa main était un cordeau de lin et une canne à mesurer, et il se tenait dans le portique.'),
('ez',40,4,'crampon1923','Cet homme me dit: " Fils de l''homme, regarde de tes yeux et écoute de tes oreilles, et applique ton cœur à tout ce que je vais te faire voir, car c''est pour qu''on te le fasse voir que tu as été amené ici. Fais connaître à la maison d''Israël tout ce que tu vas voir. "'),
('ez',40,5,'crampon1923','Et voici qu''un mur extérieur entourait la maison de tous côtés, et l''homme avait à la main un roseau à mesurer de six coudées, chaque coudée étant d''une coudée et un palme. Il mesura la largeur de cette construction: elle était d''un roseau; et la hauteur: elle était d''un roseau.'),
('ez',40,6,'crampon1923','Puis il alla au portique dont la façade était dans la direction de l''orient, et il en monta les degrés; et il mesura le seuil du portique, qui était d''un roseau en largeur; savoir, le premier seuil, d''un roseau en largeur.'),
('ez',40,7,'crampon1923','Chaque loge avait un roseau en longueur et un roseau en largeur; entre les loges, il y avait cinq coudées. Le seuil du portique, du côté du vestibule du portique, du côté de la maison, était d''un roseau.'),
('ez',40,8,'crampon1923','Il mesura le vestibule du portique, du côté de la maison; il était d''un roseau.'),
('ez',40,9,'crampon1923','Il mesura encore le vestibule du portique: il avait huit coudées, et ses piliers deux coudées. Le vestibule du portique était du côté de la maison.'),
('ez',40,10,'crampon1923','Les loges du portique oriental étaient au nombre de trois d''un côté, et de trois de l''autre côté; toutes les trois avaient la même mesure, et les piliers de chaque côté avaient aussi la même mesure.'),
('ez',40,11,'crampon1923','Il mesura la largeur de l''ouverture du portique: elle était de dix coudées; et la longueur du portique de treize coudées.'),
('ez',40,12,'crampon1923','Il y avait devant les loges une clôture d''une coudée de chaque côté; et chaque loge avait six coudées d''un côté et six de l''autre.'),
('ez',40,13,'crampon1923','Et il mesura le portique du toit d''une loge jusqu''au toit de l''autre: vingt-cinq coudées en largeur, d''une porte jusqu''à l''autre porte.'),
('ez',40,14,'crampon1923','Il compta soixante coudées pour les piliers, et à ces piliers touchait le parvis qui entourait le portique.'),
('ez',40,15,'crampon1923','L''espace entre le devant de la porte d''entrée et le devant du vestibule intérieur de la porte était de cinquante coudées.'),
('ez',40,16,'crampon1923','Il y avait aux loges, à leurs piliers, des fenêtres grillées du côté intérieur du portique, tout autour; il en était de même aux vestibules; et ainsi il y avait des fenêtres tout autour, donnant à l''intérieur; et aux pilastres il y avait des palmiers.'),
('ez',40,17,'crampon1923','Puis il me conduisit au parvis extérieur: et voici qu''il y avait des chambres et un pavé disposés tout autour du parvis; il y avait trente chambres le long du pavé.'),
('ez',40,18,'crampon1923','Le pavé longeait les portiques, correspondant à la longueur des portiques; c''était le pavé inférieur.'),
('ez',40,19,'crampon1923','Il mesura la largeur du devant du portique inférieur jusqu''au devant du parvis intérieur: cent coudées, à l''orient et au septentrion.'),
('ez',40,20,'crampon1923','Quant au portique du parvis extérieur dont la façade est dans la direction du nord, il en mesura la longueur et la largeur,'),
('ez',40,21,'crampon1923','— ses loges, trois d''un côté et trois de l''autre; ses piliers et son vestibule ayant la même mesure que ceux du premier portique, — cinquante coudées en longueur et vingt-cinq coudées en largeur.'),
('ez',40,22,'crampon1923','Ses fenêtres, son vestibule et ses palmiers avaient la même mesure que ceux du portique dont la façade est dans la direction de l''orient; on y montait par sept degrés, et son vestibule était en face des degrés.'),
('ez',40,23,'crampon1923','Il y avait un portique au parvis intérieur, en face du portique du septentrion comme en face de celui de l''orient; il mesura d''un portique à l''autre: cent coudées.'),
('ez',40,24,'crampon1923','Il me conduisit ensuite dans la direction du midi, et voici un portique dans la direction du midi; il en mesura les pilastres et le vestibule, qui avaient les mêmes dimensions'),
('ez',40,25,'crampon1923','— il avait tout autour, ainsi que son vestibule, des fenêtres pareilles aux autres fenêtres —: cinquante coudées en longueur et vingt-cinq coudées en largeur.'),
('ez',40,26,'crampon1923','On y montait par sept degrés, et son vestibule était en face des degrés; il y avait des palmiers à ses pilastres, l''un d''un côté, l''autre de l''autre.'),
('ez',40,27,'crampon1923','Le parvis intérieur avait aussi un portique dans la direction du midi; il mesura d''un portique à l''autre dans la direction du midi: cent coudées.'),
('ez',40,28,'crampon1923','Il me conduisit dans le parvis intérieur par le portique du midi, et il mesura le portique qui était au midi, qui avait les mêmes dimensions'),
('ez',40,29,'crampon1923','— ses loges, ses pilastres et son vestibule avaient les mêmes dimensions; et il avait, ainsi que son vestibule, des fenêtres tout autour —: cinquante coudées de longueur et vingt-cinq coudées de largeur.'),
('ez',40,30,'crampon1923','Il y avait des vestibules tout autour, de vingt-cinq coudées en longueur et de cinq coudées en largeur.'),
('ez',40,31,'crampon1923','Son vestibule était du côté du parvis extérieur; il avait des palmiers à ses pilastres et huit degrés pour y monter.'),
('ez',40,32,'crampon1923','Puis il me conduisit, dans le parvis intérieur, vers la direction de l''orient, et il mesura le portique qui avait les mêmes dimensions'),
('ez',40,33,'crampon1923','— ses loges, ses pilastres et son vestibule avaient les mêmes dimensions; et il avait, ainsi que son vestibule, des fenêtres tout autour — cinquante coudées en longueur et vingt-cinq coudées en largeur.'),
('ez',40,34,'crampon1923','Son vestibule touchait au parvis extérieur; il avait des palmiers à ses pilastres, d''un côté et de l''autre, et huit degrés pour y monter.'),
('ez',40,35,'crampon1923','Puis il me conduisit vers le portique du septentrion, et il y mesura les mêmes dimensions'),
('ez',40,36,'crampon1923','— Il y avait à ses loges, à ses pilastres et à son vestibule des fenêtres tout autour —: cinquante coudées de longueur et vingt-cinq coudées de largeur.'),
('ez',40,37,'crampon1923','Ses piliers touchaient au parvis extérieur; il y avait des palmiers sur ses pilastres et huit degrés pour y monter.'),
('ez',40,38,'crampon1923','Il y avait une chambre, avec sa porte, près des pilastres des portiques; c''est là qu''on lavait les holocaustes.'),
('ez',40,39,'crampon1923','Dans le vestibule du portique, il y avait deux tables d''un côté et deux tables de l''autre, sur lesquelles on devait immoler les victimes destinées à l''holocauste, au sacrifice pour le péché et au sacrifice pour le délit.'),
('ez',40,40,'crampon1923','Au côté extérieur, au septentrion pour celui qui montait à l''entrée du portique, il y avait deux tables, et de l''autre côté, vers le vestibule du portique, deux tables.'),
('ez',40,41,'crampon1923','Il se trouvait ainsi, sur les côtés de la porte, quatre tables d''une part et quatre tables de l''autre; en tout huit tables, sur lesquelles on devait immoler.'),
('ez',40,42,'crampon1923','Il y avait encore quatre tables servant aux holocaustes, en pierre de taille, longues d''une coudée et demie, larges d''une coudée et demie et hautes d''une coudée, sur lesquelles on posait les instruments avec lesquels on immolait les victimes destinées à l''holocauste et aux autres sacrifices.'),
('ez',40,43,'crampon1923','Des crochets d''un palme étaient fixés tout autour de l''édifice; et la chair des sacrifices devait être placée sur les tables.'),
('ez',40,44,'crampon1923','En dehors du portique intérieur, il y avait les chambres des chantres, dans le parvis intérieur; celle qui était à côté du portique septentrional, avait sa façade dans la direction du midi; l''autre à côté du portique oriental, avait sa façade dans la direction du nord.'),
('ez',40,45,'crampon1923','Il me dit: " Cette chambre dont la façade est dans la direction du midi est pour les prêtres qui sont chargés du service de la maison.'),
('ez',40,46,'crampon1923','Et la chambre dont la façade est dans la direction du nord est pour les prêtres chargés du service de l''autel. " Ce sont les fils de Sadoc qui, parmi les enfants de Lévi, s''approchent de Yahweh pour le servir.'),
('ez',40,47,'crampon1923','Puis il mesura le parvis, qui était carré, ayant cent coudées de longueur et cent coudées de largeur. L''autel était devant la maison.'),
('ez',40,48,'crampon1923','Il me conduisit ensuite vers le vestibule de la maison, et il mesura le pilier du vestibule: cinq coudées d''un côté et cinq coudées de l''autre; et la largeur du portique: trois coudées d''un côté et trois coudées de l''autre.'),
('ez',40,49,'crampon1923','La longueur du vestibule était de vingt coudées, et la largeur de onze coudées, aux degrés par lesquels on y montait; et il y avait des colonnes près des piliers, l''une d''un côté, l''autre de l''autre.'),
('ez',41,1,'crampon1923','Puis il me conduisit dans le temple, et il en mesura les piliers: six coudées de largeur d''un côté, et six coudées de largeur de l''autre côté, largeur de la tente.'),
('ez',41,2,'crampon1923','La largeur de la porte était de dix coudées; les parois latérales de la porte avaient cinq coudées d''un côté et cinq coudées de l''autre. Il mesura la longueur du temple: quarante coudées, et la largeur: vingt coudées.'),
('ez',41,3,'crampon1923','Il entra ensuite à l''intérieur et il mesura les piliers de la porte: deux coudées, et la porte elle-même: six coudées, et la largeur de la porte: sept coudées.'),
('ez',41,4,'crampon1923','Il mesura une longueur de vingt coudées et une largeur de vingt coudées du côté du temple, et il me dit: " C''est le Saint des saints ".'),
('ez',41,5,'crampon1923','Il mesura le mur de la maison: six coudées, et la largeur de l''édifice latéral, quatre coudées, tout autour de la maison.'),
('ez',41,6,'crampon1923','Quant aux cellules latérales, il y avait trois cellules superposées, et cela trente fois; elles aboutissaient au mur construit pour ces cellules tout autour de la maison, en sorte qu''elles s''appuyaient sans être engagées dans le mur de la maison.'),
('ez',41,7,'crampon1923','L''espace s''élargissait pour la circulation à chaque étage de cellules, car l''édifice avait un couloir circulaire à chaque étage tout autour; c''est pourquoi cette partie de l''édifice s''élargissait à chaque étage, et ainsi le couloir d''en bas était moins large que celui d''en haut, et le couloir du milieu en proportion des deux autres.'),
('ez',41,8,'crampon1923','Je vis que la maison tout autour était sur une élévation; le fondement des cellules latérales était d''un roseau plein, de six coudées vers l''angle.'),
('ez',41,9,'crampon1923','Le mur extérieur de l''édifice latéral était large de cinq coudées; à la suite venait l''assise de l''édifice latéral de la maison.'),
('ez',41,10,'crampon1923','De là jusqu''aux chambres, il y avait une largeur de vingt coudées tout autour de la maison.'),
('ez',41,11,'crampon1923','L''entrée de l''édifice latéral était sur l''assise, une porte dans la direction du nord et une porte dans la direction du midi; la largeur de l''assise était de cinq coudées tout autour.'),
('ez',41,12,'crampon1923','Le bâtiment qui était en face de l''espace vide du côté de l''occident avait soixante-dix coudées de large; la muraille du bâtiment avait cinq coudées de large tout autour, et sa longueur était de quatre-vingt-dix coudées.'),
('ez',41,13,'crampon1923','Il mesura la maison: largeur: cent coudées; l''espace vide, le bâtiment et ses murailles: longueur, cent coudées;'),
('ez',41,14,'crampon1923','et la largeur de la façade de la maison et de l''espace libre, vers l''orient: cent coudées.'),
('ez',41,15,'crampon1923','Il mesura la longueur du bâtiment en face de l''espace libre qui est sur le derrière du bâtiment, et ses galeries de chaque côté: cent coudées. Dans le temple, dans l''intérieur et dans le vestibule du parvis,'),
('ez',41,16,'crampon1923','les seuils, les fenêtres grillées et les galeries tout autour, pour tous les trois, étaient recouverts, à la hauteur du seuil, de bois uni tout autour. Le sol jusqu''aux fenêtres, — et les fenêtres étaient fermées, —'),
('ez',41,17,'crampon1923','jusqu''au dessus de la porte et jusqu''au fond de la maison, et au dehors sur chaque muraille tout à l''entour, à l''intérieur et à l''extérieur, tout était couvert de tentures,'),
('ez',41,18,'crampon1923','et de chérubins et de palmiers, un palmier entre deux chérubins, et chaque chérubin ayant deux visages,'),
('ez',41,19,'crampon1923','un visage d''homme tourné vers le palmier d''un côté, et un visage de lion tourné vers le palmier de l''autre côté; on en avait représenté sur la maison tout entière.'),
('ez',41,20,'crampon1923','Depuis le sol jusqu''au-dessus de la porte, on avait représenté des chérubins et des palmiers sur la muraille du temple.'),
('ez',41,21,'crampon1923','Le temple avait des poteaux quadrangulaires. Et devant le Saint des saints il y avait quelque chose qui avait l''aspect'),
('ez',41,22,'crampon1923','d''un autel en bois; sa hauteur était de trois coudées, et sa longueur de deux coudées; il avait ses angles, et sur toute sa longueur ses parois étaient de bois. Et il me dit: " C''est ici ta table qui est devant Yahweh. "'),
('ez',41,23,'crampon1923','Le temple et le Saint des saints avaient chacun une porte,'),
('ez',41,24,'crampon1923','et chaque porte avait deux battants, deux battants qui se repliaient en feuillets, deux feuillets pour un battant, deux feuillets pour l''autre battant.'),
('ez',41,25,'crampon1923','Sur les portes du temple étaient représentés des chérubins et des palmiers, comme ceux qui étaient représentés sur les parois; et il y avait un auvent en bois sur la façade du vestibule à l''extérieur.'),
('ez',41,26,'crampon1923','Il y avait des fenêtres grillées et des palmiers de chaque côté aux parois latérales du vestibule et aux cellules latérales de la maison, et des auvents.'),
('ez',42,1,'crampon1923','L''homme me fit sortir vers le parvis extérieur dans la direction du septentrion, et il me conduisit vers l''appartement qui était en face de l''espace vide et en face du mur, vers le septentrion.'),
('ez',42,2,'crampon1923','Il avait une longueur de cent coudées, — porte du nord, — et une largeur de cinquante coudées,'),
('ez',42,3,'crampon1923','en face des vingt coudées du parvis intérieur, et en face du pavé du parvis extérieur, galerie contre galerie à trois étages.'),
('ez',42,4,'crampon1923','Devant les chambres il y avait une allée large de dix coudées, et, pour aller à l''intérieur, un chemin d''une coudée; et leurs portes donnaient du côté du septentrion.'),
('ez',42,5,'crampon1923','Les chambres supérieures étaient plus étroites, — car les galeries empiétaient sur elles, — plus étroites que les chambres inférieures et les chambres intermédiaires de l''édifice;'),
('ez',42,6,'crampon1923','car elles étaient à trois étages, et elles n''avaient pas de colonnes comme les colonnes des parvis; c''est pourquoi les chambres du haut étaient plus étroites que celles du bas et celles du milieu.'),
('ez',42,7,'crampon1923','Le mur extérieur parallèle aux chambres, du côté du parvis extérieur, était, pour la portion en face des chambres, long de cinquante coudées.'),
('ez',42,8,'crampon1923','Car la longueur des chambres du côté du parvis extérieur était de cinquante coudées; et voici que du côté du temple il y avait cent coudées.'),
('ez',42,9,'crampon1923','Plus bas que ces chambres, il y avait une entrée tournée vers l''orient pour celui qui arrivait du parvis extérieur.'),
('ez',42,10,'crampon1923','Sur la largeur du mur du parvis, du côté de l''orient, en face de l''espace vide et en face du mur, il y avait aussi des chambres,'),
('ez',42,11,'crampon1923','et devant elles un chemin, comme ce qui paraissait aux chambres du côté du septentrion; leur longueur et leur largeur étaient les mêmes, ainsi que toutes leurs sorties et leurs arrangements;'),
('ez',42,12,'crampon1923','comme les portes de celles-là étaient aussi les portes des chambres qui étaient du côté du midi; il y avait également une porte à l''entrée du chemin, le long du mur correspondant, à l''ouest pour celui qui entrait.'),
('ez',42,13,'crampon1923','Il me dit: " Les chambres du septentrion et les chambres du midi qui sont en face de l''espace vide, ce sont les chambres du sanctuaire, où les prêtres qui s''approchent de Yahweh mangent les choses très saintes; là ils déposent les choses très saintes, les oblations et les victimes pour le péché et pour le délit; car le lieu est saint.'),
('ez',42,14,'crampon1923','Une fois entrés, les prêtres ne sortiront pas du lieu saint pour aller au parvis extérieur sans avoir déposé là leurs vêtements avec lesquels ils ont fait le service, car ces vêtements sont saints. Ils se revêtiront d''autres habits, et c''est alors qu''ils s''approcheront de ce qui concerne le peuple. "'),
('ez',42,15,'crampon1923','Quand il eut achevé de mesurer l''intérieur de la maison, il me fit sortir vers le portique dont la façade est dans la direction de l''orient, et il mesura l''enceinte tout autour.'),
('ez',42,16,'crampon1923','Il mesura le côté de l''orient avec le roseau à mesurer: cinq cents roseaux avec le roseau à mesurer tout autour.'),
('ez',42,17,'crampon1923','Il mesura le côté du septentrion: cinq cents roseaux avec le roseau à mesurer tout autour.'),
('ez',42,18,'crampon1923','Il mesura le côté du midi: cinq cents roseaux avec le roseau à mesurer.'),
('ez',42,19,'crampon1923','Il se tourna du côté de l''occident et mesura cinq cents roseaux avec le roseau à mesurer.'),
('ez',42,20,'crampon1923','Des quatre côtés il mesura l''enceinte; il y avait au temple une muraille tout autour; la longueur était de cinq cents et la largeur de cinq cents, pour séparer le sacré du profane.'),
('ez',43,1,'crampon1923','Il me conduisit ensuite à la porte, la porte qui était tournée vers l''orient.'),
('ez',43,2,'crampon1923','Et voici que la gloire du Dieu d''Israël venait de la direction de l''orient. Sa voix était comme la voix des grandes eaux, et la terre resplendissait de sa gloire.'),
('ez',43,3,'crampon1923','L''aspect de l''image que je vis était comme l''image que j''avais vue lorsque je vins pour détruire la ville, et ce qu''on voyait était comme l''image que j''avais vue près du fleuve Chobar; et je tombai sur ma face.'),
('ez',43,4,'crampon1923','Et la gloire de Yahweh entra dans la maison par le chemin de la porte dont la façade était dans la direction de l''orient.'),
('ez',43,5,'crampon1923','Alors l''Esprit m''enleva et me fit entrer dans le parvis intérieur, et voici que la maison était remplie par la gloire de Yahweh.'),
('ez',43,6,'crampon1923','Et j''entendis qu''on me parlait du dedans de la maison, un homme se tenait debout à côté de moi.'),
('ez',43,7,'crampon1923','Il me dit: " Fils de l''homme, c''est ici le lieu de mon trône, le lieu où je poserai la plante de mes pieds, où j''habiterai au milieu des enfants d''Israël à jamais. La maison d''Israël, elle et ses rois, ne souilleront plus mon saint nom par leurs prostitutions, par les cadavres de leurs rois et par leurs hauts lieux,'),
('ez',43,8,'crampon1923','en mettant leur seuil auprès de mon seuil, et leur poteau auprès de mon poteau, de sorte qu''il n''y avait que le mur entre eux et moi, souillant ainsi mon saint nom par leurs abominations qu''ils commettaient; et je les ai exterminés dans ma colère.'),
('ez',43,9,'crampon1923','Maintenant ils éloigneront de moi leurs prostitutions et les cadavres de leurs rois, et j''habiterai au milieu d''eux à jamais.'),
('ez',43,10,'crampon1923','Toi, fils de l''homme, fais connaître à la maison d''Israël cette maison, afin qu''ils soient confus de leurs péchés, et qu''ils en mesurent le modèle.'),
('ez',43,11,'crampon1923','S''ils sont confus de tout ce qu''ils ont fait, apprends-leur la forme de la maison, son ordonnance, ses issues et ses entrées, ses formes, tous ses règlements, toutes ses formes et toutes ses lois; mets tout cela sous leurs yeux par écrit, et qu''ils gardent toutes ses formes et tous ses règlements et les mettent en pratique. "'),
('ez',43,12,'crampon1923','Telle est la loi de la maison: Au sommet de la montagne, son territoire tout à l''entour est saint des saints. Telle est la loi de la maison.'),
('ez',43,13,'crampon1923','" Voici les mesures de l''autel en coudées, la coudée étant d''une coudée et d''un palme: Le chéneau a une coudée de hauteur et une coudée de largeur, et le rebord qui est sur son pourtour a un empan. Tel est le socle de l''autel.'),
('ez',43,14,'crampon1923','Du chéneau qui est sur le sol au cadre inférieur il y a deux coudées, et la largeur est d''une coudée; du petit cadre au grand cadre, il y a quatre coudées, et la largeur est d''une coudée.'),
('ez',43,15,'crampon1923','Le Harel a quatre coudées, et de l''Ariel en haut s''élèvent les quatre cornes.'),
('ez',43,16,'crampon1923','L''Ariel a douze coudées de longueur sur douze coudées de largeur; il forme un carré parfait.'),
('ez',43,17,'crampon1923','Le cadre a, de ses quatre côtés, quatorze coudées de long sur quatorze coudées de large, et le rebord qui l''entoure a une demi-coudée; il a tout autour un chéneau d''une coudée; ses degrés sont tournés vers l''orient.'),
('ez',43,18,'crampon1923','Et il me dit: " Fils de l''homme, ainsi parle le Seigneur Yahweh: Voici les lois de l''autel le jour où il sera construit, afin d''y offrir l''holocauste et d''y faire l''aspersion du sang.'),
('ez',43,19,'crampon1923','Tu donneras aux prêtres lévites qui sont de la postérité de Sadoc et qui s''approchent de moi, — oracle du Seigneur Yahweh, — pour me servir, un jeune taureau en sacrifice pour le péché.'),
('ez',43,20,'crampon1923','Tu prendras de son sang et tu le mettras sur les quatre cornes de l''autel et sur les quatre angles du cadre, et sur le rebord tout autour, et tu feras l''expiation de l''autel et sa propitiation.'),
('ez',43,21,'crampon1923','Tu prendras le taureau qui aura été offert pour le péché et on le brûlera dans le lieu réservé de la maison, en dehors du sanctuaire.'),
('ez',43,22,'crampon1923','Le second jour, tu offriras pour le péché un jeune bouc sans défaut, et on feras l''expiation de l''autel comme on l''a faite pour le taureau.'),
('ez',43,23,'crampon1923','Quand tu auras achevé de faire l''expiation, tu offriras un jeune taureau sans défaut et un bélier du troupeau sans défaut.'),
('ez',43,24,'crampon1923','Tu les présenteras devant Yahweh; les prêtres jetteront sur eux du sel et les offriront en holocauste à Yahweh.'),
('ez',43,25,'crampon1923','Pendant sept jours tu offriras en sacrifice un bouc pour le péché, chaque jour; on offrira aussi un taureau et un bélier du troupeau sans défaut.'),
('ez',43,26,'crampon1923','Pendant sept jours on fera la propitiation de l''autel, on le purifiera et on le consacrera.'),
('ez',43,27,'crampon1923','Les sept jours achevés, le huitième jour et dorénavant, les prêtres offriront sur l''autel vos holocaustes et vos sacrifices pacifiques, et je vous serai favorable, — oracle du Seigneur Yahweh. "'),
('ez',44,1,'crampon1923','Puis il me fit revenir dans la direction du portique extérieur du sanctuaire qui regardait l''orient; il était fermé.'),
('ez',44,2,'crampon1923','Et Yahweh me dit: " Ce portique sera fermé; il ne s''ouvrira point, et personne n''entrera par là, car Yahweh, le Dieu d''Israël, est entré par là; et il sera fermé.'),
('ez',44,3,'crampon1923','Quant au prince, comme étant le prince, il s''y assoira pour manger les mets devant Yahweh; il entrera par le chemin du vestibule du portique et sortira par le même chemin. "'),
('ez',44,4,'crampon1923','Il me conduisit ensuite dans la direction du portique septentrional, devant la maison; et je vis, et voici que la gloire de Yahweh remplissait la maison; et je tombai sur ma face.'),
('ez',44,5,'crampon1923','Et Yahweh me dit: " Fils de l''homme, applique ton cœur, regarde de tes yeux et écoute de tes oreilles tout ce que je vais te dire au sujet de toutes les ordonnances de la maison de Yahweh et de toutes ses lois. Applique ton cœur à ce qui doit entrer dans la maison, par toutes les issues du sanctuaire.'),
('ez',44,6,'crampon1923','Dis aux rebelles, à la maison d''Israël: Ainsi parle le Seigneur Yahweh: C''est assez de toutes vos abominations, maison d''Israël,'),
('ez',44,7,'crampon1923','assez d''avoir introduit des fils d''étranger, incirconcis de cœur et incirconcis de chair, pour qu''ils fussent dans mon sanctuaire, afin de profaner ma maison, quand vous offriez les mets qui m''appartiennent, la graisse et le sang; et ainsi ils ont rompu mon alliance par toutes vos abominations.'),
('ez',44,8,'crampon1923','Vous ne vous êtes pas acquittés du service de mes choses saintes, et vous avez établi ces étrangers pour faire mon service, dans mon sanctuaire, à votre profit.'),
('ez',44,9,'crampon1923','Ainsi parle le Seigneur Yahweh: Aucun fils d''étranger, incirconcis de cœur et incirconcis de chair, n''entrera dans mon sanctuaire; non, aucun des fils d''étranger qui sont au milieu des enfants d''Israël.'),
('ez',44,10,'crampon1923','Bien plus, les Lévites qui se sont éloignés de moi au temps de l''égarement d''Israël, qui s''est égaré loin de moi pour suivre ses idoles infâmes, porteront leur iniquité.'),
('ez',44,11,'crampon1923','Ils seront dans mon sanctuaire des serviteurs préposés aux portes de la maison et faisant le service de la maison; ce sont eux qui égorgeront pour le peuple les victimes destinées à l''holocauste et aux autres sacrifices, et ils se tiendront devant le peuple pour le servir.'),
('ez',44,12,'crampon1923','Parce qu''ils l''ont servi devant ses idoles infâmes et qu''ils ont fait tomber la maison d''Israël dans l''iniquité, à cause de cela j''ai levé ma main sur eux, — oracle du Seigneur Yahweh, — jurant qu''ils porteraient leur iniquité.'),
('ez',44,13,'crampon1923','Ils n''approcheront pas de moi pour remplir devant moi les fonctions du sacerdoce, pour s''approcher de toutes mes choses saintes, dans les lieux très saints; ils porteront leur opprobre et la peine des abominations qu''ils ont commises.'),
('ez',44,14,'crampon1923','Je les chargerai de faire le service de la maison, pour tout son ouvrage, et pour tout ce qui s''y doit faire.'),
('ez',44,15,'crampon1923','Mais les prêtres lévites, fils de Sadoc, qui ont gardé les observances de mon sanctuaire quand les enfants d''Israël s''égaraient loin de moi, ce sont eux qui s''approcheront de moi pour faire mon service et qui se tiendront devant moi pour m''offrir la graisse et le sang, — oracle du Seigneur Yahweh.'),
('ez',44,16,'crampon1923','Ce sont eux qui entreront dans mon sanctuaire, eux qui s''approcheront de ma table pour faire mon service, et ils garderont mes observances.'),
('ez',44,17,'crampon1923','Lorsqu''ils franchiront les portiques du parvis intérieur, ils se vêtiront d''habits de lin; il n''y aura point de laine sur eux, quand ils feront le service dans les portiques du parvis intérieur et au-dedans.'),
('ez',44,18,'crampon1923','Ils auront des mitres de lin sur la tête; et ils auront des caleçons de lin sur les reins; et ils ne se ceindront point de ce qui exciterait la sueur.'),
('ez',44,19,'crampon1923','Mais lorsqu''ils sortiront au parvis extérieur, au parvis extérieur vers le peuple, ils ôteront leurs vêtements avec lesquels ils ont fait le service, ils les déposeront dans les chambres du sanctuaire; et ils revêtiront d''autres vêtements et ne sanctifieront pas le peuple par leurs vêtements.'),
('ez',44,20,'crampon1923','Ils ne se raseront pas la tête et ne laisseront pas non plus croître leurs cheveux; ils se tondront la tête.'),
('ez',44,21,'crampon1923','Aucun prêtre ne boira du vin lorsqu''il entrera dans le parvis intérieur.'),
('ez',44,22,'crampon1923','Ils ne prendront pour femme ni une veuve ni une femme répudiée, mais seulement des vierges de la race de la maison d''Israël; ils pourront prendre une veuve qui sera la veuve d''un prêtre.'),
('ez',44,23,'crampon1923','Ils instruiront mon peuple à distinguer entre ce qui est saint et ce qui est profane; ils lui apprendront à distinguer entre ce qui est souillé et ce qui est pur.'),
('ez',44,24,'crampon1923','Dans les contestations, ce sont eux qui prendront place pour le jugement, et ils jugeront d''après le droit que j''ai établi. Ils observeront mes lois et mes ordonnances dans toutes mes fêtes, et ils sanctifieront mes sabbats.'),
('ez',44,25,'crampon1923','Aucun d''eux n''ira auprès du cadavre d''un homme pour se souiller; ils ne pourront se souiller que pour un père ou une mère, pour un fils ou une fille, pour un frère ou une sœur qui n''a point de mari.'),
('ez',44,26,'crampon1923','Après sa purification, on lui comptera sept jours,'),
('ez',44,27,'crampon1923','et le jour où il entrera dans le lieu saint, au parvis intérieur, pour faire le service dans le sanctuaire, il offrira son sacrifice pour le péché, — oracle du Seigneur Yahweh.'),
('ez',44,28,'crampon1923','Voici l''héritage qu''ils auront: Je serai leur héritage; vous ne leur donnerez point de possession en Israël, c''est moi qui suis leur possession.'),
('ez',44,29,'crampon1923','Ils se nourriront de l''oblation, du sacrifice pour le péché et du sacrifice pour le délit; et tout ce qui aura été dévoué par anathème en Israël sera pour eux.'),
('ez',44,30,'crampon1923','Les prémices de tous les premiers produits de toutes sortes et toutes les offrandes de toutes sortes de tout ce que vous offrirez seront pour les prêtres; vous donnerez aussi aux prêtres les prémices de vos moutures, afin que la bénédiction repose sur ta maison.'),
('ez',44,31,'crampon1923','Tout animal mort ou déchiré, soit oiseau, soit autre bête, les prêtres ne le mangeront pas. "'),
('ez',45,1,'crampon1923','" Quand vous partagerez au sort le pays pour le posséder, vous prélèverez comme offrande à Yahweh une portion sainte du pays; sa longueur sera de vingt-cinq mille coudées, et sa largeur de dix mille; elle sera sainte dans toute son étendue, tout autour.'),
('ez',45,2,'crampon1923','Il y en aura pour le sanctuaire, cinq cents sur cinq cents, en carré, tout autour, et cinquante coudées pour sa banlieue, tout autour.'),
('ez',45,3,'crampon1923','Sur cet espace mesuré, tu mesureras une longueur de vingt-cinq mille et une largeur de dix mille; c''est là que sera le sanctuaire, le Saint des saints.'),
('ez',45,4,'crampon1923','Ce sera une portion sainte du pays; elle sera pour les prêtres qui font le service du sanctuaire, qui s''approchent pour servir Yahweh; ce sera pour eux une place pour leurs maisons, et un lieu saint pour le sanctuaire.'),
('ez',45,5,'crampon1923','Vingt-cinq mille coudées en longueur et dix mille en largeur seront pour les lévites, qui font le service de la maison; ils y posséderont des villes pour y habiter.'),
('ez',45,6,'crampon1923','Comme possession de la ville, vous mettrez cinq mille coudées de largeur et une longueur de vingt-cinq mille, parallèlement à la portion sainte prélevée; cela appartiendra à la maison d''Israël.'),
('ez',45,7,'crampon1923','Pour le prince, vous réserverez un espace des deux côtés de la portion sainte prélevée et de la possession de la ville, le long de la portion sainte et le long de la possession de la ville, du côté de l''occident vers l''occident, et du côté de l''orient vers l''orient, sur une longueur correspondante à l''une des parts, de la frontière occidentale à la frontière orientale.'),
('ez',45,8,'crampon1923','Ce sera son domaine, sa possession en Israël; et mes princes n''opprimeront plus mon peuple, et ils laisseront le pays à la maison d''Israël, selon ses tribus.'),
('ez',45,9,'crampon1923','Ainsi parle le Seigneur Yahweh: C''en est assez, princes d''Israël! Ecartez la violence et la rapine! Faites droit et justice; ôtez vos exactions de dessus mon peuple, — oracle du Seigneur Yahweh.'),
('ez',45,10,'crampon1923','Ayez des balances justes, un épha juste et un bath juste.'),
('ez',45,11,'crampon1923','L''épha et le bath auront une même contenance, de sorte que l''épha contienne la dixième partie du homer, et le bath le dixième du homer; leur contenance sera d''après le homer.'),
('ez',45,12,'crampon1923','Le sicle vaudra vingt guéras. La mine aura chez vous vingt sicles, vingt-cinq sicles, quinze sicles.'),
('ez',45,13,'crampon1923','Voici l''offrande que vous prélèverez: le sixième d''un épha sur le homer de froment, et le sixième d''un épha sur le homer d''orge.'),
('ez',45,14,'crampon1923','Règle pour l''huile, pour le bath d''huile: la dixième partie d''un bath sur un cor, lequel est égal à un homer de dix baths, car un homer fait dix baths.'),
('ez',45,15,'crampon1923','Une brebis du troupeau sera donnée sur deux cents des gras pâturages d''Israël, pour l''oblation, l''holocauste et les sacrifices pacifiques, afin de faire propitiation pour eux, — oracle du Seigneur Yahweh.'),
('ez',45,16,'crampon1923','Tout le peuple du pays devra prélever cette offrande pour le prince d''Israël.'),
('ez',45,17,'crampon1923','Mais le prince sera chargé des holocaustes, des oblations et des libations, aux fêtes, aux nouvelles lunes et aux sabbats, dans toutes les solennités de la maison d''Israël; c''est lui qui pourvoira aux sacrifices pour le péché, à l''oblation, à l''holocauste et aux sacrifices d''actions de grâces, afin de faire propitiation pour la maison d''Israël. "'),
('ez',45,18,'crampon1923','Ainsi parle le Seigneur Yahweh: " Le premier mois, le premier du mois, tu prendras un jeune taureau sans défaut, et tu feras l''expiation du sanctuaire.'),
('ez',45,19,'crampon1923','Le prêtre prendra du sang de la victime pour le péché et en mettra sur le poteau de la maison, sur les quatre coins du cadre de l''autel et sur le poteau du portique du parvis intérieur.'),
('ez',45,20,'crampon1923','Tu feras de même le sept du mois pour celui qui pèche par erreur ou par simplicité, et vous ferez propitiation pour la maison.'),
('ez',45,21,'crampon1923','Le premier mois, le quatorzième jour du mois, vous aurez la Pâque, fête d''une semaine de jours. On mangera des pains sans levain.'),
('ez',45,22,'crampon1923','Le prince offrira ce jour-là, pour lui et pour tout le peuple du pays, un taureau en sacrifice pour le péché.'),
('ez',45,23,'crampon1923','Et pendant les sept jours de la fête, il offrira un holocauste à Yahweh, sept taureaux et sept béliers sans défaut, chacun des sept jours, et un bouc en sacrifice pour le péché chaque jour.'),
('ez',45,24,'crampon1923','Il fera aussi l''oblation, un épha de farine par taureau et un épha par bélier, avec un hin d''huile par épha.'),
('ez',45,25,'crampon1923','Le septième mois, le quinzième jour du mois, pendant la fête, il offrira pendant sept jours les mêmes sacrifices pour le péché, les mêmes holocaustes, les mêmes oblations et la même quantité d''huile."'),
('ez',46,1,'crampon1923','Ainsi parle le Seigneur Yahweh: " Le portique du parvis intérieur, qui regarde l''orient, restera fermé les six jours ouvriers, mais il sera ouvert le jour du sabbat; il sera aussi ouvert le jour de la nouvelle lune.'),
('ez',46,2,'crampon1923','Le prince arrivera du dehors vers le vestibule du portique et se tiendra à côté du poteau du portique; les prêtres offriront son holocauste et ses sacrifices pacifiques. Il se prosternera sur le seuil du portique, et se retirera; et le portique ne sera pas fermé jusqu''au soir.'),
('ez',46,3,'crampon1923','Le peuple du pays se prosternera à l''entrée de ce portique, aux sabbats et aux nouvelles lunes, devant Yahweh.'),
('ez',46,4,'crampon1923','L''holocauste que le prince offrira à Yahweh sera, le jour du sabbat, de six agneaux sans défaut et d''un bélier sans défaut;'),
('ez',46,5,'crampon1923','et, comme oblation, il offrira un épha de farine pour le bélier; et, comme oblation pour les agneaux, ce qu''il voudra donner, avec un hin d''huile par épha.'),
('ez',46,6,'crampon1923','Le jour de la nouvelle lune, ce sera un jeune taureau, sans défaut, six agneaux et un bélier sans défaut.'),
('ez',46,7,'crampon1923','Et il donnera comme oblation un épha par bélier, et pour les agneaux, ce qu''il pourra donner, avec un hin d''huile par épha.'),
('ez',46,8,'crampon1923','Lorsque le prince entrera, il entrera par le vestibule du portique et sortira par le même chemin.'),
('ez',46,9,'crampon1923','Lorsque le peuple du pays entrera devant Yahweh dans les solennités, celui qui entrera par le portique du septentrion pour se prosterner, sortira par le portique du midi, et celui qui entrera par le portique du midi sortira par le portique du septentrion; on ne retournera pas par le portique par lequel on sera entré; mais on sortira par celui qui est en face de lui.'),
('ez',46,10,'crampon1923','Le prince aussi entrera parmi eux quand ils entreront, et sortira comme ils sortiront.'),
('ez',46,11,'crampon1923','Aux fêtes et aux solennités, l''oblation sera d''un épha pour le taureau et d''un épha pour le bélier, et, pour les agneaux, ce que le prince voudra donner, avec un hin d''huile par épha.'),
('ez',46,12,'crampon1923','Quand le prince offrira une offrande volontaire, holocauste ou sacrifices pacifiques, offrande volontaire à Yahweh, on lui ouvrira le portique qui regarde l''orient. Il offrira son holocauste ou ses sacrifices pacifiques, comme il le fait le jour du sabbat, et il sortira; et l''on fermera la porte après qu''il sera sorti.'),
('ez',46,13,'crampon1923','Tu offriras un agneau d''un an sans défaut comme holocauste quotidien à Yahweh; tu l''offriras chaque matin.'),
('ez',46,14,'crampon1923','Tu offriras avec lui chaque matin une oblation, savoir un sixième d''épha, et le tiers d''un hin d''huile pour arroser la fleur de farine, comme oblation à Yahweh; ce sont des lois permanentes, pour toujours.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ez',46,15,'crampon1923','On offrira chaque matin l''agneau, l''oblation avec l''huile; c''est l''holocauste perpétuel. "'),
('ez',46,16,'crampon1923','Ainsi parle le Seigneur Yahweh: " Si le prince fait un don à quelqu''un de ses fils, ce don sera l''héritage de ses fils; ils le posséderont comme un héritage.'),
('ez',46,17,'crampon1923','Mais s''il fait à l''un de ses serviteurs un don pris sur son héritage, ce don appartiendra au serviteur jusqu''à l''année de la libération; puis il retournera au prince; c''est à ses fils seulement que restera son héritage.'),
('ez',46,18,'crampon1923','Le prince ne prendra l''héritage de personne en l''expulsant violemment de sa propriété; c''est de sa propriété qu''il donnera un héritage à ses fils, afin que mon peuple ne soit pas chassé, chacun de sa possession. "'),
('ez',46,19,'crampon1923','Il me conduisit, par l''entrée qui est sur le côté du portique, dans les chambres saintes destinées aux prêtres, celles qui regardent le septentrion; et voici qu''il y avait là une place dans le fond, du côté de l''occident.'),
('ez',46,20,'crampon1923','Il me dit: " C''est l''endroit où les prêtres feront bouillir les victimes offertes pour le délit et pour le péché, et feront cuire l''oblation, afin de ne pas les transporter dans le parvis extérieur pour sanctifier le peuple. "'),
('ez',46,21,'crampon1923','Puis il me fit sortir dans le parvis extérieur et me fit passer vers les quatre angles du parvis et voici qu''à chaque angle du parvis il y avait une cour.'),
('ez',46,22,'crampon1923','Aux quatre angles du parvis, il y avait des cours fermées, longues de quarante coudées et larges de trente: une même dimension pour ces quatre cours aux angles.'),
('ez',46,23,'crampon1923','Une enceinte les entourait toutes les quatre, et des foyers à cuire étaient établis au bas de ces enceintes, tout autour.'),
('ez',46,24,'crampon1923','Il me dit: " Ce sont ici les cuisines où les serviteurs de la maison feront bouillir la chair des sacrifices du peuple. "'),
('ez',47,1,'crampon1923','Il me ramena ensuite à l''entrée de la maison. Et voici que des eaux sortaient de dessous le seuil de la maison, du côté de l''orient; car la face de la maison regardait l''orient. Et les eaux descendaient de dessous le côté droit de la maison, au midi de l''autel.'),
('ez',47,2,'crampon1923','Il me fit sortir par le portique du septentrion et me fit faire le tour à l''extérieur, jusqu''au portique extérieur qui regardait l''orient; et voici que les eaux coulaient du côté droit.'),
('ez',47,3,'crampon1923','Quand l''homme fut sorti vers l''orient, avec le cordeau qu''il avait à la main, il mesura mille coudées et me fit passer par cette eau: de l''eau jusqu''aux chevilles.'),
('ez',47,4,'crampon1923','Il en mesura encore mille et me fit passer dans l''eau: de l''eau jusqu''aux genoux. Il en mesura encore mille et me fit passer: de l''eau jusqu''aux reins.'),
('ez',47,5,'crampon1923','Il en mesura encore mille: c''était un torrent que je ne pouvais traverser, car les eaux avaient grossi; c''étaient des eaux à passer à la nage, un torrent qu''on ne pouvait traverser.'),
('ez',47,6,'crampon1923','Et il me dit: " Fils de l''homme, as-tu vu? " Puis il me fit revenir au bord du torrent.'),
('ez',47,7,'crampon1923','En me retournant, voici que j''aperçus sur le bord du torrent des arbres en très grand nombre, de chaque côté.'),
('ez',47,8,'crampon1923','Et il me dit: " Ces eaux s''en vont vers le district oriental; elles descendront dans la Plaine et entreront dans la mer; elles seront dirigées vers la mer, et les eaux en deviendront saines.'),
('ez',47,9,'crampon1923','Tout être vivant qui se meut, partout où entrera le double torrent, vivra, et le poisson sera très abondant; car dès que ces eaux y arriveront, les eaux de la mer deviendront saines, et il y aura de la vie partout où arrivera le torrent.'),
('ez',47,10,'crampon1923','Aux bord de cette mer se tiendront des pécheurs; d''Engaddi à Engallim des filets seront étendus; il y aura des poissons de toute espèce, comme ceux de la grande mer, très nombreux.'),
('ez',47,11,'crampon1923','Mais ses lagunes et ses mares ne seront pas assainies; elles seront abandonnées au sel.'),
('ez',47,12,'crampon1923','Près du torrent, sur ses bords de chaque côté, croîtront toutes sortes d''arbres fruitiers, dont le feuillage ne se flétrira point et dont les fruits ne cesseront point. Chaque mois, ils produiront des fruits nouveaux, parce que ses eaux sortent du sanctuaire; leur fruit sera bon à manger, et leurs feuilles bonnes pour guérir. "'),
('ez',47,13,'crampon1923','Ainsi parle le Seigneur Yahweh: " Une vallée sera la frontière du pays dont vous entrerez en possession, selon les douze tribus d''Israël; Joseph aura deux parts.'),
('ez',47,14,'crampon1923','Vous aurez chacun, l''un comme l''autre, une part de ce pays que j''ai promis, la main levée, de donner à vos pères, et ce pays vous échoira en possession.'),
('ez',47,15,'crampon1923','Voici la frontière du pays. Du côté du nord: depuis la grande mer, le chemin de Héthalon pour aller à Sédad.'),
('ez',47,16,'crampon1923','Le pays de Hamath, Berotha et Sabarim entre la frontière de Damas et la frontière de Hamath; Hatzer-Tichon, qui est sur la frontière du Hauran.'),
('ez',47,17,'crampon1923','Voici donc la frontière depuis la mer: Hatzer-Enon, la frontière de Damas, et, en allant au nord, la frontière de Hamath. C''est là le côté du nord. —'),
('ez',47,18,'crampon1923','Et du côté de l''orient: A partir de la limite qui sépare le Hauran et Damas, la frontière passe entre Galaad et le pays d''Israël: c''est le Jourdain. Vous mesurerez à partir de la frontière du nord jusqu''à la mer orientale. C''est le côté de l''orient. —'),
('ez',47,19,'crampon1923','Le côté du midi se dirigera d''abord vers le sud, depuis Thamar, jusqu''aux eaux de Méribah de Cadès; puis ce sera le torrent qui se jette dans la grande mer. C''est le côté sud vers le négéb. —'),
('ez',47,20,'crampon1923','Le côté de l''occident sera la grande mer, de cette frontière jusque vis-à-vis de l''entrée de Hamath. C''est le côté de l''occident. "'),
('ez',47,21,'crampon1923','" Vous vous partagerez ce pays selon les tribus d''Israël.'),
('ez',47,22,'crampon1923','Vous tirerez le pays au sort pour le posséder entre vous et les étrangers qui séjourneront au milieu de vous, qui ont engendré des enfants parmi vous. Ils seront pour vous comme des indigènes parmi les enfants d''Israël; ils tireront au sort leur lot avec vous, au milieu des tribus d''Israël.'),
('ez',47,23,'crampon1923','Dans la tribu où l''étranger est établi, là vous lui donnerez sa part d''héritage, — oracle du Seigneur Yahweh. "'),
('ez',48,1,'crampon1923','Voici les noms des tribus: A partir de l''extrémité septentrionale, le long du chemin de Héthalon pour aller à Hamath, Hatzer-Enon, la frontière de Damas vers le nord, le long de Hamath, il y aura pour chaque tribu: De la limite orientale à la limite occidentale: Dan, une part.'),
('ez',48,2,'crampon1923','A la frontière de Dan, de la limite orientale à la limite occidentale: Aser, une part.'),
('ez',48,3,'crampon1923','A la frontière d''Aser, de la limite orientale à la limite occidentale, Nephthali, une part.'),
('ez',48,4,'crampon1923','A la frontière de Nephthali, de la limite orientale à la limite occidentale: Manassé, une part.'),
('ez',48,5,'crampon1923','A la frontière de Manassé, de la limite orientale à la limite occidentale, Ephraïm, une part.'),
('ez',48,6,'crampon1923','A la frontière d''Ephraïm, de la limite orientale à la limite occidentale, Ruben, une part.'),
('ez',48,7,'crampon1923','Et à la frontière de Ruben, de la limite orientale à la limite occidentale: Juda, une part.'),
('ez',48,8,'crampon1923','A la frontière de Juda, de la limite orientale à la limite occidentale, sera la portion que vous prélèverez, large de vingt-cinq mille coudées et longue comme une des parts, de la limite orientale jusqu''à la limite occidentale: au milieu d''elle sera le sanctuaire.'),
('ez',48,9,'crampon1923','La portion que vous prélèverez pour Yahweh aura vingt-cinq mille coudées de longueur et dix mille de largeur.'),
('ez',48,10,'crampon1923','Cette sainte portion prélevée appartiendra aux prêtres, savoir, au septentrion vingt-cinq mille coudées, à l''occident dix mille coudées en largeur, à l''orient dix mille coudées en largeur, et au midi vingt-cinq mille coudées en longueur: le sanctuaire de Yahweh sera au milieu d''elle.'),
('ez',48,11,'crampon1923','Elle appartiendra aux prêtres consacrés, fils de Sadoc, qui se sont acquittés de mon service, qui ne se sont pas égarés lorsque s''égarèrent les enfants d''Israël, comme se sont égarés les lévites.'),
('ez',48,12,'crampon1923','Ce sera leur part prélevée sur la portion prélevée du pays, part très sainte, à la frontière des lévites.'),
('ez',48,13,'crampon1923','Les lévites auront, le long du territoire des prêtres, vingt-cinq mille coudées en longueur et dix mille en largeur; chaque longueur sera de vingt-cinq mille coudées, et chaque largeur de dix mille.'),
('ez',48,14,'crampon1923','Ils n''en pourront rien vendre ni rien échanger, et les prémices du pays n''en seront point aliénées; car elles sont saintes pour Yahweh.'),
('ez',48,15,'crampon1923','Les cinq mille qui resteront en largeur sur les vingt-cinq mille seront un terrain profane pour la ville, tant pour les habitations que pour la banlieue; la ville sera au milieu.'),
('ez',48,16,'crampon1923','En voici les dimensions: côté du nord, quatre mille cinq cents coudées; côté du midi, quatre mille cinq cents; côté de l''orient, quatre mille cinq cents; côté de l''occident, quatre mille cinq cents.'),
('ez',48,17,'crampon1923','La ville aura une banlieue de deux cent cinquante coudées au nord, deux cent cinquante au midi, deux cent cinquante à l''orient et deux cent cinquante à l''occident.'),
('ez',48,18,'crampon1923','Il restera en longueur, le long de la portion sainte, dix mille coudées à l''orient et dix mille à l''occident, le long de la portion sainte; les produits en seront pour la nourriture de ceux qui desservent la ville.'),
('ez',48,19,'crampon1923','Les desservants de la ville, pris dans toutes les tribus d''Israël, cultiveront ce terrain.'),
('ez',48,20,'crampon1923','Ainsi, toute la portion prélevée étant de vingt-cinq mille coudées sur vingt-cinq mille, vous aurez prélevé pour le domaine de la ville une portion égale au quart de la portion sainte.'),
('ez',48,21,'crampon1923','Le reste sera pour le prince; de chaque côté de la portion sainte et du domaine de la ville, à partir des vingt-cinq mille coudées de la portion prélevée, jusqu''à la frontière de l''orient, et, à l''occident, à partir des vingt-cinq mille coudées jusqu''à la frontière de l''occident, parallèlement aux parts — ce sera pour le prince; la portion sainte et le sanctuaire de la maison seront au milieu.'),
('ez',48,22,'crampon1923','Ainsi à partir du domaine des lévites et du domaine de la ville, qui se trouvent au milieu de la portion du prince, tout ce qui est entre la frontière de Juda et la frontière de Benjamin sera au prince.'),
('ez',48,23,'crampon1923','Part du reste des tribus: de la limite orientale à la limite occidentale, Benjamin, une part.'),
('ez',48,24,'crampon1923','A la frontière de Benjamin, de la limite orientale à la limite occidentale, Siméon, une part.'),
('ez',48,25,'crampon1923','A la frontière de Siméon, de la limite orientale à la limite occidentale, Issachar, une part.'),
('ez',48,26,'crampon1923','A la frontière d''Issachar, de la limite orientale à la limite occidentale, Zabulon, une part.'),
('ez',48,27,'crampon1923','A la frontière de Zabulon, de la limite orientale à la limite occidentale, Gad, une part.'),
('ez',48,28,'crampon1923','A la frontière de Gad, du côté du négéb, vers le sud, la frontière ira de Thamar aux eaux de Méribah à Cadès, et au torrent qui va à la grande mer.'),
('ez',48,29,'crampon1923','Tel est le pays que vous tirerez au sort pour le posséder, selon les tribus d''Israël; et telles sont leurs parts, — oracle du Seigneur Yahweh.'),
('ez',48,30,'crampon1923','Voici les sorties de la ville: Du côté du nord, quatre mille cinq cents coudées de mesure,'),
('ez',48,31,'crampon1923','— les portes de la ville prendront les noms des tribus d''Israël, — et trois portes au nord: la porte de Ruben, une; la porte de Juda, une; la porte de Lévi, une.'),
('ez',48,32,'crampon1923','Du côté de l''orient, quatre mille cinq cents coudées et trois portes: la porte de Joseph, une; la porte de Benjamin, une; la porte de Dan, une.'),
('ez',48,33,'crampon1923','Du côté du midi, quatre mille cinq cents coudées de mesure et trois portes: la porte de Siméon, une; la porte d''Issachar, une; la porte de Zabulon, une.'),
('ez',48,34,'crampon1923','Du côté de l''occident, quatre mille cinq cents coudées et trois portes: la porte de Gad, une; la porte d''Aser, une; la porte de Nephthali, une.'),
('ez',48,35,'crampon1923','Dix-huit mille coudées de tour. Et le nom de la ville sera désormais: Yahweh-est-là.'),
('dn',1,1,'crampon1923','La troisième année du règne de Joakim, roi de Juda, Nabuchodonosor, roi de Babylone, vint contre Jérusalem et l''assiégea.'),
('dn',1,2,'crampon1923','Le Seigneur livra entre ses mains Joakim, roi de Juda, et une partie des vases de la maison de Dieu; et il les emporta au pays de Sennaar, dans la maison de son dieu, et il déposa les vases dans le trésor de son dieu.'),
('dn',1,3,'crampon1923','Le roi dit à Asphenez, chef de ses eunuques, d''amener d''entre les enfants d''Israël, de la race royale ou de la noblesse,'),
('dn',1,4,'crampon1923','des jeunes gens sans aucun défaut, beaux de figure, doués de toutes sortes de talents, instruits et intelligents, pleins de vigueur, pour qu''ils se tinssent dans le palais du roi et qu''on leur enseignât la littérature et la langue des Chaldéens.'),
('dn',1,5,'crampon1923','Le roi leur assigna pour chaque jour une portion des mets royaux et du vin dont il buvait, afin que, ayant été élevés pendant trois ans, ils se tinssent au bout de ce temps devant le roi.'),
('dn',1,6,'crampon1923','Il y avait parmi eux, d''entre les enfants de Juda, Daniel, Ananias, Misaël et Azarias.'),
('dn',1,7,'crampon1923','Le chef des eunuques leur donna des noms; il appela Daniel Baltassar, Ananias Sidrac, Misaël Misac, et Azarias Abdénago.'),
('dn',1,8,'crampon1923','Daniel résolut en son cœur de ne pas se souiller par les mets du roi et par le vin dont il buvait, et il demanda au chef des eunuques de ne pas l''obliger à se souiller.'),
('dn',1,9,'crampon1923','Et Dieu fit trouver à Daniel grâce et faveur auprès du chef des eunuques.'),
('dn',1,10,'crampon1923','Le chef des eunuques dit à Daniel: " Je crains le roi, mon maître, qui a fixé ce que vous devez manger et boire; car pourquoi verrait-il vos visages plus défaits que ceux des jeunes gens de votre âge? Vous mettriez en danger ma tête auprès du roi. "'),
('dn',1,11,'crampon1923','Alors Daniel dit au maître d''hôtel, que le chef des eunuques avait établi sur Daniel, Ananias, Misaël et Azarias:'),
('dn',1,12,'crampon1923','" Fais, je te prie, un essai avec tes serviteurs pendant dix jours, et qu''on nous donne des légumes à manger et de l''eau à boire.'),
('dn',1,13,'crampon1923','Après cela, tu regarderas nos visages et le visage des jeunes gens qui mangent les mets du roi, et, selon que tu auras vu, tu agiras avec tes serviteurs. "'),
('dn',1,14,'crampon1923','Il consentit à leur demande et les éprouva pendant dix jours.'),
('dn',1,15,'crampon1923','Au bout de dix jours, ils se trouvèrent avoir meilleur visage et plus d''embonpoint que tous les jeunes gens qui mangeaient les mets du roi.'),
('dn',1,16,'crampon1923','Et le maître d''hôtel emportait les mets et le vin qu''ils devaient boire, et leur donnait des légumes.'),
('dn',1,17,'crampon1923','A ces jeunes gens, à tous les quatre, Dieu donna du savoir et de l''habileté dans toute la littérature et en toute sagesse, et Daniel avait l''intelligence de toutes sortes de visions et de songes.'),
('dn',1,18,'crampon1923','Au bout du temps fixé par le roi pour les amener, le chef des eunuques les amena devant Nabuchodonosor.'),
('dn',1,19,'crampon1923','Le roi s''entretint avec eux, et il ne se trouva personne parmi eux tous comme Daniel, Ananias, Misaël et Azarias; ils furent donc admis au service du roi.'),
('dn',1,20,'crampon1923','Sur tous les sujets qui réclamaient de la sagesse et de l''intelligence, et sur lesquels le roi les interrogeait, il les trouvait dix fois supérieurs à tous les lettrés et magiciens qui étaient en tout son royaume.'),
('dn',1,21,'crampon1923','Daniel fut ainsi jusqu''à la première année du roi Cyrus.'),
('dn',2,1,'crampon1923','La seconde année du règne de Nabuchodonosor, Nabuchodonosor eut des songes, son esprit fut agité et le sommeil se retira de lui.'),
('dn',2,2,'crampon1923','Le roi fit appeler les lettrés, les magiciens, les enchanteurs et les Chaldéens pour lui expliquer ses songes; ils vinrent et ils se tinrent devant le roi.'),
('dn',2,3,'crampon1923','Le roi leur dit: " J''ai fait un songe, et mon esprit est agité, cherchant à connaître ce songe. "'),
('dn',2,4,'crampon1923','Les Chaldéens répondirent au roi en langue araméenne: " O roi, vis éternellement! Dis le songe à tes serviteurs, et nous en ferons connaître la signification. "'),
('dn',2,5,'crampon1923','Le roi répondit aux Chaldéens, en disant: " C''est chose arrêtée par moi. Si vous ne me faites savoir le songe et sa signification, vous serez coupés en morceaux et vos maisons seront réduites en cloaques.'),
('dn',2,6,'crampon1923','Mais si vous me faîtes connaître le songe et sa signification, vous recevrez de moi des dons et des présents, et de grands honneurs; ainsi faites-moi connaître le songe et sa signification. "'),
('dn',2,7,'crampon1923','Ils répondirent pour la deuxième fois en disant: " Que le roi dise le songe à ses serviteurs, et nous en ferons connaître la signification. "'),
('dn',2,8,'crampon1923','Le roi répondit et dit: " En vérité, je sais que vous cherchez à gagner du temps, parce que vous voyez que c''est chose arrêtée par moi.'),
('dn',2,9,'crampon1923','Puisque vous ne me faîtes pas savoir le songe, c''est que vous n''avez qu''une pensée, celle de concerter un discours mensonger et trompeur, pour le tenir devant moi, en attendant que les temps soient changés; ainsi, dites-moi le songe et je saurai que vous pourrez m''en faire connaître la véritable signification. "'),
('dn',2,10,'crampon1923','Les Chaldéens répondirent devant le roi en disant: " Il n''y a pas d''homme sur la terre qui puisse faire connaître ce que le roi demande. Aussi jamais roi, si grand et si puissant qu''il ait été, n''a demandé pareille chose d''aucun lettré, astrologue ou Chaldéen.'),
('dn',2,11,'crampon1923','La chose que le roi demande est difficile, et il n''y a personne qui puisse la faire connaître devant le roi, hormis les dieux dont la demeure n''est pas parmi les mortels. "'),
('dn',2,12,'crampon1923','Là-dessus le roi se mit en colère et en grande fureur, et il donna l''ordre de mettre à mort tous les sages de Babylone.'),
('dn',2,13,'crampon1923','La sentence ayant été publiée, les sages étaient mis à mort, et on cherchait Daniel et ses compagnons pour les tuer.'),
('dn',2,14,'crampon1923','Alors Daniel fit une réponse prudente et sensée à Arioch, chef des gardes du roi, qui était sorti pour mettre à mort les sages de Babylone.'),
('dn',2,15,'crampon1923','Il prit la parole et dit à Arioch, commandant du roi: " Pourquoi cette sentence sévère de la part du roi? " Et Arioch exposa la chose à Daniel.'),
('dn',2,16,'crampon1923','Alors Daniel entra dans le palais et pria le roi de lui accorder un délai afin de faire connaître au roi la signification.'),
('dn',2,17,'crampon1923','Aussitôt Daniel alla dans sa maison et informa de l''affaire Ananias, Misaël et Azarias, ses compagnons,'),
('dn',2,18,'crampon1923','les engageant à implorer la miséricorde du Dieu du ciel sur ce mystère, pour qu''on ne fit point périr Daniel et ses compagnons avec le reste des sages de Babylone.'),
('dn',2,19,'crampon1923','Alors le secret fut révélé à Daniel dans une vision pendant la nuit, et Daniel bénit le Dieu du ciel.'),
('dn',2,20,'crampon1923','Daniel prit la parole et dit: " Béni soit le nom de Dieu, d''éternité en éternité, car à lui appartiennent la sagesse et la force.'),
('dn',2,21,'crampon1923','C''est lui qui change les moments et les temps, qui renverse les rois et qui élève les rois, qui donne la sagesse aux sages et le savoir aux intelligents.'),
('dn',2,22,'crampon1923','C''est lui qui révèle les choses profondes et cachées, qui sait ce qui est dans les ténèbres, et la lumière demeure avec lui.'),
('dn',2,23,'crampon1923','C''est vous, Dieu de mes pères, que je célèbre et que je loue de ce que vous m''avez donné la sagesse et la force, et de ce que maintenant vous m''avez fait savoir ce que nous vous avons demandé, en nous faisant savoir l''affaire du roi. "'),
('dn',2,24,'crampon1923','C''est pourquoi Daniel se rendit auprès d''Arioch, que le roi avait chargé de mettre à mort les sages de Babylone; il alla et lui parla ainsi: " Ne fais pas périr les sages de Babylone; introduis-moi devant le roi, et je ferai connaître au roi la signification. "'),
('dn',2,25,'crampon1923','Arioch s''empressa de faire entrer Daniel devant le roi et lui parla ainsi: " J''ai trouvé parmi les captifs de Juda un homme qui fera savoir au roi la signification. "'),
('dn',2,26,'crampon1923','Le roi prit la parole et dit à Daniel, qui s''appelait Baltassar: " Es-tu capable de me faire savoir le songe que j''ai eu et sa signification? "'),
('dn',2,27,'crampon1923','Daniel répondit en présence du roi et dit: " Le secret que le roi demande, ni sages, ni magiciens, ni lettrés, ni astrologues ne sont capables de le faire connaître au roi.'),
('dn',2,28,'crampon1923','Mais il y a un Dieu dans le ciel qui révèle les secrets et qui a fait savoir au roi Nabuchodonosor ce qui doit arriver à la fin des jours. Ton songe et les visions de ton esprit que tu as eues sur ta couche, les voici:'),
('dn',2,29,'crampon1923','Toi, ô roi, tes pensées s''élevaient en ton esprit sur ta couche au sujet de ce qui arriverait après ce temps-ci, et celui qui révèle les secrets t''a fait connaître ce qui doit arriver.'),
('dn',2,30,'crampon1923','Et moi, ce n''est pas par une sagesse qui serait en moi, supérieure à celle de tous les vivants, que ce secret m''a été révélé, mais c''est afin qu''on en fasse savoir la signification au roi, et que tu connaisses les pensées de ton cœur.'),
('dn',2,31,'crampon1923','Toi, ô roi, tu regardais, et voici une grande statue. Cette statue était immense et sa splendeur extraordinaire; elle se dressait devant toi, et son aspect était terrible.'),
('dn',2,32,'crampon1923','Cette statue avait la tête d''or fin, la poitrine et les bras d''argent, le ventre et les cuisses d''airain,'),
('dn',2,33,'crampon1923','les jambes de fer, les pieds en partie de fer et en partie d''argile.'),
('dn',2,34,'crampon1923','Tu regardais, jusqu''à ce qu''une pierre fut détachée, non par une main, et frappa la statue à ses pieds de fer et d''argile, et les brisa.'),
('dn',2,35,'crampon1923','Alors furent brisés en même temps le fer, l''argile, l''airain, l''argent et l''or, et ils devinrent comme la balle qui s''élève de l''aire en été, et le vent les emporta sans qu''on en trouve plus aucune trace; et la pierre qui avait frappé la statue devint une grande montagne et remplit toute la terre.'),
('dn',2,36,'crampon1923','Voilà le songe; sa signification, nous allons la dire devant le roi.'),
('dn',2,37,'crampon1923','Toi, ô roi, roi des rois, à qui le Dieu du ciel a donné l''empire, la puissance, la force et la gloire,'),
('dn',2,38,'crampon1923','entre les mains de qui il a livré, en quelque lieu qu''ils habitent, les enfants des hommes, les bêtes des champs, les oiseaux des cieux, et qu''il a fait dominer sur eux tous: c''est toi qui es la tête d''or.'),
('dn',2,39,'crampon1923','Après toi, il s''élèvera un autre royaume, moindre que toi, puis un troisième royaume d''airain, qui dominera sur toute la terre.'),
('dn',2,40,'crampon1923','Un quatrième royaume sera fort comme le fer; de même que le fer écrase et brise tout, et comme le fer qui met en pièces, il écrasera et mettra en pièces tous ceux-là.'),
('dn',2,41,'crampon1923','Si tu as vu les pieds et les orteils en partie d''argile de potier et en partie de fer, c''est que ce sera un royaume divisé; il y aura en lui de la solidité du fer, selon que tu as vu du fer mêlé à l''argile.'),
('dn',2,42,'crampon1923','Mais comme les orteils des pieds étaient en partie de fer et en partie d''argile, ce royaume sera en partie fort, et il sera en partie fragile.'),
('dn',2,43,'crampon1923','Si tu as vu le fer mêlé à l''argile, c''est qu''ils seront mêlés de semence d''homme; mais ils ne tiendront pas l''un à l''autre, de même que le fer ne peut s''allier avec l''argile.'),
('dn',2,44,'crampon1923','Dans le temps de ces rois, le Dieu du ciel suscitera un royaume qui ne sera jamais détruit, et dont la domination ne sera point abandonnée à un autre peuple; il brisera et anéantira tous ces royaumes-là, et lui-même subsistera à jamais,'),
('dn',2,45,'crampon1923','selon que tu as vu qu''une pierre a été détachée de la montagne, non par une main, et qu''elle a brisé le fer, l''airain, l''argile, l''argent et l''or. Le grand Dieu a fait connaître au roi ce qui arrivera dans la suite; le songe est véritable et sa signification certaine. "'),
('dn',2,46,'crampon1923','Alors le roi Nabuchodonosor tomba sur sa face et se prosterna devant Daniel, et il ordonna qu''on lui offrit des oblations et des parfums.'),
('dn',2,47,'crampon1923','Le roi parla ensuite à Daniel et dit: " Vraiment votre Dieu est le Dieu des dieux, le seigneur des rois et le révélateur des secrets, puisque tu as pu révéler ce secret. "'),
('dn',2,48,'crampon1923','Alors le roi éleva Daniel et lui fit de nombreux et riches présents; il l''établit gouverneur sur toute la province de Babylone et chef suprême sur tous les sages de Babylone.'),
('dn',2,49,'crampon1923','A la prière de Daniel, le roi commit aux affaires de la province de Babylone Sidrac, Misac et Abdénago; et Daniel demeura à la cour.'),
('dn',3,1,'crampon1923','Le roi Nabuchodonosor fit une statue d''or, dont la hauteur était de soixante coudées et la largeur de six coudées; il la dressa dans la plaine de Dura, dans la province de Babylone.'),
('dn',3,2,'crampon1923','Et le roi Nabuchodonosor fit rassembler les satrapes, les intendants et les gouverneurs, les grands juges, les trésoriers, les légistes, les juges et tous les magistrats des provinces, pour qu''ils se rendissent à la dédicace de la statue qu''avait dressée le roi Nabuchodonosor.'),
('dn',3,3,'crampon1923','Ainsi s''assemblèrent les satrapes, les intendants et les gouverneurs, les grands juges, les trésoriers, les légistes, les juges et tous les magistrats des provinces pour la dédicace de la statue que le roi Nabuchodonosor avait dressée; et ils se tinrent devant la statue qu''avait dressée Nabuchodonosor.'),
('dn',3,4,'crampon1923','Un héraut cria d''une voix forte: " Voici ce qu''on vous fait savoir, à vous, peuples, nations et langues:'),
('dn',3,5,'crampon1923','Au moment où vous entendrez le son de la trompette, du chalumeau, de la cithare, de la sambuque, du psaltérion, de la cornemuse et de toutes sortes d''instruments, vous vous prosternerez pour adorer la statue d''or que le roi Nabuchodonosor a dressée.'),
('dn',3,6,'crampon1923','Quiconque ne se prosternera pas et n''adorera pas la statue, sera jeté à l''instant au milieu de la fournaise de feu ardent. "'),
('dn',3,7,'crampon1923','C''est pourquoi au montent où tous les peuples entendirent le son de la trompette, du chalumeau, de la cithare, de la sambuque, du psaltérion et de toutes les sortes d''instruments, tous les peuples, nations et langues se prosternèrent, adorant la statue d''or qu''avait dressée le roi Nabuchodonosor.'),
('dn',3,8,'crampon1923','Là-dessus, au moment même, des Chaldéens s''approchèrent et dirent du mal des Juifs.'),
('dn',3,9,'crampon1923','Ils prirent la parole et dirent au roi Nabuchodonosor: " O roi, vis à jamais! "'),
('dn',3,10,'crampon1923','Toi, ô roi, tu as porté un décret ordonnant que tout homme qui entendrait le son de la trompette, du chalumeau, de la cithare, de la sambuque, du psaltérion, de la cornemuse et de toutes les sortes d''instruments, se prosterne pour adorer la statue d''or,'),
('dn',3,11,'crampon1923','et que quiconque ne se prosternera pas pour l''adorer sera jeté au milieu de la fournaise de feu ardent.'),
('dn',3,12,'crampon1923','Or, il y a des juifs que tu as préposés aux affaires de la province de Babylone, Sidrac, Misac et Abdénago: ces hommes-là n''ont pas d''égard pour toi, ô roi; ils ne servent pas tes dieux et ils ne se prosternent pas devant la statue d''or que tu as dressée. "'),
('dn',3,13,'crampon1923','Alors Nabuchodonosor, irrité et furieux, ordonna d''amener Sidrac, Misac, et Abdénago; et ces hommes furent amenés devant le roi.'),
('dn',3,14,'crampon1923','Nabuchodonosor prit la parole et leur dit: " Est-ce à dessein, Sidrac, Misac et Abdénago, que vous ne servez pas mon dieu et que vous n''adorez pas la statue d''or que j''ai dressée!'),
('dn',3,15,'crampon1923','Maintenant si vous êtes prêts, au moment où vous entendrez le son de la trompette, du chalumeau, de la cithare, de la sambuque, du psaltérion, de la cornemuse et de toutes les sortes d''Instruments, à vous prosterner pour adorer la statue que j''ai faite... Mais si vous ne l''adorez pas, vous serez jetés à l''instant même au milieu de la fournaise de feu ardent, et quel est le dieu qui vous délivrera de ma main? "'),
('dn',3,16,'crampon1923','Sidrac, Misac et Abdénago répondirent au roi et dirent: " Nabuchodonosor, sur ce point nous n''avons pas besoin de t''adresser une réponse.'),
('dn',3,17,'crampon1923','Si vraiment notre Dieu que nous servons peut nous délivrer, il nous délivrera de la fournaise de feu ardent et de ta main, ô roi.'),
('dn',3,18,'crampon1923','Sinon, qu''il soit connu de toi, ô roi, que nous ne servirons pas tes dieux et que nous ne nous prosternerons pas devant la statue d''or que tu as dressée. "'),
('dn',3,19,'crampon1923','Alors Nabuchodonosor fut rempli de fureur, et l''aspect de son visage fut changé envers Sidrac, Misac, et Abdénago. Reprenant la parole, il ordonna de chauffer la fournaise sept fois plus qu''on n''avait jugé convenable de le faire,'),
('dn',3,20,'crampon1923','et il commanda à quelques-uns des plus vigoureux soldats qui étaient dans son armée de lier Sidrac, Misac et Abdénago et de les jeter dans la fournaise de feu ardent.'),
('dn',3,21,'crampon1923','Alors ces hommes, avec leurs tuniques, leurs robes, leurs manteaux et leurs autres vêtements, furent liés et jetés dans la fournaise de feu ardent.'),
('dn',3,22,'crampon1923','Comme l''ordre du roi était pressant et la fournaise extraordinairement chauffée, la flamme de feu tua ces hommes qui y avaient jeté Sidrac, Misac et Abdénago.'),
('dn',3,23,'crampon1923','Et ces trois hommes, Sidrac, Misac et Abdénago tombèrent au milieu de la fournaise ardente, tout liés. Ce qui suit, je ne l''ai pas trouvé dans les livres hébreux.'),
('dn',3,24,'crampon1923','Et ils marchaient au milieu de la flamme, louant Dieu et bénissant le Seigneur.'),
('dn',3,25,'crampon1923','Et Azarias, se levant, fit cette prière; ouvrant la bouche au milieu du feu, il dit:'),
('dn',3,26,'crampon1923','Soyez béni, Seigneur, Dieu de nos pères; votre nom est digne de louange et de gloire à jamais.'),
('dn',3,27,'crampon1923','Car vous êtes juste dans tout ce que vous nous avez fait, et toutes vos œuvres sont vraies; vos voies sont droites, et vos jugements sont équitables.'),
('dn',3,28,'crampon1923','Car vous avez rendu des jugements équitables; dans tous les maux que vous avez fait venir sur nous; et sur la ville sainte de nos pères, Jérusalem; c''est par un juste jugement que vous avez fait tout cela, à cause de nos péchés.'),
('dn',3,29,'crampon1923','Car nous avons péché et commis l''iniquité en nous retirant de vous, et nous avons manqué en toutes choses.'),
('dn',3,30,'crampon1923','Nous n''avons pas écouté vos commandements et nous ne les avons pas observés, et nous n''avons pas agi selon que vous nous l''aviez commandé, afin que nous fussions heureux.'),
('dn',3,31,'crampon1923','Tout ce que vous avez fait venir sur nous, tout ce que vous nous avez fait, c''est par un juste jugement que vous l''avez fait.'),
('dn',3,32,'crampon1923','Vous nous avez livrés aux mains d''ennemis injustes, d''apostats acharnés contre nous, et d''un roi injuste, le plus méchant de toute la terre.'),
('dn',3,33,'crampon1923','Et maintenant nous n''osons ouvrir la bouche; la honte et l''opprobre sont à vos serviteurs, et à tous ceux qui vous adorent.'),
('dn',3,34,'crampon1923','Ne nous livrez pas pour toujours, à cause de votre nom, et ne détruisez pas votre alliance.'),
('dn',3,35,'crampon1923','Ne retirez pas de nous votre miséricorde, à cause d''Abraham votre ami, d''Isaac votre serviteur, et d''Israël votre saint,'),
('dn',3,36,'crampon1923','auxquels vous avez promis de multiplier leur postérité; comme les étoiles du ciel, et comme le sable qui est sur le rivage de la mer.'),
('dn',3,37,'crampon1923','Car, Seigneur, nous sommes réduits devant toutes les nations, et nous sommes aujourd''hui humiliés par toute ta terre, à cause de nos péchés.'),
('dn',3,38,'crampon1923','Il n''y a plus en ce temps pour nous ni prince, ni chef, ni prophète, ni holocauste, ni sacrifice, ni oblation, ni encens; ni endroit pour apporter devant vous les prémices et trouver grâce.'),
('dn',3,39,'crampon1923','Mais, Seigneur, puissions-nous être reçus, le cœur contrit et l''esprit humilié,'),
('dn',3,40,'crampon1923','comme vous recevez un holocauste de béliers et de taureaux, ou de mille agneaux gras; qu''il en soit ainsi de notre sacrifice devant vous aujourd''hui, et de notre soumission envers vous, car il n''y a pas de confusion pour ceux qui se fient en vous.'),
('dn',3,41,'crampon1923','Maintenant, nous vous suivons de tout notre cœur, nous vous craignons et nous cherchons votre visage.'),
('dn',3,42,'crampon1923','Ne nous confondez pas, mais traitez-nous selon votre douceur, et selon l''abondance de votre miséricorde.'),
('dn',3,43,'crampon1923','Délivrez-nous par vos prodiges, et donnez, Seigneur, gloire à votre nom.'),
('dn',3,44,'crampon1923','Qu''ils soient confondus tous ceux qui maltraitent vos serviteurs, couverts de honte par la perte de toute leur puissance, et que leur force soit brisée,'),
('dn',3,45,'crampon1923','qu''ils sachent que vous êtes le Seigneur, le seul Dieu, et le glorieux souverain de toute la terre! "'),
('dn',3,46,'crampon1923','Cependant les serviteurs du roi qui avaient jeté ces trois hommes dans la fournaise, ne cessaient de la chauffer avec du naphte, de l''étoupe, de la poix et des sarments.'),
('dn',3,47,'crampon1923','La flamme s''élevait quarante-neuf coudées au-dessus de la fournaise;'),
('dn',3,48,'crampon1923','et, s''étant élancée, elle brûla les Chaldéens qu''elle rencontra près de la fournaise.'),
('dn',3,49,'crampon1923','Mais l''ange du Seigneur était descendu dans la fournaise avec Azarias et ses compagnons, et il écartait de la fournaise la flamme de feu.'),
('dn',3,50,'crampon1923','Et il rendit le milieu de la fournaise tel que si un vent de rosée y avait soufflé; et le feu ne les toucha même pas, il ne les blessa point et ne leur causa point le moindre mal.'),
('dn',3,51,'crampon1923','Alors ces trois hommes, comme d''une seule bouche, louaient, glorifiaient et bénissaient Dieu dans la fournaise, en disant:'),
('dn',3,52,'crampon1923','Vous êtes béni, Seigneur, Dieu de nos pères, digne d''être loué, glorifié et exalté à jamais. Béni est votre nom saint et glorieux, digne de suprême louange et exaltation à tout jamais.'),
('dn',3,53,'crampon1923','Vous êtes béni dans le temple de votre sainte gloire, digne de suprême louange et gloire à jamais.'),
('dn',3,54,'crampon1923','Vous élus béni sur le trône de votre royaume, digne de suprême louange et exaltation à jamais.'),
('dn',3,55,'crampon1923','Vous êtes béni, vous dont le regard pénètre les abîmes, et qui êtes assis sur les Chérubins, digne de suprême louange et exaltation à jamais.'),
('dn',3,56,'crampon1923','Vous êtes béni au firmament du ciel, digne de louange et de gloire à jamais.'),
('dn',3,57,'crampon1923','Bénissez toutes le Seigneur, œuvres du Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,58,'crampon1923','Anges du Seigneur, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,59,'crampon1923','Cieux, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,60,'crampon1923','Eaux et tout ce qui est au-dessus des cieux, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,61,'crampon1923','Puissances du Seigneur, bénissez toutes le Seigneur; louez-le, et exaltez-le à jamais.'),
('dn',3,62,'crampon1923','Soleil et lune, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,63,'crampon1923','Astres du ciel, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,64,'crampon1923','Pluies et rosées, bénissez toutes le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,65,'crampon1923','Vents que Dieu déchaîne, bénissez tous le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,66,'crampon1923','Feux et chaleurs, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,67,'crampon1923','Froid et chaleur, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,68,'crampon1923','Rosées et givres, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,69,'crampon1923','Gelées et frimas, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,70,'crampon1923','Glaces et neiges, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,71,'crampon1923','Nuits et jours, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,72,'crampon1923','Lumière et ténèbres, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,73,'crampon1923','Eclairs et sombres nuages, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,74,'crampon1923','Que la terre bénisse le Seigneur; qu''elle le loue et l''exalte à jamais!'),
('dn',3,75,'crampon1923','Montagnes et collines, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,76,'crampon1923','Plantes qui croissez sur la terre, bénissez toutes le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,77,'crampon1923','Fontaines, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,78,'crampon1923','Mers et fleuves, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,79,'crampon1923','Monstres et tout ce qui s''agite dans les eaux, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,80,'crampon1923','Oiseaux du ciel, bénissez tous le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,81,'crampon1923','Bêtes sauvages et troupeaux, bénissez tous le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,82,'crampon1923','Enfants des hommes, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,83,'crampon1923','Qu''Israël bénisse le Seigneur; qu''il le loue et l''exalte à jamais!'),
('dn',3,84,'crampon1923','Prêtres du Seigneur, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,85,'crampon1923','Serviteurs du Seigneur, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,86,'crampon1923','Esprits et âmes des justes, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,87,'crampon1923','Saints et humbles de cœur, bénissez le Seigneur; louez-le et exaltez-le à jamais.'),
('dn',3,88,'crampon1923','Ananias, Azarias et Misaël, bénissez le Seigneur; louez-le et exaltez-le à jamais. Car il nous à tirés du schéol, et délivrés de la puissance de la mort; il nous à sauvés du milieu de la fournaise de flamme brûlante, et tirés du milieu du feu.'),
('dn',3,89,'crampon1923','Célébrez le Seigneur, car il est bon, car sa miséricorde dure à jamais.'),
('dn',3,90,'crampon1923','Vous tous, hommes pieux, bénissez le Seigneur, le Dieu des dieux; louez-le et célébrez-le, car sa miséricorde dure à jamais. Le morceau qui se termine ici ne se trouve pas dans l''hébreu; la traduction que nous en avons donnée est faite sur l''édition de Théodotion.'),
('dn',3,91,'crampon1923','Alors le roi Nabuchodonosor fut dans la stupeur et se leva précipitamment. Il prit la parole et dit à ses conseillers: " N''avons-nous pas jeté au milieu du feu trois hommes liés? " Ils répondirent et dirent au roi: " Certainement, ô roi! "'),
('dn',3,92,'crampon1923','Il reprit et dit: " Eh bien, moi, je vois quatre hommes sans liens, marchant au milieu du feu et n''ayant aucun mal; l''aspect du quatrième ressemble à celui d''un fils des dieux. "'),
('dn',3,93,'crampon1923','Puis Nabuchodonosor s''approcha de la porte de la fournaise de feu ardent; il prit la parole et dit: " Sidrac, Misac et Abdénago, serviteurs du Dieu Très-Haut, sortez et venez! " Alors Sidrac, Misac et Abdénago sortirent du milieu du feu.'),
('dn',3,94,'crampon1923','Les satrapes, les intendants, les gouverneurs et les conseillers du roi, s''étant rassemblés, regardèrent ces hommes et virent que le feu n''avait eu aucun pouvoir sur leur corps, que les cheveux de leur tête n''avaient pas été brûlés, que leurs tuniques n''avaient pas subi de changement et qu''elles n''avaient pas l''odeur du feu.'),
('dn',3,95,'crampon1923','Nabuchodonosor prit la parole et dit: " Béni soit le Dieu de Sidrac, de Misac et d''Abdénago, lequel a envoyé son ange et délivré ses serviteurs qui se sont confiés en lui, qui ont transgressé l''ordre du roi et livré leur corps, pour ne servir et adorer aucun dieu sinon leur Dieu.'),
('dn',3,96,'crampon1923','Ordre est donné de ma part que tout homme, à quelque peuple, nation ou langue qu''il appartienne, qui parlera mal du Dieu de Sidrac, de Misac et d''Abdénago sera coupé en morceaux et sa maison sera réduite en cloaque, parce qu''il n''y a pas d''autre dieu qui puisse sauver de la sorte.'),
('dn',3,97,'crampon1923','Alors le roi fit prospérer Sidrac, Misac et Abdénago, dans la province de Babylone.'),
('dn',3,98,'crampon1923','" Le roi Nabuchodonosor à tous les peuples, nations et langues qui habitent sur toute la terre: la paix vous soit donnée en abondance!'),
('dn',3,99,'crampon1923','Il m''a paru bon de faire connaître les signes et les prodiges que le Dieu Très-Haut a opérés envers moi.'),
('dn',3,100,'crampon1923','Que ses signes sont grands et que ses prodiges sont puissants! Son règne est un règne éternel et sa domination subsiste d''âge en âge.'),
('dn',4,1,'crampon1923','Moi, Nabuchodonosor, j''étais tranquille dans ma maison et florissant dans mon palais.'),
('dn',4,2,'crampon1923','Je vis un songe qui m''épouvanta, et mes pensées sur ma couche et les visions de mon esprit me troublèrent.'),
('dn',4,3,'crampon1923','Je publiai un décret pour qu''on fit venir devant moi tous les sages de Babylone, pour me faire savoir la signification du songe.'),
('dn',4,4,'crampon1923','Alors vinrent les lettrés, les magiciens, les Chaldéens et les astrologues; je dis le songe devant eux, mais ils ne m''en firent pas savoir la signification.'),
('dn',4,5,'crampon1923','Enfin se présenta devant moi Daniel, dont le nom est Baltassar, d''après le nom de mon dieu, et qui a en lui l''esprit des dieux saints, et je dis le songe devant lui:'),
('dn',4,6,'crampon1923','" Baltassar, chef des lettrés, comme je sais que l''esprit des dieux saints est en toi et qu''aucun mystère ne t''embarrasse, expose-moi les visions que j''ai vues en songe, et leur signification.'),
('dn',4,7,'crampon1923','Voici quelles étaient les visions de mon esprit sur ma couche: Je vis, et voici au milieu de la terre un arbre dont la hauteur était grande.'),
('dn',4,8,'crampon1923','L''arbre grandit et devint fort; sa cime atteignait le ciel, et on le voyait des extrémités de toute la terre.'),
('dn',4,9,'crampon1923','Son feuillage était beau et ses fruits abondants, et il y avait sur lui de la nourriture pour tous; sous son ombre les bêtes des champs s''abritaient, dans ses branches demeuraient les oiseaux du ciel, et de lui toute chair se nourrissait.'),
('dn',4,10,'crampon1923','Je contemplai ces visions de mon esprit sur ma couche, et voici qu''un veillant, un saint, descendait du ciel.'),
('dn',4,11,'crampon1923','Il cria avec force et parla ainsi: Abattez l''arbre et coupez ses branches; secouez son feuillage et dispersez ses fruits; que les animaux s''enfuient de dessous lui, et que les oiseaux quittent ses branches.'),
('dn',4,12,'crampon1923','Toutefois laissez en terre la souche de ses racines, mais dans des chaînes de fer et d''airain, au milieu du gazon des champs. Qu''il soit trempé de la rosée du ciel et qu''il partage avec les animaux l''herbe de la terre.'),
('dn',4,13,'crampon1923','Que son cœur ne soit plus un cœur d''homme, et qu''un cœur de bête lui soit donné, et que sept temps passent sur lui.'),
('dn',4,14,'crampon1923','Cette sentence repose sur un décret des veillants, et cette affaire est un ordre des saints, afin que les vivants sachent que le Très-Haut domine sur la royauté humaine, qu''il la donne à qui il veut, et qu''il y élève le plus humble des hommes.'),
('dn',4,15,'crampon1923','Tel est le songe que j''ai vu, moi, le roi Nabuchodonosor; et toi, Baltassar, dis-en la signification, car tous les sages de mon royaume ne peuvent m''en faire savoir la signification; mais toi, tu le peux, car l''esprit des dieux saints est en toi. "'),
('dn',4,16,'crampon1923','Alors Daniel, dont le nom est Baltassar, demeura quelque temps interdit, et ses pensées le troublaient. Le roi reprit et dit: " Que le songe et sa signification ne te troublent point! " Baltassar répondit en disant: " Mon seigneur, que le songe soit pour tes ennemis, et sa signification pour tes adversaires.'),
('dn',4,17,'crampon1923','L''arbre que tu as vu, qui grandit et devint fort, dont la cime atteignait au ciel et qu''on voyait de toute la terre;'),
('dn',4,18,'crampon1923','dont le feuillage était beau et les fruits abondants; où il y avait de la nourriture pour tous; sous lequel s''abritaient les animaux des champs, et dans les branches duquel demeuraient les oiseaux du ciel,'),
('dn',4,19,'crampon1923','cet arbre, c''est toi, ô roi, qui es devenu grand et fort, dont la grandeur s''est accrue et a atteint au ciel, et dont la domination s''étend jusqu''aux extrémités de la terre.'),
('dn',4,20,'crampon1923','Si le roi a vu un veillant, un saint, descendant du ciel et disant: Abattez l''arbre et détruisez-le; toutefois laissez en terre la souche de ses racines, mais dans des chaînes de fer et d''airain, au milieu du gazon des champs; qu''il soit trempé de la rosée du ciel, et qu''il fasse sa part avec les animaux des champs, jusqu''à ce que sept temps aient passé sur lui:'),
('dn',4,21,'crampon1923','en voici la signification, ô roi! C''est un décret du Très-Haut qui s''accomplira sur mon seigneur le roi:'),
('dn',4,22,'crampon1923','On te chassera du milieu des hommes, et ta demeure sera parmi les animaux des champs; on te donnera, comme aux bœufs, de l''herbe à manger et on te laissera tremper par la rosée du ciel, et sept temps passeront sur toi, jusqu''à ce que tu saches que le Très-Haut domine sur la royauté des hommes et qu''il la donne à qui il lui plaît.'),
('dn',4,23,'crampon1923','Et si on a ordonné de laisser la souche des racines de l''arbre, c''est que ta royauté te sera rendue quand tu auras reconnu que le ciel a la domination.'),
('dn',4,24,'crampon1923','C''est pourquoi, ô roi, que mon conseil soit agréé devant toi: rachète tes péchés par la justice et tes iniquités par la miséricorde envers les malheureux, si ta prospérité doit se prolonger encore. "'),
('dn',4,25,'crampon1923','Toutes ces choses arrivèrent au roi Nabuchodonosor.'),
('dn',4,26,'crampon1923','Au bout de douze mois, comme il se promenait sur les terrasses du palais royal de Babylone,'),
('dn',4,27,'crampon1923','le roi prit la parole et dit: " N''est-ce pas là Babylone la grande, que j''ai bâtie comme résidence royale par la puissance de ma force et pour la gloire de ma majesté. "'),
('dn',4,28,'crampon1923','La parole était encore dans la bouche du roi, qu''une voix descendit du ciel: " On te fait savoir, roi Nabuchodonosor, que ta royauté a passé loin de toi.'),
('dn',4,29,'crampon1923','On te chassera du milieu des hommes, et ta demeure sera avec les animaux des champs; on te donnera, comme aux bœufs, de l''herbe a manger, et sept temps passeront sur toi, jusqu''à ce que tu saches que le Très-Haut domine sur la royauté des hommes, et qu''il la donne à qui il lui plaît. "'),
('dn',4,30,'crampon1923','Au même moment, la parole s''accomplit sur Nabuchodonosor; il fut chassé du milieu des hommes; il mangea de l''herbe comme les bœufs, et son corps fut trempé de la rosée du ciel, jusqu''à ce que ses cheveux crussent comme les plumes des aigles, et ses ongles comme ceux des oiseaux.'),
('dn',4,31,'crampon1923','Mais, à la fin des jours, moi, Nabuchodonosor, je levai les yeux vers le ciel, et ma raison me revint. Je bénis le Très-Haut, et je louai et glorifiai Celui qui vit éternellement, dont la domination est une domination éternelle, et dont le règne subsiste de génération en génération.'),
('dn',4,32,'crampon1923','Tous les habitants de la terre ne comptent pour rien devant lui; il agit comme il lui plaît avec l''armée des cieux et avec les habitants de la terre, et il n''y a personne pour lui frapper sur la main et lui dire: " Que faites-vous? "'),
('dn',4,33,'crampon1923','Dans le même temps, ma raison me revint et, pour la gloire de ma royauté, ma majesté et ma splendeur me revinrent; mes conseillers et mes grands me rappelèrent, je fus rétabli dans ma royauté, et ma puissance s''accrut encore.'),
('dn',4,34,'crampon1923','Maintenant, moi, Nabuchodonosor, je loue, j''exalte et je glorifie le roi du ciel, dont toutes les œuvres sont vraies et les voies justes, et qui peut humilier ceux qui marchent avec orgueil. "'),
('dn',5,1,'crampon1923','Le roi Baltasar fit un grand festin à mille de ses princes, et en présence de ces mille il but du vin.'),
('dn',5,2,'crampon1923','Excité par le vin, Baltasar fit apporter les vases d''or et d''argent que Nabuchodonosor, son père, avait enlevés du temple qui est à Jérusalem, afin que le roi et ses princes, ses femmes et ses concubines, s''en servissent pour boire.'),
('dn',5,3,'crampon1923','Alors on apporta les vases d''or qui avaient été enlevés du temple de la maison de Dieu qui est à Jérusalem, et le roi et ses princes, ses femmes et ses concubines s''en servirent pour boire.'),
('dn',5,4,'crampon1923','Ils burent du vin, et ils louèrent les dieux d''or et d''argent, d''airain, de fer, de bois et de pierre.'),
('dn',5,5,'crampon1923','A ce moment apparurent des doigts de main humaine qui écrivaient, en face du candélabre, sur la chaux de la muraille du palais royal; et le roi vit le bout de la main qui écrivait.'),
('dn',5,6,'crampon1923','Alors le roi changea de couleur, et ses pensées le troublèrent; les jointures de ses reins se relâchèrent et ses genoux se heurtèrent l''un contre l''autre.'),
('dn',5,7,'crampon1923','Le roi cria avec force qu''on fit venir les magiciens, les Chaldéens et les astrologues; et le roi prit la parole et dit aux sages de Babylone: " Quiconque lira cette écriture et m''en fera connaître la signification, sera revêtu de pourpre et portera au cou une chaîne d''or, et il commandera en troisième dans le royaume. "'),
('dn',5,8,'crampon1923','Alors tous les sages du roi entrèrent, mais ils ne purent lire ce qui était écrit, ni en faire savoir la signification au roi.'),
('dn',5,9,'crampon1923','Alors le roi Baltasar fut très effrayé; il changea de couleur, et ses princes furent consternés.'),
('dn',5,10,'crampon1923','La reine, apprenant les paroles du roi et de ses princes, entra dans la salle du festin; la reine prit la parole et dit: " O roi, vis éternellement! Que tes pensées ne te troublent pas, et que tes couleurs ne changent point!'),
('dn',5,11,'crampon1923','Il y a un homme de ton royaume en qui réside l''esprit des dieux saints; dans les jours de ton père, on trouva en lui une lumière, une intelligence et une sagesse pareilles à la sagesse des dieux. Aussi le roi Nabuchodonosor ton père, — le roi, ton père, — l''établit chef des lettrés, des magiciens, des Chaldéens, des astrologues,'),
('dn',5,12,'crampon1923','parce qu''un esprit supérieur, de la science et de l''intelligence pour interpréter les songes, pour faire connaître les énigmes et résoudre les questions difficiles furent trouvés en lui, en Daniel, à qui le roi avait donné le nom de Baltassar. Qu''on appelle donc Daniel et il te fera connaître la signification! "'),
('dn',5,13,'crampon1923','Alors Daniel fut introduit devant le roi. Le roi prit la parole et dit à Daniel: " Es-tu ce Daniel, l''un des captifs de Juda, que le roi, mon père, a amenés de Judée?'),
('dn',5,14,'crampon1923','J''ai entendu dire à ton sujet que l''esprit des dieux est en toi, qu''une lumière, une intelligence et une sagesse extraordinaires se trouvent en toi.'),
('dn',5,15,'crampon1923','On vient d''introduire devant moi les sages et les magiciens pour lire cette écriture et m''en faire savoir la signification; mais ils n''ont pu me faire connaître la signification de ces mots.'),
('dn',5,16,'crampon1923','Et moi, j''ai entendu dire de toi que tu peux donner les significations et résoudre les questions difficiles. Si donc tu peux lire ce qui est écrit et m''en faire savoir la signification, tu seras revêtu de pourpre, tu porteras au cou une chaîne d''or, et tu commanderas en troisième dans le royaume. "'),
('dn',5,17,'crampon1923','Alors Daniel prit la parole et dit devant le roi: " Que tes dons soient à toi, et donne à un autre tes présents! Toutefois je lirai au roi ce qui est écrit et je lui en ferai savoir la signification.'),
('dn',5,18,'crampon1923','O roi, le Dieu Très-Haut avait donné à Nabuchodonosor, ton père, la royauté et la grandeur, la gloire et la majesté;'),
('dn',5,19,'crampon1923','et à cause de la grandeur qu''il lui avait donnée, tous les peuples, nations et langues étaient dans la crainte et tremblaient devant lui; il faisait mourir qui il voulait, et il donnait la vie à qui il voulait; il élevait qui il voulait, et il abaissait qui il voulait.'),
('dn',5,20,'crampon1923','Mais son cœur s''étant élevé et son esprit s''étant endurci jusqu''à l''arrogance, on le fit descendre du trône de sa royauté et la grandeur lui fut ôtée.'),
('dn',5,21,'crampon1923','Il fut chassé du milieu des enfants des hommes, son cœur devint semblable à celui des bêtes et sa demeure fut avec les ânes sauvages; on le nourrit d''herbe comme les bœufs, et son corps fut trempé de la rosée du ciel, jusqu''à ce qu''il reconnût que le Dieu Très-haut domine sur la royauté des hommes, et qu''il y élève qui il lui plaît.'),
('dn',5,22,'crampon1923','Et toi, son fils, Baltasar, tu n''as pas humilié ton cœur, quoique tu susses toutes ces choses.'),
('dn',5,23,'crampon1923','Mais tu t''es élevé contre le Seigneur du ciel; on a apporté devant toi les vases de sa maison, et toi, tes princes, tes femmes et tes concubines, vous y avez bu du vin; tu as loué les dieux d''argent et d''or, d''airain, de fer, de bois et de pierre, qui ne voient, ni n''entendent, ni ne connaissent rien; et le Dieu qui a dans sa main ton souffle et de qui relèvent toutes tes voies, tu ne l''as pas glorifié.'),
('dn',5,24,'crampon1923','C''est alors qu''a été envoyé de sa part ce bout de main et qu''a été tracé ce qui est écrit là.'),
('dn',5,25,'crampon1923','Voici l''écriture qui a été tracée: MENÉ MENÉ. THEQEL. OUPHARSIN.'),
('dn',5,26,'crampon1923','Et voici la signification de ces mots: Mené (compté): Dieu a compté ton règne et y a mis fin.'),
('dn',5,27,'crampon1923','Theqel (pesé): tu as été pesé dans les balances et trouvé léger.'),
('dn',5,28,'crampon1923','Perès (divisé): ton royaume sera divisé et donné aux Mèdes et aux Perses. "'),
('dn',5,29,'crampon1923','Alors, sur l''ordre de Baltasar, on revêtit Daniel de pourpre, on lui mit au cou une chaîne d''or, et on publia à son sujet qu''il commanderait en troisième dans le royaume.'),
('dn',5,30,'crampon1923','Dans la nuit même, Baltasar, roi des Chaldéens, fut tué.'),
('dn',6,1,'crampon1923','Et Darius le Mède reçut la royauté, étant âgé d''environ soixante-deux ans.'),
('dn',6,2,'crampon1923','Il plut à Darius d''établir sur le royaume cent vingt satrapes, pour être répartis dans tout le royaume.'),
('dn',6,3,'crampon1923','Et il mit au-dessus d''eux trois ministres, dont Daniel était l''un, et ces satrapes devaient leur rendre compte, afin que le roi ne fût pas lésé.'),
('dn',6,4,'crampon1923','Or Daniel surpassait les ministres et les satrapes, parce qu''il y avait en lui un esprit supérieur, et le roi pensait à l''établir sur tout le royaume.'),
('dn',6,5,'crampon1923','Alors les ministres et les satrapes cherchèrent à trouver un sujet d''accusation contre Daniel touchant les affaires du royaume; mais ils ne purent trouver aucun sujet, ni rien à reprendre; car il était fidèle, et il ne se trouvait en lui rien de fautif, ni de répréhensible.'),
('dn',6,6,'crampon1923','Ces hommes dirent donc: " Nous ne trouverons aucun sujet contre ce Daniel, à moins de trouver quelque chose contre lui dans la loi de son Dieu. "'),
('dn',6,7,'crampon1923','Alors ces ministres et ces satrapes se rendirent à grand bruit chez le roi et lui parlèrent ainsi: " Roi Darius, vis éternellement!'),
('dn',6,8,'crampon1923','Tous les ministres du royaume, les intendants, les satrapes, les conseillers et les gouverneurs se sont entendus pour rendre un édit royal et publier une défense portant que quiconque, dans l''espace de trente jours, adressera des prières à quelque dieu ou homme, si ce n''est à toi, ô roi, sera jeté dans la fosse aux lions.'),
('dn',6,9,'crampon1923','Maintenant, ô roi, porte la défense et écris le décret, afin qu''il n''y puisse être dérogé, selon la loi des Mèdes et des Perses, qui est irrévocable. "'),
('dn',6,10,'crampon1923','En conséquence, le roi Darius écrivit le décret et la défense.'),
('dn',6,11,'crampon1923','Lorsque Daniel eut appris que le décret était écrit, il entra dans sa maison, qui avait, dans la chambre haute, des fenêtres ouvertes du côté de Jérusalem. Trois fois par jour il se mettait à genoux, il priait et louait Dieu, comme il le faisait auparavant.'),
('dn',6,12,'crampon1923','Alors ces hommes vinrent à grand bruit et trouvèrent Daniel priant et invoquant son Dieu.'),
('dn',6,13,'crampon1923','Alors ils s''approchèrent du roi et lui parlèrent au sujet de la défense royale: " N''as-tu pas écrit une défense portant que quiconque, pendant trente jours, prierait quelque dieu ou homme, si ce n''est toi, ô roi, serait jeté dans la fosse aux lions? " Le roi répondit et dit: " La chose est certaine, d''après la loi des Mèdes et des Perses, qui est irrévocable. "'),
('dn',6,14,'crampon1923','Alors ils reprirent et dirent devant le roi: " Daniel, l''un des captifs de Juda, n''a pas eu égard à toi, ô roi, ni à la défense que tu as écrite; mais trois fois le jour il fait sa prière. "'),
('dn',6,15,'crampon1923','Le roi, entendant ces paroles, en eut un grand déplaisir; quant à Daniel, il prit à cœur de le délivrer, et jusqu''au coucher du soleil il essaya de le sauver.'),
('dn',6,16,'crampon1923','Alors ces hommes vinrent à grand bruit vers le roi, et ils dirent au roi: " Sache, ô roi, que c''est la loi des Mèdes et des Perses qu''on ne peut déroger à toute défense et tout décret rendu par le roi. "'),
('dn',6,17,'crampon1923','Alors le roi donna l''ordre qu''on amenât Daniel et qu''on le jetât dans la fosse aux lions. Le roi prit la parole et dit à Daniel: " Puisse ton Dieu, que tu sers constamment, te délivrer lui-même! "'),
('dn',6,18,'crampon1923','On apporta une pierre et on la mit sur l''ouverture de la fosse; le roi la scella de son anneau et de l''anneau des princes, afin que rien ne fût changé à l''égard de Daniel.'),
('dn',6,19,'crampon1923','Le roi s''en alla ensuite dans son palais; il passa la nuit à jeun et ne fit pas venir de femmes auprès de lui et le sommeil s''enfuit loin de lui.'),
('dn',6,20,'crampon1923','Puis le roi se leva à l''aurore, au point du jour, et il se rendit en toute hâte à la fosse aux lions.'),
('dn',6,21,'crampon1923','Quand il fut près de la fosse, il cria vers Daniel d''une voix triste; le roi prit la parole et dit à Daniel: " Daniel, serviteur du Dieu vivant, ton Dieu que tu sers constamment a-t-il pu te délivrer des lions? "'),
('dn',6,22,'crampon1923','Alors Daniel parla avec le roi: " O roi, vis éternellement!'),
('dn',6,23,'crampon1923','Mon Dieu a envoyé son ange et fermé la gueule des lions, qui ne m''ont fait aucun mal, parce que j''ai été trouvé innocent devant mon Dieu; et devant toi non plus, ô roi, je n''ai commis aucun mal! "'),
('dn',6,24,'crampon1923','Alors le roi fut très joyeux à son sujet, et il ordonna de retirer Daniel de la fosse. Daniel fut donc retiré de la fosse, et on ne trouva sur lui aucune blessure, parce qu''il avait cru en son Dieu.'),
('dn',6,25,'crampon1923','Sur l''ordre du roi, on amena ces hommes qui avaient dit du mal de Daniel, et on les jeta dans la fosse aux lions, eux, leurs femmes et leurs enfants. Ils n''avaient pas encore atteint le fond de la fosse, que les lions les saisirent et brisèrent tous leurs os.'),
('dn',6,26,'crampon1923','Alors le roi Darius écrivit à tous les peuples, nations et langues, qui habitent sur toute la terre: " Que la paix vous soit donnée en abondance!'),
('dn',6,27,'crampon1923','Par moi est publié l''ordre que dans toute l''étendue de mon royaume on craigne et on tremble devant le Dieu de Daniel; car il est le Dieu vivant, qui subsiste éternellement; son royaume ne sera jamais détruit et sa domination n''aura pas de fin.'),
('dn',6,28,'crampon1923','Il délivre et il sauve, il fait des signes et des prodiges au ciel et sur la terre; c''est lui qui a délivré Daniel de la griffe des lions. "'),
('dn',6,29,'crampon1923','Et ce Daniel prospéra sous le règne de Darius et sous le règne de Cyrus le Perse.'),
('dn',7,1,'crampon1923','La première année du règne de Baltasar, roi de Babylone, Daniel, étant sur sa couche, vit un songe et des visions en son esprit. Il écrivit ensuite le songe et raconta la substance des faits.'),
('dn',7,2,'crampon1923','Daniel prit la parole et dit: " je voyais dans ma vision pendant la nuit, et voici que les quatre vents du ciel fondaient sur la grande mer,'),
('dn',7,3,'crampon1923','Et quatre grandes bêtes montèrent de la mer, différentes l''une de l''autre.'),
('dn',7,4,'crampon1923','La première était semblable à un lion et avait des ailes d''aigle. Je contemplais, jusqu''au moment où ses ailes furent arrachées, et où elle fut enlevée de terre, et dressée sur ses pieds, comme un homme, et où un cœur d''homme lui fut donné.'),
('dn',7,5,'crampon1923','Et voici une autre bête, une deuxième, ressemblant à un ours; elle dressait l''un de ses côtés, et trois côtes étaient dans sa gueule entre ses dents, et on lui disait: " Lève-toi, mange beaucoup de chair!'),
('dn',7,6,'crampon1923','Après cela, je regardais, et voici une autre bête semblable a un léopard; elle avait sur son dos quatre ailes d''oiseau, et la bête avait quatre têtes; et la domination lui fut donnée.'),
('dn',7,7,'crampon1923','Après cela je regardais dans les visions de la nuit, et voici une quatrième bête, terrible, effrayante et extraordinairement forte; elle avait de grandes dents de fer; elle dévorait et brisait, et le reste elle le foulait aux pieds; elle était différente de toutes les bêtes qui l''avaient précédée, et elle avait dix cornes.'),
('dn',7,8,'crampon1923','Je considérais les cornes, et voici qu''une autre corne, petite, s''éleva au milieu d''elles, et trois des premières cornes furent arrachées par elle; et voici que cette corne avait des yeux comme des yeux d''homme, et une bouche qui disait de grandes choses.'),
('dn',7,9,'crampon1923','Je regardais, jusqu''au moment où des trônes furent placés, et où un vieillard s''assit. Son vêtement était blanc comme de la neige, et les cheveux de sa tête étaient comme de la laine pure. Son trône était des flammes de feu; les roues, un feu ardent.'),
('dn',7,10,'crampon1923','Un fleuve de feu coulait, sortant de devant lui; mille milliers le servaient, et une myriade de myriades se tenaient debout devant lui. Le Juge s''assit, et des livres furent ouverts.'),
('dn',7,11,'crampon1923','Je regardais alors, à cause du bruit des grandes paroles que la corne proférait; je regardais, jusqu''au moment où la bête fut tuée, et son corps détruit et livré à la flamme de feu.'),
('dn',7,12,'crampon1923','Au reste des bêtes aussi, on avait ôté leur domination, et la durée de leur vie avait été fixée jusqu''à un temps et un moment.'),
('dn',7,13,'crampon1923','Je regardais dans les visions de la nuit, et voici que sur les nuées vint comme un Fils d''homme; il s''avança jusqu''au vieillard, et on le fit approcher devant lui.'),
('dn',7,14,'crampon1923','Et il lui fut donné domination, gloire et règne, et tous les peuples, nations et langues le servirent. Sa domination est une domination éternelle qui ne passera point, et son règne ne sera jamais détruit.'),
('dn',7,15,'crampon1923','Pour moi, Daniel, mon esprit fut troublé au dedans de moi, et les visions de ma tête m''effrayèrent.'),
('dn',7,16,'crampon1923','Je m''approchai vers l''un de ceux qui se tenaient là, et je lui demandai quelque chose de certain sur tout cela, et il me parla pour m''en donner l''explication.'),
('dn',7,17,'crampon1923','Ces grandes bêtes, qui sont quatre, ce sont quatre rois qui s''élèveront de la terre;'),
('dn',7,18,'crampon1923','mais les Saints du Très-Haut recevront le royaume, et ils posséderont le royaume pour l''éternité, pour une éternité d''éternités.'),
('dn',7,19,'crampon1923','Alors je voulus avoir une certitude sur la quatrième bête qui était différente de toutes les autres, extrêmement terrible, dont les dents étaient de fer et les griffes d''airain, qui mangeait, brisait et foulait aux pieds ce qui restait;'),
('dn',7,20,'crampon1923','et sur les dix cornes qui étaient sur sa tête, et sur l''autre corne qui s''était élevée et devant laquelle trois étaient tombées, cette corne qui avait des yeux et une bouche proférant de grandes choses, et qui paraissait plus grande que ses compagnes.'),
('dn',7,21,'crampon1923','Je regardai, et cette corne faisait la guerre aux Saints et l''emportait sur eux,'),
('dn',7,22,'crampon1923','jusqu''à ce que le vieillard vint, que le jugement fut donné aux Saints du Très Haut, et que le temps arriva où les Saints possédèrent le royaume.'),
('dn',7,23,'crampon1923','Il me parla ainsi: " La quatrième bête, c''est un quatrième royaume qui sera sur la terre, différent de tous les royaumes, et qui dévorera toute la terre, la foulera et la réduira en poudre.'),
('dn',7,24,'crampon1923','Les dix cornes signifient que de ce royaume se lèveront dix rois; un autre se lèvera après eux, qui différera des précédents, et il abattra trois rois.'),
('dn',7,25,'crampon1923','Il proférera des paroles contre le Très-Haut, il opprimera les Saints du Très-Haut, et formera le dessein de changer les temps et la loi, et les Saints seront livrés en sa main jusqu''à un temps, des temps et une moitié de temps.'),
('dn',7,26,'crampon1923','Et le jugement se tiendra, et on lui ôtera sa domination pour le détruire et l''anéantir pour toujours.'),
('dn',7,27,'crampon1923','Et le règne, la domination et la grandeur des royaumes qui sont sous tous les cieux seront donnés au peuple des Saints du Très-Haut; son règne est un règne éternel, et toutes les puissances le serviront et lui obéiront. "'),
('dn',7,28,'crampon1923','Voilà la fin du discours. Moi, Daniel, mes pensées m''effrayèrent beaucoup, je changeai de couleur; mais je conservai la chose dans mon cœur.'),
('dn',8,1,'crampon1923','La troisième année du règne du roi Baltasar, une vision m''apparut, à moi Daniel, après celle qui m''était apparue auparavant.'),
('dn',8,2,'crampon1923','Et je vis dans la vision; et il arriva, comme je regardais, que je me trouvais à Suse, la forteresse qui est dans la province d''Elam, et je vis dans la vision, et j''étais près du fleuve Oulaï.'),
('dn',8,3,'crampon1923','Je levai les yeux et je vis: et voici qu''un bélier se tenait devant le fleuve; il avait deux cornes; les deux cornes étaient hautes, mais l''une était plus haute que l''autre, et la plus haute s''élevait la dernière.'),
('dn',8,4,'crampon1923','Je vis le bélier heurtant de ses cornes vers l''occident, vers le septentrion et vers le midi; aucune bête ne tenait devant lui, et personne ne délivrait de sa main; il faisait ce qu''il voulait et grandissait.'),
('dn',8,5,'crampon1923','Et moi, je considérais avec attention, et voici qu''un jeune bouc venait de l''occident sur la face de toute la terre, sans toucher la terre, et le bouc avait entre les yeux une corne très apparente.'),
('dn',8,6,'crampon1923','Il arriva jusqu''au bélier aux deux cornes, que j''avais vu se tenant devant le fleuve, et il courut contre lui dans l''ardeur de sa force.'),
('dn',8,7,'crampon1923','Je le vis s''approcher du bélier; s''irritant contre lui, il frappa le bélier et lui brisa les deux cornes, sans que le bélier eut la force de se tenir devant lui; il le jeta par terre et le foula aux pieds, et personne ne délivrait le bélier de sa main.'),
('dn',8,8,'crampon1923','Le jeune bouc grandit extrêmement et, quand il fut devenu fort, la grande corne se brisa, et je vis quatre cornes s''élever à sa place vers les quatre vents du ciel.'),
('dn',8,9,'crampon1923','De l''une d''elles sortit une corne, petite, qui grandit beaucoup vers le midi, vers l''orient et vers le glorieux pays.'),
('dn',8,10,'crampon1923','Elle grandit jusqu''à l''armée des cieux; elle fit tomber à terre une partie de cette armée et des étoiles, et les foula aux pieds.'),
('dn',8,11,'crampon1923','Elle grandit jusqu''au chef de l''armée et lui enleva le culte perpétuel, et le lieu de son sanctuaire fut renversé.'),
('dn',8,12,'crampon1923','Et une armée a été livrée par infidélité, avec le culte perpétuel, et la corne a jeté la vérité par terre; elle l''a fait et elle a réussi.'),
('dn',8,13,'crampon1923','Et j''entendis un saint qui parlait: et un autre saint dit à celui qui parlait: " Jusqu''à quand durera ce qu''annonce la vision touchant le culte perpétuel, le péché de désolation. ainsi que l''abandon du sanctuaire et de l''armée pour être foulés? "'),
('dn',8,14,'crampon1923','Il me dit: " Jusqu''à deux mille trois cents soirs et matins; puis le sanctuaire sera purifié. "'),
('dn',8,15,'crampon1923','Tandis que moi, Daniel, je voyais la vision et que j''en cherchais l''intelligence, voici que se tenait devant moi comme une figure d''homme.'),
('dn',8,16,'crampon1923','Et j''entendis une voix d''homme du milieu de l''Oulaï; elle cria et dit: " Gabriel, fais-lui comprendre la vision. "'),
('dn',8,17,'crampon1923','Il vint alors près du lieu où je me tenais, et à son approche je fus effrayé, et je tombai sur ma face. Il me dit: " Comprends, fils de l''homme, que la vision est pour le temps de la fin. "'),
('dn',8,18,'crampon1923','Comme il me parlait, je tombai par terre sur ma face, frappé d''assoupissement; mais il me toucha et me fit tenir debout, au lieu où je me tenais.'),
('dn',8,19,'crampon1923','Et il dit: " Voici que je vais t''apprendre ce qui arrivera au dernier temps de la colère; car c''est pour le temps de la fin.'),
('dn',8,20,'crampon1923','Le bélier à deux cornes que tu as vu, ce sont les rois de Médie et de Perse;'),
('dn',8,21,'crampon1923','le bouc velu, c''est le roi de Javan, et la grande corne entre ses yeux, c''est le premier roi.'),
('dn',8,22,'crampon1923','Si cette corne s''est brisée, et si quatre cornes se sont dressées à sa place; c''est que quatre royautés s''élèveront de cette nation, mais sans avoir la même force.'),
('dn',8,23,'crampon1923','A la fin de leur domination, quand le nombre des infidèles sera complet, il s''élèvera un roi au dur visage et pénétrant les choses cachées.'),
('dn',8,24,'crampon1923','Sa force s''accroîtra, mais non par sa propre force; il fera de prodigieux ravages; il réussira dans ses entreprises; il ravagera les puissants et le peuple des saints.'),
('dn',8,25,'crampon1923','A cause de son habileté, il fera prospérer la ruse dans sa main; il s''enorgueillira dans son cœur, et en pleine paix il fera périr beaucoup de gens; il s''élèvera contre le prince des princes, et il sera brisé sans la main d''un homme.'),
('dn',8,26,'crampon1923','La vision touchant le soir et le matin, qui a été exposée c''est la vérité. Mais toi, serre la vision, car elle se rapporte à un temps éloigné. "'),
('dn',8,27,'crampon1923','Et moi, Daniel, je tombai en défaillance et fus malade pendant plusieurs jours; puis je me levai et m''occupai des affaires du roi. J''étais stupéfait de ce que j''avais vu, et personne ne le comprenait.'),
('dn',9,1,'crampon1923','La première année de Darius, fils d''Assuérus, de la race des Mèdes, qui fut établi roi sur le royaume des Chaldéens;'),
('dn',9,2,'crampon1923','la première année de son règne, moi, Daniel, je portai mon attention, en lisant les livres, sur le nombre des années au sujet desquelles la parole de Yahweh avait été adressée au prophète Jérémie, et qui devaient s''accomplir sur les ruines de Jérusalem, soixante-dix ans.'),
('dn',9,3,'crampon1923','Et je tournai ma face vers le Seigneur Dieu, me disposant à la prière et à la supplication par le jeûne, et avec le sac et la cendre.'),
('dn',9,4,'crampon1923','Je priai Yahweh, mon Dieu, et je fis confession, et je dis: " Ah! Seigneur, Dieu grand et redoutable, qui gardez l''alliance et la miséricorde à ceux qui vous aiment et qui gardent vos commandements,'),
('dn',9,5,'crampon1923','nous avons péché, nous avons commis l''iniquité, nous avons été méchants et rebelles, nous nous sommes détournés de vos commandements et de vos lois.'),
('dn',9,6,'crampon1923','Nous n''avons pas écouté vos serviteurs les prophètes, qui ont parlé en votre nom à nos rois, à nos chefs, à nos pères et à tout le peuple du pays.'),
('dn',9,7,'crampon1923','A vous, Seigneur, la justice, à nous la confusion de visage, comme c''est le cas aujourd''hui, aux hommes de Juda, aux habitants de Jérusalem et à tout Israël, à ceux qui sont près et à ceux qui sont loin, dans tous les pays où vous les avez chassés, à cause de leurs iniquités qu''ils ont commises contre vous.'),
('dn',9,8,'crampon1923','Seigneur, à nous la confusion de visage, à nos rois, à nos chefs, et à nos pères, parce que nous avons péché contre vous.'),
('dn',9,9,'crampon1923','Au Seigneur, notre Dieu, les miséricordes et les pardons, car nous nous sommes révoltés contre vous.'),
('dn',9,10,'crampon1923','Nous n''avons pas obéi à la voix de Yahweh, notre Dieu, pour suivre ses lois qu''il a mises devant nous par l''intermédiaire de ses serviteurs les prophètes.'),
('dn',9,11,'crampon1923','Tout Israël a transgressé votre loi et s''est détourné pour ne pas écouter votre voix; alors se sont répandues sur nous la malédiction et l''imprécation qui sont écrites dans la loi de Moïse, serviteur de Dieu, parce que nous avons péché contre lui.'),
('dn',9,12,'crampon1923','Il a tenu ses paroles qu''il a prononcées contre nous et contre nos juges qui nous jugeaient, en faisant venir sur nous une calamité si grande, qu''il n''en est jamais arrivé sous le ciel de pareille à celle qui est arrivée à Jérusalem.'),
('dn',9,13,'crampon1923','Comme il est écrit dans la loi de Dieu, toute cette calamité est venue sur nous, et nous n''avons pas cherché à apaiser Yahweh, notre Dieu, en nous détournant de nos iniquités et en nous rendant attentifs à votre Vérité.'),
('dn',9,14,'crampon1923','Et Yahweh a veillé sur le mal, et il l''a fait venir sur nous; car Yahweh, notre Dieu, est juste dans toutes ses œuvres qu''il a faites, et nous n''avons pas écouté sa voix.'),
('dn',9,15,'crampon1923','Maintenant, Seigneur, notre Dieu, qui avez tiré votre peuple du pays d''Egypte par votre main puissante, et qui vous êtes fait un nom, comme il est aujourd''hui, nous avons péché, nous avons été méchants.'),
('dn',9,16,'crampon1923','Seigneur, puissent, selon toutes vos justices, votre colère et votre indignation se détourner de votre ville de Jérusalem, votre montagne sainte; car c''est à cause de nos péchés et des iniquités de nos pères que Jérusalem et votre peuple sont en opprobre à tous ceux qui nous entourent.'),
('dn',9,17,'crampon1923','Maintenant, écoutez, ô notre Dieu, la prière de votre serviteur et ses supplications, et faites briller votre visage sur votre sanctuaire dévasté, pour l''amour du Seigneur.'),
('dn',9,18,'crampon1923','Mon Dieu, prêtez l''oreille et écoutez; ouvrez vos yeux et voyez nos désolations et la ville sur laquelle votre nom a été prononcé. Car ce n''est pas à cause de nos justices que nous déposons devant vous nos supplications, mais à cause de vos grandes miséricordes.'),
('dn',9,19,'crampon1923','Seigneur, entendez; Seigneur, pardonnez; Seigneur, soyez attentif et agissez; ne tardez pas, à cause de vous-même, ô mon Dieu; car votre nom a été prononcé sur votre ville et votre peuple! "'),
('dn',9,20,'crampon1923','Comme je parlais encore, priant, confessant mon péché et le péché de mon peuple d''Israël, et déposant ma supplication devant Yahweh, mon Dieu, pour la sainte montagne de mon Dieu;'),
('dn',9,21,'crampon1923','comme je parlais encore dans ma prière, cet homme, Gabriel, que j''avais vu auparavant en vision, s''approcha de moi d''un vol rapide vers le temps de l''oblation du soir.'),
('dn',9,22,'crampon1923','Il m''instruisit, me parla et dit: " Daniel, je suis venu en ce moment pour t''ouvrir l''intelligence.'),
('dn',9,23,'crampon1923','Dès le commencement de ta prière, une parole est sortie, et moi je suis venu pour te la faire connaître, car tu es un homme favorisé de Dieu. Sois donc attentif à la parole et comprends la vision.'),
('dn',9,24,'crampon1923','Soixante-dix semaines ont été déterminées sur ton peuple et sur ta ville sainte pour enfermer la prévarication, pour sceller les péchés et pour expier l''iniquité, et pour amener la justice éternelle, pour sceller vision et prophète et pour oindre le Saint des saints.'),
('dn',9,25,'crampon1923','Sache donc et comprends: depuis la sortie d''une parole ordonnant de rebâtir Jérusalem jusqu''à un oint, un chef, il y a sept semaines, et soixante-deux semaines; elle sera rebâtie, places et enceinte, dans la détresse des temps.'),
('dn',9,26,'crampon1923','Et après soixante-deux semaines, un oint sera retranché, et personne pour lui. Et le peuple d''un chef qui viendra détruira la ville et le sanctuaire, et sa fin sera dans l''inondation, et jusqu''à la fin il y aura guerre, ce qui est décrété touchant la dévastation.'),
('dn',9,27,'crampon1923','Il conclura une alliance ferme avec un grand nombre pendant une semaine; et, au milieu de la semaine, il fera cesser le sacrifice et l''oblation, et sur l''aile des abominations viendra un dévastateur, et cela jusqu''à ce que la destruction et ce qui a été décrété se répandent sur le dévasté.'),
('dn',10,1,'crampon1923','La troisième année de Cyrus, roi de Perse, une parole fut révélée à Daniel, qui avait été nommé Baltassar; cette parole est véritable, et elle annonçait une grande guerre. Il comprit la parole et il eut l''intelligence de la vision:'),
('dn',10,2,'crampon1923','En ces jours-là, moi, Daniel, je fus dans le deuil pendant trois semaines de jours.'),
('dn',10,3,'crampon1923','Je ne mangeai aucun mets délicat; il n''entra dans ma bouche ni viande, ni vin, et je ne m''oignis point jusqu''à ce que les trois semaines de jours fussent accomplies.'),
('dn',10,4,'crampon1923','Le vingt-quatrième jour du premier mois, j''étais sur le bord du grand fleuve, qui est le Tigre.'),
('dn',10,5,'crampon1923','Je levai les yeux et je regardai: et voici un homme vêtu de lin, les reins ceints d''une ceinture d''or d''Uphaz.'),
('dn',10,6,'crampon1923','Son corps était comme le chrysolithe, son visage avait l''aspect de l''éclair, ses yeux étaient comme des torches de feu, ses bras et ses pieds avaient l''aspect de l''airain poli, et sa voix, quand il parlait, était comme la voix d''une multitude.'),
('dn',10,7,'crampon1923','Moi, Daniel, je vis seul l''apparition, et les hommes qui étaient avec moi ne virent pas l''apparition, mais une grande frayeur tomba sur eux, et ils s''enfuirent pour se cacher.'),
('dn',10,8,'crampon1923','Et moi, je restai seul et je vis cette grande apparition, et il ne resta plus en moi de force; mon visage changea de couleur et se décomposa sans conserver aucune force.'),
('dn',10,9,'crampon1923','J''entendis le son de ses paroles et, en entendant le son de ses paroles, je tombai assoupi, la face contre terre.'),
('dn',10,10,'crampon1923','Et voici qu''une main me toucha et me fit dresser sur mes genoux et sur les paumes de mes mains.'),
('dn',10,11,'crampon1923','Puis il me dit: " Daniel, homme favorisé de Dieu, comprends les paroles que je vais te dire et tiens-toi debout; car je suis maintenant envoyé vers toi. " Quand il m''eut parlé en ces termes, je me tins debout en tremblant.'),
('dn',10,12,'crampon1923','Il me dit: " Ne crains point, Daniel, car dès le premier jour où tu as appliqué ton cœur à comprendre et à t''humilier devant ton Dieu, tes paroles ont été entendues, et moi, je suis venu à cause de tes paroles.'),
('dn',10,13,'crampon1923','Mais le chef du royaume de Perse s''est tenu devant moi vingt et un jours, et voici que Michel, un des premiers chefs, est venu à mon secours, et je suis resté là auprès des rois de Perse.'),
('dn',10,14,'crampon1923','Et je suis venu pour te faire comprendre ce qui doit arriver à ton peuple à la fin des jours; car c''est encore une vision pour des jours lointains.'),
('dn',10,15,'crampon1923','Pendant qu''il parlait avec moi en ces termes, je tournais la face vers la terre et je restais muet.'),
('dn',10,16,'crampon1923','Et voici: comme une ressemblance de fils de l''homme toucha mes lèvres, et j''ouvris la bouche et je parlai; je dis à celui qui se tenait devant moi: " Mon seigneur, à cette apparition, les angoisses m''ont saisi et je n''ai conservé aucune force.'),
('dn',10,17,'crampon1923','Comment le serviteur de mon seigneur que voici pourrait-il parler à mon seigneur que voilà? En ce moment, il n''y a plus de force en moi et il ne reste plus de souffle en moi. "'),
('dn',10,18,'crampon1923','Alors celui qui avait la ressemblance d''un homme me toucha de nouveau et me fortifia.'),
('dn',10,19,'crampon1923','Puis il me dit: " Ne crains point, homme favorisé de Dieu; que la paix soit avec toi! Courage! courage! " Pendant qu''il parlait avec moi, je repris des forces et je dis: " Que mon seigneur parle, car tu m''as fortifié. "'),
('dn',10,20,'crampon1923','Il me dit: " Sais-tu pourquoi je suis venu vers toi? Maintenant, je vais retourner combattre le chef de la Perse; et, au moment où je m''en irai, voici le chef de Javan qui viendra.'),
('dn',10,21,'crampon1923','Mais je te déclarerai ce qui est écrit dans le livre de vérité; et il n''y en a pas un qui se tienne avec moi contre ceux-là, sinon Michel, votre chef.'),
('dn',11,1,'crampon1923','Et moi, dans la première année de Darius le Mède, je me tenais auprès de lui pour le soutenir et le fortifier.'),
('dn',11,2,'crampon1923','Maintenant je vais te déclarer la vérité. Voici que trois rois se lèveront encore pour la Perse; le quatrième possédera de plus grandes richesses que tous les autres et, quand il sera puissant par ses richesses, il soulèvera tout contre le royaume de Javan.'),
('dn',11,3,'crampon1923','Et il s''élèvera un roi vaillant, qui aura une grande puissance et fera ce qui lui plaira.'),
('dn',11,4,'crampon1923','Dès qu''il se sera élevé, son royaume se brisera et sera divisé aux quatre vents du ciel, sans appartenir à ses descendants et sans avoir la même puissance qu''il avait eue; car son royaume sera déchiré, et il passera à d''autres qu''eux.'),
('dn',11,5,'crampon1923','Le roi du Midi deviendra fort, ainsi qu''un de ses généraux, lequel deviendra plus fort que lui et sera puissant; sa puissance sera une grande puissance.'),
('dn',11,6,'crampon1923','Au bout de quelques années, ils s''allieront, et la fille du roi du Midi viendra vers le roi du Septentrion pour établir un accord. Mais elle ne conservera pas l''appui d''un bras, car il ne tiendra pas, non plus que son propre bras; et elle sera livrée, elle et ceux qui l''avaient amenée, celui qui lui avait donné naissance et celui qui l''avait soutenue pendant quelque temps.'),
('dn',11,7,'crampon1923','Un des rejetons de ses racines s''élèvera à sa place; il viendra à l''armée, il entrera dans la forteresse du roi du Septentrion, il les traitera à son gré et il l''emportera.'),
('dn',11,8,'crampon1923','Leurs dieux mêmes, leurs images de fonte et leurs vases précieux d''argent et d''or, il les emmènera captifs en Egypte, et il prévaudra plusieurs années sur le roi du Septentrion.'),
('dn',11,9,'crampon1923','Celui-ci entrera dans le royaume du Midi, et il s''en retournera dans son pays.'),
('dn',11,10,'crampon1923','Mais ses fils s''armeront pour la guerre et rassembleront une grande multitude de troupes; l''un d''eux viendra, il inondera, il envahira, puis il reviendra, et poussera les hostilités contre la forteresse.'),
('dn',11,11,'crampon1923','Le roi du Midi s''irritera, il partira et combattra contre lui, contre le roi du Septentrion; il lèvera de grandes troupes, et la troupe du roi du Septentrion lui sera livrée.'),
('dn',11,12,'crampon1923','Devant la multitude levée contre lui, son courage s''élèvera; il en fera tomber des milliers, mais il n''en sera pas plus fort.'),
('dn',11,13,'crampon1923','Car le roi du Septentrion rassemblera de nouveau des troupes plus nombreuses que les premières et, au bout d''un certain nombre d''années, il se mettra en marche avec une grande armée et un train considérable.'),
('dn',11,14,'crampon1923','En ces temps-là beaucoup de gens s''élèveront contre le roi du Midi, et des hommes violents de ton peuple se lèveront pour accomplir la vision, et ils tomberont.'),
('dn',11,15,'crampon1923','Le roi du Septentrion viendra, il élèvera des terrasses et prendra une ville fortifiée; les bras du Midi ne tiendront pas, non plus que sa troupe d''élite; il n''y aura pas de force pour résister.'),
('dn',11,16,'crampon1923','Celui qui aura marché contre lui fera ce qui lui plaira, et personne ne tiendra devant lui; il s''arrêtera dans le glorieux pays, et la destruction sera dans sa main.'),
('dn',11,17,'crampon1923','Il se décidera à venir avec la force de tout son royaume et il fera un arrangement avec lui; et il lui donnera une jeune fille pour amener sa ruine; mais cela ne réussira pas, et ce royaume ne sera point à lui.'),
('dn',11,18,'crampon1923','Puis il se tournera vers les îles et en prendra beaucoup; mais un capitaine lui fera cesser son injure et, sans avoir reçu son injure, il la lui rendra.'),
('dn',11,19,'crampon1923','Il se tournera vers les forteresses de son pays; mais il trébuchera, il tombera, et on ne le trouvera plus.'),
('dn',11,20,'crampon1923','Un autre se tiendra à sa place, qui fera passer un exacteur dans le lieu qui est la gloire du royaume, et en quelques jours il sera brisé, et ce ne sera ni par la colère ni par la guerre.'),
('dn',11,21,'crampon1923','A sa place se tiendra un homme méprisé, à qui on n''aura pas donné la dignité royale; il viendra sans bruit et s''emparera de la royauté par des intrigues.'),
('dn',11,22,'crampon1923','Les forces de l''inondation seront submergées devant lui et seront brisées, et aussi le chef de l''alliance.'),
('dn',11,23,'crampon1923','Sans tenir compte de l''alliance conclue avec lui, il agira de ruse, il se mettra en marche et aura le dessus avec peu de gens.'),
('dn',11,24,'crampon1923','Il viendra sans bruit dans les plus riches provinces du pays; il fera ce que n''avaient pas fait ses pères, ni les pères de ses pères, il leur distribuera butin, dépouilles et richesses, et il formera des projets contre les forteresses, et cela jusqu''à un certain temps.'),
('dn',11,25,'crampon1923','Il excitera sa force et son courage contre le roi du Midi, à la tête d''une grande armée. Et le roi du Midi s''engagera dans la guerre avec une armée nombreuse et très forte; mais il ne tiendra pas, parce qu''on formera des complots contre lui.'),
('dn',11,26,'crampon1923','Ceux qui mangent les mets de sa table le briseront, son armée se dissipera, et beaucoup d''hommes tomberont frappés de mort.'),
('dn',11,27,'crampon1923','Les deux rois chercheront dans leur cœur à se nuire, et, à une même table, ils se diront des mensonges; mais cela ne réussira pas, car la fin ne viendra qu''au temps marqué.'),
('dn',11,28,'crampon1923','Il retournera dans son pays avec de grandes richesses; son cœur médite le mal contre l''alliance sainte, et il le fait, et il rentre dans son pays.'),
('dn',11,29,'crampon1923','Au temps marqué, il arrivera de nouveau dans le Midi; mais cette dernière campagne ne sera pas comme la première.'),
('dn',11,30,'crampon1923','Des navires de Céthim viendront contre lui et il perdra courage; il s''en retournera et il s''irritera contre l''alliance sainte; et il agira, et il s''entendra encore une fois avec ceux qui auront abandonné l''alliance.'),
('dn',11,31,'crampon1923','Des troupes envoyées par lui se tiendront là; elles profaneront le sanctuaire, la forteresse; elles feront cesser le sacrifice perpétuel et dresseront l''abomination du dévastateur.'),
('dn',11,32,'crampon1923','Par des flatteries, il gagnera à l''idolâtrie les violateurs de l''alliance; mais le peuple de ceux qui connaissent leur Dieu tiendra ferme et agira.'),
('dn',11,33,'crampon1923','Ceux qui sont intelligents parmi le peuple instruiront la multitude; mais ils tomberont par l''épée et la flamme, par la captivité et le pillage, un certain temps.'),
('dn',11,34,'crampon1923','Pendant qu''ils tomberont ainsi, ils seront secourus d''un léger secours, et plusieurs se joindront à eux, mais avec hypocrisie.'),
('dn',11,35,'crampon1923','Et parmi ces intelligents, il y en a qui tomberont, afin qu''ils soient éprouvés, purifiés et blanchis, jusqu''au temps de la fin, car on ne sera pas encore au terme fixé.'),
('dn',11,36,'crampon1923','Le roi fera ce qui lui plaira, il s''élèvera et se grandira au-dessus de tout dieu, et contre le Dieu des dieux il dira des choses prodigieuses; et il prospérera, jusqu''à ce que la colère soit consommée; car ce qui est décrété doit s''accomplir.'),
('dn',11,37,'crampon1923','Il n''aura égard ni aux dieux de ses pères, ni à la divinité chère aux femmes; il n''aura égard à aucun dieu; car il se grandira au-dessus de tout.'),
('dn',11,38,'crampon1923','Mais il honorera le dieu des forteresses en son lieu; le dieu que n''ont pas connu ses pères, il l''honorera avec de l''or, de l''argent, des pierres précieuses et des joyaux.'),
('dn',11,39,'crampon1923','Il attaquera les remparts des forteresses avec le dieu étranger; ceux qui le reconnaîtront, il les comblera d''honneurs, il les fera dominer sur la multitude et leur distribuera des terres en récompense.'),
('dn',11,40,'crampon1923','Au temps de la fin, le roi du Midi se heurtera avec lui. Le roi du Septentrion fondra sur lui, avec des chars et des cavaliers et de nombreux vaisseaux; il s''avancera dans les terres et passera en débordant.'),
('dn',11,41,'crampon1923','Il entrera dans le glorieux pays, et beaucoup tomberont sous ses coups, mais ceux-ci échapperont à sa main: Edom et Moab et la fleur des enfants d''Ammon.'),
('dn',11,42,'crampon1923','Il étendra la main sur les pays, et le pays d''Egypte n''échappera point.'),
('dn',11,43,'crampon1923','Il se rendra maître de tous les trésors d''or et d''argent et de toutes les choses précieuses de l''Egypte; les Libyens et les Ethiopiens marcheront à sa suite.'),
('dn',11,44,'crampon1923','Mais des nouvelles de l''orient et du septentrion viendront le troubler, et il partira avec une grande fureur pour détruire et exterminer une foule de gens.'),
('dn',11,45,'crampon1923','Il dressera les tentes de son palais entre les mers, vers la montagne sainte et glorieuse. Puis il arrivera à sa fin, et personne ne le secourra.'),
('dn',12,1,'crampon1923','En ce temps-là se lèvera Michel, le grand chef, qui tient pour les enfants de ton peuple, et ce sera un temps de détresse telle qu''il n''y en a point eu de pareille, depuis qu''il existe une nation jusqu''à ce temps-là. Et en ce temps-là, ton peuple sera sauvé, quiconque sera trouvé inscrit dans le livre.'),
('dn',12,2,'crampon1923','Et beaucoup de ceux qui dorment dans la poussière se réveilleront, les uns pour une vie éternelle, les autres pour les opprobres, pour la réprobation éternelle.'),
('dn',12,3,'crampon1923','Ceux qui auront été intelligents brilleront comme la splendeur du firmament et ceux qui en auront conduit beaucoup à la justice seront comme les étoiles, éternellement et toujours.'),
('dn',12,4,'crampon1923','Et toi, Daniel, serre les paroles et scelle le livre jusqu''au temps de la fin. Beaucoup le scruteront, et la connaissance s''accroîtra. "'),
('dn',12,5,'crampon1923','Moi, Daniel, je regardai et voici que deux autres hommes se tenaient debout, l''un sur une rive du fleuve, l''autre sur l''autre rive du fleuve.'),
('dn',12,6,'crampon1923','L''un d''eux parla à l''homme vêtu de lin, qui était au-dessus des eaux du fleuve: " Jusqu''à quand le terme de ces choses merveilleuses? "'),
('dn',12,7,'crampon1923','Et j''entendis l''homme vêtu de lin qui était au-dessus des eaux; il leva vers le ciel sa main droite et sa main gauche, et il jura par celui qui vit éternellement que ce serait dans un temps, des temps et une moitié de temps, et que, quand on aurait achevé de briser la force du peuple saint, alors s''accompliront toutes ces choses.'),
('dn',12,8,'crampon1923','Et moi, j''entendis, mais sans comprendre, et je dis: " Mon seigneur, quelle sera la fin de ces choses? "'),
('dn',12,9,'crampon1923','Il dit: " Va, Daniel, car les paroles sont serrées et scellées jusqu''au temps de la fin.'),
('dn',12,10,'crampon1923','Il y en aura beaucoup qui seront purifiés, blanchis et éprouvés; et les méchants feront le mal, et aucun méchant ne comprendra; mais les intelligents comprendront.'),
('dn',12,11,'crampon1923','Depuis le temps où sera interrompu le sacrifice perpétuel, et où sera dressée l''abomination du dévastateur, il y aura mille deux cent quatre-vingt-dix jours.'),
('dn',12,12,'crampon1923','Heureux celui qui attendra et arrivera jusqu''à mille trois cent trente-cinq jours!'),
('dn',12,13,'crampon1923','Toi, va à ta fin et repose-toi; tu seras debout pour ton héritage à la fin des jours. " Jusqu''ici nous avons lu Daniel dans le texte Hébreu; ce qui suit jusqu''à la fin du livre, a été traduit d''après l''édition de Théodotion. HISTOIRE DE SUSANNE.'),
('dn',13,1,'crampon1923','Il y avait un homme qui demeurait à Babylone, et son nom était Joakim.'),
('dn',13,2,'crampon1923','Il prit une femme nommée Susanne, fille d''Helcias, d''une grande beauté et craignant Dieu;'),
('dn',13,3,'crampon1923','car ses parents, qui étaient justes, avaient instruit leur fille selon la loi de Moïse.'),
('dn',13,4,'crampon1923','Or Joakim était fort riche, et il avait un jardin près de sa maison, et les Juifs affluaient chez lui, parce qu''il était le plus honorable de tous.'),
('dn',13,5,'crampon1923','On avait établi juges cette année-là deux anciens d''entre le peuple, dont le Maître a dit: " L''iniquité est sortie de Babylone par des vieillards qui étaient juges, qui paraissaient régir le peuple. "'),
('dn',13,6,'crampon1923','Ils fréquentaient la maison de Joakim, et tous ceux qui avaient des différends se rendaient auprès d''eux.'),
('dn',13,7,'crampon1923','Vers le milieu du jour, lorsque le peuple s''était retiré, Susanne entrait dans le jardin de son mari et s''y promenait.'),
('dn',13,8,'crampon1923','Les deux vieillards la voyaient chaque jour y entrer et s''y promener, et ils conçurent pour elle une ardente passion.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('dn',13,9,'crampon1923','Ils pervertirent leur sens et détournèrent leurs yeux pour ne pas voir le ciel et ne pas se souvenir des justes jugements de Dieu.'),
('dn',13,10,'crampon1923','Ils étaient donc blessés d''amour pour elle, mais ils ne se communiquaient pas mutuellement leur souffrance,'),
('dn',13,11,'crampon1923','car ils avaient honte de révéler l''un à l''autre la passion qui leur faisait désirer d''être avec elle.'),
('dn',13,12,'crampon1923','Ils l''observaient chaque jour avec soin pour la voir, et ils se dirent l''un à l''autre:'),
('dn',13,13,'crampon1923','" Allons chez nous, c''est l''heure du dîner. " Et ils sortirent et se séparèrent.'),
('dn',13,14,'crampon1923','Mais étant revenus sur leurs pas, ils se rencontrèrent, et s''étant demandé le motif de leur retour, ils s''avouèrent leur passion; puis ils convinrent entre eux du moment où ils pourraient la trouver seule.'),
('dn',13,15,'crampon1923','Comme ils épiaient un jour convenable, il arriva que Suzanne entra dans le jardin, comme elle l''avait fait la veille et l''avant-veille, sans autre compagnie que deux jeunes filles; elle voulut se baigner dans le jardin, car il faisait chaud.'),
('dn',13,16,'crampon1923','Il n''y avait là personne, sinon les deux vieillards, qui s''étaient cachés et qui l''épiaient.'),
('dn',13,17,'crampon1923','Elle dit aux jeunes filles: " Apportez-moi de l''huile parfumée et des onguents, et fermez les portes du jardin, afin que je me baigne. "'),
('dn',13,18,'crampon1923','Elles firent ce que Suzanne avait commandé et, ayant fermé la porte du jardin, elles sortirent par une porte de derrière, pour apporter ce qui leur avait été demandé; elles ne savaient pas que les vieillards étaient cachés dans le jardin.'),
('dn',13,19,'crampon1923','Dès que les jeunes filles furent sorties, les deux vieillards se levèrent, coururent à Susanne et lui dirent:'),
('dn',13,20,'crampon1923','" Vois, les portes du jardin sont fermées, personne ne nous aperçoit, et nous brûlons d''amour pour toi; consens donc à notre désir et sois à nous.'),
('dn',13,21,'crampon1923','Si non, nous nous porterons témoins contre toi, et nous dirons qu''un jeune homme était avec toi, et que c''est pour cela que tu as renvoyé les jeunes filles. "'),
('dn',13,22,'crampon1923','Susanne soupira et dit: " De tous côtés l''angoisse m''environne. Si je fais cela, c''est la mort pour moi, et si je ne le fais pas, je n''échapperai pas de vos mains.'),
('dn',13,23,'crampon1923','Mais il vaut mieux pour moi tomber entre vos mains sans avoir fait le mal que de pécher en présence du Seigneur. "'),
('dn',13,24,'crampon1923','Alors Susanne jeta un grand cri, et les deux vieillards crièrent aussi contre elle.'),
('dn',13,25,'crampon1923','Et l''on d''eux courut ouvrir les portes du jardin.'),
('dn',13,26,'crampon1923','Quand les serviteurs de la maison entendirent les cris poussés dans le jardin, ils se précipitèrent par la porte de derrière pour voir ce qu''il y avait.'),
('dn',13,27,'crampon1923','Lorsque les vieillards se furent expliqués, les serviteurs eurent grande honte, parce qu''on n''avait jamais dit chose semblable de Susanne.'),
('dn',13,28,'crampon1923','Le lendemain, le peuple s''étant rassemblé chez Joakim, mari de Susanne, les deux vieillards y vinrent aussi, tout remplis de pensées méchantes contre elle, afin de la faire périr.'),
('dn',13,29,'crampon1923','Ils dirent devant le peuple: " Envoyez chercher Suzanne, fille d''Helcias, femme de Joakim. " Et on envoya aussitôt.'),
('dn',13,30,'crampon1923','Elle vint avec ses parents, ses fils et tous ses proches.'),
('dn',13,31,'crampon1923','Or Suzanne, avait les traits délicats et une grande beauté.'),
('dn',13,32,'crampon1923','Comme elle était voilée, les juges méchants commandèrent qu''on lui ôtât son voile, pour se rassasier de sa beauté.'),
('dn',13,33,'crampon1923','Mais tous les siens et tous ceux qui la connaissaient versaient des larmes.'),
('dn',13,34,'crampon1923','Les deux vieillards, se levant au milieu du peuple, mirent leurs mains sur sa tête.'),
('dn',13,35,'crampon1923','Elle, en pleurant, regarda vers le ciel, car son cœur avait confiance dans le Seigneur.'),
('dn',13,36,'crampon1923','Les vieillards dirent: " Comme nous nous promenions seuls dans le jardin, elle est entrée avec deux jeunes filles et, après avoir fait fermer les portes du jardin, elle a renvoyé les jeunes filles.'),
('dn',13,37,'crampon1923','Et un jeune homme qui était caché est venu à elle et a fait le mal avec elle.'),
('dn',13,38,'crampon1923','Nous étions dans un coin du jardin; en voyant le crime, nous avons couru à eux, et nous les avons vus dans cette infamie.'),
('dn',13,39,'crampon1923','Nous n''avons pu prendre le jeune homme, parce qu''il était plus fort que nous, et qu''ayant ouvert la porte, il s''est échappé.'),
('dn',13,40,'crampon1923','Mais elle, après l''avoir prise, nous lui avons demandé quel était ce jeune homme, et elle n''a pas voulu nous le dire. Voilà ce que nous attestons. "'),
('dn',13,41,'crampon1923','La foule les crut, parce que c''étaient des vieillards et des juges du peuple, et ils la condamnèrent à mort.'),
('dn',13,42,'crampon1923','Alors Susanne s''écria à haute voix et dit: " Dieu éternel, qui connaissez ce qui est caché et qui savez toutes choses avant qu''elles n''arrivent,'),
('dn',13,43,'crampon1923','vous savez qu''ils ont rendu un faux témoignage contre moi; et voici que je meurs, sans avoir rien fait de ce qu''ils ont méchamment inventé contre moi. "'),
('dn',13,44,'crampon1923','Le Seigneur entendit sa voix.'),
('dn',13,45,'crampon1923','Comme on la conduisait à la mort, Dieu éveilla l''esprit saint d''un jeune enfant nommé Daniel.'),
('dn',13,46,'crampon1923','Il cria à haute voix: " Pour moi, je suis pur du sang de cette femme! "'),
('dn',13,47,'crampon1923','Tout le peuple se tourna vers lui et lui dit: " Que signifie cette parole que tu dis-là? "'),
('dn',13,48,'crampon1923','Daniel, se tenant au milieu d''eux, dit: " Etes-vous donc insensés à ce point, enfants d''Israël, de faire mourir une fille d''Israël sans examen, sans chercher à connaître la vérité?'),
('dn',13,49,'crampon1923','Retournez au tribunal, car ils ont rendu un faux témoignage contre elle. "'),
('dn',13,50,'crampon1923','Alors le peuple retourna en hâte, et les anciens dirent à Daniel: " Viens, prends place au milieu de nous, et expose-nous ton avis, car Dieu t''a donné l''honneur de la vieillesse. "'),
('dn',13,51,'crampon1923','Daniel dit au peuple: " Séparez-les loin l''un de l''autre, et je les jugerai. "'),
('dn',13,52,'crampon1923','Quand ils furent séparés l''un de l''autre, Daniel en appela un et lui dit: " Homme vieilli dans le crime, les péchés que tu as commis autrefois sont maintenant venus sur toi,'),
('dn',13,53,'crampon1923','toi qui rendais des jugements injustes, qui condamnais les innocents et relâchais les coupables, quand le Seigneur a dit: Tu ne feras pas mourir l''innocent et le juste.'),
('dn',13,54,'crampon1923','Eh bien, si tu l''as vue, dis sous quel arbre tu les as vus s''entretenant ensemble. " Il répondit: " Sous un lentisque. "'),
('dn',13,55,'crampon1923','Daniel dit: " Justement tu dis un mensonge pour ta perte; car l''ange de Dieu qui a déjà reçu l''arrêt divin va te fendre par le milieu. "'),
('dn',13,56,'crampon1923','Après l''avoir renvoyé, il ordonna d''amener l''autre, et il lui dit: " Race de Chanaan, et non de Juda, la beauté d''une femme t''a séduit et la passion a perverti ton cœur.'),
('dn',13,57,'crampon1923','C''est ainsi que vous en agissiez avec les filles d''Israël, et elles, ayant peur de vous, vous parlaient; mais une fille de Juda n''a pu souffrir votre iniquité.'),
('dn',13,58,'crampon1923','Dis-moi donc maintenant sous quel arbre tu les as surpris s''entretenant ensemble. " Il dit: " Sous un chêne. "'),
('dn',13,59,'crampon1923','Daniel lui dit: " Justement tu as dit, toi aussi, un mensonge pour ta perte; car l''ange du Seigneur attend, le glaive en main, le moment de te couper par le milieu, afin de vous faire mourir. "'),
('dn',13,60,'crampon1923','Alors toute l''assemblée jeta un grand cri, et ils bénirent Dieu qui sauve ceux qui espèrent en lui.'),
('dn',13,61,'crampon1923','Puis ils s''élevèrent contre les deux vieillards, que Daniel avait convaincus par leur propre bouche d''avoir rendu un faux témoignage, et ils leur firent le mal qu''eux-mêmes avaient voulu faire à leur prochain;'),
('dn',13,62,'crampon1923','afin d''accomplir la loi de Moïse, et ils les firent donc mourir, et le sang innocent fut sauvé en ce jour-là.'),
('dn',13,63,'crampon1923','Helcias et sa femme louèrent Dieu au sujet de leur fille Susanne, avec Joakim, son mari, et tous ses parents, parce qu''il ne s''était trouvé en elle rien de déshonnête.'),
('dn',13,64,'crampon1923','Et Daniel devint grand devant le peuple, à partir de ce jour et dans la suite des temps. BEL ET LE DRAGON. Le roi Astyage ayant été réuni à ses pères, Cyrus le Perse reçut le royaume.'),
('dn',14,1,'crampon1923','Or Daniel mangeait à la table du roi, et il était honoré plus que tous ses autres amis.'),
('dn',14,2,'crampon1923','Il y avait chez les Babyloniens une idole nommée Bel; on dépensait chaque jour pour elle douze artabes de farine, quarante brebis et six métrètes de vin.'),
('dn',14,3,'crampon1923','Le roi aussi la vénérait, et il allait chaque jour l''adorer; mais Daniel adorait son Dieu.'),
('dn',14,4,'crampon1923','Le roi lui dit: " Pourquoi n''adores-tu pas Bel? " Il lui répondit: " Parce que je ne vénère pas des idoles faites de main d''homme, mais le Dieu vivant qui a fait le ciel et la terre et qui a puissance sur toute chair. "'),
('dn',14,5,'crampon1923','Le roi lui dit: " Est-ce que Bel ne te semble pas un être vivant? Ne vois-tu pas tout ce qu''il mange et boit chaque jour? "'),
('dn',14,6,'crampon1923','Daniel répondit en souriant: " Ne t''y trompes pas, ô roi; car il est de boue en dedans et d''airain à l''extérieur, et il n''a jamais rien mangé. "'),
('dn',14,7,'crampon1923','Le roi irrité appela les prêtres de Bel et leur dit: " Si vous ne me dites pas qui est celui qui mange ces offrandes, vous mourrez;'),
('dn',14,8,'crampon1923','mais si vous me démontrez que c''est Bel qui les mange, Daniel mourra, parce qu''il a blasphémé contre Bel. "'),
('dn',14,9,'crampon1923','Or il y avait soixante-dix prêtres de Bel, sans compter leurs femmes et leurs enfants. Et le roi se rendit avec Daniel au temple de Bel.'),
('dn',14,10,'crampon1923','Les prêtres de Bel dirent: " Voici que nous allons sortir; toi, ô roi, fais placer les mets et apporter le vin, après l''avoir mélangé; puis ferme la porte, et scelle-la avec ton anneau.'),
('dn',14,11,'crampon1923','Et quand tu entreras demain matin, si tu ne trouves pas que tout a été mangé par Bel, nous mourrons; ou bien ce sera Daniel, qui a menti contre nous. "'),
('dn',14,12,'crampon1923','Ils songeaient qu''ils avaient fait sous la table une ouverture secrète, par laquelle ils s''introduisaient toujours et venaient consommer les offrandes.'),
('dn',14,13,'crampon1923','Lorsqu''ils furent sortis et que le roi eut fait mettre les aliments devant Bel, Daniel commanda à ses serviteurs d''apporter de la cendre, et il la répandirent par tout le temple en présence du roi seul; puis ils sortirent, fermèrent la porte en la scellant avec l''anneau du roi, et s''en allèrent.'),
('dn',14,14,'crampon1923','Pendant la nuit, les prêtres entrèrent selon leur coutume avec leurs femmes et leurs enfants, et ils mangèrent et burent tout ce qui était là.'),
('dn',14,15,'crampon1923','Le roi se leva dès le point du jour, et Daniel avec lui.'),
('dn',14,16,'crampon1923','Le roi dit: " Les sceaux sont-ils intacts, Daniel? " Celui-ci répondit: " Ils sont intacts, ô roi. "'),
('dn',14,17,'crampon1923','Dès qu''il eut ouvert la porte et regardé la table, le roi s''écria à haute voix: " Tu es grand, ô Bel, et il n''y a pas la moindre tromperie en toi. "'),
('dn',14,18,'crampon1923','Daniel se prit à rire et, retenant le roi pour qu''il n''entrât pas plus avant, il lui dit: " Regarde le pavé, considère de qui sont ces pas. "'),
('dn',14,19,'crampon1923','Le roi dit: " je vois des pas d''hommes, de femmes et d''enfants; " et le roi entra dans une grande colère.'),
('dn',14,20,'crampon1923','Alors il fit saisir les prêtres, leurs femmes et leurs enfants, et ils lui montrèrent les portes secrètes par où ils s''introduisaient et venaient manger ce qui était sur la table.'),
('dn',14,21,'crampon1923','Il les fit mettre à mort et livra Bel au pouvoir de Daniel, qui le détruisit ainsi que son temple.'),
('dn',14,22,'crampon1923','Il y avait aussi un grand dragon, et les Babyloniens le vénéraient.'),
('dn',14,23,'crampon1923','Le roi dit à Daniel: " Diras-tu encore que celui-ci est d''airain? Vois, il vit, il mange et boit. Maintenant, tu ne pourras pas dire que ce n''est pas un dieu vivant. "'),
('dn',14,24,'crampon1923','Daniel répondit: " J''adore le Seigneur, mon Dieu, car lui est un Dieu vivant; mais celui-ci n''est point un dieu vivant.'),
('dn',14,25,'crampon1923','Toi, ô roi, donne-moi la permission, et je tuerai ce dragon sans épée ni bâton. " Le roi dit: " Je te la donne. "'),
('dn',14,26,'crampon1923','Alors Daniel prit de la poix, de la graisse et des poils, fit bouillir le tout ensemble et en fit des boules qu''il jeta dans la gueule du dragon. Et le dragon creva. Et il dit: " Voilà celui que vous vénériez! "'),
('dn',14,27,'crampon1923','Les Babyloniens, l''ayant appris, furent saisis d''une vive indignation; ils se rassemblèrent contre le roi et dirent: " Le roi est devenu juif; il a détruit Bel, fait mourir le dragon et massacrer les prêtres. "'),
('dn',14,28,'crampon1923','Ils vinrent donc trouver le roi et lui dirent: " Livre-nous Daniel; sinon, nous te ferons mourir, toi et ta maison. "'),
('dn',14,29,'crampon1923','Le roi vit qu''ils se jetaient sur lui avec violence; cédant à la nécessité, il leur livra Daniel.'),
('dn',14,30,'crampon1923','Ils le jetèrent dans la fosse aux lions, et il y demeura six jours.'),
('dn',14,31,'crampon1923','Dans la fosse, il y avait sept lions, et on leur donnait chaque jour deux corps et deux brebis; mais alors on ne leur donna pas cette pâture, afin qu''ils dévorassent Daniel.'),
('dn',14,32,'crampon1923','Or le prophète Habacuc était en Judée; après avoir fait cuire une bouillie et émietté du pain dans un vase, il allait aux champs le porter à ses moissonneurs.'),
('dn',14,33,'crampon1923','L''ange du Seigneur dit à Habacuc: " Porte le repas que tu tiens à Babylone, à Daniel, qui est dans la fosse aux lions. "'),
('dn',14,34,'crampon1923','Habacuc dit: " Seigneur, je n''ai jamais vu Babylone, et je ne connais pas la fosse. "'),
('dn',14,35,'crampon1923','Alors l''ange le prit par le haut de la tête, le porta, par les cheveux de sa tête, et le déposa à Babylone, au-dessus de la fosse, avec toute l''agilité de sa nature spirituelle.'),
('dn',14,36,'crampon1923','Et Habacuc cria: " Daniel, serviteur de Dieu, prends le repas que Dieu t''envoie. "'),
('dn',14,37,'crampon1923','Daniel répondit: " Vous vous êtes, en effet, souvenu de moi, ô Dieu, et vous n''avez pas abandonné ceux qui vous aiment. "'),
('dn',14,38,'crampon1923','Et Daniel se leva et mangea. Et l''ange du Seigneur remit aussitôt Habacuc en son lieu.'),
('dn',14,39,'crampon1923','Le septième jour, le roi vint pour pleurer Daniel; étant venu vers la fosse, il regarda, et voici que Daniel était assis au milieu des lions.'),
('dn',14,40,'crampon1923','Il cria à haute voix et dit: " Vous êtes grand, Seigneur, Dieu de Daniel, et il n''y en a point d''autre que vous! " Et il le retira de la fosse aux lions.'),
('dn',14,41,'crampon1923','Puis il fit jeter dans la fosse ceux qui avaient voulu le perdre, et ils furent dévorés sous ses yeux, en un instant.'),
('dn',14,42,'crampon1923','Alors le roi dit: " Que tous les habitants de la terre entière craignent le Dieu de Daniel, car c''est lui qui est le Sauveur, qui fait des signes et des prodiges sur la terre, lui qui a délivré Daniel de la fosse aux lions! "'),
('dn',14,43,'crampon1923',''),
('os',1,1,'crampon1923','Parole de Yahweh qui fut adressée à Osée, fils de Béeri, dans les jours d''Ozias, de Joatham, d''Achaz, d''Ezéchias, rois de Juda, et dans les jours de Jéroboam, fils de Joas, roi d''Israël.'),
('os',1,2,'crampon1923','Lorsque Yahweh commença à parler à Osée, Yahweh dit à Osée: " Va, prends une femme de prostitution et des enfants de prostitution, car le pays ne fait que se prostituer en abandonnant Yahweh. "'),
('os',1,3,'crampon1923','Il alla et prit Gomer, fille de Débelaïm; elle conçut et lui enfanta un fils.'),
('os',1,4,'crampon1923','Et Yahweh lui dit: " Nomme-le Jezrahel, car encore un peu de temps et je punirai le sang de Jezrahel sur la maison de Jéhu, et je mettrai fin à la royauté de la maison d''Israël.'),
('os',1,5,'crampon1923','En ce jour-là je briserai l''arc d''Israël dans la plaine de Jezrahel. "'),
('os',1,6,'crampon1923','Elle conçut encore et enfanta une fille; et Yahweh dit à Osée: " Nomme-la Lô-Ruchama, car je n''aurai plus compassion de la maison d''Israël pour lui pardonner ses péchés.'),
('os',1,7,'crampon1923','Mais j''aurai compassion de la maison de Juda, et je les sauverai par Yahweh, leur Dieu; je ne les sauverai ni par l''arc et l''épée, ni par le combat, ni par les chevaux et les cavaliers. "'),
('os',1,8,'crampon1923','Elle sevra Lô-Ruchama; puis elle conçut et enfanta un fils.'),
('os',1,9,'crampon1923','Et Yahweh dit à Osée: " Nomme-le Lô-Ammi, car vous n''êtes pas mon peuple, et moi je ne serai pas votre Dieu. "'),
('os',2,1,'crampon1923','Le nombre des enfants d''Israël sera comme le sable de la mer, qui ne se mesure, ni ne se compte; et au lieu où on leur disait: " Vous n''êtes pas mon peuple, " on leur dira: " Fils du Dieu vivant!'),
('os',2,2,'crampon1923','Et les enfants de Juda et les enfants d''Israël se réuniront, ils se donneront un même chef et monteront hors du pays, car grande sera la journée de Jezrahel.'),
('os',2,3,'crampon1923','Dites à vos frères: " Ammi! " et à vos sœurs: " Ruchama! "'),
('os',2,4,'crampon1923','Plaidez contre votre mère, plaidez! car elle n''est plus ma femme, et moi je ne suis plus son mari. Qu''elle éloigne de sa face ses prostitutions, et ses adultères du milieu de ses seins,'),
('os',2,5,'crampon1923','de peur que je ne la déshabille à nu, et que je ne la mette telle qu''au jour de sa naissance, que je ne la rende pareille au désert, faisant d''elle une terre desséchée, et que je ne la fasse mourir de soif.'),
('os',2,6,'crampon1923','Je n''aurai pas compassion de ses enfants, car ce sont des enfants de prostitution.'),
('os',2,7,'crampon1923','Car leur mère s''est prostituée, celle qui les a conçus a fait des choses honteuses; elle a dit: " J''irai après mes amants, qui me donnent mon pain et mon eau, ma laine et mon lin, mon huile et ma boisson. "'),
('os',2,8,'crampon1923','C''est pourquoi voici que je vais fermer ton chemin avec des ronces; j''élèverai un mur, et elle ne trouvera plus ses sentiers.'),
('os',2,9,'crampon1923','Elle poursuivra ses amants et ne les atteindra pas; elle les cherchera et ne les trouvera pas. Puis elle dira: " J''irai et je retournerai vers mon premier mari, car j''étais plus heureuse alors que maintenant. "'),
('os',2,10,'crampon1923','Elle n''a pas reconnu que c''est moi qui lui ai donné le froment, le vin nouveau et l''huile, qui lui ai multiplié l''argent et l''or, qu''ils ont employés pour Baal.'),
('os',2,11,'crampon1923','C''est pourquoi je reprendrai mon froment en son temps, et mon vin nouveau dans sa saison, et je retirerai ma laine et mon lin, qui servent à couvrir sa nudité.'),
('os',2,12,'crampon1923','Et maintenant je découvrirai sa honte, aux yeux de ses amants, et personne ne la dégagera de ma main.'),
('os',2,13,'crampon1923','Je ferai cesser toutes ses réjouissances, ses fêtes, ses nouvelles lunes, ses sabbats, et toutes ses solennités.'),
('os',2,14,'crampon1923','Je dévasterai ses vignes et ses figuiers dont elle disait: " C''est le salaire que m''ont donné mes amants; " et je les réduirai en forêts, et les bêtes sauvages les dévoreront.'),
('os',2,15,'crampon1923','Je la punirai pour les jours des Baals; auxquels elle offrait de l''encens; alors qu''elle se parait de son anneau et de son collier et allait après ses amants; et moi, elle m''oubliait, — oracle de Yahweh.'),
('os',2,16,'crampon1923','C''est pourquoi, voici que moi je l''attirerai, et la conduirai au désert, et je lui parlerai au cœur;'),
('os',2,17,'crampon1923','et de là je lui donnerai ses vignes, et la vallée d''Achor comme une porte d''espérance; et elle répondra là comme aux jours de sa jeunesse, et comme au jour où elle monta hors du pays d''Egypte.'),
('os',2,18,'crampon1923','En ce jour-là, — oracle de Yahweh, tu m''appelleras: " Mon mari ", et tu ne m''appelleras plus: " Mon Baal ".'),
('os',2,19,'crampon1923','J''ôterai de sa bouche les noms des Baals, et ils ne seront plus mentionnés par leur nom.'),
('os',2,20,'crampon1923','Je ferai pour eux un pacte, en ce jour, avec les bêtes sauvages, avec les oiseaux du ciel, et les reptiles de la terre; je ferai disparaître du pays l''arc, l''épée et la guerre, et je les ferai reposer en sécurité.'),
('os',2,21,'crampon1923','Je te fiancerai à moi pour toujours; je te fiancerai à moi dans la justice et le jugement, dans la grâce et la tendresse;'),
('os',2,22,'crampon1923','je te fiancerai à moi dans la fidélité, et tu connaîtras Yahweh.'),
('os',2,23,'crampon1923','Et il arrivera en ce jour, je répondrai, — oracle de Yahweh, je répondrai aux cieux, et eux répondront à la terre;'),
('os',2,24,'crampon1923','la terre répondra au froment, au vin nouveau et à l''huile, et eux répondront à Jezrahel.'),
('os',2,25,'crampon1923','J''ensemencerai pour moi Israël dans le pays, et je ferai miséricorde à Lô-Ruchama; je dirai à Lô-Ammi: " Tu es mon peuple! " et il dira: " Mon Dieu! "'),
('os',3,1,'crampon1923','Et Yahweh me dit: " Va encore, et aime une femme qui est aimée d''un amant et adultère: comme Yahweh aime les enfants d''Israël, tandis qu''eux se tournent vers d''autres dieux et aiment les gâteaux de raisin. "'),
('os',3,2,'crampon1923','Je l''achetai pour quinze sicles d''argent, un homer d''orge et un léthec d''orge,'),
('os',3,3,'crampon1923','et je lui dis: " Pendant de nombreux jours tu me resteras là, tu ne te prostitueras point et tu ne seras à aucun homme, et moi aussi, je ferai de même à ton égard. "'),
('os',3,4,'crampon1923','Car pendant de nombreux jours les enfants d''Israël demeureront sans roi et sans chef, sans sacrifice et sans stèle, sans éphod et sans théraphim.'),
('os',3,5,'crampon1923','Après cela les enfants d''Israël se convertiront et chercheront de nouveau Yahweh, leur Dieu, et David, leur roi; ils reviendront en tremblant vers Yahweh et vers sa bonté, à la fin des jours.'),
('os',4,1,'crampon1923','Ecoutez la parole de Yahweh, enfants d''Israël; car Yahweh a un procès avec les habitants du pays. Car il n''y a ni vérité, ni compassion, ni connaissance de Dieu dans le pays.'),
('os',4,2,'crampon1923','On se parjure, on ment, on tue, on vole, on commet l''adultère; ils font violence, et le sang versé touche le sang versé.'),
('os',4,3,'crampon1923','C''est pourquoi le pays est dans le deuil, et quiconque y habite est sans force, jusqu''aux bêtes des champs et aux oiseaux du ciel; même les poissons de la mer disparaissent.'),
('os',4,4,'crampon1923','Mais que nul ne conteste, et que nul ne réclame! Car ton peuple est comme ceux qui auraient un procès avec le prêtre.'),
('os',4,5,'crampon1923','Tu trébucheras pendant le jour, le prophète aussi trébuchera avec toi pendant la nuit; et je ferai périr ta mère.'),
('os',4,6,'crampon1923','Mon peuple périt faute de connaissance; parce que tu as rejeté la connaissance, je te rejetterai de mon sacerdoce. Tu as oublié la loi de ton Dieu; moi aussi, j''oublierai tes enfants.'),
('os',4,7,'crampon1923','Tant qu''ils sont, ils ont péché contre moi; je changerai leur gloire en ignominie.'),
('os',4,8,'crampon1923','Ils se repaissent des péchés de mon peuple, ils ne désirent que ses iniquités.'),
('os',4,9,'crampon1923','Il en sera du prêtre comme du peuple; je vengerai sur lui ses voies, et je ferai retomber sur lui ses œuvres.'),
('os',4,10,'crampon1923','Ils mangeront et ne seront pas rassasiés, ils se prostitueront et ne se multiplieront pas; car ils ont abandonné Yahweh pour ne plus le servir.'),
('os',4,11,'crampon1923','La luxure, le vin et le moût enlèvent le sens.'),
('os',4,12,'crampon1923','Mon peuple consulte son bois, et son bâton lui apprend l''avenir; car un esprit de prostitution les a égarés, et ils se sont prostitués loin de leur Dieu.'),
('os',4,13,'crampon1923','Ils offrent des sacrifices sur les sommets des montagnes, et ils brûlent de l''encens sur les collines, sous le chêne, le peuplier, le térébinthe, parce que l''ombrage en est bon. C''est pourquoi, si vos filles se prostituent, et si vos jeunes femmes sont adultères,'),
('os',4,14,'crampon1923','je ne punirai pas vos filles parce qu''elles se sont prostituées, ni vos jeunes brus pour leurs adultères; car eux-mêmes vont à l''écart avec les prostituées, et sacrifient avec les courtisanes. Et le peuple sans intelligence court à sa perte.'),
('os',4,15,'crampon1923','Si tu te prostitues, O Israël, que Juda ne se rende point coupable! Ne venez pas à Galgala, et ne montez pas à Bethaven, et ne jurez pas en disant: " Yahweh est vivant! "'),
('os',4,16,'crampon1923','Parce que pareil à une génisse rétive, Israël a été rétif, maintenant Yahweh les fera paître, comme des agneaux, dans une plaine ouverte.'),
('os',4,17,'crampon1923','Ephraïm est attaché aux idoles; laisse-le!'),
('os',4,18,'crampon1923','Dès qu''ils ont fini de boire, ils se livrent à la prostitution; leurs chefs n''aspirent qu''à l''ignominie.'),
('os',4,19,'crampon1923','Le vent les a enserrés dans ses ailes, et ils seront confus à cause de leurs sacrifices.'),
('os',5,1,'crampon1923','Entendez ceci, ô prêtres; soyez attentive, maison d''Israël; maison du roi, prêtez l''oreille; car c''est pour vous que la sentence est portée, parce que vous avez été un piège à Maspha, et un filet tendu sur le Thabor.'),
('os',5,2,'crampon1923','Par leurs sacrifices, ils ont mis le comble à leurs transgressions; mais je vais être un châtiment pour vous tous!'),
('os',5,3,'crampon1923','Moi, je connais Ephraïm, et Israël ne m''est point caché; or tu t''es prostitué, Ephraïm; Israël s''est souillé.'),
('os',5,4,'crampon1923','Leurs œuvres ne leur permettent pas de revenir à leur Dieu; car un esprit de prostitution est au milieu d''eux, et ils ne connaissent pas Yahweh.'),
('os',5,5,'crampon1923','L''orgueil d''Israël témoigne contre lui; Israël et Ephraïm tomberont par leur iniquité; avec eux aussi tombera Juda.'),
('os',5,6,'crampon1923','Avec leurs brebis et leurs bœufs, ils iront chercher Yahweh, et ils ne le trouveront point; il s''est séparé d''eux.'),
('os',5,7,'crampon1923','Ils ont trompé Yahweh, car ils ont engendré des fils étrangers; maintenant la prochaine lune les dévorera, avec leurs biens.'),
('os',5,8,'crampon1923','Sonnez du clairon à Gabaa, de la trompette à Rama; poussez des cris d''alarme à Bethaven! Prends garde, Benjamin!'),
('os',5,9,'crampon1923','Ephraïm sera dévasté au jour du châtiment; sur les tribus d''Israël j''annonce une chose certaine.'),
('os',5,10,'crampon1923','Les princes de Juda ont été comme ceux qui déplacent les bornes; je répandrai sur eux ma colère comme de l''eau.'),
('os',5,11,'crampon1923','Ephraïm est opprimé, brisé par le jugement, parce qu''il a voulu aller après de viles idoles.'),
('os',5,12,'crampon1923','Et moi, je suis comme la teigne pour Ephraïm, comme la pourriture pour la maison de Juda.'),
('os',5,13,'crampon1923','Quand Ephraïm a vu sa maladie, et Juda sa blessure, Ephraïm est allé vers Assur, et il a envoyé vers un roi qui le vengeât; mais ce roi ne pourra pas vous guérir, et votre plaie ne vous sera pas ôtée.'),
('os',5,14,'crampon1923','Car je serai comme un lion pour Ephraïm, comme un jeune lion pour la maison de Juda; moi, moi, je déchirerai et m''en irai; j''emporterai ma proie, et nul ne me l''arrachera.'),
('os',5,15,'crampon1923','Je m''en irai, je retournerai dans ma demeure, jusqu''à ce qu''ils se reconnaissent coupables, et qu''ils cherchent ma face. Dans leur détresse, ils me rechercheront.'),
('os',6,1,'crampon1923','Venez et retournons à Yahweh;'),
('os',6,2,'crampon1923','car c''est lui qui a déchiré, il nous guérira; il frappe mais il bandera nos plaies.'),
('os',6,3,'crampon1923','Après deux jours, il nous fera revivre; le troisième jour, il nous relèvera, et nous vivrons devant lui. Connaissons, appliquons-nous à connaître Yahweh; son lever est certain comme celui de l''aurore; et il viendra à nous comme l''ondée, comme la pluie tardive qui arrose la terre.'),
('os',6,4,'crampon1923','Que te ferai-je, Ephraïm? Que te ferai-je, Juda? Votre piété est comme une nuée du matin, comme la rosée matinale qui passe.'),
('os',6,5,'crampon1923','C''est pourquoi je les ai taillés en pièces par les prophètes; je tes ai tués par les paroles de ma bouche; ton jugement, c''est la lumière qui se lèvera.'),
('os',6,6,'crampon1923','Car je prends plaisir à la piété, et non au sacrifice: à la connaissance de Dieu, plus qu''aux holocaustes.'),
('os',6,7,'crampon1923','Mais, comme Adam, ils ont transgressé l''alliance; là, ils m''ont été infidèles.'),
('os',6,8,'crampon1923','Galaad est une ville de malfaiteurs, marquée de traces de sang.'),
('os',6,9,'crampon1923','Comme des bandits en embuscade, ainsi une troupe de prêtres assassine, sur la route de Sichem; car ils commettent la scélératesse.'),
('os',6,10,'crampon1923','Dans la maison d''Israël j''ai vu des choses horribles; c''est là qu''Ephraïm se prostitue, qu''Israël s''est souillé.'),
('os',6,11,'crampon1923','Toi aussi, Juda, une moisson t''est destinée, quand je ramènerai la captivité de mon peuple.'),
('os',7,1,'crampon1923','Quand j''ai voulu guérir Israël, alors s''est révélée l''iniquité d''Ephraïm, et la méchanceté de Samarie; car ils pratiquent le mensonge; le voleur pénètre dans la maison, le brigand se répand au dehors.'),
('os',7,2,'crampon1923','Et ils ne disent pas en leurs cœurs que je me souviens de toute leur méchanceté. Maintenant leurs forfaits les entourent, ils sont là devant moi.'),
('os',7,3,'crampon1923','Ils égaient le roi par leur méchanceté, et les princes par leurs mensonges.'),
('os',7,4,'crampon1923','Ils sont tous adultères, pareils à un four allumé par le boulanger, qui cesse d''attiser le feu, depuis qu''il a pétri la pâte jusqu''à ce qu''elle soit levée.'),
('os',7,5,'crampon1923','Au jour de notre roi, les princes se rendent malades par la chaleur du vin; il a étendu sa main avec les moqueurs.'),
('os',7,6,'crampon1923','Car, dans leur complot, ils ont mis leurs cœurs comme dans un four. Leur boulanger a dormi toute la nuit; le matin, il a été embrasé comme une flamme ardente.'),
('os',7,7,'crampon1923','Tous sont chauffés comme un four, et ils dévorent leurs juges. Tous leur rois sont tombés, sans qu''aucun d''eux ait crié vers moi.'),
('os',7,8,'crampon1923','Ephraïm se mêle avec les peuples; Ephraïm est un gâteau qu''on n''a pas retourné.'),
('os',7,9,'crampon1923','Des étrangers ont dévoré sa force, et il ne le sait pas; des cheveux blancs parsèment sa tête, et il ne le sait pas.'),
('os',7,10,'crampon1923','L''orgueil d''Ephraïm témoigne contre lui; ils ne reviennent pas à Yahweh, leur Dieu, et ils ne le recherchent pas, malgré tout cela.'),
('os',7,11,'crampon1923','Ephraïm est devenu comme une colombe, simple et sans intelligence; ils invoquent l''Egypte, ils vont en Assyrie.'),
('os',7,12,'crampon1923','Pendant qu''ils y vont, j''étends sur eux mon filet; je les ferai tomber comme les oiseaux du ciel, je les châtierai comme on l''a annoncé dans leur assemblée.'),
('os',7,13,'crampon1923','Malheur à eux, car ils ont fui loin de moi! Ruine sur eux, car ils m''ont été infidèles! Et moi, je voudrais les sauver; mais eux disent contre moi des mensonges.'),
('os',7,14,'crampon1923','Ils ne crient point vers moi dans leur cœur, quand ils se lamentent sur leurs couches. Ils se tourmentent au sujet du froment et du vin nouveau, se détournant de moi.'),
('os',7,15,'crampon1923','Moi, je les instruisais et je fortifiais leurs bras, et ils méditent le mal contre moi.'),
('os',7,16,'crampon1923','Ils se tournent, mais non pas en haut; ils sont comme un arc trompeur; leurs chefs tomberont par l''épée à cause de la fureur de leurs langues; et cela fera rire d''eux au pays d''Egypte.'),
('os',8,1,'crampon1923','A ta bouche la trompette! Comme un aigle sur la maison de Yahweh!... Parce qu''ils ont transgressé mon alliance, et péché contre ma loi.'),
('os',8,2,'crampon1923','Ils crient vers moi: " Mon Dieu! nous t''avons connu, nous, Israël! "'),
('os',8,3,'crampon1923','Israël s''est dégoûté du bien; que l''ennemi le poursuive!'),
('os',8,4,'crampon1923','Ils ont fait des rois, mais non de ma part; ils ont établi des chefs, mais que je n''ai pas connus; de leur argent et de leur or ils ont fait des idoles, pour que l''argent et l''or leur fussent ôtés.'),
('os',8,5,'crampon1923','Ton veau m''a dégoûté, Samarie; ma colère s''est enflammée contre eux; jusques à quand ne pourront-ils être purifiés?'),
('os',8,6,'crampon1923','Car il vient d''Israël, lui aussi; un ouvrier l''a fabriqué, et ce n''est pas un Dieu; car il sera mis en pièces, le veau de Samarie!'),
('os',8,7,'crampon1923','Parce qu''ils ont semé le vent, ils moissonneront la tempête. Il n''y aura pas pour lui d''épi, mais du blé qui ne donnera pas de farine; et, s''il en donne, les étrangers le dévoreront.'),
('os',8,8,'crampon1923','Israël est dévoré; maintenant ils sont devenus parmi les nations comme un objet sans valeur.'),
('os',8,9,'crampon1923','Car eux-mêmes sont montés vers Assur; L''onagre vit à l''écart; Ephraïm s''est acheté des amants.'),
('os',8,10,'crampon1923','Même s''ils font des présents aux nations, je les rassemblerai contre eux, et ils trembleront pour un peu de temps, sous le fardeau du roi des princes.'),
('os',8,11,'crampon1923','Ephraïm a multiplié les autels en péchant, et ces autels l''ont fait tomber dans le péché.'),
('os',8,12,'crampon1923','Que j''écrive pour lui mille articles de ma loi, ils sont regardés comme une chose étrangère.'),
('os',8,13,'crampon1923','Les sacrifices qu''ils m''offrent, c''est de la viande qu''ils immolent, et ils la mangent; Yahweh n''y prend point de plaisir. Maintenant il se souviendra de leur iniquité, et il punira leurs péchés; ils retourneront, eux, en Egypte.'),
('os',8,14,'crampon1923','Israël a oublié son auteur, et il a bâti des palais; et Juda a multiplié ses villes fortes. J''enverrai le feu dans ses villes, et il dévorera ses châteaux.'),
('os',9,1,'crampon1923','Ne te livre pas à la joie, Israël, à l''allégresse comme les peuples; car tu t''es prostitué loin de ton Dieu, tu as aimé le salaire de la prostituée, sur toutes les aires à blé.'),
('os',9,2,'crampon1923','Ni l''aire ni la cuve ne les nourriront, et le vin nouveau les reniera.'),
('os',9,3,'crampon1923','Ils n''habiteront pas dans la terre de Yahweh; Ephraïm retournera en Egypte, et ils mangeront en Assyrie des aliments impurs.'),
('os',9,4,'crampon1923','Ils ne feront pas à Yahweh des libations de vin, et leurs sacrifices ne lui seront pas agréables; ce sera pour eux comme un pain de deuil, ceux qui en mangeront se rendront impurs; car leur pain sera pour eux-mêmes, il n''entrera pas dans la maison de Yahweh.'),
('os',9,5,'crampon1923','Que ferez-vous au jour de solennité, au jour de la fête de Yahweh?'),
('os',9,6,'crampon1923','Car voici qu''ils sont partis devant la dévastation, l''Egypte les recueillera. Memphis les ensevelira; leurs objets précieux d''argent, le chardon s''en emparera; l''épine envahira leurs tentes.'),
('os',9,7,'crampon1923','Ils sont venus les jours du châtiment! ils sont venus les jours de la rétribution! Israël va le savoir. Le prophète est fou, l''homme de l''esprit est en délire! A cause de la grandeur de ton iniquité, et de ta grande hostilité.'),
('os',9,8,'crampon1923','La sentinelle d''Ephraïm est avec mon Dieu; le prophète trouve un filet d''oiseleur sur toutes ses voies, la persécution dans la maison de son Dieu.'),
('os',9,9,'crampon1923','Ils sont corrompus jusqu''au fond, comme aux jours de Gabaa; Yahweh se souviendra de leur iniquité, il punira leurs péchés.'),
('os',9,10,'crampon1923','Comme des raisins dans le désert, j''ai trouvé Israël; comme une primeur sur un jeune figuier, j''ai vu vos pères. Mais eux sont arrivés à Béelphégor; ils se sont consacrés à l''idole infâme, et sont devenus abominables comme l''objet de leur amour.'),
('os',9,11,'crampon1923','La gloire d''Ephraïm s''envolera comme un oiseau; plus d''enfantement, plus de grossesse, plus de conception.'),
('os',9,12,'crampon1923','Lors même qu''ils élèveraient leurs enfants, je les en priverai avant qu''ils soient devenus hommes; car malheur à eux aussi, si je me retire d''eux!'),
('os',9,13,'crampon1923','Ephraïm, quand je porte mon regard du côté de Tyr, est planté dans une belle prairie; et Ephraïm va mener ses enfants à l''égorgeur!'),
('os',9,14,'crampon1923','Donne-leur, Yahweh... que leur donneras-tu?... Donne-leur un sein stérile, et des mamelles desséchées.'),
('os',9,15,'crampon1923','Toute leur malice est a Galgal, car c''est là que je les ai pris en haine. A cause de la méchanceté de leurs actions, je les chasserai de ma maison; je n''aurai plus d''amour pour eux: tous leurs chefs sont des rebelles.'),
('os',9,16,'crampon1923','Ephraïm est frappé; sa racine est desséchée, ils ne porteront pas de fruit. Et si même ils enfantent, je ferai périr les fruits chéris de leurs entrailles.'),
('os',9,17,'crampon1923','Mon Dieu les rejettera, parce qu''ils ne l''ont pas écouté, et ils seront errants parmi les nations.'),
('os',10,1,'crampon1923','Israël est une vigne luxuriante, qui s''est chargée de fruit. Plus ses fruits étaient abondants, plus il a multiplié les autels; plus le pays était beau, plus belles ils ont fait les stèles.'),
('os',10,2,'crampon1923','Leur cœur est hypocrite: ils vont en porter la peine. Lui, il renversera leurs autels, il détruira leurs stèles.'),
('os',10,3,'crampon1923','Bientôt ils diront: " Nous n''avons plus de roi; parce que nous n''avons pas craint Yahweh; et le roi, que fera-t-il pour nous? "'),
('os',10,4,'crampon1923','Ils diront des paroles, faisant de vains serments, concluant des alliances, et le jugement éclôt comme le pavot, dans les sillons des champs.'),
('os',10,5,'crampon1923','Pour les génisses de Bethaven, les habitants de Samarie ont peur; car son peuple prend le deuil sur l''idole, et ses prêtres tremblent à son sujet, pour sa gloire qui a émigré loin de lui.'),
('os',10,6,'crampon1923','Elle aussi, on la transportera en Assyrie, comme offrande au roi vengeur; la confusion saisira Ephraïm; Israël aura honte de ses desseins.'),
('os',10,7,'crampon1923','Samarie est anéantie; son roi est comme un fétu sur la surface de l''eau.'),
('os',10,8,'crampon1923','Ils seront détruits les hauts lieux d''Aven, péché d''Israël; l''épine et la ronce monteront sur leurs autels. Ils diront aux montagnes: " Couvrez-nous! " et aux collines: " Tombez sur nous! "'),
('os',10,9,'crampon1923','Depuis les jours de Gabaa tu as péché, Israël; ils persévèrent dans le crime; ne les atteindra-t-elle pas à Gabaa, la guerre déclarée aux fils d''iniquité?'),
('os',10,10,'crampon1923','Je les châtierai à mon gré, et les peuples seront rassemblés contre eux, lorsqu''on les liera à leurs deux péchés.'),
('os',10,11,'crampon1923','Ephraïm était une génisse bien dressée, qui prenait plaisir à fouler le blé. Et moi, j''ai fait passer le joug sur son beau cou; j''attellerai Ephraïm, Juda labourera, Jacob traînera la herse.'),
('os',10,12,'crampon1923','Faites vos semences selon la justice, moissonnez selon la miséricorde, défrichez-vous des terres nouvelles; il est temps de chercher Yahweh, jusqu''à ce qu''il vienne répandre sur vous la justice.'),
('os',10,13,'crampon1923','Mais vous avez labouré la méchanceté, vous avez moissonné l''iniquité, vous avez mangé le fruit du mensonge. Tu t''es confié dans tes propres voies, dans le grand nombre de tes vaillants.'),
('os',10,14,'crampon1923','Le tumulte s''élève parmi ton peuple, et toutes tes forteresses seront dévastées, comme Salman dévasta Beth-Arbel, au jour de la guerre où la mère fut écrasée sur ses enfants.'),
('os',10,15,'crampon1923','Voilà ce que vous a fait Béthel, à cause de votre extrême méchanceté. Vienne l''aurore, et c''en est fait du roi d''Israël!'),
('os',11,1,'crampon1923','Quand Israël était enfant, je l''aimai, et dès l''Egypte, j''ai adressé des appels à mon fils.'),
('os',11,2,'crampon1923','On leur a adressé des appels et ils se sont détournés. Ils ont offert des sacrifices aux Baals, et de l''encens aux idoles.'),
('os',11,3,'crampon1923','Et moi, j''apprenais à marcher à Ephraïm, je les prenais par les bras, et ils n''ont pas compris que je les soignais.'),
('os',11,4,'crampon1923','Je les menais avec des cordeaux d''humanité, avec des liens d''amour; j''ai été pour eux comme celui qui aurait soulevé le joug de dessus leurs mâchoires, et je me penchai vers lui et je le fis manger.'),
('os',11,5,'crampon1923','Il ne retournera pas au pays d''Egypte, et Assur, lui, sera son roi, parce qu''ils n''ont pas voulu se convertir.'),
('os',11,6,'crampon1923','L''épée sera brandie dans ses villes; elle brisera les verrous et dévorera, à cause de leurs desseins.'),
('os',11,7,'crampon1923','Mon peuple est décidé à se séparer de moi; on les appelle en haut, mais aucun d''eux ne lève les yeux.'),
('os',11,8,'crampon1923','Comment te délaisserais-je, Ephraïm, te livrerais-je, Israël? Comment te laisserais-je devenir comme Adama, te rendrais-je comme Séboïm? Mon cœur se retourne en moi, et toutes ensemble, mes compassions s''émeuvent.'),
('os',11,9,'crampon1923','Je ne donnerai pas cours à l''ardeur de ma colère, je ne détruirai pas de nouveau Ephraïm. Car je suis Dieu, moi, et non pas homme: au milieu de toi est le Saint, et je ne viendrai pas dans ma fureur.'),
('os',11,10,'crampon1923','Ils iront après Yahweh; comme un lion, il rugira. Quand il rugira, lui, ses fils accourront tremblants, de l''Occident.'),
('os',11,11,'crampon1923','Ils accourront, tremblants comme un oiseau, de l''Egypte, et comme une colombe, du pays d''Assur; et je les ferai habiter dans leurs maisons, — oracle de Yahweh.'),
('os',12,1,'crampon1923','Ephraïm m''a environné de mensonge, et la maison d''Israël de tromperie; Juda aussi est sans frein vis-à-vis de Dieu, et vis-à-vis du Saint, qui est fidèle.'),
('os',12,2,'crampon1923','Ephraïm se repaît de vent, et il court après le vent d''orient. Tout le jour il accumule le mensonge et la violence; ils concluent alliance avec Assur, et l''huile est transportée en Egypte.'),
('os',12,3,'crampon1923','Yahweh a aussi procès avec Juda; il va châtier Jacob selon ses voies, il lui rendra selon ses œuvres.'),
('os',12,4,'crampon1923','Dans le sein de sa mère, Jacob supplanta son frère, et dans sa vigueur il lutta avec Dieu.'),
('os',12,5,'crampon1923','Il lutta avec l''ange et il eut le dessus; il pleura et lui demanda grâce; il le trouva ensuite à Béthel, et là Dieu a parlé avec nous.'),
('os',12,6,'crampon1923','Or Yahweh est le Dieu des armées, son nom est Yahweh.'),
('os',12,7,'crampon1923','Et toi, tu reviendras à ton Dieu; garde la bonté et la justice, et espère en ton Dieu toujours.'),
('os',12,8,'crampon1923','Chanaan tient dans sa main une balance fausse, il aime à extorquer.'),
('os',12,9,'crampon1923','Ephraïm dit: " Pourtant je me suis enrichi, je me suis fait une fortune; dans tous mes gains, on ne trouvera pas pour moi un tort qui soit un péché. "'),
('os',12,10,'crampon1923','Et moi je suis Yahweh, ton Dieu, depuis le pays d''Egypte; je te ferai encore habiter dans les tentes, comme aux jours de fête.'),
('os',12,11,'crampon1923','Et j''ai parlé aux prophètes, et moi, j''ai multiplié la vision; et, par l''intermédiaire des prophètes, j''ai parlé en paraboles.'),
('os',12,12,'crampon1923','Si Galaad est vanité, ils ne seront que néant; à Galgal, ils ont sacrifié des taureaux; aussi leurs autels seront comme des monceaux de pierres, sur les sillons des champs.'),
('os',12,13,'crampon1923','Jacob s''enfuit dans la plaine d''Aram; Israël servit pour une femme, et pour une femme il garda les troupeaux.'),
('os',12,14,'crampon1923','Et par un prophète, Yahweh fit monter Israël hors d''Egypte, et par un prophète il fut gardé.'),
('os',12,15,'crampon1923','Ephraïm a provoqué amèrement la colère divine; Il laissera tomber son sang sur lui, et son Seigneur lui rendra son outrage.'),
('os',13,1,'crampon1923','Dès qu''Ephraïm parlait, on tremblait; il s''éleva en Israël. Mais il se rendit coupable par Baal, et il mourut.'),
('os',13,2,'crampon1923','Et maintenant, ils continuent à pécher; de leur argent ils ont fait une statue de fonte, des idoles selon leur idée: œuvre d''artisans que tout cela! On dit d''eux: " Sacrificateurs d''hommes, ils baisent des veaux! "'),
('os',13,3,'crampon1923','C''est pourquoi ils seront comme une nuée du matin, et comme la rosée matinale qui se dissipe, comme la balle que le vent emporte de l''aire, et comme la fumée qui s''en va par la fenêtre.'),
('os',13,4,'crampon1923','Et moi, je suis Yahweh, ton Dieu, depuis le pays d''Egypte; tu ne connaîtras pas d''autre Dieu que moi, et en dehors de moi il n''y a pas de Sauveur.'),
('os',13,5,'crampon1923','Je t''ai connu dans le désert, dans le pays de la sécheresse.'),
('os',13,6,'crampon1923','Quand ils ont eu leur pâture, ils se sont rassasiés; ils se sont rassasiés, et leur cœur s''est élevé, et à cause de cela ils m''ont oublié.'),
('os',13,7,'crampon1923','Je serai pour eux comme un lion, comme une panthère, je les guetterai au bord du chemin.'),
('os',13,8,'crampon1923','Je fondrai sur eux comme l''ourse privée de ses petits; je déchirerai l''enveloppe de leur cœur, et je les dévorerai là comme une lionne; la bête des champs les mettra en pièces.'),
('os',13,9,'crampon1923','Ce qui te perd. Israël, c''est que tu es contre moi, contre celui qui est ton secours.'),
('os',13,10,'crampon1923','Où donc est ton roi, pour qu''il te sauve dans toutes les villes? Et où sont tes juges dont tu as dit: " Donne-moi un roi et des princes? "'),
('os',13,11,'crampon1923','Je te donne un roi dans ma colère, je te le prendrai dans ma fureur.'),
('os',13,12,'crampon1923','L''iniquité d''Ephraïm est liée, son péché est mis en réserve.'),
('os',13,13,'crampon1923','Les douleurs de l''enfantement viennent pour lui; c''est un enfant dénué de sagesse; car, le moment venu, il ne se présente pas pour naître.'),
('os',13,14,'crampon1923','Je les délivrerai de la puissance du schéol, je les rachèterai de la mort. Où est ta peste, ô mort? Où est ta destruction, ô schéol? Le repentir est caché à mes yeux.'),
('os',13,15,'crampon1923','Car Ephraïm fructifiera au milieu de ses frères! mais le vent d''orient viendra; le souffle de Yahweh montera du désert; sa source se desséchera, sa fontaine tarira; il pillera les trésors de tous les objets précieux.'),
('os',14,1,'crampon1923','Samarie sera punie, car elle s''est révoltée contre son Dieu; ils tomberont par l''épée! Leurs petits enfants seront écrasés, et l''on fendra le ventre de leurs femmes enceintes.'),
('os',14,2,'crampon1923','Reviens, Israël, à Yahweh, car tu es tombé par ton iniquité.'),
('os',14,3,'crampon1923','Prenez avec vous des paroles, et revenez à Yahweh; dites-lui: " Otez toute iniquité et prenez ce qui est bon! Que nous vous offrions, au lieu de taureaux, les paroles de nos lèvres.'),
('os',14,4,'crampon1923','Assur ne nous sauvera pas, nous ne monterons pas sur des chevaux; et nous ne dirons plus: " Notre Dieu! " à l''œuvre de nos mains. O vous, en qui l''orphelin trouve compassion!'),
('os',14,5,'crampon1923','Je guérirai leur infidélité, je les aimerai de bon cœur; car ma colère s''est retirée d''eux.'),
('os',14,6,'crampon1923','Je serai comme la rosée pour Israël; il croîtra comme le lis, il poussera ses racines comme le Liban.'),
('os',14,7,'crampon1923','Ses rejetons s''étendront, sa gloire sera comme celle de l''olivier, et son parfum comme celui du Liban.'),
('os',14,8,'crampon1923','Ceux qui viendront se reposer à son ombre feront revivre le froment; ils croîtront comme la vigne; son nom sera comme le vin du Liban.'),
('os',14,9,'crampon1923','Ephraïm... qu''aurait-il encore à faire avec les idoles? C''est moi qui lui réponds, qui le regarde; je suis comme un cyprès verdoyant; c''est de moi que procède ton fruit.'),
('os',14,10,'crampon1923','Celui qui est sage, qu''il comprenne ces choses, celui qui est intelligent, qu''il les reconnaisse! Car les voies de Yahweh sont droites; les justes y marcheront, mais les rebelles y tomberont.'),
('jl',1,1,'crampon1923','Parole de Yahweh qui fut adressée à Joël, fils de Phatuel.'),
('jl',1,2,'crampon1923','Écoutez ceci, vieillards; prêtez l''oreille, vous tous habitants du pays! Pareille chose est-elle arrivée de vos jours, ou bien dans les jours de vos pères?'),
('jl',1,3,'crampon1923','Faites-en le récit à vos enfants, et vos enfants à leurs enfants, et leurs enfants à une autre génération.'),
('jl',1,4,'crampon1923','Ce qu''a laissé le gazam, la sauterelle l''a dévoré; ce qu''a laissé la sauterelle, le yéleq l''a dévoré; ce qu''a laissé le yéleq, le chasil l''a dévoré.'),
('jl',1,5,'crampon1923','Réveillez-vous, ivrognes, et pleurez; vous tous, buveurs de vin, lamentez-vous, à cause du vin nouveau; car il vous est retiré de la bouche.'),
('jl',1,6,'crampon1923','Car un peuple est monté sur mon pays, puissant et innombrable; ses dents sont des dents de lion, et il a des mâchoires de lionne.'),
('jl',1,7,'crampon1923','Il a dévasté ma vigne, et mis en morceaux mon figuier; il les a pelés complètement et abattus; les rameaux sont devenus tout blancs.'),
('jl',1,8,'crampon1923','Désole-toi comme une vierge revêtue du sac, pour pleurer l''époux de sa jeunesse.'),
('jl',1,9,'crampon1923','Offrandes et libations ont été retranchées de la maison de Yahweh; ils sont dans le deuil les prêtres, ministres de Yahweh!'),
('jl',1,10,'crampon1923','Les champs sont ravagés, le sol est dans le deuil; car le blé est détruit, le vin nouveau est dans la confusion, l''huile languit.'),
('jl',1,11,'crampon1923','Soyez confus, laboureurs, lamentez-vous, vignerons, à cause du froment et de l''orge; car la moisson des champs est anéantie.'),
('jl',1,12,'crampon1923','La vigne est dans la confusion, et les figuiers languissent; le grenadier, et aussi le palmier et le pommier, tous les arbres des champs sont desséchés; la joie s''est retirée confuse, loin des enfants des hommes.'),
('jl',1,13,'crampon1923','Prêtres, ceignez-vous et poussez des plaintes; lamentez-vous, ministres de l''autel! Venez, passez la nuit vêtus du sac, ministres de mon Dieu; car l''offrande et la libation sont retenues loin de la maison de votre Dieu.'),
('jl',1,14,'crampon1923','Publiez un jeûne, convoquez une assemblée; réunissez les anciens, tous ceux qui habitent le pays, dans la maison de Yahweh, votre Dieu,'),
('jl',1,15,'crampon1923','et criez à Yahweh: " Ah! quel jour!... " Car le jour de Yahweh est proche! Il vient comme un ravage, de la part du Tout-Puissant!'),
('jl',1,16,'crampon1923','La nourriture n''a-t-elle pas été retranchée sous nos yeux, ainsi que la joie et l''allégresse, de la maison de notre Dieu?'),
('jl',1,17,'crampon1923','Les semences ont séché sous leurs mottes; les greniers sont vides, les magasins tombent en ruines, parce que le blé est dans la confusion.'),
('jl',1,18,'crampon1923','Comme les bêtes gémissent! Les troupeaux de bœufs sont effarés, parce qu''ils n''ont point de pâture; même les troupeaux de brebis pâtissent.'),
('jl',1,19,'crampon1923','Je crie vers vous, Yahweh; car le feu a dévoré les pâturages du désert, la flamme a brûlé tous les arbres des champs.'),
('jl',1,20,'crampon1923','Les bêtes sauvages mêmes brament après vous, parce que les courants d''eau sont à sec, et que le feu a dévoré les pâturages du désert.'),
('jl',2,1,'crampon1923','Sonnez du cor en Sion, et sonnez de la trompette sur ma sainte montagne! Que tous les habitants du pays tremblent, car le jour de Yahweh vient, car il est proche!'),
('jl',2,2,'crampon1923','Jour de ténèbres et d''obscurité, jour de nuages et de sombre nuée! Comme l''aurore qui s''étend sur les montagnes, un peuple vient, nombreux et fort, tel qu''il n''y en a jamais eu depuis l''origine, et qu''il n''y en aura pas après lui, jusqu''aux années des âges les plus lointains.'),
('jl',2,3,'crampon1923','Devant lui le feu dévore, et derrière lui la flamme brûle. Le pays est comme un jardin d''Éden devant lui, et derrière lui, c''est un désert dévasté; rien ne lui échappe.'),
('jl',2,4,'crampon1923','Son aspect est comme l''aspect des chevaux, et ils courent comme des cavaliers.'),
('jl',2,5,'crampon1923','On entend comme un bruit de chars, qui bondiraient sur les sommets des montagnes! c''est comme le bruit de la flamme de feu, qui dévore le chaume; c''est comme un peuple robuste, rangé en bataille.'),
('jl',2,6,'crampon1923','Devant lui les peuples tremblent d''effroi, tous les visages pâlissent.'),
('jl',2,7,'crampon1923','Ils courent comme des héros; ils escaladent la muraille comme des hommes de guerre; ils marchent chacun dans leurs sentiers, ils ne confondent pas leurs routes.'),
('jl',2,8,'crampon1923','Ils ne se poussent point les uns les autres, chacun va dans son chemin; ils se précipitent au travers des traits, et ils ne rompent point leurs rangs.'),
('jl',2,9,'crampon1923','Ils se répandent dans la ville, ils courent sur le mur, ils montent dans les maisons; ils entrent par les fenêtres, comme le voleur.'),
('jl',2,10,'crampon1923','Devant lui la terre tremble, les cieux s''ébranlent, le soleil et la lune s''obscurcissent, les étoiles perdent leur éclat.'),
('jl',2,11,'crampon1923','Yahweh fait entendre sa voix à la tête de son armée; car immense est son camp, car puissant est l''exécuteur de sa parole. Car le jour de Yahweh est grand et très redoutable; et qui pourrait le soutenir?'),
('jl',2,12,'crampon1923','Mais maintenant encore – oracle de Yahweh, revenez à moi de tout votre cœur, avec des jeûnes, avec des larmes et des lamentations.'),
('jl',2,13,'crampon1923','Déchirez vos cœurs, et non vos vêtements, et revenez à Yahweh, votre Dieu; car il est miséricordieux et compatissant, lent à la colère et riche en bonté, et il s''afflige du mal qu''il envoie.'),
('jl',2,14,'crampon1923','Qui sait s''il ne reviendra pas et ne se repentira pas, et s''il ne laissera pas après lui une bénédiction, l''offrande et la libation pour Yahweh, notre Dieu?'),
('jl',2,15,'crampon1923','Sonnez de la trompette en Sion, publiez un jeûne, convoquez une assemblée.'),
('jl',2,16,'crampon1923','Assemblez le peuple, publiez une sainte réunion, rassemblez les vieillards, réunissez les enfants et les nourrissons à la mamelle. Que le nouvel époux quitte sa chambre, et l''épouse son pavillon.'),
('jl',2,17,'crampon1923','Qu''entre le portique et l''autel, les prêtres, ministres de Yahweh, pleurent, et qu''ils disent: " Yahweh, épargnez votre peuple, et ne livrez pas votre héritage à l''opprobre, pour être l''objet des moqueries des nations. Pourquoi dirait-on parmi les peuples: Où est leur Dieu? "'),
('jl',2,18,'crampon1923','Yahweh a été ému de jalousie pour son pays, et il a eu pitié de son peuple.'),
('jl',2,19,'crampon1923','Yahweh a répondu et dit à son peuple: Voici que je vais vous envoyer le blé, le vin nouveau et l''huile, et vous en serez rassasiés; et je ne ferai plus de vous un sujet d''opprobre parmi les nations.'),
('jl',2,20,'crampon1923','Celui qui vient du septentrion, je l''éloignerai de vous, et je le chasserai vers une terre aride et déserte, l''avant garde vers la mer Orientale, l''arrière-garde vers la mer occidentale; il s''en élèvera une infection, et sa puanteur montera, car il a fait grand!'),
('jl',2,21,'crampon1923','Terre, ne crains pas, sois dans l''allégresse et réjouis-toi; car Yahweh a fait grand!'),
('jl',2,22,'crampon1923','Ne craignez point, bêtes des champs, car les pâturages du désert ont reverdi, car l''arbre porte son fruit, le figuier et la vigne donnent leurs richesses.'),
('jl',2,23,'crampon1923','Et vous, enfants de Sion, soyez dans l''allégresse et réjouissez-vous en Yahweh, votre Dieu; car il vous a donné le docteur pour vous enseigner la justice, et il fait descendre pour vous l''ondée, pluie d''automne et pluie du printemps, comme autrefois.'),
('jl',2,24,'crampon1923','Vos aires se rempliront de froment, et les cuves regorgeront de vin nouveau et d''huile.'),
('jl',2,25,'crampon1923','Je vous compenserai les années qu''ont dévorées la sauterelle, le yélek, le chasil et le gazam, ma grande armée, que j''avais envoyée sur vous.'),
('jl',2,26,'crampon1923','Vous mangerez abondamment et vous serez rassasiés, et vous louerez le nom de Yahweh, votre Dieu, qui a fait pour vous des merveilles; et mon peuple ne sera plus jamais confus.'),
('jl',2,27,'crampon1923','Et vous saurez que je suis au milieu d''Israël! Moi, je suis Yahweh, votre Dieu, et il n''y en a point d''autre, et mon peuple ne sera plus jamais confus!'),
('jl',3,1,'crampon1923','Et il arrivera après cela que je répandrai mon Esprit sur toute chair. Et vos fils et vos filles prophétiseront, vos vieillards auront des songes, vos jeunes gens verront des visions.'),
('jl',3,2,'crampon1923','Même sur les serviteurs et sur les servantes, en ces jours-là je répandrai mon esprit.'),
('jl',3,3,'crampon1923','Je ferai paraître des prodiges dans les cieux et sur la terre, du sang, du feu et des colonnes de fumée.'),
('jl',3,4,'crampon1923','Le soleil se changera en ténèbres, et la lune en sang, avant que vienne le jour de Yahweh, grand et terrible.'),
('jl',3,5,'crampon1923','Et quiconque invoquera le nom de Yahweh sera sauvé; car sur la montagne de Sion et de Jérusalem, il y aura une réunion de sauvés, comme l''a dit Yahweh, et parmi les survivants que Yahweh appelle!'),
('jl',4,1,'crampon1923','Car voici qu''en ces jours-là et en ce temps-là, où je ramènerai les captifs de Juda et de Jérusalem,'),
('jl',4,2,'crampon1923','j''assemblerai toutes les nations, et je les ferai descendre dans la vallée de Josaphat; et là j''entrerai en jugement avec elles, au sujet de mon peuple et de mon héritage d''Israël, qu''elles ont dispersé parmi les nations, et de mon pays qu''elles ont partagé.'),
('jl',4,3,'crampon1923','Car ils ont jeté le sort sur mon peuple, ils ont donné le jeune garçon pour une courtisane, et ils ont vendu la jeune fille pour du vin, et ils ont bu.'),
('jl',4,4,'crampon1923','Et vous aussi, qu''êtes-vous pour moi, Tyr et Sidon, et tous les districts de Philistie? Est-ce que vous tireriez de moi une vengeance? Que si vous me provoquez, je ferai vite, promptement retomber votre provocation sur votre tête;'),
('jl',4,5,'crampon1923','vous qui avez pris mon argent et mon or, et qui avez emporté dans vos temples mes joyaux les plus précieux;'),
('jl',4,6,'crampon1923','vous qui avez vendu aux fils de Javan, les fils de Juda et les fils de Jérusalem, pour qu''on les éloigne de leur pays!'),
('jl',4,7,'crampon1923','Voici que je vais les faire lever du lieu où vous les avez vendus, et je ferai retomber votre provocation sur votre tête.'),
('jl',4,8,'crampon1923','Je vendrai vos fils et vos filles aux mains des enfants de Juda, qui les vendront aux Sabéens, à un peuple lointain; car Yahweh a parlé.'),
('jl',4,9,'crampon1923','Publiez ceci parmi les nations: Préparez la guerre! Faites lever les vaillants! Qu''ils s''approchent, qu''ils montent, tous les hommes de guerre!'),
('jl',4,10,'crampon1923','De vos socs forgez des épées, et de vos serpes des lances; que le faible dise: " Je suis un brave! "'),
('jl',4,11,'crampon1923','Hâtez-vous et venez, vous toutes, nations d''alentour, et rassemblez-vous! Là même, Yahweh, faites descendre vos braves!'),
('jl',4,12,'crampon1923','Que les nations se lèvent et qu''elles montent à la vallée de Josaphat! Car c''est là que je siégerai pour juger toutes les nations d''alentour.'),
('jl',4,13,'crampon1923','Mettez la faucille, car la moisson est mûre; venez, foulez, car le pressoir est rempli; les cuves regorgent, car leur méchanceté est grande.'),
('jl',4,14,'crampon1923','Des foules, des foules dans la vallée de la décision!'),
('jl',4,15,'crampon1923','Le soleil et la lune se sont obscurcis, et les étoiles ont perdu leur éclat.'),
('jl',4,16,'crampon1923','De Sion Yahweh rugira, de Jérusalem il fera entendre sa voix; les cieux et la terre trembleront. Mais Yahweh sera un refuge pour son peuple, une retraite pour les enfants d''Israël.'),
('jl',4,17,'crampon1923','Et vous saurez que je suis Yahweh, votre Dieu, qui habite Sion, ma montagne sainte; Jérusalem sera un sanctuaire, et les étrangers n''y passeront plus.'),
('jl',4,18,'crampon1923','En ce jour-là, les montagnes dégoutteront de vin nouveau, les collines ruisselleront de lait, et tous les torrents de Juda ruisselleront d''eau. Une source sortira de la maison de Yahweh, et elle arrosera la vallée des Acacias.'),
('jl',4,19,'crampon1923','L''Egypte deviendra une terre dévastée, Edom un désert de dévastation, à cause des violences commises contre les enfants de Juda, parce qu''ils ont répandu dans leur pays le sang innocent.'),
('jl',4,20,'crampon1923','Mais Juda sera habité éternellement, et Jérusalem d''âge en âge.'),
('jl',4,21,'crampon1923','Et je laverai leur sang que je n''avais pas encore lavé. Et Yahweh habitera en Sion.'),
('am',1,1,'crampon1923','Paroles d''Amos, qui fut parmi les bergers de Thécué. Ce qu''il a vu au sujet d''Israël, dans les jours d''Ozias, roi de Juda, et dans les jours de Jéroboam, fils de Joas, roi d''Israël, deux ans avant le tremblement de terre.'),
('am',1,2,'crampon1923','Il dit: Yahweh rugira de Sion; de Jérusalem il fera entendre sa voix; les pâturages des bergers seront en deuil, et le sommet du Carmel sera desséché.'),
('am',1,3,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes de Damas, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils ont broyé Galaad avec des traîneaux de fer,'),
('am',1,4,'crampon1923','j''enverrai le feu dans la maison d''Hazaël, et il dévorera les palais de Ben-Hadad;'),
('am',1,5,'crampon1923','je briserai le verrou de Damas, j''exterminerai de Biqath-Aven l''habitant, et de Beth-Eden, celui qui tient le sceptre; et le peuple de Syrie ira captif à Qir, dit Yahweh.'),
('am',1,6,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes de Gaza, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils ont déporté des convois entiers de captifs, pour les livrer à Edom,'),
('am',1,7,'crampon1923','j''enverrai le feu dans les murs de Gaza, et il dévorera ses palais;'),
('am',1,8,'crampon1923','j''exterminerai d''Azot l''habitant, et d''Ascalon celui qui tient le sceptre, et je tournerai ma main sur Accaron; et le reste des Philistins périra, dit le Seigneur Yahweh.'),
('am',1,9,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes de Tyr, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils ont livré des convois entiers de captifs à Edom, et ne se sont pas souvenus de l''alliance fraternelle,'),
('am',1,10,'crampon1923','j''enverrai le feu sur le mur de Tyr, et il dévorera ses palais.'),
('am',1,11,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes d''Edom, et à cause de quatre, — je ne le révoquerai point. Parce qu''il a poursuivi son frère avec le glaive, et qu''il a étouffé sa compassion, et parce que sa colère déchire à jamais, et qu''il garde jusqu''à la fin sa rancune,'),
('am',1,12,'crampon1923','j''enverrai le feu dans Théman, et il dévorera les palais de Bosra.'),
('am',1,13,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes des enfants d''Ammon, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils ont fendu le ventre des femmes enceintes de Galaad, afin d''élargir leur frontière,'),
('am',1,14,'crampon1923','j''allumerai un feu sur le mur de Rabbah, et il dévorera ses palais, au milieu des cris de guerre d''un jour de bataille, au milieu du tourbillon d''un jour de tempête.'),
('am',1,15,'crampon1923','Et leur roi s''en ira en captivité, lui et ses princes avec lui, dit Yahweh.'),
('am',2,1,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes de Moab, et à cause de quatre, — je ne le révoquerai point. Parce qu''il à brûlé les os du roi d''Edom jusqu''à les calciner,'),
('am',2,2,'crampon1923','j''enverrai le feu dans Moab, et il dévorera les palais de Carioth; et Moab mourra au milieu du tumulte, des cris de guerre, du son de la trompette.'),
('am',2,3,'crampon1923','J''exterminerai de son sein le Juge, et j''égorgerai avec lui tous ses princes, dit Yahweh.'),
('am',2,4,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes de Juda, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils ont rejeté la loi de Yahweh, et qu''ils n''ont pas gardé ses ordonnances, et que leurs idoles de mensonge les ont égarés, celles que leurs pères avaient suivies,'),
('am',2,5,'crampon1923','j''enverrai le feu en Juda, et il dévorera les palais de Jérusalem.'),
('am',2,6,'crampon1923','Ainsi parle Yahweh: A cause de trois crimes d''Israël, et à cause de quatre, — je ne le révoquerai point. Parce qu''ils vendent le juste à prix d''argent, et l''indigent à cause d''une paire de sandales;'),
('am',2,7,'crampon1923','parce qu''ils aspirent à voir la poussière de la terre sur la tête des misérables, et qu''ils font fléchir la voie des petits; parce que le fils et son père vont vers la même fille, pour profaner mon saint nom;'),
('am',2,8,'crampon1923','parce qu''ils s''étendent sur des vêtements reçus en gage, à côté de tous les autels, et qu''ils boivent le vin de ceux qu''ils ont frappés d''amende, dans la maison de leur Dieu.'),
('am',2,9,'crampon1923','Et pourtant j''avais détruit devant eux l''Amorrhéen, dont la hauteur était comme celle des cèdres, et qui était fort comme les chênes; j''avais détruit son fruit en haut, et ses racines en bas.'),
('am',2,10,'crampon1923','Et pourtant je vous avais fait monter du pays d''Egypte, et je vous avais conduits quarante ans dans le désert, pour vous mettre en possession du pays de l''Amorrhéen.'),
('am',2,11,'crampon1923','J''avais suscité parmi vos fils des prophètes, et parmi vos jeunes gens des nazaréens, — n''en est-il pas ainsi, enfants d''Israël? — oracle de Yahweh.'),
('am',2,12,'crampon1923','Mais vous avez fait boire du vin aux nazaréens et vous avez donné cet ordre aux prophètes: " Ne prophétisez pas "!'),
('am',2,13,'crampon1923','Voici que je vais vous fouler, comme foule la terre un chariot, quand il est rempli de gerbes.'),
('am',2,14,'crampon1923','La fuite manquera à l''homme agile, et le vigoureux ne trouvera plus sa force; et le vaillant ne sauvera pas sa vie,'),
('am',2,15,'crampon1923','et celui qui manie l''arc ne résistera pas; et l''homme aux pieds agiles ne se sauvera pas, et le cavalier ne sauvera pas sa vie.'),
('am',2,16,'crampon1923','Et le plus courageux d''entre les braves s''enfuira tout nu en ce jour-là, — oracle de Yahweh.'),
('am',3,1,'crampon1923','Ecoutez cette parole que Yahweh a prononcée sur vous, enfants d''Israël, " sur toute la famille que j''ai fait monter du pays d''Egypte ", — en ces termes:'),
('am',3,2,'crampon1923','Je n''ai connu que vous seuls parmi toutes les familles de la terre; c''est pourquoi je vous punirai de toutes vos iniquités.'),
('am',3,3,'crampon1923','Deux hommes marchent-ils ensemble, sans qu''ils se soient accordés?'),
('am',3,4,'crampon1923','Le lion rugit-il dans la forêt, sans avoir une proie? Le lionceau fait-il retentir sa voix du fond de sa tanière, sans qu''il ait rien pris?'),
('am',3,5,'crampon1923','Le passereau tombe-t-il dans le filet à terre, sans qu''il y ait un appât pour lui! Le filet se lève-t-il du sol, sans qu''il ait pris quelque chose?'),
('am',3,6,'crampon1923','Sonne-t-on de la trompette dans une ville, sans que le peuple s''épouvante? Arrive-t-il un malheur dans une ville, sans que Yahweh en soit l''auteur?'),
('am',3,7,'crampon1923','Car le Seigneur Yahweh ne fait rien sans qu''il ait révélé son secret à ses serviteurs, les prophètes.'),
('am',3,8,'crampon1923','Le lion a rugi: qui ne craindrait? Le Seigneur Yahweh a parlé: qui ne prophétiserait?'),
('am',3,9,'crampon1923','Faites entendre cette parole sur les palais dans Azot, et sur les palais dans la terre d''Egypte, et dites: Rassemblez-vous sur les montagnes de Samarie, et voyez quels nombreux désordres sont au milieu d''elle, et quelles violences dans son sein.'),
('am',3,10,'crampon1923','Et ils ne savent pas agir avec droiture, — oracle de Yahweh, eux qui entassent la violence et le pillage dans leurs palais.'),
('am',3,11,'crampon1923','C''est pourquoi ainsi parle le Seigneur Yahweh: Voici l''ennemi, il enserre le pays; il te dépouillera de ta force, et tes palais seront pillés.'),
('am',3,12,'crampon1923','Ainsi parle Yahweh: Comme le berger arrache de la gueule du lion deux jarrets ou un bout d''oreille, ainsi seront sauvés les enfants d''Israël, qui sont assis à Samarie, au coin d''un divan, sur des coussins de Damas.'),
('am',3,13,'crampon1923','Écoutez, et attestez ceci dans la maison de Jacob, — oracle du Seigneur Yahweh, le Dieu des armées:'),
('am',3,14,'crampon1923','Le jour où je vengerai sur lui les transgressions d''Israël, je vengerai aussi les autels de Béthel; les cornes de l''autel seront brisées, et elles tomberont à terre.'),
('am',3,15,'crampon1923','Je frapperai la maison d''hiver, avec la maison d''été; les maisons d''ivoire seront dévastées, et de nombreuses maisons seront détruites, — oracle de Yahweh.'),
('am',4,1,'crampon1923','Écoutez cette parole, vaches de Basan, qui êtes sur la montagne de Samarie, vous qui opprimez les faibles, et qui foulez les indigents, vous qui dites à vos maris: " Apportez et buvons! "'),
('am',4,2,'crampon1923','Le Seigneur Yahweh a juré par sa sainteté: Voici que des jours viendront sur vous où l''on vous enlèvera avec des crocs, et votre postérité avec des harpons.'),
('am',4,3,'crampon1923','Vous sortirez par les brèches, chacune devant soi, et vous serez jetées en Armon, — oracle de Yahweh.'),
('am',4,4,'crampon1923','Venez à Béthel et péchez, à Galgala, et multipliez vos péchés! Amenez chaque matin vos sacrifices, et tous les trois jours vos dîmes!'),
('am',4,5,'crampon1923','Faites fumer l''oblation de louange sans levain; annoncez des dons volontaires, publiez-les! Car c''est cela que vous aimez, enfants d''Israël, — oracle du Seigneur Yahweh.'),
('am',4,6,'crampon1923','Aussi je vous ai procuré la netteté des dents en toutes vos villes, et la disette de pain dans toutes vos demeures; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('am',4,7,'crampon1923','Aussi je vous ai retenu la pluie, lorsqu''il y avait encore trois mois avant la moisson; j''ai fait pleuvoir sur une ville, et je ne faisais pas pleuvoir sur une autre ville; une région était arrosée par la pluie, et une autre région, sur laquelle il ne pleuvait pas, se desséchait.'),
('am',4,8,'crampon1923','Deux, trois villes couraient à une autre ville, pour boire de l''eau, et ne se désaltéraient pas; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('am',4,9,'crampon1923','Je vous ai frappés par la rouille et la nielle; vos nombreux jardins, vos vignes, vos figuiers et vos oliviers, la sauterelle les a dévorés; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('am',4,10,'crampon1923','J''ai envoyé parmi vous la peste, à la manière d''Egypte; j''ai tué par l''épée vos jeunes gens, pendant que vos chevaux étaient capturés; j''ai fait monter la puanteur de votre camp, et elle est arrivée à vos narines; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('am',4,11,'crampon1923','J''ai causé en vous des bouleversements, comme Dieu a bouleversé Sodome et Gomorrhe, et vous avez été comme un tison arraché de l''incendie; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('am',4,12,'crampon1923','C''est pourquoi, ainsi te ferai-je, Israël! Puisque je te ferai cela, prépare-toi à la rencontre de ton Dieu, Israël!'),
('am',4,13,'crampon1923','Car c''est lui qui a formé les montagnes, et qui a créé le vent, qui fait connaître à l''homme quelle est sa pensée, qui fait de l''aurore les ténèbres, et qui marche sur les sommets de la terre! Yahweh, le Dieu des armées, est son nom.'),
('am',5,1,'crampon1923','Écoutez cette parole, que je profère sur vous, — une lamentation, — maison d''Israël:'),
('am',5,2,'crampon1923','Elle est tombée, elle ne se relèvera plus, la vierge d''Israël! Elle est renversée sur sa terre, personne ne la relèvera.'),
('am',5,3,'crampon1923','Car ainsi parle Yahweh: La ville qui se mettait en campagne avec mille guerriers en gardera cent; celle qui se mettait en campagne avec cent en gardera dix, pour la maison d''Israël.'),
('am',5,4,'crampon1923','Car ainsi parle Yahweh à la maison d''Israël: Cherchez-moi et vivez!'),
('am',5,5,'crampon1923','Ne cherchez pas Béthel, ne venez pas à Galgala, ne passez pas à Bersabée! Car Galgala sera emmené captif, et Béthel deviendra néant.'),
('am',5,6,'crampon1923','Cherchez Yahweh et vivez, de peur qu''il ne fonde, comme un feu, sur la maison de Joseph, et ne la dévore, sans que Béthel ait personne pour éteindre.'),
('am',5,7,'crampon1923','Ils changent le droit en absinthe, et jettent à terre la justice!'),
('am',5,8,'crampon1923','Il a fait les Pléiades et Orion; il change en aurore les ténèbres, et le jour en une nuit obscure; il appelle les eaux de la mer, et les répand sur la face de la terre; Yahweh est son nom.'),
('am',5,9,'crampon1923','Il fait éclater la ruine sur le puissant, et la ruine fond sur la ville forte.'),
('am',5,10,'crampon1923','Ils haïssent à la Porte celui qui censure; et celui qui parle avec intégrité, ils l''ont en horreur.'),
('am',5,11,'crampon1923','C''est pourquoi, parce que vous foulez aux pieds le pauvre, et que vous prélevez sur lui un tribut de blé; vous avez bâti des maisons en pierres de taille, et vous n''y habiterez pas, vous avez planté des vignes excellentes, et vous n''en boirez pas le vin.'),
('am',5,12,'crampon1923','Car je sais que nombreux sont vos crimes, que grands sont vos péchés, vous qui opprimez le juste, qui prenez des présents, et qui faites fléchir le droit des pauvres à la Porte.'),
('am',5,13,'crampon1923','C''est pourquoi l''homme sage, en ce temps-ci, se tait; car c''est un temps mauvais.'),
('am',5,14,'crampon1923','Cherchez le bien et non le mal, afin que vous viviez, et qu''ainsi Yahweh, le Dieu des armées, soit avec vous, comme vous le dites.'),
('am',5,15,'crampon1923','Haïssez le mal et aimez le bien, et restaurez le droit à la Porte: peut-être Yahweh, le Dieu des armées, aura-t-il pitié du reste de Joseph!'),
('am',5,16,'crampon1923','C''est pourquoi ainsi parle Yahweh, le Dieu des armées, le Seigneur: Dans toutes les places, on se lamentera; dans toutes les rues on dira: Hélas! hélas! On appellera le laboureur au deuil, et aux lamentations, avec ceux qui savent gémir.'),
('am',5,17,'crampon1923','Dans toutes les vignes on se lamentera; car je passerai au milieu de toi, dit Yahweh.'),
('am',5,18,'crampon1923','Malheur à ceux qui désirent le jour de Yahweh! Que sera-t-il pour vous, le jour de Yahweh? Il sera ténèbres, et non lumière.'),
('am',5,19,'crampon1923','Comme un homme qui s''enfuit devant le lion, et l''ours vient à sa rencontre; il entre dans sa maison, appuie sa main sur le mur, et le serpent le mord!...'),
('am',5,20,'crampon1923','N''est-il pas ténèbres, le jour de Yahweh, et non lumière, obscurité, sans aucun éclat?'),
('am',5,21,'crampon1923','Je hais, je dédaigne vos fêtes, je n''ai aucun goût à vos assemblées.'),
('am',5,22,'crampon1923','Si vous m''offrez vos holocaustes et vos oblations, je n''y prends pas plaisir, et vos sacrifices de veaux engraissés, je ne les regarde pas.'),
('am',5,23,'crampon1923','Éloigne de moi le bruit de tes cantiques; que je n''entende pas le son de tes harpes!'),
('am',5,24,'crampon1923','Mais que le jugement coule comme l''eau, et la justice comme un torrent qui ne tarit pas!'),
('am',5,25,'crampon1923','Des sacrifices et des oblations m''en avez-vous offert, dans le désert pendant quarante ans, maison d''Israël?'),
('am',5,26,'crampon1923','Vous avez porté la tente de votre roi, et Kijoum, vos idoles, l''étoile de votre dieu, que vous vous êtes fabriqué.'),
('am',5,27,'crampon1923','Je vous déporterai par delà Damas, dit Yahweh; Dieu des armées est son nom.'),
('am',6,1,'crampon1923','Malheur à ceux qui vivent tranquilles dans Sion, et en sécurité sur la montagne de Samarie, les plus nobles du premier des peuples, auprès desquels va la maison d''Israël!'),
('am',6,2,'crampon1923','Passez à Calné et voyez; allez de là à Hamath la grande; descendez à Geth des Philistins; Ces villes sont-elles plus prospères que ces royaumes, et leur territoire est-il plus étendu que le vôtre?'),
('am',6,3,'crampon1923','Vous éloignez le jour du malheur, et vous faites approcher le règne de la violence!'),
('am',6,4,'crampon1923','Ils sont couchés sur des lits d''ivoire, et s''étendent sur leurs divans; ils mangent les agneaux du troupeau, et les veaux engraissés dans l''étable.'),
('am',6,5,'crampon1923','Ils folâtrent au son de la harpe; comme David, ils ont inventé des instruments de musique.'),
('am',6,6,'crampon1923','Ils boivent le vin dans de larges coupes, ils se parfument avec les huiles les plus exquises. Et ils ne sont pas malades de la plaie de Joseph.'),
('am',6,7,'crampon1923','C''est pourquoi ils iront en exil, à la tête des captifs, et les cris de joie des voluptueux disparaîtront.'),
('am',6,8,'crampon1923','Le Seigneur Yahweh l''a juré par lui-même, — oracle de Yahweh, le Dieu des armées: J''ai en abomination l''orgueil de Jacob, et je hais ses palais; je livrerai la ville et ce qu''elle renferme.'),
('am',6,9,'crampon1923','Et s''il reste dix hommes dans une seule maison, ils mourront.'),
('am',6,10,'crampon1923','Un parent avec celui qui brûle les cadavres enlèvera le mort, et emportera de la maison les ossements; et l''un dira à celui qui est au fond de la maison: " Y en a-t-il encore avec toi? " Il répondra: " Plus personne! " Et le premier dira: " Silence! " Car il ne faut pas prononcer le nom de Yahweh.'),
('am',6,11,'crampon1923','Car voici que Yahweh commande, et il fait tomber en ruines la grande maison, et en débris la petite maison.'),
('am',6,12,'crampon1923','Les chevaux courent-ils sur le rocher, où y laboure-t-on avec des bœufs, que vous avez changé le droit en poison, et le fruit de la justice en absinthe?'),
('am',6,13,'crampon1923','Vous vous réjouissez de ce qui n''est rien, vous dites: " N''est-ce pas par notre force que nous avons acquis de la puissance? "'),
('am',6,14,'crampon1923','Car voici que je suscite contre vous, maison d''Israël, — oracle de Yahweh, le Dieu des armées! — une nation qui vous opprimera depuis l''entrée de Hamath jusqu''au torrent du désert.'),
('am',7,1,'crampon1923','Ainsi me fit voir le Seigneur Yahweh, et voici qu''il formait des sauterelles, au commencement de la pousse des regains; c''était le regain après la coupe du roi.'),
('am',7,2,'crampon1923','Quand elles eurent achevé de dévorer l''herbe de la terre, je dis: " Seigneur Yahweh, daignez pardonner! Comment Jacob tiendra-t-il? Car il est petit. "'),
('am',7,3,'crampon1923','Et Yahweh se repentit de cela: " Cela ne sera pas ", dit Yahweh.'),
('am',7,4,'crampon1923','Ainsi me fit voir le Seigneur Yahweh, et voici que le Seigneur Yahweh venait châtier par le feu, et le feu dévorait le grand abîme, et il dévorait la portion du Seigneur.'),
('am',7,5,'crampon1923','Et je dis: " Seigneur Yahweh, daignez cesser! Comment Jacob tiendra-t-il? Car il est petit. "'),
('am',7,6,'crampon1923','Yahweh se repentit: " Cela non plus ne sera pas ", dit le Seigneur Yahweh.'),
('am',7,7,'crampon1923','Ainsi me fit voir Yahweh, et voici que le Seigneur se tenait sur un mur vertical, et il avait dans sa main un fil à plomb.'),
('am',7,8,'crampon1923','Et Yahweh me dit: " Que vois-tu, Amos? " Je répondis: " Un fil à plomb. " Et le Seigneur me dit: " Voici que je mets le fil à plomb au milieu de mon peuple d''Israël; je ne lui pardonnerai pas plus longtemps.'),
('am',7,9,'crampon1923','Les hauts lieux d''Isaac seront dévastés, et les sanctuaires d''Israël seront détruits, et je me lèverai contre la maison de Jéroboam, avec l''épée. "'),
('am',7,10,'crampon1923','Et Amasias, prêtre de Béthel, envoya dire à Jéroboam, roi d''Israël: " Amos conspire contre toi au milieu de la maison d''Israël; le pays ne peut plus supporter toutes ses paroles.'),
('am',7,11,'crampon1923','Car Amos a parlé ainsi: Jéroboam mourra par l''épée, et Israël sera emmené captif hors de son pays. "'),
('am',7,12,'crampon1923','Et Amasias dit à Amos: " Voyant, va-t-en, fuis au pays de Juda, et manges-y ton pain; là tu prophétiseras.'),
('am',7,13,'crampon1923','Mais ne continue pas de prophétiser à Béthel, car c''est un sanctuaire du roi, et c''est une maison royale ".'),
('am',7,14,'crampon1923','Amos répondit et dit à Amasias: " Je ne suis pas un prophète, je ne suis pas un fils de prophète; je suis bouvier et je cultive les sycomores.'),
('am',7,15,'crampon1923','Et Yahweh m''a pris derrière le troupeau, et Yahweh m''a dit: Va, prophétise à mon peuple d''Israël.'),
('am',7,16,'crampon1923','Et maintenant, écoute la parole de Yahweh: Tu dis: Tu ne prophétiseras pas contre Israël, et tu ne parleras pas contre la maison d''Isaac!...'),
('am',7,17,'crampon1923','C''est pourquoi ainsi parle Yahweh: Ta femme sera prostituée dans la ville, tes fils et tes filles tomberont par l''épée, ta terre sera partagée au cordeau; et toi, tu mourras sur une terre impure, et Israël sera emmené captif hors de sa terre. "'),
('am',8,1,'crampon1923','Ainsi me fit voir le Seigneur Yahweh, et voici une corbeille de fruits mûrs.'),
('am',8,2,'crampon1923','Et il dit: " Que vois-tu, Amos? " Je répondis: " Une corbeille de fruits mûrs. " Et Yahweh me dit: " La fin est venue pour mon peuple d''Israël; je ne lui pardonnerai pas plus longtemps.'),
('am',8,3,'crampon1923','Les chants du palais seront des hurlements en ce jour-là, — oracle du Seigneur Yahweh. Il y aura de nombreux cadavres, en tout lieu on les jette en silence. "'),
('am',8,4,'crampon1923','Écoutez ceci, vous qui engloutissez le pauvre, et qui voudriez faire disparaître les humbles du pays,'),
('am',8,5,'crampon1923','en disant: " Quand la nouvelle lune sera-t-elle passée, afin que nous puissions vendre du froment, et le sabbat, pour que nous ouvrions nos magasins à blé, en diminuant l''épha et en grossissant le sicle, en faussant la balance pour tromper?'),
('am',8,6,'crampon1923','Nous achèterons pour de l''argent les misérables, et les pauvres à cause d''une paire de sandales, et nous vendrons la criblure du froment? "'),
('am',8,7,'crampon1923','Yahweh l''a juré par l''orgueil de Jacob: Je n''oublierai pas jusqu''à la fin toutes leurs actions.'),
('am',8,8,'crampon1923','A cause de cela, la terre ne tremblera-t-elle pas, et tous ses habitants ne seront-ils pas dans le deuil? Elle montera tout entière comme le Nil, elle se soulèvera et s''affaissera, comme le Nil d''Egypte.'),
('am',8,9,'crampon1923','Il arrivera en ce jour-là, — oracle du Seigneur Yahweh, je ferai coucher le soleil en plein midi, et j''envelopperai la terre de ténèbres en un jour serein.'),
('am',8,10,'crampon1923','Je changerai vos fêtes en deuil, et tous vos chants de joie en lamentations; je mettrai le sac sur tous les reins, et je rendrai chauve toute tête; je mettrai le pays comme en un deuil de fils unique, et sa fin sera comme un jour amer.'),
('am',8,11,'crampon1923','Voici que des jours viennent, — oracle du Seigneur Yahweh, et j''enverrai une faim sur la terre, non une faim de pain, et non une soif d''eau, mais d''entendre les paroles de Yahweh.'),
('am',8,12,'crampon1923','Et ils erreront d''une mer à l''autre, et du septentrion à l''orient; ils iront de côté et d''autre pour chercher la parole de Yahweh, et ils ne la trouveront pas.'),
('am',8,13,'crampon1923','En ces jours-là seront épuisés les belles vierges et les jeunes hommes, par la soif.'),
('am',8,14,'crampon1923','Ceux qui jurent par le péché de Samarie et disent: " Par la vie de ton Dieu, ô Dan! Par la voie de Bersabée! " tomberont et ne se relèveront pas.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('am',9,1,'crampon1923','Je vis le Seigneur debout près de l''autel, et il dit: " Frappe le chapiteau, et que les seuils soient ébranlés, et brise-les sur leurs têtes à tous! Et ce qui restera, je l''égorgerai par l''épée; pas un ne se sauvera, pas un n''échappera.'),
('am',9,2,'crampon1923','S''ils pénètrent jusqu''au schéol, ma main les en retirera; s''ils montent aux cieux, je les en ferai descendre.'),
('am',9,3,'crampon1923','S''ils se cachent au sommet du Carmel, je les y chercherai et les prendrai; et s''ils se dérobent à mes yeux au fond de la mer, là je commanderai au serpent de les mordre.'),
('am',9,4,'crampon1923','Et s''ils s''en vont en captivité devant leurs ennemis, là je commanderai à l''épée de les égorger. Et je fixerai mon œil sur eux, pour le malheur et non pour le bien. "'),
('am',9,5,'crampon1923','Le Seigneur Yahweh des armées, touche la terre et elle se fond, et tous ses habitants sont en deuil; elle monte tout entière comme le Nil, et s''affaisse comme le fleuve d''Egypte.'),
('am',9,6,'crampon1923','Il construit ses degrés dans le ciel, et fonde sa voûte sur la terre; il appelle les eaux de la mer, et il les répand sur la face de la terre: Yahweh est son nom.'),
('am',9,7,'crampon1923','N''êtes-vous pas pour moi comme les fils des Cuschites, enfants d''Israël, — oracle de Yahweh? N''ai-je pas fait monter Israël du pays d''Egypte, et les Philistins de Caphtor, et les Syriens de Qir?'),
('am',9,8,'crampon1923','Voici que les yeux du Seigneur Yahweh sont fixés sur le royaume pécheur, et je le détruirai de dessus la face de la terre; toutefois je ne détruirai pas entièrement la maison de Jacob, — oracle de Yahweh.'),
('am',9,9,'crampon1923','Car voici que je vais donner des ordres, et je secouerai la maison d''Israël parmi toutes les nations, comme on secoue le blé avec le crible, et le bon grain ne tombera pas à terre.'),
('am',9,10,'crampon1923','Tous les pécheurs de mon peuple périront par l''épée, eux qui disent: " Le malheur ne s''approchera pas de nous, le malheur ne nous atteindra pas. "'),
('am',9,11,'crampon1923','En ce jour-là, je relèverai la hutte de David qui est tombée; je réparerai ses brèches, je relèverai ses ruines, et je la rebâtirai telle qu''aux jours d''autrefois,'),
('am',9,12,'crampon1923','afin qu''ils possèdent le reste d''Edom, et toutes les nations sur lesquelles mon nom a été invoqué, — oracle de Yahweh, qui fait ces choses.'),
('am',9,13,'crampon1923','Voici que des jours viennent, — oracle de Yahweh, et le laboureur joindra le moissonneur, et celui qui foule les grappes joindra celui qui répand la semence; les montagnes dégoutteront de vin nouveau, et toutes les collines ruisselleront.'),
('am',9,14,'crampon1923','Je ramènerai les captifs de mon peuple d''Israël; ils bâtiront les villes dévastées et les habiteront, ils planteront les vignes et en boiront le vin, ils feront des jardins et en mangeront les fruits.'),
('am',9,15,'crampon1923','Et je les planterai sur leur sol, et ils ne seront plus jamais arrachés de leur terre, que je leur ai donnée, dit Yahweh, ton Dieu.'),
('ab',1,1,'crampon1923','Vision d''Abdias. Ainsi a dit le Seigneur Yahweh à Edom: — Nous avons reçu de Yahweh un message, et un héraut a été envoyé parmi les nations: " Debout! Levons-nous contre lui pour combattre! " —'),
('ab',1,2,'crampon1923','Voici que je t''ai rendu petit parmi les nations, tu es l''objet du plus grand mépris.'),
('ab',1,3,'crampon1923','La fierté de ton cœur t''a égaré! Lui qui habite dans des creux de rochers, dont les hauteurs sont la demeure, il dit dans son cœur: " Qui me fera descendre à terre? "'),
('ab',1,4,'crampon1923','Quand tu t''élèverais aussi haut que l''aigle, que tu placerais ton aire parmi les étoiles, je t''en ferais descendre, — oracle de Yahweh.'),
('ab',1,5,'crampon1923','Si des voleurs étaient entrés chez toi, des pillards de nuit, — comme te voilà dévasté! — n''auraient-ils pas emporté que ce qui leur suffisait? Si des vendangeurs étaient entrés chez toi, n''auraient-ils rien laissé à grappiller?'),
('ab',1,6,'crampon1923','Comme Esaü a été fouillé, comme On a cherché ses trésors cachés!'),
('ab',1,7,'crampon1923','Ils t''ont chassé jusqu''à la frontière, tous tes alliés; ils t''ont joué, ils ont prévalu sur toi, ceux qui jouissaient de ton amitié; ceux qui mangeaient ton pain ont mis un piège sous tes pas. Il n''y a point en lui d''intelligence!'),
('ab',1,8,'crampon1923','Est-ce qu''en ce jour-là, — oracle de Yahweh, je n''ôterai pas d''Edom les sages, et de la montagne d''Esaü l''intelligence?'),
('ab',1,9,'crampon1923','Tes guerriers, ô Théman, seront dans l''épouvante, afin que tout homme soit retranché de la montagne d''Esaü.'),
('ab',1,10,'crampon1923','A cause du massacre, à cause de la violence contre ton frère Jacob, la honte te couvrira, et tu seras retranché à jamais.'),
('ab',1,11,'crampon1923','Au jour où tu te tenais en face de lui, au jour où des ennemis emmenaient son armée, et où des étrangers pénétraient dans ses portes, et jetaient le sort sur Jérusalem, toi aussi, tu étais comme l''un d''eux!'),
('ab',1,12,'crampon1923','Ne repais pas ta vue du jour de ton frère, au jour de son infortune; ne te réjouis pas au sujet des enfants de Juda, au jour de leur ruine; et ne profère pas d''insolentes paroles, au jour de la détresse.'),
('ab',1,13,'crampon1923','N''entre pas dans la porte de mon peuple; au jour de leur calamité; ne repais pas ta vue, toi aussi, de son malheur, au jour de sa calamité; et n''étends pas ta main sur ses richesses, au jour de sa calamité.'),
('ab',1,14,'crampon1923','Ne te tiens pas au carrefour des chemins, pour massacrer ses fuyards; ne livre pas ses réchappés, au jour de la détresse.'),
('ab',1,15,'crampon1923','Car il est proche le jour de Yahweh, pour toutes les nations; comme tu as fait, il te sera fait; ton œuvre retombera sur ta tête.'),
('ab',1,16,'crampon1923','Car, de même que vous avez bu sur ma sainte montagne, toutes les nations boiront continuellement; elles boiront, elles avaleront, et elles seront comme n''ayant pas été.'),
('ab',1,17,'crampon1923','Mais sur la montagne de Sion il y aura des réchappés; elle sera un lieu saint, et la maison de Jacob rentrera dans ses possessions.'),
('ab',1,18,'crampon1923','La maison de Jacob sera un feu, la maison de Joseph une flamme, et la maison d''Esaü sera réduite à être du chaume. Celles-là l''allumeront et le dévoreront, et il n''y aura pas de survivant pour la maison d''Esaü; car Yahweh a parlé.'),
('ab',1,19,'crampon1923','Ceux du négéb posséderont la montagne d''Esaü et ceux de la sephélah le pays des Philistins; ils posséderont le territoire d''Ephraïm, et le territoire de Samarie; et ceux de Benjamin posséderont Galaad.'),
('ab',1,20,'crampon1923','Les captifs de cette armée des enfants d''Israël posséderont le pays des Chananéens jusqu''à Sarepta. Et les captifs de Jérusalem qui sont à Sépharad posséderont les villes du négéb.'),
('ab',1,21,'crampon1923','Et des libérateurs monteront à la montagne de Sion, pour juger la montagne d''Esaü; et à Yahweh sera l''empire.'),
('jon',1,1,'crampon1923','La parole de Yahweh fut adressée à Jonas, fils d''Amathi, en ces termes:'),
('jon',1,2,'crampon1923','" Lève-toi, va à Ninive, la grande ville, et prêche contre elle; car leur méchanceté est montée jusqu''à moi. "'),
('jon',1,3,'crampon1923','Et Jonas se leva pour s''enfuir à Tharsis, loin de la face de Yahweh. Il descendit à Joppé, et trouva un vaisseau qui allait à Tharsis et, ayant payé son passage, il y descendit pour aller avec eux à Tharsis, loin de la face de Yahweh.'),
('jon',1,4,'crampon1923','Mais Yahweh fit souffler un grand vent sur la mer, et il y eut sur la mer une grande tempête; le vaisseau menaçait de se briser.'),
('jon',1,5,'crampon1923','Les mariniers eurent peur; ils crièrent chacun à leur dieu, et jetèrent à la mer les objets qui étaient sur le vaisseau, pour s''alléger. Et Jonas était descendu au fond du navire; il s''était couché et dormait profondément.'),
('jon',1,6,'crampon1923','Alors le chef de l''équipage s''approcha de lui et lui dit: " Qu''as-tu à dormir? Lève-toi, invoque ton Dieu; peut-être Dieu pensera-t-il à nous, et nous ne périrons point! "'),
('jon',1,7,'crampon1923','Et ils se dirent les uns aux autres: " Venez, jetons les sorts, afin que nous sachions de qui nous vient ce mal. " Ils jetèrent les sorts, et le sort tomba sur Jonas.'),
('jon',1,8,'crampon1923','Alors ils lui dirent: " Dis-nous donc à cause de qui nous arrive ce mal; quelle est ta profession, d''où viens-tu, quel est ton pays et de quel peuple es-tu?'),
('jon',1,9,'crampon1923','Il leur répondit: " Je suis un Hébreu et j''adore Yahweh, le Dieu du ciel, qui a fait la mer et la terre. "'),
('jon',1,10,'crampon1923','Les hommes furent saisis d''une grande crainte, et ils lui dirent: " Qu''as-tu fait! " Car les hommes savaient qu''il s''enfuyait loin de la face de Yahweh, parce qu''il le leur avait déclaré.'),
('jon',1,11,'crampon1923','Ils lui dirent: " Que te ferons-nous, pour que la mer s''apaise pour nous? " Car la mer continuait de se soulever de plus en plus.'),
('jon',1,12,'crampon1923','Il leur répondit: " Prenez-moi et me jetez à la mer, et la mer s''apaisera pour vous; car je sais que c''est à cause de moi que cette grande tempête est venue sur vous. "'),
('jon',1,13,'crampon1923','Les hommes ramaient pour ramener le vaisseau à la terre, mais ils ne le purent pas; car la mer continuait de se soulever de plus en plus contre eux.'),
('jon',1,14,'crampon1923','Alors ils crièrent à Yahweh et dirent: " Ah! Yahweh, que nous ne périssions pas pour l''âme de cet homme, et ne nous chargez pas d''un sang innocent; car c''est vous, Yahweh, qui avez fait comme il vous a plu. "'),
('jon',1,15,'crampon1923','Et prenant Jonas, ils le jetèrent à la mer; et la mer calma sa fureur.'),
('jon',1,16,'crampon1923','Et les hommes furent saisis d''une grande crainte pour Yahweh; ils offrirent un sacrifice à Yahweh et firent des vœux.'),
('jon',2,1,'crampon1923','Et Yahweh fit venir un grand poisson pour engloutir Jonas; et Jonas fut dans les entrailles du poisson trois jours et trois nuits.'),
('jon',2,2,'crampon1923','Et des entrailles du poisson Jonas pria Yahweh, son Dieu.'),
('jon',2,3,'crampon1923','Il dit: De la détresse où j''étais, j''ai invoqué Yahweh, et il m''a répondu; du ventre du schéol, j''ai crié: vous avez entendu ma voix.'),
('jon',2,4,'crampon1923','Vous m''aviez jeté dans l''abîme, au cœur des mers, et l''onde m''environnait; tous vos flots et toutes vos vagues ont passé sur moi.'),
('jon',2,5,'crampon1923','Et moi, je disais: je suis chassé de devant vos yeux; pourtant je contemplerai encore votre saint temple.'),
('jon',2,6,'crampon1923','Les eaux m''avaient enserré jusqu''à l''âme, l''abîme m''environnait, l''algue encerclait ma tête.'),
('jon',2,7,'crampon1923','J''étais descendu jusqu''aux racines des montagnes; les verrous de la terre étaient tirés sur moi pour toujours! Et vous avez fait remonter ma vie de la fosse, Yahweh, mon Dieu!'),
('jon',2,8,'crampon1923','Quand mon âme défaillait en moi, je me suis souvenu de Yahweh; et ma prière est parvenue jusqu''à vous, à votre saint temple.'),
('jon',2,9,'crampon1923','Ceux qui s''attachent à des vanités futiles abandonnent l''auteur de leur grâce.'),
('jon',2,10,'crampon1923','Mais moi, aux accents de louange, je vous offrirai un sacrifice; le vœu que j''ai fait, je l''accomplirai. A Yahweh est le salut!'),
('jon',2,11,'crampon1923','Yahweh parla au poisson, et le poisson vomit Jonas sur la terre.'),
('jon',3,1,'crampon1923','La parole de Yahweh fut adressée une seconde fois à Jonas, en ces termes:'),
('jon',3,2,'crampon1923','" Lève-toi, va à Ninive, la grande ville, et prêche-lui la prédication que je te dirai. "'),
('jon',3,3,'crampon1923','Et Jonas se leva et alla à Ninive, selon la parole de Yahweh. Or Ninive était une ville grande devant Dieu, de trois journées de marche.'),
('jon',3,4,'crampon1923','Jonas commença à pénétrer dans la ville la marche d''une journée; et il prêcha et dit: " Encore quarante jours et Ninive sera détruite!... "'),
('jon',3,5,'crampon1923','Les gens de Ninive crurent en Dieu; ils publièrent un jeûne et se revêtirent de sacs, depuis le plus grand jusqu''au plus petit.'),
('jon',3,6,'crampon1923','La chose étant parvenue au roi de Ninive, il se leva de son trône, ôta son manteau, se couvrit d''un sac et s''assît sur la cendre.'),
('jon',3,7,'crampon1923','Et on cria dans Ninive et on dit, par décret du roi et de ses grands, ces paroles: " Que ni hommes ni bêtes, bœufs et brebis, ne goûtent rien, ne paissent point et ne boivent point d''eau;'),
('jon',3,8,'crampon1923','qu''ils se couvrent de sacs, hommes et bêtes, qu''ils crient à Dieu avec force, et qu''ils se détournent chacun de sa mauvaise voie et des actions de violence que commettent ses mains!'),
('jon',3,9,'crampon1923','Qui sait si Dieu ne viendra pas à se repentir, et s''il ne reviendra pas de l''ardeur de sa colère, en sorte que nous ne périssions point? "'),
('jon',3,10,'crampon1923','Dieu vit ce qu''ils faisaient, comment ils se détournaient de leur mauvaise voie; et Dieu se repentit du mal qu''il avait annoncé qu''il leur ferait; et il ne le fit pas.'),
('jon',4,1,'crampon1923','Jonas en éprouva un vif chagrin, et il fut irrité.'),
('jon',4,2,'crampon1923','Il fit une prière à Yahweh et dit: " Ah! Yahweh, n''est-ce pas là ce que je disais lorsque j''étais encore dans mon pays? C''est pourquoi je me suis d''abord enfui à Tharsis; car je savais que vous êtes un Dieu miséricordieux et clément, lent à la colère, riche en grâce et vous repentant du mal.'),
('jon',4,3,'crampon1923','Maintenant, Yahweh, retirez donc de moi mon âme, car la mort vaut mieux pour moi que la vie. "'),
('jon',4,4,'crampon1923','Et Yahweh répondit: " Fais-tu bien de t''irriter? "'),
('jon',4,5,'crampon1923','Et Jonas sortit de la ville et s''assit à l''orient de la ville; là il se fit une hutte et s''assit dessous à l''ombre, jusqu''à ce qu''il vît ce qui arriverait dans la ville.'),
('jon',4,6,'crampon1923','Et Yahweh-Dieu fit pousser un ricin qui s''éleva au-dessus de Jonas pour qu''il y eût de l''ombre sur sa tête, afin de le délivrer de son mal; et Jonas éprouva une grande joie à cause du ricin.'),
('jon',4,7,'crampon1923','Mais Yahweh fit venir, au lever de l''aurore, le lendemain, un ver qui piqua le ricin; et il sécha.'),
('jon',4,8,'crampon1923','Et quand le soleil se leva, Yahweh fit venir un vent brûlant d''orient; et le soleil donna sur la tête de Jonas, au point qu''il défaillit. Il demanda de mourir et dit: " La mort vaut mieux pour moi que la vie. "'),
('jon',4,9,'crampon1923','Alors Dieu dit à Jonas: " Fais-tu bien de t''irriter à cause du ricin? " Il répondit: " Je fais bien de m''irriter jusqu''à la mort. "'),
('jon',4,10,'crampon1923','Et Yahweh dit: " Tu t''affliges au sujet du ricin pour lequel tu n''as pas travaillé et que tu n''as pas fait croître, qui est venu en une nuit et qui a péri en une nuit;'),
('jon',4,11,'crampon1923','et moi, je ne m''affligerais pas au sujet de Ninive, la grande ville, dans laquelle il y a plus de cent vingt mille hommes qui ne distinguent pas leur droite de leur gauche, et des animaux en grand nombre! "'),
('mi',1,1,'crampon1923','Parole de Yahweh qui fut adressée à Michée de Moréseth, dans les jours de Joathan, d''Achaz et d''Ezéchias, rois de Juda, dont il eut la vision touchant Samarie et Jérusalem.'),
('mi',1,2,'crampon1923','Ecoutez, vous tous, peuples! Sois attentive, terre, avec ce qui te remplit! Le Seigneur Yahweh va témoigner contre vous, le Seigneur, du palais de sa sainteté!'),
('mi',1,3,'crampon1923','Car voici que Yahweh va sortir de sa demeure; il descendra, il marchera sur les hauteurs de la terre.'),
('mi',1,4,'crampon1923','Les montagnes se fondront sous ses pas, les vallées se fendront, comme la cire devant le feu, comme l''eau versée sur une pente.'),
('mi',1,5,'crampon1923','Tout cela, à cause du crime de Jacob, et à cause des péchés de la maison d''Israël. Quel est le crime de Jacob? n''est-ce pas Samarie? Et quels sont les hauts lieux de Juda? n''est-ce pas Jérusalem?'),
('mi',1,6,'crampon1923','Je ferai de Samarie un tas de pierres dans un champ, un lieu à planter la vigne; je ferai rouler ses pierres dans la vallée, et je mettrai à nu ses fondements.'),
('mi',1,7,'crampon1923','Toutes ses statues seront brisées; et tous ses salaires consumés par le feu; de toutes ses idoles je ferai une ruine, car elle les a amassées avec le salaire de la prostitution, et elles redeviendront un salaire de prostitution.'),
('mi',1,8,'crampon1923','A cause de cela, je me lamenterai et je hurlerai, je marcherai dépouillé et nu; je répandrai une lamentation comme le chacal, et une plainte comme l''autruche.'),
('mi',1,9,'crampon1923','Car sa plaie est mortelle; car elle vient jusqu''à Juda, elle arrive jusqu''à la porte de mon peuple, jusqu''à Jérusalem.'),
('mi',1,10,'crampon1923','Ne l''annoncez pas dans Geth; ne pleurez pas dans Acco! A Beth-Aphra je me roule dans la poussière.'),
('mi',1,11,'crampon1923','Passe, habitante de Saphir, dans une honteuse nudité! L''habitante de Tsoanan n''est point sortie; le deuil de Beth-Haetsel vous prive de son abri.'),
('mi',1,12,'crampon1923','L''habitante de Maroth est en détresse à cause de ses biens; car le malheur est descendu d''auprès de Yahweh, sur la porte de Jérusalem.'),
('mi',1,13,'crampon1923','Attelle le char au coursier, habitante de Lachis; ce fut le commencement du péché pour la fille de Sion, qu''on ait trouvé chez toi les crimes d''Israël.'),
('mi',1,14,'crampon1923','C''est pourquoi tu renonceras à posséder Moréseth de Geth; les maisons d''Aczib seront une déception pour les rois d''Israël.'),
('mi',1,15,'crampon1923','Je t''amènerai un conquérant, habitante de Marésa; la noblesse d''Israël s''en ira jusqu''à Odollam.'),
('mi',1,16,'crampon1923','Arrache tes cheveux, rase-les, à cause de tes enfants bien-aimés; fais-toi chauve comme le vautour, car ils s''en vont en captivité loin de toi!'),
('mi',2,1,'crampon1923','Malheur à ceux qui méditent l''iniquité et qui préparent le mal sur leurs couches! au point du jour ils l''exécutent, quand c''est au pouvoir de leurs mains.'),
('mi',2,2,'crampon1923','Ils convoitent les champs et les ravissent, les maisons, et ils s''en emparent; ils font violence à l''homme et à sa maison, au maître et à son héritage.'),
('mi',2,3,'crampon1923','C''est pourquoi ainsi parle Yahweh: Voici que je médite contre cette race un mal, dont vous ne pourrez dégager votre cou; et vous ne marcherez plus la tête haute, car ce sera un temps mauvais.'),
('mi',2,4,'crampon1923','En ce jour-là on prononcera sur vous un proverbe, et on chantera une complainte: " C''en est fait, dira-t-on, nous sommes entièrement dévastés: il aliène la part de mon peuple! Comment me l''enlève-t-il? Il distribue nos champs aux infidèles? "'),
('mi',2,5,'crampon1923','C''est pourquoi tu n''auras personne qui étende chez toi le cordeau, pour une part d''héritage, dans l''assemblée de Yahweh.'),
('mi',2,6,'crampon1923','— Ne prophétisez plus, prophétisent-ils. Si on ne prophétise pas à ceux-ci, l''opprobre ne s''éloignera pas.'),
('mi',2,7,'crampon1923','Toi qu''on nomme maison de Jacob, est-ce que Yahweh est dépourvu de patience? Sont-ce là ses œuvres? — Mes paroles ne sont-elles pas bienveillantes pour celui qui marche avec droiture?'),
('mi',2,8,'crampon1923','Hier mon peuple s''est levé en adversaire: de dessus la robe vous arrachez le manteau; ceux qui passent sans défiance, vous les traitez en ennemis.'),
('mi',2,9,'crampon1923','Vous chassez les femmes de mon peuple, de leurs maisons chéries; à leurs petits enfants vous ôtez pour jamais ma gloire!'),
('mi',2,10,'crampon1923','Levez-vous! Partez..., car ce pays n''est pas un lieu de repos, à cause de la souillure qui vous tourmentera, et d''un cruel tourment.'),
('mi',2,11,'crampon1923','S''il y avait un homme courant après le vent et débitant des mensonges, en disant: " Je vais te prophétiser vin et cervoise! " ce serait le prophète de ce peuple.'),
('mi',2,12,'crampon1923','Je te rassemblerai tout entier, ô Jacob, je recueillerai les restes d''Israël; je les grouperai ensemble comme des brebis dans un bercail; comme un troupeau au milieu de son enclos, ainsi bruira la multitude des hommes.'),
('mi',2,13,'crampon1923','Celui qui fait la brèche monte devant eux; ils font la brèche, ils franchissent la porte, et par elle ils sortent; leur roi passe devant eux, et Yahweh est à leur tête.'),
('mi',3,1,'crampon1923','J''ai dit: Ecoutez donc, chefs de Jacob, et magistrats de la maison d''Israël! N''est-ce pas à vous de connaître le droit,'),
('mi',3,2,'crampon1923','vous qui haïssez le bien et aimez le mal, qui leur arrachez la peau de dessus le corps, et la chair de dessus les os?'),
('mi',3,3,'crampon1923','Ils dévorent la chair de mon peuple: ils lui arrachent la peau de dessus le corps, ils brisent ses os, ils les mettent en pièces comme ce qui est dans la marmite; et comme de la viande dans une chaudière.'),
('mi',3,4,'crampon1923','Alors ils crieront à Yahweh, et il ne les exaucera point; il leur cachera sa face en ce temps-là, selon la malice qu''ils ont mise en leurs actions.'),
('mi',3,5,'crampon1923','Ainsi parle Yahweh sur les prophètes qui égarent mon peuple, qui, tant que leurs dents ont de quoi mordre, proclament la paix, et à quiconque ne leur met rien dans la bouche, déclarent la guerre:'),
('mi',3,6,'crampon1923','" C''est pourquoi vous aurez la nuit au lieu de visions; et vous aurez les ténèbres au lieu de divination; le soleil se couchera pour les prophètes, et le jour s''obscurcira pour eux.'),
('mi',3,7,'crampon1923','Les voyants seront confus, et les devins rougiront de honte; tous, ils se couvriront la barbe, car il n''y aura plus de réponse de Dieu. "'),
('mi',3,8,'crampon1923','Mais moi, je suis rempli de force, avec l''esprit de Yahweh, et de jugement et de courage, pour dénoncer à Jacob son crime, et à Israël son péché.'),
('mi',3,9,'crampon1923','Ecoutez donc ceci, chefs de la maison de Jacob, et magistrats de la maison d''Israël, qui avez en horreur la justice, et qui pervertissez ce qui est droit,'),
('mi',3,10,'crampon1923','bâtissant Sion avec le sang, et Jérusalem avec l''iniquité!'),
('mi',3,11,'crampon1923','Ses chefs jugent pour des présents, ses prêtres enseignent pour un salaire; et ses prophètes exercent la divination pour de l''argent, et ils s''appuient sur Yahweh, en disant: " Yahweh n''est-il pas au milieu de nous? Le malheur ne saurait venir sur nous! "'),
('mi',3,12,'crampon1923','C''est pourquoi, à cause de vous, Sion deviendra un champ qu''on laboure, Jérusalem sera un monceau de pierres, et la montagne du temple un haut lieu boisé!'),
('mi',4,1,'crampon1923','Il arrivera à la fin des jours, que la Montagne de la maison de Yahweh sera établie au sommet des montagnes, et élevée au-dessus des collines. Et sur elle les nations afflueront.'),
('mi',4,2,'crampon1923','Et des peuples nombreux viendront et diront: " Venez, montons à la montagne de Yahweh, et à la maison du Dieu de Jacob; il nous instruira de ses voies, et nous marcherons dans ses sentiers. " Car de Sion sortira la loi, et de Jérusalem la parole de Yahweh.'),
('mi',4,3,'crampon1923','Il sera l''arbitre de nations nombreuses, et le juge de peuples puissants, jusqu''au loin. Ils forgeront leurs épées en socs de charrue, et leurs lances en faucilles; une nation ne lèvera plus l''épée contre l''autre, et l''on n''apprendra plus la guerre.'),
('mi',4,4,'crampon1923','Ils resteront assis chacun sous sa vigne, et sous son figuier, sans qu''il y ait personne pour les troubler; car la bouche de Yahweh des armées a parlé.'),
('mi',4,5,'crampon1923','Car tous les peuples marchent chacun au nom de son dieu; et nous, nous marchons au nom de Yahweh notre Dieu, toujours et à jamais.'),
('mi',4,6,'crampon1923','En ce jour-là, — oracle de Yahweh, je recueillerai celles qui boitent, je rassemblerai celles qui étaient dispersées, et auxquelles j''avais fait du mal.'),
('mi',4,7,'crampon1923','Et je ferai de celles qui boitent un reste, et de celles qui sont éloignées une nation puissante. Et Yahweh régnera sur eux, sur la montagne de Sion, dès lors et à jamais.'),
('mi',4,8,'crampon1923','Et toi, tour du troupeau, colline de la fille de Sion, elle viendra jusqu''à toi, elle te reviendra, l''ancienne domination, la royauté qui appartient à la fille de Jérusalem.'),
('mi',4,9,'crampon1923','Pourquoi maintenant pousses-tu des cris? N''y a-t-il plus, de roi en toi, et ton conseiller a-t-il péri, pour que la douleur t''ait saisie comme une femme qui enfante?'),
('mi',4,10,'crampon1923','Sois dans les douleurs et les efforts, fille de Sion, comme celle qui enfante! Car maintenant tu vas sortir de la ville; et demeurer dans les champs, et tu iras jusqu''à Babylone; là tu seras délivrée; là Yahweh te rachètera, de la main de tes ennemis.'),
('mi',4,11,'crampon1923','Et maintenant, contre toi se sont rassemblées des nations nombreuses; elles disent: " Qu''elle soit profanée, et que nos yeux contemplent Sion! "'),
('mi',4,12,'crampon1923','Mais elles ne connaissent pas les pensées de Yahweh, et elles ne comprennent pas ses desseins: savoir qu''il les a rassemblées comme des gerbes sur l''aire.'),
('mi',4,13,'crampon1923','Lève-toi et foule, fille de Sion! Car je ferai que ta corne soit de fer, et je ferai que tes sabots soient d''airain; et tu broieras des peuples nombreux; et je consacrerai leurs gains à Yahweh, et leurs richesses au Seigneur de toute la terre.'),
('mi',4,14,'crampon1923','Maintenant, fille de troupes, rassemble tes troupes! On a mis le siège contre nous, on frappe de la verge sur la joue le juge d''Israël.'),
('mi',5,1,'crampon1923','Et toi, Bethléem Ephrata, petite pour être entre les milliers de Juda, de toi sortira pour moi celui qui doit être dominateur en Israël, et ses origines dateront des temps anciens, des jours de l''éternité.'),
('mi',5,2,'crampon1923','C''est pourquoi il les livrera, jusqu''au temps où celle qui doit enfanter aura enfanté; et le reste de ses frères reviendra aux enfants d''Israël.'),
('mi',5,3,'crampon1923','Il se tiendra ferme, et il paîtra ses brebis, dans la force de Yahweh, dans la majesté du nom de Yahweh, son Dieu; et on demeurera en sécurité, car maintenant il sera grand, jusqu''aux extrémités de la terre.'),
('mi',5,4,'crampon1923','C''est lui qui sera la paix. Quand l''Assyrien viendra dans notre pays, et que son pied foulera nos palais, nous ferons lever contre lui sept pasteurs, et huit princes du peuple.'),
('mi',5,5,'crampon1923','Ils paîtront le pays d''Assur avec l''épée, et le pays de Nemrod dans ses portes; Il nous délivrera de l''Assyrien, lorsqu''il viendra dans notre pays, et que son pied foulera notre territoire.'),
('mi',5,6,'crampon1923','Et le reste de Jacob sera, au milieu de peuples nombreux, comme une rosée venant de Yahweh, comme des gouttes de pluie sur le gazon, lequel n''attend personne, et n''espère pas dans les enfants des hommes.'),
('mi',5,7,'crampon1923','Et le reste de Jacob sera aussi parmi les nations, au milieu de peuples nombreux, comme un lion parmi les bêtes de la forêt, comme un jeune lion parmi les troupeaux de brebis; lorsqu''il passe, foule et déchire, personne ne délivre.'),
('mi',5,8,'crampon1923','Que votre main se lève contre vos adversaires, et que vos ennemis soient exterminés!'),
('mi',5,9,'crampon1923','En ce jour-là, — oracle de Yahweh, j''exterminerai tes chevaux du milieu de toi, et je détruirai tes chars.'),
('mi',5,10,'crampon1923','Je ruinerai les villes de ton pays, et je démolirai toutes tes forteresses.'),
('mi',5,11,'crampon1923','Je retrancherai de ta main les sortilèges, et il n''y aura plus chez toi de devins.'),
('mi',5,12,'crampon1923','J''exterminerai du milieu de toi tes idoles et tes stèles, et tu n''adoreras plus l''ouvrage de tes mains.'),
('mi',5,13,'crampon1923','J''arracherai du milieu de toi tes aschéras, et je détruirai tes villes.'),
('mi',5,14,'crampon1923','Et dans ma colère et dans ma fureur, je tirerai vengeance des peuples qui n''auront pas écouté.'),
('mi',6,1,'crampon1923','Ecoutez donc ce que dit Yahweh: — Lève-toi et vide ta querelle devant les montagnes, et que les collines entendent ta voix!'),
('mi',6,2,'crampon1923','Ecoutez, montagnes, la querelle de Yahweh, et vous, immuables fondements de la terre! Car Yahweh a une querelle avec son peuple; et il va plaider contre Israël. —'),
('mi',6,3,'crampon1923','Mon peuple, que t''ai-je fait, en quoi t''ai-je causé de la peine? Réponds-moi.'),
('mi',6,4,'crampon1923','Car je t''ai fait monter du pays d''Egypte, je t''ai racheté de la maison de servitude, et j''ai envoyé devant toi Moïse, Aaron et Marie.'),
('mi',6,5,'crampon1923','Mon peuple, souviens-toi donc du conseil qu''avait donné Balac, roi de Moab, et de ce que lui répondit Balaam, fils de Beor; souviens-toi de Sétim jusqu''à Galgala, afin que tu connaisses les justices de Yahweh.'),
('mi',6,6,'crampon1923','Avec quoi me présenterai-je devant Yahweh, me prosternerai-je devant le Dieu de là-haut? Me présenterai-je devant lui avec des holocaustes, avec des veaux d''un an?'),
('mi',6,7,'crampon1923','Yahweh agréera-t-il des milliers de béliers, des myriades de torrents d''huile? Donnerai-je mon premier-né pour ma faute, le fruit de mes entrailles pour le péché de mon âme? —'),
('mi',6,8,'crampon1923','On t''a fait connaître, ô homme, ce qui est bon, et ce que Yahweh demande de toi: c''est de pratiquer la justice, d''aimer la miséricorde, et de marcher humblement avec ton Dieu.'),
('mi',6,9,'crampon1923','La voix de Yahweh crie à la ville, — et c''est sagesse de prendre garde à votre nom: — Écoutez la verge, et celui qui l''a ordonnée!'),
('mi',6,10,'crampon1923','Y a-t-il encore dans la maison du méchant des trésors iniques, et un épha amoindri, abominable?'),
('mi',6,11,'crampon1923','Serais-je pur avec des balances injustes, et de faux poids dans le sac?'),
('mi',6,12,'crampon1923','Les riches de cette ville sont pleins de violence, ses habitants profèrent le mensonge, et leur langue n''est que tromperie dans leur bouche.'),
('mi',6,13,'crampon1923','Moi, à mon tour, je te frapperai de coups mortels, je te dévasterai à cause de tes péchés.'),
('mi',6,14,'crampon1923','Tu mangeras, mais sans te rassasier, et ta faim sera au-dedans de toi; tu éloigneras, mais sans rien sauver, et ce que tu sauveras, je le livrerai à l''épée.'),
('mi',6,15,'crampon1923','Tu sèmeras, mais tu ne moissonneras pas; tu presseras l''olive, mais tu ne t''oindras pas d''huile; le moût, mais tu ne boiras pas de vin.'),
('mi',6,16,'crampon1923','On observe les ordonnances d''Amri, et toutes les pratiques de la maison d''Achab, et vous marchez d''après leurs conseils, afin que je vous livre à la destruction, et les habitants du pays aux sifflets, et que vous portiez l''opprobre de mon peuple.'),
('mi',7,1,'crampon1923','Hélas! je suis comme après la récolte des fruits d''été, comme après le grappillage de la vendange: pas une grappe a manger! pas une des premières figues que mon âme désire!'),
('mi',7,2,'crampon1923','L''homme pieux a disparu de la terre, et il n''y a plus un juste parmi les hommes. Tous ils se mettent en embuscade pour répandre le sang; chacun fait la chasse à son frère et lui tend le filet.'),
('mi',7,3,'crampon1923','Le mal, il y a des mains pour le bien faire; le prince exige, le juge fait son prix, et le grand manifeste son avidité; c''est ainsi qu''ils ourdissent ensemble leur trame.'),
('mi',7,4,'crampon1923','Le meilleur d''entre eux est pareil à l''épine; le plus droit, pire qu''une haie de ronces. — Le jour annoncé par tes sentinelles, le jour de ton châtiment est venu; maintenant ils vont être dans la confusion! —'),
('mi',7,5,'crampon1923','Ne croyez pas à un ami, ne vous fiez pas à un intime; devant celle qui repose sur ton sein, garde les paroles de ta bouche!'),
('mi',7,6,'crampon1923','Car le fils traite son père de fou; la fille s''insurge contre sa mère, la belle-fille contre sa belle-mère; chacun a pour ennemis les gens de sa maison.'),
('mi',7,7,'crampon1923','Et moi je regarderai vers Yahweh, j''espérerai dans le Dieu de mon salut; mon Dieu m''écoutera.'),
('mi',7,8,'crampon1923','Ne te réjouis pas à mon sujet, ô mon ennemie; car, si je suis tombée, je me relèverai; si je suis assise dans les ténèbres, Yahweh est ma lumière.'),
('mi',7,9,'crampon1923','Je porterai la colère de Yahweh, puisque j''ai péché contre lui, jusqu''à ce qu''il prenne en main ma cause, et qu''il établisse mon droit; il me fera sortir à la lumière, je contemplerai sa justice.'),
('mi',7,10,'crampon1923','Que mon ennemie le voie, et que la honte la recouvre, elle qui me disait: " Où est Yahweh, ton Dieu? " Mes yeux la contempleront; maintenant elle sera foulée aux pieds, comme la boue des rues.'),
('mi',7,11,'crampon1923','Le jour vient où tes murs seront rebâtis; ce jour-là le décret sera retiré.'),
('mi',7,12,'crampon1923','Ce jour-là, on viendra jusqu''à toi, de l''Assyrie et des villes d''Egypte, de l''Egypte jusqu''au fleuve, d''une mer à l''autre et d''une montagne à l''autre.'),
('mi',7,13,'crampon1923','Le pays deviendra un désert, à cause de ses habitants: c''est là le fruit de leurs actions.'),
('mi',7,14,'crampon1923','Pais ton peuple avec ta houlette, le troupeau de ton héritage, qui habite solitaire dans la forêt, au milieu du Carmel; qu''elles paissent en Basan et en Galaad, comme aux jours anciens!'),
('mi',7,15,'crampon1923','Comme au jour où tu sortis du pays d''Egypte, je lui ferai voir des prodiges.'),
('mi',7,16,'crampon1923','Les nations le verront, et seront confuses de toute leur puissance; elles mettront la main sur la bouche; leurs oreilles seront assourdies.'),
('mi',7,17,'crampon1923','Elles lécheront la poussière comme le serpent; comme les reptiles de la terre, elles sortiront avec effroi de leurs retraites; elles viendront en tremblant vers Yahweh, notre Dieu, et elles vous craindront.'),
('mi',7,18,'crampon1923','Quel Dieu est semblable à vous, qui ôtez l''iniquité, et qui pardonnez la transgression au reste de votre héritage? Il ne fait pas à toujours prévaloir sa colère, car il prend plaisir, lui, à faire grâce.'),
('mi',7,19,'crampon1923','Il aura encore pitié de nous, il foulera encore aux pieds nos iniquités! Vous jetterez au fond de la mer tous leurs péchés;'),
('mi',7,20,'crampon1923','vous ferez voir à Jacob votre fidélité, à Abraham la miséricorde, que vous avez jurée à nos pères, dès les jours anciens.'),
('na',1,1,'crampon1923','Oracle sur Ninive. Livre de la Vision de Nahum d''Elqosch.'),
('na',1,2,'crampon1923','C''est un Dieu jaloux et vengeur que Yahweh; vengeur est Yahweh et connaissant le courroux; Yahweh se venge de ses adversaires, et garde rancune à ses ennemis.'),
('na',1,3,'crampon1923','Yahweh est patient et grand en force, et il n''accorde pas l''impunité. Yahweh marche dans la tempête et dans l''ouragan, et la nuée est la poussière de ses pieds.'),
('na',1,4,'crampon1923','Il menace la mer et il la dessèche, et il fait tarir tous les fleuves. Basan et le Carmel sont flétris, flétrie est la végétation du Liban.'),
('na',1,5,'crampon1923','Les montagnes tremblent devant lui, et les collines se fondent; la terre se soulève devant sa face, le monde et tous ceux qui l''habitent.'),
('na',1,6,'crampon1923','Devant sa fureur qui subsistera, qui tiendra contre l''ardeur de sa colère? Son courroux se répand comme le feu, et les rochers se brisent devant lui.'),
('na',1,7,'crampon1923','Yahweh est bon; il est un refuge au jour de la détresse, et il connaît ceux qui se confient en lui.'),
('na',1,8,'crampon1923','Par un flot débordant il détruira entièrement ce lieu, et il poursuivra ses ennemis jusque dans les ténèbres.'),
('na',1,9,'crampon1923','Quelles sont vos pensées sur Yahweh? Il consommera la ruine; la détresse ne surgira pas deux fois.'),
('na',1,10,'crampon1923','Car, entrelacés comme des épines, et comme ivres de leur vin, ils seront consumés comme de la paille toute sèche.'),
('na',1,11,'crampon1923','De toi est sorti celui qui médite le mal contre Yahweh, celui qui forme des desseins criminels.'),
('na',1,12,'crampon1923','Ainsi parte Yahweh: Bien qu''ils soient intacts et nombreux, ils seront moissonnés et disparaîtront. Je t''ai humiliée et je ne t''humilierai plus.'),
('na',1,13,'crampon1923','Et maintenant, ô Juda, je briserai son joug de dessus toi, et je romprai tes liens.'),
('na',1,14,'crampon1923','Quant à toi, voici ce qu''a ordonné Yahweh: Il n''y aura plus de postérité de ton nom; je détruirai de la maison de ton Dieu les images taillées et celles de fonte; je prépare ton sépulcre, parce que tu as été léger.'),
('na',2,1,'crampon1923','Voici sur les montagnes les pieds d''un messager de bonnes nouvelles, qui annonce la paix. Célèbre tes fêtes, ô Juda, accomplis tes vœux! Car il ne passera plus chez toi; le méchant est entièrement détruit.'),
('na',2,2,'crampon1923','Un destructeur s''avance contre toi; garde la forteresse, surveille le chemin, affermis tes reins, ramasse toute ta force!'),
('na',2,3,'crampon1923','Car Yahweh rétablit la gloire de Jacob, ainsi que la gloire d''Israël, parce que des pillards les ont pillés, et ont détruit leurs ceps.'),
('na',2,4,'crampon1923','Le bouclier de ses guerriers est teint en rouge, ses hommes d''armes sont vêtus d''écarlate; dans le feu des aciers ses chars apparaissent, au jour où il prépare la bataille, et les lances s''agitent.'),
('na',2,5,'crampon1923','Dans les rues les chars s''élancent avec furie; ils se précipitent sur les places. Leur aspect est celui des flammes, des éclairs qui courent.'),
('na',2,6,'crampon1923','Il se souvient de ses nobles; eux trébuchent dans leur marche. Ils se précipitent vers les murs; on se prépare à la défense.'),
('na',2,7,'crampon1923','Les portes des fleuves s''ouvrent, et le palais s''effondre.'),
('na',2,8,'crampon1923','C''en est fait, elle est mise à nu, elle est emmenée, et ses servantes poussent des gémissements, pareils aux plaintes des colombes; elles se frappent la poitrine.'),
('na',2,9,'crampon1923','Ninive est comme un bassin d''eau depuis son origine... Ils s''enfuient!... Arrêtez! Arrêtez!... Pas un ne se retourne!'),
('na',2,10,'crampon1923','Pillez l''argent, pillez l''or! Car il n''y a pas de fin à ses richesses, à l''amas de tous ses objets précieux.'),
('na',2,11,'crampon1923','Vidée, pillée, mise à sec! Les cœurs défaillent, les genoux tremblent; tous les reins sont dans l''angoisse, tous les visages sont livides.'),
('na',2,12,'crampon1923','Où est-il, le repaire des lions, qui était un lieu de pâture pour les jeunes lions; où se retiraient le lion, la lionne et le lionceau, sans que personne les effrayât?'),
('na',2,13,'crampon1923','Le lion ravissait ce qu''il fallait à ses petits, il étranglait pour ses lionnes, il remplissait de proie ses cavernes, et ses antres de dépouilles.'),
('na',2,14,'crampon1923','Me voici contre toi! — oracle de Yahweh des armées; je vais réduire tes chars en fumée; l''épée dévorera tes jeunes lions; j''arracherai du pays ta proie, et l''on n''entendra plus la voix de tes messagers.'),
('na',3,1,'crampon1923','Malheur à la ville de sang, toute pleine de fraude, de violence, et qui ne cesse pas ses rapines!'),
('na',3,2,'crampon1923','On entend le bruit du fouet, le bruit du fracas des roues, le galop des chevaux, les chariots qui bondissent!'),
('na',3,3,'crampon1923','Cavaliers qui s''élancent, épée flamboyante, lance fulgurante! Multitude de blessés, masse de morts, des cadavres à l''infini... On trébuche sur leurs cadavres.'),
('na',3,4,'crampon1923','C''est à cause des nombreuses prostitutions de la prostituée, pleine d''attraits, habile aux enchantements, qui vendait les nations par ses prostitutions, et les peuples par ses enchantements.'),
('na',3,5,'crampon1923','Me voici contre toi! — oracle de Yahweh des armées; je vais relever les pans de ta robe jusque sur ton visage, je montrerai aux nations ta nudité, et ta honte aux royaumes.'),
('na',3,6,'crampon1923','Je jetterai sur toi des ordures et je t''avilirai, et je te donnerai en spectacle.'),
('na',3,7,'crampon1923','Quiconque te verra, fuira loin de toi, et dira: " Ninive est détruite! " Qui la plaindra? Où te chercherai-je des consolateurs?'),
('na',3,8,'crampon1923','Vaux-tu mieux que No-Amon, qui était assise sur les fleuves, que les eaux environnaient, qui avait la mer pour rempart, et dont la mer était la muraille?'),
('na',3,9,'crampon1923','L''Ethiopie était sa force, ainsi que l''Egypte, et ils étaient innombrables; Phut et les Libyens étaient tes auxiliaires.'),
('na',3,10,'crampon1923','Pourtant, elle est allée en exil, elle a été captive; ses petits enfants aussi ont été écrasés, à l''angle de toutes les rues; on a jeté le sort sur ses nobles, et tous ses grands ont été chargés de chaînes.'),
('na',3,11,'crampon1923','Toi aussi, tu seras enivrée et tu disparaîtras; toi aussi, tu chercheras un refuge devant l''ennemi.'),
('na',3,12,'crampon1923','Toutes tes places fortes sont des figuiers aux figues mûres; on secoue, et elles tombent dans la bouche de qui veut les manger.'),
('na',3,13,'crampon1923','Voici que ton peuple est comme des femmes au milieu de toi; devant tes ennemis s''ouvriront toutes grandes les portes de ton pays; le feu dévore tes verrous.'),
('na',3,14,'crampon1923','Puise-toi de l''eau en vue du siège, restaure tes forts, pétris l''argile et foule la terre glaise, saisis le moule à briques.'),
('na',3,15,'crampon1923','Là le feu te dévorera, l''épée t''exterminera, elle te dévorera comme le yéléq, quand tu serais nombreux comme le yéléq, nombreux comme la sauterelle.'),
('na',3,16,'crampon1923','Tu as multiplié tes marchands, plus que les étoiles du ciel; le yéléq ouvre ses ailes et s''envole.'),
('na',3,17,'crampon1923','Tes gardes sont comme le yéléq et tes chefs comme un amas de sauterelles; elles se posent sur les haies en un jour froid; dès que le soleil paraît, elles fuient, et l''on ne connaît plus leur séjour; où sont-elles?'),
('na',3,18,'crampon1923','Tes pasteurs sont endormis, roi d''Assyrie; tes vaillants hommes sont couchés, ton peuple est dispersé sur les montagnes, et il n''y a personne qui les rassemble.'),
('na',3,19,'crampon1923','Ta blessure est sans remède, ta plaie est grave; tous ceux qui entendront raconter ton sort battront des mains à ton sujet; car sur qui ta méchanceté n''a-t-elle pas passé sans trêve?'),
('ha',1,1,'crampon1923','Sentence dont Habacuc, le prophète, eut la vision.'),
('ha',1,2,'crampon1923','Jusques à quand, Yahweh, t''implorerai-je, sans que tu m''entendes, crierai-je vers toi à la violence, sans que tu me délivres?'),
('ha',1,3,'crampon1923','Pourquoi me fais-tu voir l''iniquité, et contemples-tu la souffrance? La dévastation et la violence sont devant moi, il y a des querelles et la discorde s''élève;'),
('ha',1,4,'crampon1923','à cause de cela la loi se meurt, et la justice ne voit plus le jour; car le méchant circonvient le juste; c''est pourquoi le droit sort faussé.'),
('ha',1,5,'crampon1923','Jetez les yeux sur les nations et regardez; soyez étonnés, stupéfaits. Car je vais faire en vos jours une œuvre, que vous ne croiriez pas si on vous la racontait.'),
('ha',1,6,'crampon1923','Car voici que je suscite les Chaldéens, peuple féroce et impétueux, qui s''avance vers les larges espaces de la terre, pour s''emparer de demeures qui ne sont pas à lui.'),
('ha',1,7,'crampon1923','Il est terrible et formidable, et c''est de lui-même que vient son droit et sa grandeur.'),
('ha',1,8,'crampon1923','Ses chevaux sont plus légers que les léopards, plus ardents que les loups du soir. Ses cavaliers s''élancent, ses cavaliers viennent de loin, ils volent comme l''aigle pressé de dévorer.'),
('ha',1,9,'crampon1923','Tout ce peuple vient pour exercer la violence; leurs regards avides se portent en avant; il amasse les captifs comme du sable.'),
('ha',1,10,'crampon1923','Lui, il se moque des rois, et les princes sont sa risée; il se rit de toutes les forteresses, il entasse de la poussière et les prend.'),
('ha',1,11,'crampon1923','Puis l''ouragan s''avance et passe; et il se rend coupable; sa force à lui, voilà son Dieu!'),
('ha',1,12,'crampon1923','N''es-tu pas dès le commencement, Yahweh, mon Dieu, mon saint? Nous ne mourrons pas. Yahweh, tu as établi ce peuple pour le droit, ô mon Rocher, tu l''as affermi pour châtier.'),
('ha',1,13,'crampon1923','Tes yeux sont trop purs pour voir le mal, et tu ne peux contempler la souffrance. Pourquoi regarderais-tu les perfides, et te tairais-tu, quand le méchant dévore un plus juste que lui?'),
('ha',1,14,'crampon1923','Tu traiterais donc les hommes comme les poissons de la mer, comme les reptiles qui n''ont point de chef!...'),
('ha',1,15,'crampon1923','Il prend le tout à l''hameçon, il le tire avec son filet, le rassemble dans ses rets; et c''est pourquoi il est dans la joie, il jubile.'),
('ha',1,16,'crampon1923','C''est pourquoi il sacrifie à son filet, et il offre de l''encens à ses rets; car par eux sa portion est grasse, et sa nourriture succulente.'),
('ha',1,17,'crampon1923','Continuera-t-il donc de vider son filet, et toujours égorgera-t-il sans pitié les nations!'),
('ha',2,1,'crampon1923','Je veux me tenir à mon poste, et me placer sur la tour de garde; et j''observerai pour voir ce que me dira Yahweh, et ce que je répondrai à la remontrance qui me sera faite.'),
('ha',2,2,'crampon1923','Et Yahweh me répondit et dit: Écris la vision et grave-la sur les tables, afin qu''on y lise couramment.'),
('ha',2,3,'crampon1923','Car il y a encore une vision pour un temps fixé; elle se hâte vers son terme et ne mentira pas; si elle tarde, attends-là, car elle arrivera certainement, elle ne manquera pas:'),
('ha',2,4,'crampon1923','Celui dont l''âme s''enfle au-dedans de lui n''est pas dans le droit chemin; mais le juste vivra par sa foi.'),
('ha',2,5,'crampon1923','Et de plus le vin est perfide! L''homme arrogant ne subsistera pas, lui qui s''est fait un appétit large comme le schéol, qui, comme la mort, est insatiable; il rassemble vers lui toutes les nations, et ramasse à lui tous les peuples.'),
('ha',2,6,'crampon1923','Est-ce que ceux-ci, eux tous, ne prononceront pas à son sujet des sentences, des fables et des énigmes à son adresse? On dira: Malheur à qui amasse ce qui n''est pas à lui, — jusques à quand? — à qui met sur soi un fardeau de gages!'),
('ha',2,7,'crampon1923','Tes créanciers ne se lèveront-ils pas soudain, tes bourreaux ne se réveilleront-ils pas, et ne deviendras-tu pas leur proie?'),
('ha',2,8,'crampon1923','Parce que tu as dépouillé beaucoup de nations, tous les peuples qui restent te dépouilleront, à cause du sang humain répandu, des violences faites à la terre, à la ville et à tous ses habitants.'),
('ha',2,9,'crampon1923','Malheur à qui amasse pour sa maison des gains iniques, afin de placer son nid bien haut, pour échapper à l''atteinte du malheur!'),
('ha',2,10,'crampon1923','Tu as médité la honte de ta maison; en détruisant beaucoup de peuples, tu as péché contre toi-même.'),
('ha',2,11,'crampon1923','Car la pierre criera de la muraille, et la poutre lui répondra de la charpente.'),
('ha',2,12,'crampon1923','Malheur à qui bâtit une ville dans le sang, et fonde une cité sur l''injustice!'),
('ha',2,13,'crampon1923','N''est-ce pas, ceci, la volonté de Yahweh des armées: que les peuples travaillent pour le feu, et que les nations se fatiguent pour le néant?'),
('ha',2,14,'crampon1923','Car la terre sera remplie de la connaissance de la gloire de Yahweh, comme les eaux recouvrent le fond de la mer.'),
('ha',2,15,'crampon1923','Malheur à qui fait boire son prochain, à toi qui lui verses ta fureur jusqu''à l''enivrer, pour regarder sa nudité!'),
('ha',2,16,'crampon1923','Tu t''es rassasié d''opprobre, au lieu de gloire; bois, toi aussi, et montre ton incirconcision; la coupe de la droite de Yahweh se retournera sur toi; l''ignominie couvrira ta gloire.'),
('ha',2,17,'crampon1923','Car la violence faite au Liban retombera sur toi, ainsi que la destruction des animaux frappés d''épouvante, à cause du sang humain répandu, des violences faites à la terre, à la ville et à tous ses habitants.'),
('ha',2,18,'crampon1923','A quoi sert l''image taillée, pour que son auteur la taille, l''idole de fonte, et l''oracle de mensonge, pour que l''auteur de cet ouvrage se confie en lui, en façonnant des divinités silencieuses?'),
('ha',2,19,'crampon1923','Malheur à qui dit au bois: " Lève-toi! " " Réveille-toi! " à la pierre muette. Enseignera-t-elle?... Voici qu''elle est plaquée d''or et d''argent, et il n''y a pas au dedans d''elle un souffle de vie.'),
('ha',2,20,'crampon1923','Mais Yahweh est dans son saint temple; tais-toi, devant lui, ô terre toute entière!'),
('ha',3,1,'crampon1923','Prière d''Habacuc le prophète. Sur le mode dithyrambique.'),
('ha',3,2,'crampon1923','Yahweh, j''ai entendu ce que tu as fait entendre, je suis saisi de crainte, Yahweh! Ton œuvre, dans le cours des âges, fais-la vivre; dans le cours des âges fais-la connaître! Dans ta colère, souviens-toi d''avoir pitié.'),
('ha',3,3,'crampon1923','Dieu vient de Théman, et le Saint de la montagne de Pharan (Séla). Sa majesté a couvert les cieux, et la terre a été remplie de sa gloire.'),
('ha',3,4,'crampon1923','C''est un éclat comme la lumière du soleil levant; des rayons partent de ses mains; là se cache sa puissance.'),
('ha',3,5,'crampon1923','Devant lui marche la mortalité, et la fièvre brûlante est sur ses pas.'),
('ha',3,6,'crampon1923','Il s''est arrêté et a fait trembler la terre, il a regardé et a secoué les nations; les montagnes éternelles se sont brisées, les collines antiques se sont affaissées; il suit ses voies d''autrefois.'),
('ha',3,7,'crampon1923','J''ai vu dans la détresse les tentes de Cuschan; les pavillons de la terre de Moab frémissent.'),
('ha',3,8,'crampon1923','Est-ce contre des fleuves que Yahweh s''est irrité? Ou bien est-ce contre les fleuves que s''enflamme ta colère; contre la mer que se déchaîne ta fureur, lorsque tu montes sur tes chevaux, sur tes chars de délivrance?'),
('ha',3,9,'crampon1923','A nu ton arc se découvre; tes traits sont les serments que tu as prononcés (Séla). En torrents tu fends la terre.'),
('ha',3,10,'crampon1923','Les montagnes t''ont vu et tremblent; une trombe d''eau a passé; l''abîme a fait entendre sa voix, il tend ses mains en haut.'),
('ha',3,11,'crampon1923','Le soleil et la lune sont restés dans leur demeure; on marche à la clarté de tes flèches à la lueur des éclairs de ta lance.'),
('ha',3,12,'crampon1923','Tu parcours la terre avec fureur, tu foules les nations avec colère.'),
('ha',3,13,'crampon1923','Tu es sorti pour la délivrance de ton peuple; pour la délivrance de ton Oint; tu as brisé le faîte de la maison du méchant, mettant à nu les fondements jusqu''en bas (Séla).'),
('ha',3,14,'crampon1923','Tu as percé de ses propres traits le chef de ses bandes, qui se précipitaient pour me disperser, en poussant des cris de joie, comme s''ils allaient dévorer le malheureux dans leur repaire.'),
('ha',3,15,'crampon1923','Tu foules la mer sous les pieds de tes chevaux, l''amas des grandes eaux.'),
('ha',3,16,'crampon1923','J''ai entendu, et mes entrailles se sont émues; à cette voix mes lèvres frémissent, la carie entre dans mes os, mes genoux tremblent sous moi, de ce que je dois attendre en repos le jour de détresse; où l''ennemi montera contre un peuple pour l''opprimer.'),
('ha',3,17,'crampon1923','Car alors le figuier ne fleurira pas, il n''y aura rien à récolter dans les vignes; le fruit de l''olivier manquera, et les champs ne donneront pas de nourriture; la brebis disparaîtra de la bergerie, et il n''y aura plus de bœufs dans les étables.'),
('ha',3,18,'crampon1923','Et moi, je veux me réjouir en Yahweh, tressaillir de joie dans le Dieu de mon salut.'),
('ha',3,19,'crampon1923','Yahweh, le Seigneur, est ma force; il rend mes pieds pareils à ceux des biches, et me fait marcher sur mes lieux élevés. Au chef des chantres, sur mes instruments à cordes.'),
('so',1,1,'crampon1923','La parole de Yahweh qui fut adressée à Sophonie, fils de Chusi, fils de Godolias, fils d''Amarias, fils d''Ezéchias, dans les jours de Josias, fils d''Amon, roi de Juda.'),
('so',1,2,'crampon1923','J''enlèverai tout de dessus la face de la terre, — oracle de Yahweh;'),
('so',1,3,'crampon1923','j''enlèverai les hommes et les bêtes, j''enlèverai les oiseaux du ciel et les poissons de la mer, et les scandales avec les impies, et j''exterminerai l''homme de dessus la face de la terre, — oracle de Yahweh.'),
('so',1,4,'crampon1923','Et j''étendrai ma main sur Juda, et sur tous les habitants de Jérusalem, et j''exterminerai de ce lieu le reste de Baal, le nom de ses ministres en même temps que les prêtres;'),
('so',1,5,'crampon1923','et ceux qui se prosternent sur les toits, devant l''armée des cieux; et ceux qui se prosternent en faisant serment à Yahweh, tout en jurant par leur roi;'),
('so',1,6,'crampon1923','et ceux qui se détournent de Yahweh, qui ne cherchent pas Yahweh, et ne se soucient pas de lui.'),
('so',1,7,'crampon1923','Silence devant le Seigneur Yahweh! Car le jour de Yahweh est proche; car Yahweh a préparé un sacrifice, il a consacré ses invités.'),
('so',1,8,'crampon1923','Et il arrivera: Au jour du sacrifice de Yahweh, je châtierai les princes, et les fils de roi, et tous ceux qui revêtent des vêtements étrangers.'),
('so',1,9,'crampon1923','Et je châtierai en ce jour-là tous ceux qui sautent par-dessus le seuil, qui remplissent de violence et de fraude la maison de leur maître.'),
('so',1,10,'crampon1923','Et il arrivera en ce jour-là, — oracle de Yahweh: De la porte des poissons retentiront des cris, de la seconde ville des gémissements, et des collines un grand fracas.'),
('so',1,11,'crampon1923','Gémissez, habitants du Mortier, car tout le peuple chananéen est anéanti, tous ceux qui sont chargés d''argent sont exterminés.'),
('so',1,12,'crampon1923','Et il arrivera en ce temps-là: Je fouillerai Jérusalem avec des lanternes, et je châtierai les hommes figés sur leur lie, qui disent en leur cœur: " Yahweh ne fait ni bien ni mal! "'),
('so',1,13,'crampon1923','Leurs biens seront livrés au pillage, et leurs maisons à la dévastation; ils bâtiront des maisons, et ils n''y habiteront point; ils planteront des vignes, et ils n''en boiront pas le vin.'),
('so',1,14,'crampon1923','Il est proche le grand jour de Yahweh, il est proche, il vient en toute hâte! On l''entend venir, le jour de Yahweh! L''homme brave y poussera des cris amers.'),
('so',1,15,'crampon1923','C''est un jour de fureur que ce jour-là, un jour d''angoisse et d''affliction, un jour de désolation et de ruine, un jour de ténèbres et d''obscurité, un jour de nuages et d''épais brouillards,'),
('so',1,16,'crampon1923','un jour de trompette et d''alarme, sur les villes fortes et les créneaux élevés.'),
('so',1,17,'crampon1923','Je mettrai les hommes dans la détresse, et ils marcheront comme des aveugles, parce qu''ils ont péché contre Yahweh; leur sang sera répandu comme la poussière; et leur chair comme du fumier.'),
('so',1,18,'crampon1923','Ni leur argent, ni leur or ne pourront les délivrer; au jour de la fureur de Yahweh; par le feu de sa jalousie, toute la terre sera dévorée; car il fera une destruction totale, une ruine soudaine, de tous les habitants de la terre.'),
('so',2,1,'crampon1923','Recueillez-vous, rentrez en vous-mêmes, race sans pudeur,'),
('so',2,2,'crampon1923','avant que le décret ait enfanté, que le jour ait passé comme la paille; avant que vienne sur vous l''ardeur de la colère de Yahweh, avant que vienne sur vous le jour de la colère de Yahweh.'),
('so',2,3,'crampon1923','Cherchez Yahweh, vous tous humbles du pays, qui avez pratiqué sa loi; recherchez la justice, recherchez l''humilité. Peut-être serez-vous à l''abri au jour de la colère de Yahweh!...'),
('so',2,4,'crampon1923','Car Gaza sera abandonnée, et Ascalon réduite en désert; on chassera Azot en plein midi, et Accaron sera déracinée.'),
('so',2,5,'crampon1923','Malheur aux habitants de la région de la mer, à la nation des Crétois! La parole de Yahweh est prononcée contre vous, Chanaan, terre des Philistins: " Et je te détruirai en sorte qu''il ne te reste plus d''habitants. "'),
('so',2,6,'crampon1923','La région de la mer deviendra des pâturages, des grottes de bergers et des parcs de moutons.'),
('so',2,7,'crampon1923','Ce sera un territoire pour le reste de la maison de Juda, ils y paîtront leurs troupeaux; le soir, ils prendront leur gîte dans les maisons d''Ascalon, car Yahweh, leur Dieu, les visitera et les rétablira.'),
('so',2,8,'crampon1923','J''ai entendu les insultes de Moab, et les outrages des fils d''Ammon, qui insultaient mon peuple, et s''agrandissaient aux dépens de ses frontières.'),
('so',2,9,'crampon1923','C''est pourquoi, je suis vivant, — oracle de Yahweh des armées, le Dieu d''Israël: Moab sera comme Sodome, et les fils d''Ammon comme Gomorrhe: un lieu livré aux orties, une carrière de sel, un désert à jamais. Le reste de mon peuple le pillera, et ce qui demeurera de ma nation, les aura en héritage.'),
('so',2,10,'crampon1923','Cela leur arrivera pour leur orgueil, parce qu''ils ont été méprisants et insolents, contre le peuple de Yahweh des armées.'),
('so',2,11,'crampon1923','Yahweh sera un objet de terreur pour eux, car il anéantira tous les dieux de la terre; et devant lui se prosterneront, chacun de son lieu, les habitants de toutes les îles des nations.'),
('so',2,12,'crampon1923','Vous aussi, Ethiopiens!... Ils seront transpercés par mon épée.'),
('so',2,13,'crampon1923','Il étendra aussi sa main contre le nord, il détruira Assur, et il fera de Ninive une solitude, aride comme le désert.'),
('so',2,14,'crampon1923','Au milieu d''elle prendront leur gîte des troupeaux, des animaux de toute espèce; même le pélican, même le hérisson se logeront sur ses chapiteaux; on entendra des chants dans les fenêtres, la désolation sera sur le seuil, car on a mis à nu les boiseries de cèdres.'),
('so',2,15,'crampon1923','C''est là la ville joyeuse, assise avec assurance, qui disait en son cœur: " Moi, et rien que moi! " Comment est-elle devenue un désert, une demeure pour les bêtes? Quiconque passera sur elle sifflera et agitera la main.'),
('so',3,1,'crampon1923','Malheur à la rebelle et à la souillée, à la ville d''oppression!'),
('so',3,2,'crampon1923','Elle n''a écouté aucune voix, elle n''a point accepté d''avertissement; elle ne s''est pas confiée en Yahweh, elle ne s''est point approchée de son Dieu.'),
('so',3,3,'crampon1923','Ses princes au milieu d''elle sont des lions rugissants, ses juges des loups du soir, qui ne gardent rien pour le matin.'),
('so',3,4,'crampon1923','Ses prophètes sont des fanfarons, des hommes perfides; ses prêtres profanent les choses saintes, ils violent la loi.'),
('so',3,5,'crampon1923','Yahweh est juste au milieu d''elle, il ne fait rien d''inique; chaque matin il produit son jugement, pour donner la lumière, sans jamais y manquer; mais l''impie ne connaît point de honte!'),
('so',3,6,'crampon1923','J''ai exterminé des nations; leurs tours ont été détruites; j''ai désolé leurs rues, si bien qu''on n''y passe plus; leurs villes ont été dévastées, si bien qu''il n''y reste personne, aucun habitant.'),
('so',3,7,'crampon1923','Je disais: " Au moins tu me craindras, tu accepteras l''avertissement; et sa demeure ne sera pas détruite, selon tout ce que j''ai décidé à son égard. " Mais ils n''ont été que plus empressés à pervertir toutes leurs actions.'),
('so',3,8,'crampon1923','C''est pourquoi attendez-moi, — oracle de Yahweh, pour le jour où je me lèverai pour le butin! Car mon arrêt est que j''assemble les nations, que je rassemble les royaumes, pour verser sur eux ma fureur, toute l''ardeur de ma colère. Car par le feu de ma jalousie, toute la terre sera dévorée.'),
('so',3,9,'crampon1923','Car alors je donnerai aux peuples des lèvres pures, afin qu''ils invoquent tous le nom de Yahweh, et le servent d''un commun accord.'),
('so',3,10,'crampon1923','D''au delà des fleuves de l''Ethiopie, mes adorateurs, mes dispersés, apporteront mon offrande.'),
('so',3,11,'crampon1923','En ce jour-là, tu n''auras plus à rougir de toutes tes actions par lesquelles tu as péché contre moi; car alors j''ôterai du milieu de toi ceux qui se réjouissaient avec arrogance; et tu ne t''enorgueilliras plus désormais, sur ma montagne sainte.'),
('so',3,12,'crampon1923','je laisserai au milieu de toi un peuple humble et petit, qui se confiera au nom de Yahweh.'),
('so',3,13,'crampon1923','Le reste d''Israël ne commettra pas l''iniquité, il ne dira pas de mensonge, et il ne se trouvera plus dans leur bouche de langue trompeuse. Car ils paîtront et se reposeront, sans que personne les trouble.'),
('so',3,14,'crampon1923','Pousse des cris de joie, fille de Sion! Pousse des cris d''allégresse, Israël! Réjouis-toi et triomphe de tout ton cœur, fille de Jérusalem!'),
('so',3,15,'crampon1923','Yahweh a retiré les jugements portés contre toi, il a détourné ton ennemi. Le roi d''Israël, Yahweh, est au milieu de toi; tu ne verras plus le malheur!'),
('so',3,16,'crampon1923','En ce jour-là, on dira à Jérusalem: Ne crains point, Sion, que tes mains ne s''affaissent point!'),
('so',3,17,'crampon1923','Yahweh, ton Dieu, est au milieu de toi, un vaillant sauveur! Il fera éclater sa joie à cause de toi; il se taira dans son amour; il tressaillera à cause de toi avec des cris de joie.'),
('so',3,18,'crampon1923','Je rassemblerai ceux qui sont dans la tristesse, privés des fêtes solennelles; car ils étaient des tiens, l''opprobre pèse sur eux.'),
('so',3,19,'crampon1923','Voici que j''en finirai, en ce temps-là, avec tous tes oppresseurs; je sauverai celle qui boite, et je recueillerai la rejetée, et je les ferai glorieux et renommés dans tous les pays où ils ont été honnis.'),
('so',3,20,'crampon1923','En ce temps-là, je vous ramènerai; et, au temps où je vous rassemblerai, je vous ferai renommés et glorieux, chez tous les peuples de la terre, quand je ferai cesser votre captivité à vos yeux, dit Yahweh.'),
('ag',1,1,'crampon1923','La deuxième année du roi Darius, au sixième mois, le premier jour du mois, la parole de Yahweh fut adressée, par l''intermédiaire d''Aggée, le prophète, à Zorobabel, fils de Salathiel, gouverneur de Juda, et à Jésus, fils de Josédec, le grand prêtre, en ces termes:'),
('ag',1,2,'crampon1923','Ainsi parle Yahweh des armées: Ce peuple dit: " Le temps n''est pas venu, le temps pour la maison de Yahweh d''être rebâtie. "'),
('ag',1,3,'crampon1923','Et la parole de Yahweh se fit entendre par l''intermédiaire d''Aggée, le prophète, en ces termes:'),
('ag',1,4,'crampon1923','Est-il temps pour vous autres d''habiter vos maisons lambrissées, quand cette maison-là est en ruines?'),
('ag',1,5,'crampon1923','Et maintenant ainsi parle Yahweh des armées: Considérez attentivement vos voies.'),
('ag',1,6,'crampon1923','Vous avez semé beaucoup et recueilli peu; vous mangez, mais non jusqu''à être rassasiés; vous buvez, mais non jusqu''à votre soûl; vous êtes vêtus, mais non jusqu''à être réchauffés; et le salarié gagne son salaire pour une bourse trouée.'),
('ag',1,7,'crampon1923','Ainsi parle Yahweh des armées: Considérez attentivement vos voies.'),
('ag',1,8,'crampon1923','Allez à la montagne, apportez du bois, et bâtissez la maison; j''en aurai plaisir et gloire, dit Yahweh.'),
('ag',1,9,'crampon1923','Vous comptiez sur beaucoup, et voici que cela se réduit à peu; vous aviez rentré vos récoltes, et j''ai soufflé dessus. A cause de quoi — oracle de Yahweh des armées? A cause de ma maison qui est en ruines, tandis que vous vous empressez chacun pour votre maison.'),
('ag',1,10,'crampon1923','C''est pourquoi les cieux vous ont retenu la rosée, et la terre a retenu ses fruits.'),
('ag',1,11,'crampon1923','J''ai appelé la sécheresse sur la terre et sur les montagnes, sur le blé, sur le vin nouveau, sur l''huile, et sur ce que peut produire le sol, et sur l''homme et sur les bêtes; et sur tout le travail des mains.'),
('ag',1,12,'crampon1923','Alors Zorobabel, fils de Salathiel, et Jésus, fils de Josédec, le grand prêtre, et tout le reste du peuple, écoutèrent la voix de Yahweh, leur Dieu, et les paroles d''Aggée, le prophète, selon la mission qu''il avait reçue de Yahweh, leur Dieu; et le peuple craignit devant Yahweh.'),
('ag',1,13,'crampon1923','Et Aggée, envoyé de Yahweh, sur l''ordre de Yahweh, parla au peuple en ces termes: " Je suis avec vous, — oracle de Yahweh. "'),
('ag',1,14,'crampon1923','Et Yahweh réveilla l''esprit de Zorobabel, fils de Salathiel, gouverneur de Juda, l''esprit de Jésus, fils de Josédec, le grand prêtre, et l''esprit de tout le reste du peuple; et ils vinrent et travaillèrent à la maison de Yahweh des armées, leur Dieu,'),
('ag',1,15,'crampon1923','le vingt-quatrième jour du sixième mois, la deuxième année du roi Darius.'),
('ag',2,1,'crampon1923','Au septième mois le vingt et un du mois, la parole de Yahweh se fit entendre par l''intermédiaire d''Aggée, le prophète, en ces termes:'),
('ag',2,2,'crampon1923','Parle donc à Zorobabel, fils de Salathiel, gouverneur de Juda, à Jésus, fils de Josédec, le grand prêtre, et au reste du peuple, en ces termes:'),
('ag',2,3,'crampon1923','Quel est parmi vous le survivant qui a vu cette maison dans sa gloire première, et en quel état la voyez-vous maintenant? Ne paraît-elle pas à vos yeux comme rien?'),
('ag',2,4,'crampon1923','Et maintenant, courage Zorobabel! — oracle de Yahweh. Courage, Jésus fils de Josédec, grand prêtre! Courage, tout le peuple du pays, — oracle de Yahweh, — et agissez! Car je suis avec vous, — oracle de Yahweh des armées.'),
('ag',2,5,'crampon1923','Il y a l''engagement que j''ai pris avec vous, quand vous êtes sortis d''Égypte; et mon Esprit demeure au milieu de vous: ne craignez rien!'),
('ag',2,6,'crampon1923','Car ainsi parle Yahweh des armées: Une fois encore, et ce sera dans peu, j''ébranlerai les cieux et la terre, la mer et le continent.'),
('ag',2,7,'crampon1923','J''ébranlerai toutes les nations, et les trésors de toutes les nations viendront; et je remplirai de gloire cette maison, dit Yahweh des armées.'),
('ag',2,8,'crampon1923','A moi l''argent, à moi l''or, — oracle de Yahweh des armées.'),
('ag',2,9,'crampon1923','Grande sera la gloire de cette maison; la dernière plus que la première; et en ce lieu je mettrai la paix, — oracle de Yahweh des armées.'),
('ag',2,10,'crampon1923','Le vingt-quatrième jour du neuvième mois, la deuxième année de Darius, la parole de Yahweh se fit entendre par l''intermédiaire d''Aggée, le prophète, en ces termes:'),
('ag',2,11,'crampon1923','Ainsi parle Yahweh des armées: Demande aux prêtres une décision en ces termes:'),
('ag',2,12,'crampon1923','Voici qu''un homme porte dans le pan de son vêtement de la viande consacrée; il touche de ce pan du pain, un mets bouilli, du vin, de l''huile, ou tout autre aliment: sera-ce consacré? Les prêtres répondirent et dirent: Non.'),
('ag',2,13,'crampon1923','— Et Aggée dit: si un homme souillé par le contact d''un mort touche à toutes ces choses, seront-elles souillées? Les prêtres répondirent et dirent: elles seront souillées.'),
('ag',2,14,'crampon1923','— Alors Aggée, reprenant la parole, dit: Tel est ce peuple, telle est cette nation devant moi, — oracle de Yahweh; telles sont toutes les œuvres de leurs mains: ce qu''ils offrent là est souillé.'),
('ag',2,15,'crampon1923','Et maintenant, portez votre attention de ce jour-ci en arrière, avant qu''on n''eut encore mis pierre sur pierre, au temple de Yahweh.'),
('ag',2,16,'crampon1923','Alors, quand on venait à un tas de vingt mesures, il n''y en avait que dix; quand on venait au pressoir pour y puiser cinquante mesures, il n''y en avait que vingt.'),
('ag',2,17,'crampon1923','Je vous ai frappés par la rouille, la nielle et la grêle, j''ai frappé tout le travail de vos mains; et vous n''êtes pas revenus à moi, — oracle de Yahweh.'),
('ag',2,18,'crampon1923','Portez donc votre attention de ce jour-ci en arrière; depuis le vingt-quatrième jour du neuvième mois jusqu''à partir du jour où a été fondé le temple de Yahweh, portez votre attention!'),
('ag',2,19,'crampon1923','La semence était-elle encore dans le grenier? Même la vigne, le figuier, le grenadier et l''olivier n''ont rien produit: mais à partir de ce jour, je bénirai.'),
('ag',2,20,'crampon1923','La parole de Yahweh fut adressée une seconde fois à Aggée le vingt-quatrième jour du mois en ces termes:'),
('ag',2,21,'crampon1923','Parle ainsi à Zorobabel, gouverneur de Juda: J''ébranlerai les cieux et la terre;'),
('ag',2,22,'crampon1923','je renverserai le trône des royaumes, je détruirai la puissance des royaumes des nations; je renverserai les chars et ceux qui les montent; les chevaux avec leurs cavaliers tomberont, par l''épée les uns des autres.'),
('ag',2,23,'crampon1923','En ce jour-là, — oracle de Yahweh des armées, je te prendrai, Zorobabel, fils de Salathiel, mon serviteur, — oracle de Yahweh, et je ferai de toi comme un cachet; car je t''ai élu, — oracle de Yahweh des armées.'),
('za',1,1,'crampon1923','Le huitième mois, en la deuxième année de Darius, la parole de Yahweh fut adressée à Zacharie, fils de Barachie, petit-fils d''Addo, le prophète, en ces termes:'),
('za',1,2,'crampon1923','Yahweh a été dans un grand courroux contre vos pères.'),
('za',1,3,'crampon1923','Et tu leur diras: Ainsi parle Yahweh des armées: Revenez à moi, — oracle de Yahweh des armées, et je reviendrai à vous, — dit Yahweh des armées.'),
('za',1,4,'crampon1923','Ne soyez pas comme vos pères, auxquels ont prêché les premiers prophètes en disant: " Ainsi parle Yahweh des armées: Revenez donc de vos mauvaises voies, et de vos mauvaises actions! " et qui n''ont pas écouté et ne m''ont pas prêté attention, — oracle de Yahweh.'),
('za',1,5,'crampon1923','Vos pères, où sont-ils? Et les prophètes, pouvaient-ils vivre éternellement?'),
('za',1,6,'crampon1923','Mais mes paroles et mes décrets, dont j''avais chargé mes serviteurs les prophètes, n''ont-ils pas atteint vos pères, si bien qu''ils se sont convertis et ont dit: " Comme Yahweh des armées avait résolu d''agir à notre égard, selon nos voies et selon nos actions, ainsi il a agi envers nous. "'),
('za',1,7,'crampon1923','Le vingt-quatrième jour du onzième mois, qui est le mois de Sabath, en la deuxième année de Darius, la parole de Dieu fut adressée à Zacharie, fils de Barachie, petit-fils d''Addo, le prophète, en ces termes:'),
('za',1,8,'crampon1923','J''ai eu une vision pendant la nuit: Voici qu''un homme était monté sur un cheval roux, et il se tenait entre des myrtes dans un lieu ombragé, et il y avait derrière lui des chevaux roux, alezans et blancs.'),
('za',1,9,'crampon1923','Je dis: " Que sont ceux-ci, mon seigneur? " Et l''ange qui parlait avec moi me dit: " Je te ferai voir ce que sont ceux-ci. "'),
('za',1,10,'crampon1923','Et l''homme qui se tenait entre les myrtes prit la parole et dit: " Ce sont ceux que Yahweh a envoyés pour parcourir la terre. "'),
('za',1,11,'crampon1923','Et ils répondirent à l''ange de Yahweh qui se tenait entre les myrtes, et ils dirent: " Nous avons parcouru la terre, et voici que toute la terre est habitée et tranquille. "'),
('za',1,12,'crampon1923','L''ange de Yahweh prit la parole et dit: " Yahweh des armées, jusques à quand n''auras-tu pas pitié de Jérusalem et des villes de Juda contre lesquelles tu es irrité voilà soixante-dix ans? "'),
('za',1,13,'crampon1923','Et Yahweh adressa à l''ange qui parlait avec moi de bonnes paroles, des paroles de consolation.'),
('za',1,14,'crampon1923','Et l''ange qui parlait avec moi me dit: " Proclame ceci: Ainsi parle Yahweh des armées: J''ai été animé d''une grande jalousie pour Jérusalem et pour Sion;'),
('za',1,15,'crampon1923','et je suis animé d''un grand courroux contre les nations qui vivent dans l''opulence! Car moi, j''étais un peu irrité; et elles ont, elles, travaillé à la ruine.'),
('za',1,16,'crampon1923','C''est pourquoi ainsi parle Yahweh: Je reviens à Jérusalem avec compassion; ma maison y sera rebâtie, — oracle de Yahweh des armées, et le cordeau sera étendu sur Jérusalem.'),
('za',1,17,'crampon1923','Proclame encore ceci: Ainsi parle Yahweh des armées: Mes villes regorgeront encore de biens, et Yahweh consolera encore Sion, et choisira encore Jérusalem. "'),
('za',2,1,'crampon1923','Je levai les yeux et je vis: Et voici quatre cornes.'),
('za',2,2,'crampon1923','Et je dis à l''ange qui parlait avec moi: " Que sont celles-ci? " Il me dit: " Ce sont les cornes qui ont dispersé Juda, Israël et Jérusalem. "'),
('za',2,3,'crampon1923','Et Yahweh me fit voir quatre forgerons.'),
('za',2,4,'crampon1923','Et je dis: " Que viennent faire ceux-ci? " Il répondit en ces termes: " Ce sont là les cornes qui ont dispersé Juda, au point que personne ne levait la tête, et ceux-ci sont venus pour les frapper de terreur, pour abattre les cornes des nations qui ont levé la corne contre le pays de Juda pour le disperser.'),
('za',2,5,'crampon1923','Je levai les yeux et je vis: Et voici un homme ayant à la main un cordeau à mesurer.'),
('za',2,6,'crampon1923','Et je dis: " Où vas-tu? " Et il me dit: " Je vais mesurer Jérusalem pour voir quelle en doit être la largeur et quelle en doit être la longueur. "'),
('za',2,7,'crampon1923','Et voici que parut l''ange qui parlait avec moi; et un autre ange apparut, allant à sa rencontre;'),
('za',2,8,'crampon1923','et il lui dit: " Cours! Parle à ce jeune homme en ces termes: C''est comme une ville ouverte que sera habitée Jérusalem, tant il y aura en son sein d''hommes et de bêtes.'),
('za',2,9,'crampon1923','Et moi, je serai pour elle, — oracle de Yahweh, — une muraille de feu à l''entour, et je serai en gloire au milieu d''elle.'),
('za',2,10,'crampon1923','Holà! Holà! Fuyez du pays du septentrion, — oracle de Yahweh, car je vous ai dispersés aux quatre vents du ciel, — oracle de Yahweh.'),
('za',2,11,'crampon1923','Holà! Sion, sauve-toi, toi qui habites chez la fille de Babylone!'),
('za',2,12,'crampon1923','Car ainsi parle Yahweh des armées: Pour sa gloire il m''a envoyé vers les nations qui vous ont pillés; car qui vous touche touche la prunelle de son œil.'),
('za',2,13,'crampon1923','Car voici que j''agite ma main sur elles, et elles seront un butin pour ceux qui leur sont asservis; et vous saurez que Yahweh des armées m''a envoyé.'),
('za',2,14,'crampon1923','Pousse des cris de joie et sois dans l''allégresse, fille de Sion; car voici que je viens et j''habiterai au milieu de toi, — oracle de Yahweh.'),
('za',2,15,'crampon1923','Beaucoup de nations s''attacheront à Yahweh en ce jour-là, et elles seront mon peuple; et j''habiterai au milieu de toi, et tu sauras que Yahweh des armées m''a envoyé vers toi.'),
('za',2,16,'crampon1923','Yahweh possédera Juda comme sa portion sur la terre sainte, et il choisira encore Jérusalem.'),
('za',2,17,'crampon1923','Que toute chair fasse silence devant Yahweh, car il s''est élevé de sa sainte demeure.'),
('za',3,1,'crampon1923','Il me fit voir Jésus, le grand prêtre, debout devant l''ange de Yahweh; et Satan se tenait à sa droite pour lui faire opposition.'),
('za',3,2,'crampon1923','Et Yahweh dit à Satan: " Que Yahweh te réprime, Satan, que Yahweh te réprime, lui qui a choisi Jérusalem! Celui-ci n''est-il pas un tison arraché du feu? "'),
('za',3,3,'crampon1923','Or Jésus était couvert d''habits sales et se tenait devant l''ange.'),
('za',3,4,'crampon1923','Et l''ange prit la parole et parla à ceux qui se tenaient devant lui, en ces termes: " Otez-lui les vêtements sales. " Et il lui dit: " Vois, j''ai fait enlever de dessus toi ton iniquité, et je t''ai revêtu d''habits de fête. "'),
('za',3,5,'crampon1923','Et je dis: " Qu''ils lui mettent une tiare pure sur la tête. " Et ils posèrent la tiare pure sur sa tête, et le revêtirent d''habits; et l''ange de Yahweh se tenait debout.'),
('za',3,6,'crampon1923','Et l''ange de Yahweh fit à Jésus cette déclaration:'),
('za',3,7,'crampon1923','Ainsi parle Yahweh des armées: Si tu marches dans mes voies, et si tu es fidèle à mon ministère, toi aussi tu gouverneras ma maison, et tu garderas mes parvis; et je te donnerai libre accès parmi ceux qui se tiennent ici.'),
('za',3,8,'crampon1923','Ecoute donc, Jésus, grand prêtre, toi et tes collègues qui siègent devant toi: — car ce sont des hommes de présage; — Voici que je vais faire venir mon serviteur Germe.'),
('za',3,9,'crampon1923','Car voici la pierre que j''ai placée devant Jésus; sur cette unique pierre il y a sept yeux; voici que je vais sculpter sa sculpture, — oracle de Yahweh des armées, et j''enlèverai l''iniquité de ce pays en un seul jour!'),
('za',3,10,'crampon1923','En ce jour-là, — oracle de Yahweh des armées, vous vous inviterez les uns les autres, sous la vigne et sous le figuier.'),
('za',4,1,'crampon1923','L''ange qui parlait avec moi revint, et il me réveilla comme un homme qui se réveille de son sommeil.'),
('za',4,2,'crampon1923','Et il me dit: " Que vois-tu? " Je répondis: " J''ai vu, et voici un candélabre tout en or, avec son bassin à son sommet, portant ses sept lampes avec sept conduits pour les lampes qui sont au sommet du candélabre.'),
('za',4,3,'crampon1923','Et deux oliviers sont à côté de lui, l''un à droite du bassin, et l''autre à sa gauche. "'),
('za',4,4,'crampon1923','Et je repris la parole et je dis à l''ange qui parlait avec moi: " Que sont ces choses, mon seigneur? "'),
('za',4,5,'crampon1923','L''ange qui parlait avec moi me répondit et me dit: " Ne sais-tu pas ce que sont ces choses? " Je répondis: " Non, mon seigneur. "'),
('za',4,6,'crampon1923','Et il reprit et me dit: Ceci est la parole de Yahweh à Zorobabel, savoir: " Ni par une armée, ni par la force, mais par mon Esprit, dit Yahweh des armées.'),
('za',4,7,'crampon1923','Qui es-tu, grande montagne, devant Zorobabel? Tu seras une plaine. Et il élèvera la pierre du sommet au milieu des acclamations: Grâce, grâce sur elle! "'),
('za',4,8,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('za',4,9,'crampon1923','" Les mains de Zorobabel ont fondé cette maison, et ses mains l''achèveront, et tu sauras que Yahweh des armées m''a envoyé vers vous.'),
('za',4,10,'crampon1923','Car qui mépriserait le temps des petites choses? Ils se réjouiront en voyant le fil à plomb dans la main de Zorobabel. " " Ces sept lampes sont les yeux de Yahweh, qui parcourent toute la terre. "'),
('za',4,11,'crampon1923','Je repris la parole et je lui dis: " Que sont ces deux oliviers à la droite du candélabre et à sa gauche? "'),
('za',4,12,'crampon1923','Je repris une seconde fois la parole et lui dis: " Que sont ces deux grappes d''olivier qui se trouvent auprès des deux entonnoirs d''or d''où l''or découle? "'),
('za',4,13,'crampon1923','Il me parla en ces termes: " Ne sais-tu pas ce que c''est? " Je répondis: " Non, mon seigneur. "'),
('za',4,14,'crampon1923','Et il me dit: " Ce sont les deux fils de l''onction qui se tiennent prés du Seigneur de toute la terre. "'),
('za',4,15,'crampon1923',''),
('za',4,16,'crampon1923',''),
('za',5,1,'crampon1923','Je levai de nouveau les yeux et je vis: Et voici un rouleau qui volait.'),
('za',5,2,'crampon1923','Il me dit: " Que vois-tu? " Je dis: " Je vois un rouleau qui vole; sa longueur est de vingt coudées et sa largeur de dix coudées. "'),
('za',5,3,'crampon1923','Et il me dit: C''est la malédiction qui sort sur la face de tout le pays; car, selon ce qui y est écrit, quiconque dérobe sera balayé d''ici, et, selon ce qui y est écrit, quiconque jure sera balayé d''ici.'),
('za',5,4,'crampon1923','Je l''ai déchaînée, — oracle de Yahweh des armées, — et elle arrivera à la maison du voleur et à la maison de celui qui jure par mon nom en mentant; elle se logera au milieu de sa maison et la consumera, le bois et les pierres.'),
('za',5,5,'crampon1923','L''ange qui parlait avec moi parut et me dit: " Lève les yeux et regarde ce qui apparaît. " Je dis: " Qu''est-ce? "'),
('za',5,6,'crampon1923','Il dit: " C''est l''épha qui apparaît ". Et il ajouta: " C''est à cela que s''attache leur regard dans tout le pays. "'),
('za',5,7,'crampon1923','Et voici qu''un disque de plomb fut soulevé, et il y avait une femme assise au milieu de l''épha.'),
('za',5,8,'crampon1923','Il dit: " Cette femme est l''improbité. " Et il la repoussa au milieu de l''épha et jeta sur l''ouverture de celui-ci la masse de plomb.'),
('za',5,9,'crampon1923','Et je levai les yeux, et je vis. Et voici que deux femmes apparurent; du vent soufflait dans leurs ailes; elles avaient des ailes pareilles aux ailes de la cigogne. Et elles enlevèrent l''épha entre le ciel et la terre.'),
('za',5,10,'crampon1923','Je dis à l''ange qui parlait avec moi: " Où emportent-elles l''épha? "'),
('za',5,11,'crampon1923','Il me répondit: " Elles l''emportent pour lui bâtir une maison au pays de Sennaar; et, quand elle aura été fondée, on le placera là en son lieu.'),
('za',6,1,'crampon1923','Je levai de nouveau les yeux et je vis: Et voici quatre chars sortant d''entre les deux montagnes, et les montagnes étaient des montagnes d''airain.'),
('za',6,2,'crampon1923','Au premier char il y avait des chevaux roux, au second char des chevaux noirs,'),
('za',6,3,'crampon1923','au troisième char des chevaux blancs, et au quatrième char des chevaux tachetés, vigoureux.'),
('za',6,4,'crampon1923','Je pris la parole et je dis à l''ange qui parlait avec moi: " Que sont ceux-ci, mon seigneur? "'),
('za',6,5,'crampon1923','L''ange répondit et me dit: " Ce sont les quatre vents du ciel qui viennent de se tenir devant le Seigneur de toute la terre. "'),
('za',6,6,'crampon1923','Le char auquel il y a des chevaux noirs sortit vers le pays du septentrion; les blancs sortirent après eux, et les tachetés sortirent vers le pays du midi.'),
('za',6,7,'crampon1923','Les coursiers vigoureux sortirent et ils demandèrent à partir pour parcourir la terre. L''ange leur dit: " Allez, parcourez la terre! " Et ils parcoururent la terre.'),
('za',6,8,'crampon1923','Et il m''appela et il me parla en ces termes: " Vois, ceux qui sont partis vers le pays du septentrion ont apaisé mon esprit dans le pays du septentrion ".'),
('za',6,9,'crampon1923','La parole de Yahweh me fut adressée en ces termes:'),
('za',6,10,'crampon1923','Prends de la main des exilés, de Holdaï, de Tobia et d''Idaïa, — tu iras toi-même en ce jour-là, tu iras dans la maison de Josias, chez qui ils se sont rendus en arrivant de Babylone, —'),
('za',6,11,'crampon1923','et tu prendras de l''argent et de l''or, et tu feras des couronnes, et tu les poseras sur la tête de Jésus, fils de Josédec, le grand prêtre.'),
('za',6,12,'crampon1923','Tu lui parleras en ces termes: Ainsi parle Yahweh des armées: Voici un homme dont le nom est Germe; il lèvera en son lieu, et il bâtira le temple de Yahweh.'),
('za',6,13,'crampon1923','Il bâtira le temple de Yahweh, et sera revêtu de majesté; il sera assis en souverain sur son trône, et il sera prêtre sur son trône, et entre eux deux il y aura un conseil de paix.'),
('za',6,14,'crampon1923','Et la couronne sera pour Hélem, pour Tobia, pour Idaïa et pour Hen, fils de Sophonie, en souvenir dans le temple de Yahweh.'),
('za',6,15,'crampon1923','Des hommes qui sont au loin viendront et travailleront à la construction du temple de Yahweh, et vous saurez que Yahweh des armées m''a envoyé vers vous. Cela arrivera si vous obéissez fidèlement à la voix de Yahweh.'),
('za',7,1,'crampon1923','La quatrième année du roi Darius, la parole de Yahweh fut adressée à Zacharie, au quatrième jour du neuvième mois, en Casleu.'),
('za',7,2,'crampon1923','Béthel avait envoyé Sarasar et Rogommélech, avec ses gens, pour implorer Yahweh,'),
('za',7,3,'crampon1923','pour parler aux prêtres de la maison de Yahweh des armées et aux prophètes, en ces termes: " Dois-je pleurer au cinquième mois, et faire abstinence, comme j''ai fait depuis tant d''années? "'),
('za',7,4,'crampon1923','La parole de Yahweh des armées me fut adressée en ces termes:'),
('za',7,5,'crampon1923','Parle à tout le peuple du pays et aux prêtres, en ces termes: Quand vous avez jeûné et célébré le deuil au cinquième et au septième mois, et cela depuis soixante-dix ans, est-ce pour moi que vous jeûniez?'),
('za',7,6,'crampon1923','Et quand vous mangez et buvez, n''est-ce pas vous qui mangez et vous qui buvez?'),
('za',7,7,'crampon1923','N''y a-t-il pas les paroles qu''a proclamées Yahweh par l''intermédiaire des anciens prophètes, quand Jérusalem était habitée et tranquille, avec ses villes autour d''elle, et que le négéb et la sephélah étaient habités?'),
('za',7,8,'crampon1923','La parole de Yahweh fut adressée à Zacharie en ces termes:'),
('za',7,9,'crampon1923','Ainsi parlait Yahweh des armées en disant: " Rendez la justice selon la vérité; pratiquez la miséricorde et la compassion chacun envers son frère;'),
('za',7,10,'crampon1923','n''opprimez pas la veuve et l''orphelin, l''étranger et le pauvre, et me méditez pas l''un contre l''autre le mal dans vos cœurs. "'),
('za',7,11,'crampon1923','Mais ils ont refusé d''écouter, ils ont prêté une épaule rebelle et endurci leurs oreilles pour ne pas entendre.'),
('za',7,12,'crampon1923','Ils ont rendu leur cœur tel que le diamant, pour ne pas entendre la loi et les paroles que Yahweh des armées leur adressait par son Esprit, par l''intermédiaire des anciens prophètes. Aussi y eut-il une violente indignation de la part de Yahweh des armées.'),
('za',7,13,'crampon1923','Et il arriva: De même qu''il avait appelé sans qu''ils écoutassent, " de même ils appelleront sans que je les écoute, dit Yahweh des armées.'),
('za',7,14,'crampon1923','Je les disperserai parmi toutes les nations qu''ils ne connaissent pas, et derrière eux le pays restera désolé, sans personne qui passe ou revienne. " D''un pays de délices ils ont fait un désert.'),
('za',8,1,'crampon1923','La parole de Yahweh des armées se fit entendre en ces termes:'),
('za',8,2,'crampon1923','Ainsi parle Yahweh des armées: Je suis animé pour Sion d''un grand zèle; je suis animé pour elle d''une grande fureur.'),
('za',8,3,'crampon1923','Ainsi parle Yahweh: Je suis revenu à Sion et je veux habiter au milieu de Jérusalem; Jérusalem sera appelée la ville de vérité, et la montagne de Yahweh des armées, montagne de sainteté.'),
('za',8,4,'crampon1923','Ainsi parle Yahweh des armées: Il y aura de nouveau des vieillards et des femmes âgées assis sur les places de Jérusalem, chacun son bâton à la main, à cause du grand nombre de leurs jours.'),
('za',8,5,'crampon1923','Les places de la ville seront remplies de jeunes garçons et de jeunes filles jouant sur ses places.'),
('za',8,6,'crampon1923','Ainsi parle Yahweh des armées: Si cela paraît merveilleux aux yeux du reste de ce peuple, en ces jours-là, cela sera-t-il merveilleux aussi à mes yeux, — oracle de Yahweh des armées?'),
('za',8,7,'crampon1923','Ainsi parle Yahweh des armées: Voici que je vais délivrer mon peuple du pays de l''orient et du pays du soleil couchant.'),
('za',8,8,'crampon1923','Je les amènerai et ils habiteront au milieu de Jérusalem; ils seront mon peuple, et moi je serai leur Dieu, avec vérité et justice.'),
('za',8,9,'crampon1923','Ainsi parle Yahweh des armées: Que vos mains se fortifient, vous qui entendez en ces jours ces paroles de la bouche des prophètes qui ont parlé au jour où fut fondée la maison de Yahweh des armées, pour que le temple soit rebâti.'),
('za',8,10,'crampon1923','Car, avant ces jours-là, il n''y avait point de salaire pour les hommes, point de salaire pour le bétail, point de sûreté contre l''ennemi pour ceux qui sortaient et entraient, et j''avais lâché tous les hommes les uns contre les autres.'),
('za',8,11,'crampon1923','Mais maintenant, je ne suis plus, moi, à l''égard du reste de ce peuple comme aux jours d''autrefois, — oracle de Yahweh des armées.'),
('za',8,12,'crampon1923','Car la semence prospérera, la vigne donnera son fruit, la terre donnera ses produits, les cieux donneront leur rosée, et je mettrai le reste de ce peuple en possession de toutes ces choses.'),
('za',8,13,'crampon1923','Et il arrivera: comme vous avez été malédiction parmi les nations, maison de Juda et maison d''Israël, ainsi je vous délivrerai, et vous serez bénédiction! Ne craignez point, que vos mains se fortifient!'),
('za',8,14,'crampon1923','Car ainsi parle Yahweh des armées: Comme J''ai eu le dessein de vous faire du mal lorsque vos pères provoquaient ma colère, dit Yahweh des armées, et que je ne m''en suis pas repenti,'),
('za',8,15,'crampon1923','ainsi j''ai en ces jours-ci, au contraire, le dessein de faire du bien à Jérusalem et à la maison de Juda; ne craignez point!'),
('za',8,16,'crampon1923','Voici les paroles que vous observerez: Dites la vérité, chacun à votre prochain; rendez la justice dans vos portes selon la vérité et pour la paix;'),
('za',8,17,'crampon1923','ne méditez pas dans vos cœurs le mal les uns des autres; et n''aimez pas le faux serment; car ce sont là toutes choses que je hais, — oracle de Yahweh.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('za',8,18,'crampon1923','La parole de Yahweh des armées me fut adressée en ces termes:'),
('za',8,19,'crampon1923','Ainsi parle Yahweh des armées: Le jeûne du quatrième mois, le jeûne du cinquième, le jeune du septième et le jeûne du dixième mois seront changés pour la maison de Juda en réjouissance et en allégresse, et en solennités joyeuses.'),
('za',8,20,'crampon1923','Ainsi parle Yahweh des armées: Il viendra encore des peuples et des habitants d''un grand nombre de villes.'),
('za',8,21,'crampon1923','Les habitants de l''une iront à l''autre, en disant: " Allons, allons implorer Yahweh et chercher Yahweh des armées! " — " Moi aussi, je veux aller! "'),
('za',8,22,'crampon1923','Des peuples nombreux et de puissantes nations viendront chercher Yahweh des armées à Jérusalem et implorer Yahweh.'),
('za',8,23,'crampon1923','Ainsi parle Yahweh des armées: En ces jours-là, dix hommes de toutes les langues des nations saisiront, oui, saisiront le pan de la robe d''un Juif en disant: Nous voulons aller aussi avec vous, car nous avons appris que Dieu est avec vous. "'),
('za',9,1,'crampon1923','Sentence Parole de Yahweh contre le pays d''Hadrach; et à Damas sera son séjour, — car Yahweh a l''œil sur les hommes, et sur toutes les tribus d''Israël; —'),
('za',9,2,'crampon1923','et aussi à Hamath, voisine de Damas, à Tyr, ainsi qu''à Sidon, parce que leur sagesse est grande.'),
('za',9,3,'crampon1923','Tyr s''est construit une citadelle, elle a amassé l''argent comme la poussière, et l''or comme la boue des rues.'),
('za',9,4,'crampon1923','Voici que le Seigneur s''en emparera; il frappera sur mer sa puissance, et elle-même sera dévorée par le feu.'),
('za',9,5,'crampon1923','Ascalon le verra et craindra; Gaza aussi, et elle se tordra de douleur; Accaron aussi, car son espérance est confondue. Il n''y aura plus de roi à Gaza, et Ascalon ne sera plus habitée.'),
('za',9,6,'crampon1923','Un vil étranger s''installera à Azoth, et je détruirai l''orgueil des Philistins.'),
('za',9,7,'crampon1923','J''ôterai son sang de sa bouche, et ses abominations d''entre ses dents; et lui aussi sera un reste pour notre Dieu; il sera comme un chef en Juda; et Accaron sera comme le Jébuséen.'),
('za',9,8,'crampon1923','Je camperai autour de ma maison pour la défendre; contre toute armée, tout allant et venant; et il ne passera plus chez eux d''oppresseur, car maintenant j''ai vu de mes yeux.'),
('za',9,9,'crampon1923','Tressaille d''une grande joie, fille de Sion! Pousse des cris d''allégresse, fille de Jérusalem! Voici que ton Roi vient à toi; il est juste, lui, et protégé de Dieu; il est humble; monté sur un âne, et sur un poulain, petit d''une ânesse.'),
('za',9,10,'crampon1923','Je retrancherai d''Ephraïm les chars de guerre, et de Jérusalem les chevaux, et l''arc du combat sera détruit. Il parlera de paix aux nations; sa domination s''étendra d''une mer à l''autre, du fleuve jusqu''aux extrémités de la terre.'),
('za',9,11,'crampon1923','Pour toi aussi, à cause du sang de ton alliance, je retirerai tes captifs de la fosse sans eau.'),
('za',9,12,'crampon1923','Revenez au lieu fort, captifs d''espérance! Aujourd''hui encore je le déclare: je te rendrai au double.'),
('za',9,13,'crampon1923','Car je bande pour moi Juda, et sur l''arc je place Ephraïm; j''exciterai tes fils, ô Sion, contre tes fils, ô Javan, et je ferai de toi comme une épée de vaillant.'),
('za',9,14,'crampon1923','Yahweh apparaîtra au-dessus d''eux, sa flèche partira comme l''éclair; le Seigneur Yahweh sonnera de la trompette, et s''avancera dans les ouragans du midi.'),
('za',9,15,'crampon1923','Yahweh des armées les protégera; Ils dévoreront, ils fouleront aux pieds les pierres de fronde! Ils boiront, ils se démèneront comme pris de vin, et ils seront remplis comme la coupe des sacrifices, comme les cornes de l''autel.'),
('za',9,16,'crampon1923','Yahweh leur Dieu sera leur salut en ce jour-là, le salut du troupeau qui est son peuple; ils seront comme des pierres de diadème, qui brilleront dans son pays.'),
('za',9,17,'crampon1923','Quelle prospérité, quelle beauté que la leur! Le froment fera croître les jeunes gens, et le vin nouveau les vierges.'),
('za',10,1,'crampon1923','Demandez à Yahweh de la pluie au printemps. C''est Yahweh qui fait les éclairs; il leur donnera une pluie abondante, à chacun de l''herbe dans son champ.'),
('za',10,2,'crampon1923','Car les théraphim ont parlé futilité, et les devins ont eu des visions de mensonge; ils débitent de vains songes, et donnent de fausses consolations. C''est pourquoi ils sont partis comme un troupeau; ils ont été opprimés, faute de berger.'),
('za',10,3,'crampon1923','Ma colère s''est enflammée contre les bergers, et je châtierai les boucs! Car Yahweh des armées visite son troupeau, la maison de Juda, et il en fait son cheval d''honneur dans la bataille.'),
('za',10,4,'crampon1923','De lui viendra la troupe, de lui le pieu, de lui l''arc de guerre; de lui sortiront tous les chefs ensemble.'),
('za',10,5,'crampon1923','Ils seront comme des héros, foulant la boue des chemins dans la bataille; ils combattront, car Yahweh sera avec eux, et ils couvriront de honte ceux qui sont montés sur des chevaux.'),
('za',10,6,'crampon1923','Je fortifierai la maison de Juda, et je sauverai la maison de Joseph; je les rétablirai, car j''ai compassion d''eux, et ils seront comme si je ne les avais pas rejetés. Car moi, je suis Yahweh, leur Dieu, et je les exaucerai.'),
('za',10,7,'crampon1923','Ceux d''Ephraïm seront comme des héros, et leur cœur sera joyeux comme par le vin; leurs fils le verront et se réjouiront, et leur cœur tressaillira en Yahweh.'),
('za',10,8,'crampon1923','Je sifflerai après eux, et je les rassemblerai, car je les ai rachetés, et ils se multiplieront comme ils s''étaient multipliés.'),
('za',10,9,'crampon1923','Quand je les aurai répandus parmi les peuples, et qu''ils se souviendront de moi dans les pays lointains, ils vivront avec leurs enfants et ils reviendront.'),
('za',10,10,'crampon1923','Je les ramènerai du pays d''Egypte, et je les rassemblerai d''Assyrie, et je les ferai venir au pays de Galaad et au Liban, et il ne se trouvera pas assez d''espace pour eux.'),
('za',10,11,'crampon1923','Il passera par la mer, mer de détresse, il frappera les flots dans la mer, et toutes les profondeurs du fleuve seront mises à sec. L''orgueil de l''Assyrie sera abattu, et le sceptre de l''Egypte sera ôté.'),
('za',10,12,'crampon1923','Je les fortifierai en Yahweh, et ils marcheront en son nom, — oracle de Yahweh.'),
('za',11,1,'crampon1923','Ouvre tes portes, Liban, et que le feu dévore tes cèdres!'),
('za',11,2,'crampon1923','Lamente-toi, cyprès, car le cèdre est tombé, les arbres magnifiques ont été ravagés! Lamentez-vous, chênes de Basan, car la forêt impénétrable est abattue!'),
('za',11,3,'crampon1923','On entend la lamentation des bergers, parce que leur gloire est ruinée; on entend le rugissement des lionceaux, car ce qui faisait l''orgueil du Jourdain a été ruiné.'),
('za',11,4,'crampon1923','Ainsi parle Yahweh, mon Dieu: " Sois pasteur du troupeau de carnage'),
('za',11,5,'crampon1923','que leurs acheteurs tuent impunément, et dont les vendeurs disent: Béni soit Yahweh! je m''enrichis, — et que leurs bergers n''épargnent point.'),
('za',11,6,'crampon1923','Car je n''épargnerai plus les habitants du pays, — oracle de Yahweh; voici que moi-même je livrerai les hommes aux mains les uns des autres et aux mains de leur roi; ils dévasteront le pays, et je ne délivrerai pas de leur main. "'),
('za',11,7,'crampon1923','Alors je me fis pasteur du troupeau de carnage, et aussi des plus misérables du troupeau. Je pris deux houlettes; je nommai l''une Grâce, et je nommai l''autre Lien, et je fis paître le troupeau.'),
('za',11,8,'crampon1923','Je retranchai les trois pasteurs en un seul mois. Et je perdis patience avec les brebis, et elles aussi étaient lasses de moi.'),
('za',11,9,'crampon1923','Et je dis: " Je ne vous paîtrai plus; que celle qui meurt, meure; que celle qui disparaît, disparaisse, et que celles qui restent se dévorent les unes les autres! "'),
('za',11,10,'crampon1923','Je pris ma houlette Grâce et je la brisai, pour rompre mon alliance que j''avais faite avec tous les peuples.'),
('za',11,11,'crampon1923','Elle fut brisée en ce jour-là, et ainsi les plus misérables du troupeau, qui faisaient cas de moi, connurent que telle était la parole de Yahweh.'),
('za',11,12,'crampon1923','Et je leur dis: " Si vous le trouvez bon, donnez-moi mon salaire; sinon, n''en faites rien. " Et ils pesèrent mon salaire, trente sicles d''argent.'),
('za',11,13,'crampon1923','Et Yahweh me dit: " Jette-le au potier, ce prix magnifique auquel j''ai été estimé par eux! " Et je pris les trente sicles d''argent et je les jetai dans la maison de Yahweh, au potier.'),
('za',11,14,'crampon1923','Je brisai ensuite ma seconde houlette Lien, pour rompre la fraternité entre Juda et Israël.'),
('za',11,15,'crampon1923','Yahweh me dit: " Prends maintenant l''attirail d''un nouveau pasteur.'),
('za',11,16,'crampon1923','Car voici que moi-même je vais susciter sur le pays un berger qui n''aura pas souci des brebis qui se perdent, qui ne cherchera pas ce qui est dispersé, qui ne guérira pas celle qui est blessée; il ne nourrira pas celle qui est saine, il mangera la chair de celle qui est grasse et fendra leur sabot.'),
('za',11,17,'crampon1923','Malheur au pasteur de néant qui délaisse le troupeau! Que le glaive soit sur son bras et sur son œil droit! Que son bras se dessèche,et que son œil droit s''éteigne! "'),
('za',12,1,'crampon1923','Sentence. Parole de Yahweh sur Israël. Oracle de Yahweh qui a étendu les cieux et fondé la terre, et qui a formé l''esprit de l''homme au-dedans de lui:'),
('za',12,2,'crampon1923','Voici que moi, je ferai de Jérusalem un seuil d''ébranlement, pour tous les peuples d''alentour; et cela sera aussi pour Juda, quand on assiégera Jérusalem.'),
('za',12,3,'crampon1923','Et il arrivera en ce jour-là: je ferai de Jérusalem une pierre à soulever, pour tous les peuples; quiconque la soulèvera sera tout meurtri, et toutes les nations de la terre s''assembleront contre elle.'),
('za',12,4,'crampon1923','En ce jour-là, — oracle de Yahweh, je frapperai de terreur tous les chevaux, et de délire leurs cavaliers; j''aurai les yeux ouverts sur la maison de Juda, mais je frapperai d''aveuglement tous les chevaux des peuples.'),
('za',12,5,'crampon1923','Et les chefs de Juda diront en leur cœur: " Les habitants de Jérusalem sont une force pour moi, par Yahweh des armées, leur Dieu. "'),
('za',12,6,'crampon1923','En ce jour-là, je ferai des chefs de Juda comme un brasier ardent dans du bois, comme une torche enflammée dans une gerbe; et ils dévoreront à droite et à gauche tous les peuples d''alentour, et Jérusalem restera encore à sa place, à Jérusalem.'),
('za',12,7,'crampon1923','Yahweh sauvera les tentes de Juda en premier lieu, afin que l''orgueil de la maison de David et l''orgueil des habitants de Jérusalem ne s''élève pas au-dessus de Juda.'),
('za',12,8,'crampon1923','En ce jour-là, Yahweh établira un rempart autour des habitants de Jérusalem, et celui qui chancelle parmi eux sera en ce jour-là comme David, et la maison de David sera comme Dieu, comme l''ange de Yahweh devant eux.'),
('za',12,9,'crampon1923','Et il arrivera en ce jour-là: Je m''appliquerai à détruire tous les peuples qui viendront contre Jérusalem.'),
('za',12,10,'crampon1923','Et je répandrai sur la maison de David et sur l''habitant de Jérusalem un esprit de grâce et de supplication, et ils tourneront les yeux vers moi qu''ils ont transpercé. Et ils feront le deuil sur lui, comme on fait le deuil sur un fils unique; ils pleureront amèrement sur lui, comme on pleure amèrement sur un premier-né.'),
('za',12,11,'crampon1923','En ce jour-là, le deuil sera grand à Jérusalem, comme le deuil d''Adadremmon dans la vallée de Mageddo.'),
('za',12,12,'crampon1923','Le pays sera dans le deuil, chaque famille à part; la famille de la maison de David à part et ses femmes à part; la famille de la maison de Nathan à part et ses femmes à part;'),
('za',12,13,'crampon1923','la famille de la maison de Lévi à part et ses femmes à part; la famille de Séméï à part et ses femmes à part;'),
('za',12,14,'crampon1923','toutes les familles qui restent, chaque famille à part et ses femmes à part.'),
('za',13,1,'crampon1923','En ce jour-là, il y aura une source ouverte à la maison de David et aux habitants de Jérusalem pour laver le péché et la souillure.'),
('za',13,2,'crampon1923','Et il arrivera en ce jour-là, — oracle de Yahweh des armées: J''abolirai du pays les noms des idoles, et on n''en fera plus mention; et j''ôterai aussi du pays les prophètes et l''esprit d''impureté.'),
('za',13,3,'crampon1923','Et si quelqu''un prophétise encore, son père et sa mère, qui l''ont engendré, lui diront: " Tu ne vivras pas, car tu as dit des mensonges, au nom de Yahweh! " Et son père et sa mère, qui l''ont engendré, le transperceront pendant qu''il prophétisera.'),
('za',13,4,'crampon1923','Et il arrivera en ce jour-là: Les prophètes auront honte, chacun de sa vision quand il prophétisera, et ils ne revêtiront plus le manteau de poil, en vue de mentir.'),
('za',13,5,'crampon1923','Tel dira: " Je ne suis pas prophète, moi; moi, je suis un homme qui cultive la terre, car un homme m''a acheté dès ma jeunesse. "'),
('za',13,6,'crampon1923','Et on lui dira: " Qu''est-ce que ces blessures à tes mains? " et il répondra: " J''ai reçu ces coups dans la maison de mes amis. "'),
('za',13,7,'crampon1923','Epée, réveille-toi contre mon pasteur, contre l''homme qui est mon compagnon, — oracle de Yahweh des armées! Frappe le pasteur, et que le troupeau soit dispersé. Et je ramènerai ma main sur les petit.'),
('za',13,8,'crampon1923','Et dans tout le pays, — oracle de Yahweh, — les deux tiers seront exterminés, périront, et l''autre tiers y sera laissé.'),
('za',13,9,'crampon1923','Je ferai entrer ce tiers dans le feu et je l''épurerai comme on épure l''argent, je l''éprouverai comme on éprouve l''or. Lui, il invoquera mon nom, et moi je l''exaucerai. Je dirai: " C''est mon peuple! " Et il dira: " Yahweh est mon Dieu! "'),
('za',14,1,'crampon1923','Voici qu''un jour vient pour Yahweh, et tes dépouilles seront partagées au milieu de toi.'),
('za',14,2,'crampon1923','J''assemblerai toutes les nations devant Jérusalem pour la guerre; et la ville sera prise, les maisons seront pillées, les femmes violées, et la moitié de la ville partira en captivité; mais le reste du peuple ne sera pas retranché de la ville.'),
('za',14,3,'crampon1923','Et Yahweh sortira et combattra contre ces nations, comme lorsqu''il combat, en un jour de bataille.'),
('za',14,4,'crampon1923','Ses pieds se poseront en ce jour-là sur la montagne des Oliviers, qui est en face de Jérusalem, du coté de l''orient; et le mont des Oliviers se fendra par le milieu, vers l''orient et vers l''occident, en une très grande vallée; une moitié de la montagne reculera vers le septentrion, et l''autre moitié vers le midi;'),
('za',14,5,'crampon1923','et vous fuirez par la vallée de mes montagnes, car la vallée des montagnes s''étendra jusqu''à Atsal. Vous fuirez comme vous avez fui devant le tremblement de terre, aux jours d''Osias, roi de Juda. Et Yahweh, mon Dieu, viendra, tous les saints avec toi.'),
('za',14,6,'crampon1923','Et il arrivera en ce jour-là: Il n''y aura point de lumière, mais du froid et de la glace.'),
('za',14,7,'crampon1923','Ce sera un jour unique, et il est connu de Yahweh; et il ne sera ni jour ni nuit, et au temps du soir la lumière sera.'),
('za',14,8,'crampon1923','Et il arrivera en ce jour-là: Des eaux vives sortiront de Jérusalem, moitié vers la mer orientale, moitié vers la mer occidentale; il en sera ainsi en été comme en hiver.'),
('za',14,9,'crampon1923','Et Yahweh deviendra roi sur toute la terre; en ce jour-là, Yahweh sera unique, et son nom unique.'),
('za',14,10,'crampon1923','Tout le pays sera transformé en plaine, depuis Gabaa jusqu''à Remmon, au midi de Jérusalem. Et Jérusalem sera élevée et occupera son lieu, de la porte de Benjamin jusqu''à l''emplacement de la première porte, jusqu''à la porte de l''Angle, et depuis la tour de Hananéel jusqu''aux pressoirs du roi.'),
('za',14,11,'crampon1923','On y habitera, et il n''y aura plus d''anathème; et Jérusalem reposera en sécurité.'),
('za',14,12,'crampon1923','Voici quelle sera la plaie dont Yahweh frappera tous les peuples qui auront combattu contre Jérusalem: il fera tomber leur chair en pourriture pendant qu''ils seront sur pied; leurs yeux pourriront dans leurs orbites, et leur langue pourrira dans leur bouche.'),
('za',14,13,'crampon1923','Et il arrivera en ce jour-là: Il y aura de par Yahweh un grand désarroi parmi eux; chacun saisira la main de son frère, et ils lèveront la main les uns sur les autres.'),
('za',14,14,'crampon1923','Juda aussi combattra contre Jérusalem. Et les richesses de toutes les nations d''alentour seront réunies, de l''or, de l''argent et des vêtements en très grande quantité.'),
('za',14,15,'crampon1923','Et la plaie qui frappera les chevaux, les mulets, les chameaux, les ânes et toutes les bêtes qui seront dans ces camps sera semblable à cette plaie-là.'),
('za',14,16,'crampon1923','Tous ceux qui resteront, de toutes les nations qui seront venues contre Jérusalem, monteront chaque année pour se prosterner devant le Roi Yahweh des armées, et pour célébrer la fête des Tabernacles.'),
('za',14,17,'crampon1923','Celle des familles de la terre qui ne montera pas à Jérusalem pour se prosterner devant le Roi Yahweh des armées, il n''y aura pas sur elle de pluie.'),
('za',14,18,'crampon1923','Et si la famille d''Egypte ne monte pas et ne vient pas, il n''y aura pas non plus de pluie sur elle; elle sera frappée de la plaie dont Yahweh frappera les nations qui ne monteront pas pour célébrer la fête des Tabernacles.'),
('za',14,19,'crampon1923','Telle sera la punition de l''Egypte, et la punition de toutes les nations qui ne monteront pas pour célébrer la fête des Tabernacles.'),
('za',14,20,'crampon1923','En ce jour-là, il y aura sur les clochettes des chevaux: " Sainteté à Yahweh "; et les chaudières, dans la maison de Yahweh, seront comme les coupes devant l''autel.'),
('za',14,21,'crampon1923','Et toute chaudière dans Jérusalem et dans Juda sera chose consacrée à Yahweh des armées. Et tous ceux qui sacrifieront viendront en prendre et y cuiront leurs viandes, et il n''y aura plus de Chananéen dans la maison de Yahweh des armées, en ce jour-là.'),
('ml',1,1,'crampon1923','Sentence. Parole de Yahweh à Israël par l''intermédiaire de Malachie.'),
('ml',1,2,'crampon1923','Je vous ai aimés, dit Yahweh; et vous dites: " En quoi nous as-tu aimés? " — Esaü n''est-il pas frère de Jacob? — oracle de Yahweh; et j''ai aimé Jacob,'),
('ml',1,3,'crampon1923','mais j''ai haï Esaü; j''ai fait de ses montagnes une solitude, et livré son héritage aux chacals du désert.'),
('ml',1,4,'crampon1923','Si Edom dit: " Nous avons été détruits, mais nous rebâtirons les ruines, " — ainsi parle Yahweh des armées: Eux, ils bâtiront, et moi, je renverserai; et l''on dira d''eux: " Territoire d''iniquité, peuple contre lequel Yahweh est irrité pour toujours. "'),
('ml',1,5,'crampon1923','Vos yeux le verront, et vous vous direz: " Que Yahweh soit glorifié sur le territoire d''Israël! "'),
('ml',1,6,'crampon1923','Un fils honore son père, et un serviteur son maître. Or, si je suis père, moi, où est l''honneur qui m''appartient? Et si je suis Seigneur, où est la crainte qui m''est due? dit Yahweh des armées, à vous, prêtres, qui méprisez mon nom. Vous dites: " En quoi avons-nous méprisé ton nom? "'),
('ml',1,7,'crampon1923','En ce que vous apportez sur mon autel un pain souillé. Et vous dites: " En quoi t''avons-nous souillé? " En ce que vous dites: " La table de Yahweh est chose vile. "'),
('ml',1,8,'crampon1923','Quand vous présentez une bête aveugle pour la sacrifier, il n''y a pas de mal! Et quand vous en amenez une boiteuse et malade, il n''y a pas de mal! Va donc l''offrir à ton gouverneur? T''agréera-t-il? Te sera-t-il favorable? dit Yahweh des armées.'),
('ml',1,9,'crampon1923','Et maintenant, suppliez donc Dieu d''avoir pitié de vous! C''est par votre main que cela s''est fait; sera-t-il amené par vous à avoir des égards? dit Yahweh des armées.'),
('ml',1,10,'crampon1923','Que l''un d''entre vous ne ferme-t-il plutôt les portes, pour que vous n''embrasiez pas mon autel en pure perte! Je ne prends pas plaisir en vous, dit Yahweh des armées, et je n''agrée pas d''offrande de votre main.'),
('ml',1,11,'crampon1923','Car, du lever du soleil à son coucher, mon nom est grand parmi les nations, et en tout lieu on offre à mon nom de l''encens et une oblation pure, car mon nom est grand parmi les nations, dit Yahweh des armées.'),
('ml',1,12,'crampon1923','Et vous, vous le profanez quand vous dites: " La table du Seigneur est souillée, et ce qu''elle rapporte n''est qu''une méprisable nourriture. "'),
('ml',1,13,'crampon1923','Et vous dites: " Voici! Quel ennui! " et vous la dédaignez, dit Yahweh des armées. Et vous amenez ce qui est dérobé, ce qui est boiteux et ce qui est malade, et vous présentez cette offrande! Puis-je l''agréer de votre main? dit Yahweh.'),
('ml',1,14,'crampon1923','Maudit soit le fraudeur, celui qui, ayant dans son troupeau un mâle, fait un vœu, et sacrifie au Seigneur une bête chétive! Car je suis un grand roi, dit Yahweh des armées, et mon nom est redouté chez les nations.'),
('ml',2,1,'crampon1923','Maintenant donc, c''est pour vous qu''est ce décret, ô prêtres.'),
('ml',2,2,'crampon1923','Si vous n''écoutez pas et si vous ne prenez pas à cœur de donner gloire à mon nom, dit Yahweh des armées, j''enverrai contre vous la malédiction, et je maudirai vos bénédictions; — et déjà je les ai maudites, parce que vous n''avez pas pris à cœur! —'),
('ml',2,3,'crampon1923','Voici que je ferai manquer vos semences, je répandrai du fumier sur vos visages, le fumier de vos fêtes, et on vous emportera avec lui.'),
('ml',2,4,'crampon1923','Vous saurez alors que je vous ai adressé ce décret, afin que mon alliance avec Lévi demeure, dit Yahweh des armées.'),
('ml',2,5,'crampon1923','Mon alliance avec Lévi fut une alliance de vie et de paix, et je lui donnai ces biens; une alliance de crainte, et il me craignit et trembla devant mon nom.'),
('ml',2,6,'crampon1923','La loi de vérité était dans sa bouche, et il ne se trouvait pas d''iniquité sur ses lèvres; il marchait avec moi dans la paix et la droiture, et il détourna du mal un grand nombre d''hommes.'),
('ml',2,7,'crampon1923','Car les lèvres du prêtre gardent la science, et de sa bouche on demande l''enseignement, parce qu''il est l''ange de Yahweh des armées.'),
('ml',2,8,'crampon1923','Mais vous, vous vous êtes écartés de la voie; vous en avez fait trébucher un grand nombre dans la loi; vous avez perverti l''alliance de Lévi, dit Yahweh des armées.'),
('ml',2,9,'crampon1923','Et moi, à mon tour, je vous ai rendus méprisables et vils pour tout le peuple, parce que vous ne gardez pas mes voies et que vous avez égard aux personnes en appliquant la loi.'),
('ml',2,10,'crampon1923','N''y a-t-il pas un même père pour nous tous? Un même Dieu ne nous a-t-il pas tous créés? Pourquoi sommes-nous infidèles l''un envers l''autre, profanant l''alliance de nos pères?'),
('ml',2,11,'crampon1923','Juda est infidèle, et une abomination est commise en Israël et à Jérusalem; car Juda profane ce qui est consacré à Yahweh, ce que Yahweh aime; il épouse la fille d''un dieu étranger.'),
('ml',2,12,'crampon1923','Pour l''homme qui fait cela, que Yahweh retranche des tentes de Jacob celui qui veille et celui qui répond, et celui qui offre l''oblation à Yahweh des armées!'),
('ml',2,13,'crampon1923','Voici une seconde chose que vous faites: vous couvrez de larmes l''autel de Yahweh, vous le couvrez de pleurs et de gémissements, en sorte que Yahweh n''a plus égard à l''oblation, et qu''il ne reçoit plus de votre main une offrande agréable.'),
('ml',2,14,'crampon1923','Et vous dites: " Pourquoi? " — Parce que Yahweh a été témoin entre toi et la femme de ta jeunesse, à laquelle tu as été infidèle, elle qui était ta compagne et la femme de ton alliance.'),
('ml',2,15,'crampon1923','Aucun n''a fait cela, ayant du reste de l''Esprit divin. — " Et que fit l''Un? " — Il cherchait une postérité divine. Prenez donc garde à votre vie, et que nul ne soit infidèle à la femme de sa jeunesse.'),
('ml',2,16,'crampon1923','Car je hais la répudiation, dit Yahweh, le Dieu d''Israël; car c''est couvrir de violence son vêtement, dit Yahweh des armées. Prenez donc garde à votre vie et ne soyez pas infidèles.'),
('ml',2,17,'crampon1923','Vous avez fatigué Yahweh par vos paroles. Et vous dites: " En quoi l''avons-nous fatigué? " — En disant: " Quiconque fait le mal est bon aux yeux de Yahweh, et en ces gens-là il prend plaisir! " Ou bien: " Où est le Dieu de la justice? "'),
('ml',3,1,'crampon1923','Voici que j''envoie mon messager, et il préparera le chemin devant moi; et soudain viendra dans son temple le Seigneur que vous cherchez, l''ange de l''alliance que vous désirez. Voici, il vient, dit Yahweh des armées.'),
('ml',3,2,'crampon1923','Et qui soutiendra le jour de sa venue, et qui restera debout quand il apparaîtra? Car il sera comme le feu du fondeur, comme la potasse des foulons.'),
('ml',3,3,'crampon1923','Il s''assoira, fondant et purifiant l''argent; il purifiera les fils de Lévi, et les épurera comme l''or et l''argent; et ils seront pour Yahweh des ministres qui lui présenteront l''oblation selon la justice;'),
('ml',3,4,'crampon1923','et l''oblation de Juda et de Jérusalem sera agréable à Yahweh comme aux anciens jours, comme dans les années d''autrefois.'),
('ml',3,5,'crampon1923','Je m''approcherai de vous pour le jugement, et je serai un témoin prompt contre les enchanteurs, contre les adultères, contre ceux qui jurent faussement, contre ceux qui extorquent au mercenaire son salaire, qui oppriment la veuve et l''orphelin, qui repoussent l''étranger, et qui ne me craignent pas, dit Yahweh des armées.'),
('ml',3,6,'crampon1923','C''est parce que moi, Yahweh, je ne change pas, que vous, les enfants de Jacob, vous n''avez pas été consumés.'),
('ml',3,7,'crampon1923','Depuis les jours de vos pères, vous vous êtes écartés de mes ordonnances et vous ne les avez pas observées. Revenez à moi et je reviendrai à vous, dit Yahweh des armées. — Et vous dites: " En quoi reviendrons-nous? " —'),
('ml',3,8,'crampon1923','Un homme oserait-il frauder Dieu, que vous me fraudiez? — Et vous dites: " En quoi t''avons-nous fraudé? " — Dans la dîme et la part à prélever.'),
('ml',3,9,'crampon1923','Vous êtes frappés, vous, de la malédiction, et moi, vous me fraudez, vous, toute la nation!'),
('ml',3,10,'crampon1923','Apportez toute la dîme au trésor et qu''il y ait des vivres dans ma maison! Et mettez-moi donc à l''épreuve en ceci, dit Yahweh des armées: si je n''ouvre pas pour vous les écluses des cieux, et si je ne répands pas sur vous la bénédiction jusqu''à surabondance.'),
('ml',3,11,'crampon1923','Pour vous, je chasserai l''insecte qui dévore; il ne vous détruira plus les fruits du sol, et la vigne ne sera plus stérile pour vous dans la campagne, dit Yahweh des armées.'),
('ml',3,12,'crampon1923','Toutes les nations vous diront heureux, car vous serez un pays de délices, dit Yahweh des armées.'),
('ml',3,13,'crampon1923','Vos paroles sont dures contre moi, dit Yahweh. Et vous dites: " Qu''avons-nous dit de toi entre nous? "'),
('ml',3,14,'crampon1923','— Vous avez dit: " Inutile de servir Dieu; qu''avons-nous gagné à observer ses préceptes et à marcher avec tristesse devant Yahweh des armées? "'),
('ml',3,15,'crampon1923','Et maintenant, nous proclamons heureux les impies; ils prospèrent, ceux qui font le mal; ils tentent Dieu, et pourtant ils échappent. "'),
('ml',3,16,'crampon1923','Alors ceux qui craignent Yahweh se sont entretenus les uns avec les autres. Et Yahweh a été attentif, il a entendu, et un livre de souvenir a été écrit devant lui, pour ceux qui craignent Yahweh et qui respectent son nom.'),
('ml',3,17,'crampon1923','Au jour que je prépare, dit Yahweh des armées, ils seront pour moi un bien particulier, et je serai pour eux plein de tendresse, comme un homme est plein de tendresse, pour son fils qui le sert.'),
('ml',3,18,'crampon1923','Et vous verrez de nouveau la différence entre le juste et le méchant, entre celui qui sert Dieu et celui qui ne le sert pas.'),
('ml',3,19,'crampon1923','Car voici que le jour vient, ardent comme une fournaise. Tous les orgueilleux, tous ceux qui font le mal seront du chaume, et le jour qui vient les embrasera, dit Yahweh des armées, en sorte qu''il ne leur laissera ni racine, ni rameau.'),
('ml',3,20,'crampon1923','Mais pour vous qui craignez mon nom, se lèvera un soleil de justice, et la guérison sera dans ses rayons; vous sortirez et vous bondirez comme des veaux d''étable.'),
('ml',3,21,'crampon1923','Vous foulerez les méchants, car ils seront comme de la cendre sous la plante de vos pieds, au jour que je prépare, dit Yahweh des armées.'),
('ml',3,22,'crampon1923','Souvenez-vous de la loi de Moïse mon serviteur, auquel je donnai en Horeb des préceptes pour tout Israël et des ordonnances.'),
('ml',3,23,'crampon1923','Voici que je vous envoie Élie, le prophète, avant que vienne le jour de Yahweh, grand et redoutable.'),
('ml',3,24,'crampon1923','Il ramènera le cœur des pères vers les enfants et le cœur des enfants vers les pères, de peur que je ne vienne et que je ne frappe la terre d''anathème.'),
('mt',1,1,'crampon1923','Généalogie de Jésus-Christ, fils de David, fils d''Abraham.'),
('mt',1,2,'crampon1923','Abraham engendra Isaac; Isaac engendra Jacob; Jacob engendra Juda et ses frères;'),
('mt',1,3,'crampon1923','Juda, de Thamar, engendra Pharès et Zara; Pharès engendra Esron; Esron engendra Aram;'),
('mt',1,4,'crampon1923','Aram engendra Aminadab; Aminadab engendra Naasson; Naasson engendra Salmon;'),
('mt',1,5,'crampon1923','Salmon, de Rahab, engendra Booz; Booz, de Ruth, engendra Obed; Obed engendra Jessé; Jessé engendra le roi David.'),
('mt',1,6,'crampon1923','David engendra Salomon, de celle qui fut la femme d''Urie;'),
('mt',1,7,'crampon1923','Salomon engendra Roboam; Roboam engendra Abias; Abias engendra Asa;'),
('mt',1,8,'crampon1923','Asa engendra Josaphat; Josaphat engendra Joram; Joram engendra Ozias;'),
('mt',1,9,'crampon1923','Ozias engendra Joathan; Joathan engendra Achaz; Achaz engendra Ezéchias;'),
('mt',1,10,'crampon1923','Ezéchias engendra Manassé; Manassé engendra Amon; Amon engendra Josias;'),
('mt',1,11,'crampon1923','Josias engendra Jéchonias et ses frères, au temps de la déportation à Babylone.'),
('mt',1,12,'crampon1923','Et après la déportation à Babylone, Jéchonias engendra Salathiel; Salathiel engendra Zorobabel;'),
('mt',1,13,'crampon1923','Zorobabel engendra Abiud; Abiud engendra Eliacim; Eliacim engendra Azor;'),
('mt',1,14,'crampon1923','Azor engendra Sadoc; Sadoc engendra Achim; Achim engendra Eliud;'),
('mt',1,15,'crampon1923','Eliud engendra Eléazar; Eléazar engendra Mathan; Mathan engendra Jacob;'),
('mt',1,16,'crampon1923','Et Jacob engendra Joseph, l''époux de Marie, de laquelle est né Jésus, qu''on appelle Christ.'),
('mt',1,17,'crampon1923','Il y a donc en tout quatorze générations depuis Abraham jusqu''à David, quatorze générations depuis David jusqu''à la déportation à Babylone, quatorze générations depuis la déportation à Babylone jusqu''au Christ.'),
('mt',1,18,'crampon1923','Or la naissance de Jésus-Christ arriva ainsi. Marie, sa mère, étant fiancée à Joseph, il se trouva, avant qu''ils eussent habité ensemble, qu''elle avait conçu par la vertu du Saint-Esprit.'),
('mt',1,19,'crampon1923','Joseph, son mari, qui était un homme juste, ne voulant pas la diffamer, résolut de la renvoyer secrètement.'),
('mt',1,20,'crampon1923','Comme il était dans cette pensée, voici qu''un ange du Seigneur lui apparut en songe, et lui dit: " Joseph, fils de David, ne craint point de prendre avec toi Marie ton épouse, car ce qui est formé en elle est l''ouvrage du Saint-Esprit.'),
('mt',1,21,'crampon1923','Et elle enfantera un fils, et tu lui donneras le nom de Jésus; car il sauvera son peuple de ses péchés. "'),
('mt',1,22,'crampon1923','Or tout cela arriva afin que fût accompli ce qu''avait dit le Seigneur par le prophète:'),
('mt',1,23,'crampon1923','" Voici que la Vierge concevra et enfantera un fils; et on le nommera Emmanuel, " c''est à dire Dieu avec nous.'),
('mt',1,24,'crampon1923','Réveillé de son sommeil, Joseph fit ce que l''ange du Seigneur lui avait commandé: il prit avec lui Marie son épouse.'),
('mt',1,25,'crampon1923','Mais il ne la connut point jusqu''à ce qu''elle enfantât son fils premier-né, à qui il donna le nom de Jésus.'),
('mt',2,1,'crampon1923','Jésus étant né à Bethléem de Judée, aux jours du roi Hérode, voici que des Mages arrivèrent d''Orient à Jérusalem,'),
('mt',2,2,'crampon1923','disant: " Où est le roi des Juifs qui vient de naître? Car nous avons vu son étoile en Orient, et nous sommes venus l''adorer. "'),
('mt',2,3,'crampon1923','Ce que le roi Hérode ayant appris, il fut troublé, et tout Jérusalem avec lui.'),
('mt',2,4,'crampon1923','Il assembla tous les Princes des prêtres et les Scribes du peuple, et s''enquit auprès d''eux où devait naître le Christ.'),
('mt',2,5,'crampon1923','Ils lui dirent: " A Bethléem de Judée, selon ce qui a été écrit par le prophète:'),
('mt',2,6,'crampon1923','Et toi, Bethléem, terre de Juda, tu n''es pas la moindre parmi les principales villes de Juda, car de toi sortira un Chef qui doit paître Israël, mon peuple. "'),
('mt',2,7,'crampon1923','Alors Hérode, ayant fait venir secrètement les Mages, apprit d''eux la date précise à laquelle l''étoile était apparue.'),
('mt',2,8,'crampon1923','Et il les envoya à Bethléem en disant: " Allez, informez-vous exactement de l''Enfant, et lorsque vous l''aurez trouvé, faites-le-moi savoir, afin que moi aussi j''aille l''adorer. "'),
('mt',2,9,'crampon1923','Ayant entendu les paroles du roi, ils partirent. Et voilà que l''étoile qu''ils avaient vue en Orient allait devant eux, jusqu''à ce que, venant au-dessus du lieu où était l''Enfant, elle s''arrêta.'),
('mt',2,10,'crampon1923','A la vue de l''étoile, ils se réjouirent d''une grande joie.'),
('mt',2,11,'crampon1923','Ils entrèrent dans la maison, trouvèrent l''Enfant avec Marie, sa mère, et, se prosternant, ils l''adorèrent; puis, ouvrant leurs trésors, ils lui offrirent en présent de l''or, de l''encens et de la myrrhe.'),
('mt',2,12,'crampon1923','Mais ayant été avertis en songe de ne point retourner vers Hérode, ils regagnèrent leur pays par un autre chemin.'),
('mt',2,13,'crampon1923','Après leur départ, voici qu''un ange du Seigneur apparut à Joseph pendant son sommeil, et lui dit: " Lève-toi, prends l''Enfant et sa mère, fuis en Egypte et restes-y jusqu''à ce que je t''avertisse; car Hérode va rechercher l''Enfant pour le faire périr. "'),
('mt',2,14,'crampon1923','Joseph se leva, et la nuit même, prenant l''Enfant avec sa mère, il se retira en Egypte.'),
('mt',2,15,'crampon1923','Et il y resta jusqu''à la mort d''Hérode, afin que s''accomplît ce qu''avait dit le Seigneur par le Prophète: " J''ai rappelé mon fils d''Egypte. "'),
('mt',2,16,'crampon1923','Alors Hérode, voyant que les Mages s''étaient joués de lui, entra dans une grande colère, et envoya tuer tous les enfants qui étaient dans Bethléem et dans les environs, depuis l''âge de deux ans et au-dessous, d''après la date qu''il connaissait exactement par les Mages.'),
('mt',2,17,'crampon1923','Alors fut accompli l''oracle du prophète Jérémie disant:'),
('mt',2,18,'crampon1923','Une voix a été entendue dans Rama, des plaintes et des cris lamentables: Rachel pleure ses enfants; et elle n''a pas voulu être consolée, parce qu''ils ne sont plus.'),
('mt',2,19,'crampon1923','Hérode étant mort, voici qu''un ange du Seigneur apparut en songe à Joseph dans la terre d''Egypte,'),
('mt',2,20,'crampon1923','et lui dit: " Lève-toi, prends l''Enfant et sa mère, et va dans la terre d''Israël, car ceux qui en voulaient à la vie de l''Enfant sont morts. "'),
('mt',2,21,'crampon1923','Joseph s''étant levé, prit l''Enfant et sa mère, et vint dans la terre d''Israël.'),
('mt',2,22,'crampon1923','Mais, apprenant qu''Archélaüs régnait en Judée à la place d''Hérode, son père, il n''osa y aller, et, ayant été averti en songe, il se retira dans la Galilée'),
('mt',2,23,'crampon1923','et vint habiter une ville nommée Nazareth, afin que s''accomplît ce qu''avaient dit les prophètes: " Il sera appelé Nazaréen. "'),
('mt',3,1,'crampon1923','En ces jours-là parut Jean-Baptiste, prêchant dans le désert de Judée,'),
('mt',3,2,'crampon1923','et disant: " Repentez-vous, car le royaume des cieux est proche. "'),
('mt',3,3,'crampon1923','C''est lui qui a été annoncé par le prophète Isaïe, disant: " Une voix a retenti au désert: Préparez le chemin du Seigneur, aplanissez ses sentiers. "'),
('mt',3,4,'crampon1923','Or Jean avait un vêtement de poils de chameau, et autour de ses reins une ceinture de cuir, et il se nourrissait de sauterelles et de miel sauvage.'),
('mt',3,5,'crampon1923','Alors venaient à lui Jérusalem, et toute la Judée, et tout le pays qu''arrose le Jourdain.'),
('mt',3,6,'crampon1923','Et, confessant leurs péchés, ils se faisaient baptiser par lui dans le Jourdain.'),
('mt',3,7,'crampon1923','Voyant un grand nombre de Pharisiens et de Sadducéens venir à ce baptême il leur dit: " Race de vipères, qui vous a appris à fuir la colère qui vient?'),
('mt',3,8,'crampon1923','Faites donc de dignes fruits de repentir.'),
('mt',3,9,'crampon1923','Et n''essayez pas de dire en vous-mêmes: Nous avons Abraham pour père; car je vous dis que de ces pierres mêmes Dieu peut faire naître des enfants à Abraham.'),
('mt',3,10,'crampon1923','Déjà la cognée est à la racine des arbres: tout arbre donc qui ne porte pas de bon fruit sera coupé et jeté au feu.'),
('mt',3,11,'crampon1923','Moi, je vous baptise dans l''eau pour le repentir; mais celui qui doit venir après moi est plus puissant que moi, et je ne suis pas digne de porter sa chaussure; il vous baptisera dans l''Esprit-Saint et dans le feu.'),
('mt',3,12,'crampon1923','Sa main tient le van; il nettoiera son aire, il amassera son froment dans le grenier, et il brûlera la paille dans un feu qui ne s''éteint point. "'),
('mt',3,13,'crampon1923','Alors Jésus, venant de Galilée, alla trouver Jean au Jourdain pour être baptisé par lui.'),
('mt',3,14,'crampon1923','Jean s''en défendait en disant: " C''est moi qui doit être baptisé par vous, et vous venez à moi! "'),
('mt',3,15,'crampon1923','Jésus lui répondit: " Laisse faire maintenant, car il convient que nous accomplissions ainsi toute justice. " Alors Jean le laissa faire.'),
('mt',3,16,'crampon1923','Jésus ayant été baptisé sortit aussitôt de l''eau, et voilà que les cieux lui furent ouverts, et il vit l''Esprit de Dieu descendre comme une colombe et venir sur lui.'),
('mt',3,17,'crampon1923','Et du ciel une voix disait: " Celui-ci est mon Fils bien-aimé, en qui j''ai mis mes complaisances. "'),
('mt',4,1,'crampon1923','Alors Jésus fut conduit par l''Esprit dans le désert pour y être tenté par le diable.'),
('mt',4,2,'crampon1923','Après avoir jeûné pendant quarante jours et quarante nuits, il eut faim.'),
('mt',4,3,'crampon1923','Et le tentateur, s''approchant, lui dit: " Si vous êtes le Fils de Dieu, commandez que ces pierres deviennent des pains. "'),
('mt',4,4,'crampon1923','Jésus lui répondit: " Il est écrit: L''homme ne vit pas seulement de pain, mais de toute parole qui sort de la bouche de Dieu. "'),
('mt',4,5,'crampon1923','Alors le diable le transporta dans la ville sainte, et l''ayant posé sur le pinacle du temple,'),
('mt',4,6,'crampon1923','il lui dit: " Si vous êtes le Fils de Dieu, jetez-vous en bas; car il est écrit: Il a donné pour vous des ordres à ses anges, et ils vous porteront dans leurs mains, de peur que votre pied ne heurte contre la pierre. "'),
('mt',4,7,'crampon1923','Jésus lui dit: " Il est écrit aussi: Tu ne tenteras point le Seigneur, ton Dieu. "'),
('mt',4,8,'crampon1923','Le diable, de nouveau, le transporta sur une montagne très élevée, et lui montrant tous les royaumes du monde, avec leur gloire,'),
('mt',4,9,'crampon1923','il lui dit: " Je vous donnerai tout cela, si, tombant à mes pieds, vous m''adorez ".'),
('mt',4,10,'crampon1923','Alors Jésus lui dit: " Retire-toi, Satan; car il est écrit: Tu adoreras le Seigneur, ton Dieu, et tu ne serviras que lui seul. "'),
('mt',4,11,'crampon1923','Alors le diable le laissa; aussitôt des anges s''approchèrent, et ils le servaient.'),
('mt',4,12,'crampon1923','Quand Jésus eut appris que Jean avait été mis en prison, il se retira en Galilée.'),
('mt',4,13,'crampon1923','Et laissant la ville de Nazareth, il vint demeurer à Capharnaüm, sur les bords de la mer, aux confins de Zabulon et de Nephtali,'),
('mt',4,14,'crampon1923','afin que s''accomplît cette parole du prophète Isaïe:'),
('mt',4,15,'crampon1923','" Terre de Zabulon et terre de Nephtali, qui confines à la mer, pays au-delà du Jourdain, Galilée des Gentils!'),
('mt',4,16,'crampon1923','Le peuple qui était assis dans les ténèbres a vu une grande lumière; et sur ceux qui étaient assis dans la région de l''ombre de la mort, la lumière s''est levée!'),
('mt',4,17,'crampon1923','Dès lors Jésus commença à prêcher, en disant: " Repentez-vous, car le royaume des cieux est proche. "'),
('mt',4,18,'crampon1923','Comme il marchait le long de la mer de Galilée, Jésus vit deux frères, Simon, appelé Pierre, et André son frère, qui jetaient leur filet dans la mer; car ils étaient pêcheurs.'),
('mt',4,19,'crampon1923','Et il leur dit: " Suivez-moi, et je vous ferai pêcheurs d''hommes. "'),
('mt',4,20,'crampon1923','Eux aussitôt, laissant leurs filets, le suivirent.'),
('mt',4,21,'crampon1923','S''avançant plus loin, il vit deux autres frères, Jacques, fils de Zébédée, et Jean son frère, dans une barque, avec leur père Zébédée, réparant leurs filets, et il les appela.'),
('mt',4,22,'crampon1923','Eux aussi, laissant à l''heure même leur barque et leur père, le suivirent.'),
('mt',4,23,'crampon1923','Jésus parcourait toute la Galilée, enseignant dans leurs synagogues, prêchant l''Evangile du royaume de Dieu, et guérissant toute maladie et toute infirmité parmi le peuple.'),
('mt',4,24,'crampon1923','Sa renommée se répandit dans toute la Syrie, et on lui présentait tous les malades atteints d''infirmités et de souffrances diverses, des possédés, des lunatiques, des paralytiques, et il les guérissait.'),
('mt',4,25,'crampon1923','Et une grande multitude le suivit de la Galilée, de la Décapole, de Jérusalem, de la Judée et d''au delà du Jourdain.'),
('mt',5,1,'crampon1923','Jésus, voyant cette foule, monta sur la montagne, et lorsqu''il se fut assis, ses disciples s''approchèrent de lui.'),
('mt',5,2,'crampon1923','Alors, ouvrant sa bouche, il se mit à les enseigner, en disant:'),
('mt',5,3,'crampon1923','" Heureux les pauvres en esprit, car le royaume des cieux est à eux!'),
('mt',5,4,'crampon1923','Heureux ceux qui sont doux, car ils posséderont la terre!'),
('mt',5,5,'crampon1923','Heureux ceux qui pleurent, car ils seront consolés!'),
('mt',5,6,'crampon1923','Heureux ceux qui ont faim et soif de la justice, car ils seront rassasiés!'),
('mt',5,7,'crampon1923','Heureux les miséricordieux, car ils obtiendront miséricorde!'),
('mt',5,8,'crampon1923','Heureux ceux qui ont le cœur pur, car ils verront Dieu!'),
('mt',5,9,'crampon1923','Heureux les pacifiques, car ils seront appelés enfants de Dieu!'),
('mt',5,10,'crampon1923','Heureux ceux qui souffrent persécution pour la justice, car le royaume des cieux est à eux!'),
('mt',5,11,'crampon1923','Heureux êtes-vous, lorsqu''on vous insultera, qu''on vous persécutera, et qu''on dira faussement toute sorte de mal contre vous, à cause de moi.'),
('mt',5,12,'crampon1923','Réjouissez-vous et soyez dans l''allégresse, car votre récompense est grande dans les cieux: c''est ainsi qu''ils ont persécuté les prophètes qui ont été avant vous.'),
('mt',5,13,'crampon1923','Vous êtes le sel de la terre. Si le sel s''affadit, avec quoi lui rendra-t-on sa saveur? Il n''est plus bon à rien qu''à être jeté dehors et foulé aux pieds par les hommes.'),
('mt',5,14,'crampon1923','Vous êtes la lumière du monde. Une ville située au sommet d''une montagne ne peut être cachée;'),
('mt',5,15,'crampon1923','et on n''allume pas une lampe pour la mettre sous le boisseau, mais sur le chandelier, et elle éclaire tous ceux qui sont dans la maison.'),
('mt',5,16,'crampon1923','Qu''ainsi votre lumière brille devant les hommes, afin que, voyant vos bonnes œuvres, ils glorifient votre Père qui est dans les cieux.'),
('mt',5,17,'crampon1923','Ne pensez pas que je sois venu abolir la Loi ou les Prophètes; je ne suis pas venu les abolir, mais les accomplir.'),
('mt',5,18,'crampon1923','Car, je vous le dis en vérité, jusqu''à ce que passent le ciel et la terre, un seul iota ou un seul trait de la Loi ne passera pas, que tout ne soit accompli.'),
('mt',5,19,'crampon1923','Celui donc qui aura violé un de ces moindres commandements, et appris aux hommes à faire de même, sera le moindre dans le royaume des cieux; mais celui qui les aura pratiqués et enseignés, sera grand dans le royaume des cieux.'),
('mt',5,20,'crampon1923','Car je vous dis que si votre justice ne surpasse celle des Scribes et des Pharisiens, vous n''entrerez point dans le royaume des cieux.'),
('mt',5,21,'crampon1923','Vous avez appris qu''il a été dit aux anciens: " Tu ne tueras point, et celui qui tuera mérite d''être puni par le tribunal. "'),
('mt',5,22,'crampon1923','Et moi, je vous dis: Quiconque se met en colère contre son frère mérite d''être puni par le tribunal; et celui qui dira à son frère: Raca, mérite d''être puni par le Conseil; et celui qui lui dira: Fou, mérite d''être jeté dans la géhenne du feu.'),
('mt',5,23,'crampon1923','Si donc, lorsque tu présentes ton offrande à l''autel, tu te souviens que ton frère a quelque chose contre toi,'),
('mt',5,24,'crampon1923','laisse là ton offrande devant l''autel, et va d''abord te réconcilier avec ton frère; puis viens présenter ton offrande.'),
('mt',5,25,'crampon1923','Accorde-toi au plus tôt avec ton adversaire, pendant que vous allez ensemble au tribunal, de peur qu''il ne te livre au juge, que le juge ne te livre à l''appariteur, et que tu ne sois jeté en prison.'),
('mt',5,26,'crampon1923','En vérité, je te le dis, tu n''en sortiras pas que tu n''aies payé jusqu''à la dernière obole.'),
('mt',5,27,'crampon1923','Vous avez appris qu''il a été dit: " Tu ne commettras point d''adultère. "'),
('mt',5,28,'crampon1923','Et moi, je vous dis que quiconque regarde une femme avec convoitise, a déjà commis l''adultère avec elle, dans son cœur.'),
('mt',5,29,'crampon1923','Si ton œil droit est pour toi une occasion de chute, arrache-le et jette-le loin de toi; car il vaut mieux pour toi qu''un seul de tes membres périsse, et que ton corps tout entier ne soit pas jeté dans la géhenne.'),
('mt',5,30,'crampon1923','Et si ta main droite est pour toi une occasion de chute, coupe-la et jette-la loin de toi; car il vaut mieux pour toi qu''un seul de tes membres périsse, et que ton corps tout entier ne soit pas jeté dans la géhenne.'),
('mt',5,31,'crampon1923','Il a été dit aussi: " Quiconque renvoie sa femme, qu''il lui donne un acte de divorce. "'),
('mt',5,32,'crampon1923','Et moi, je vous dis: Quiconque renvoie sa femme, hors le cas d''impudicité, la rend adultère; et quiconque épouse la femme renvoyée, commet un adultère.'),
('mt',5,33,'crampon1923','Vous avez encore appris qu''il a été dit aux anciens: " Tu ne te parjureras point, mais tu t''acquitteras envers le Seigneur de tes serments. "'),
('mt',5,34,'crampon1923','Et moi, je vous dis de ne faire aucune sorte de serments: ni par le ciel, parce que c''est le trône de Dieu;'),
('mt',5,35,'crampon1923','ni par la terre, parce que c''est l''escabeau de ses pieds; ni par Jérusalem, parce que c''est la ville du grand Roi.'),
('mt',5,36,'crampon1923','Ne jure pas non plus par ta tête, parce que tu ne peux en rendre un seul cheveu blanc ou noir.'),
('mt',5,37,'crampon1923','Mais que votre langage soit: Cela est, cela n''est pas. Ce qui se dit de plus vient du Malin.'),
('mt',5,38,'crampon1923','Vous avez appris qu''il a été dit: " Œil pour œil et dent pour dent. "'),
('mt',5,39,'crampon1923','Et moi, je vous dis de ne pas tenir tête au méchant; mais si quelqu''un te frappe sur la joue droite, présente-lui encore l''autre.'),
('mt',5,40,'crampon1923','Et à celui qui veut t''appeler en justice pour avoir ta tunique, abandonne encore ton manteau.'),
('mt',5,41,'crampon1923','Et si quelqu''un veut t''obliger à faire mille pas, fais-en avec lui deux mille.'),
('mt',5,42,'crampon1923','Donne à qui te demande, et ne cherche pas à éviter celui qui veut te faire un emprunt.'),
('mt',5,43,'crampon1923','Vous avez appris qu''il a été dit: " Tu aimeras ton prochain, et tu haïras ton ennemi. "'),
('mt',5,44,'crampon1923','Et moi, je vous dis: Aimez vos ennemis, bénissez ceux qui vous maudissent, faites du bien à ceux qui vous haïssent, et priez pour ceux qui vous maltraitent et qui vous persécutent:'),
('mt',5,45,'crampon1923','afin que vous soyez les enfants de votre Père qui est dans les cieux; car il fait lever son soleil sur les méchants et sur les bons, et descendre sa pluie sur les justes et sur les injustes.'),
('mt',5,46,'crampon1923','Si vous aimez ceux qui vous aiment, quelle récompense méritez-vous? Les publicains n''en font-ils pas autant?'),
('mt',5,47,'crampon1923','Et si vous ne saluez que vos frères, que faites-vous d''extraordinaire? Les païens même n''en font-ils pas autant?'),
('mt',5,48,'crampon1923','Vous donc, soyez parfaits comme votre Père céleste est parfait.'),
('mt',6,1,'crampon1923','Gardez-vous de faire vos bonnes œuvres devant les hommes, pour être vus d''eux: autrement vous n''aurez pas de récompense auprès de votre Père qui est dans les cieux.'),
('mt',6,2,'crampon1923','Quand donc tu fais l''aumône, ne sonne pas de la trompette devant toi, comme font les hypocrites dans les synagogues et dans les rues, afin d''être honorés des hommes. En vérité, je vous le dis, ils ont reçu leur récompense.'),
('mt',6,3,'crampon1923','Pour toi, quand tu fais l''aumône, que ta main gauche ne sache pas ce que fait ta main droite,'),
('mt',6,4,'crampon1923','afin que ton aumône soit dans le secret; et ton Père, qui voit dans le secret, te le rendra.'),
('mt',6,5,'crampon1923','Lorsque vous priez, ne faites pas comme les hypocrites, qui aiment à prier debout dans les synagogues et au coin des rues, afin d''être vus des hommes. En vérité, je vous le dis, ils ont reçu leur récompense.'),
('mt',6,6,'crampon1923','Pour toi, quand tu veux prier, entre dans ta chambre, et, ayant fermé ta porte, prie ton Père qui est présent dans le secret; et ton Père, qui voit dans le secret, te le rendra.'),
('mt',6,7,'crampon1923','Dans vos prières, ne multipliez pas les paroles, comme font les païens, qui s''imaginent être exaucés à force de paroles.'),
('mt',6,8,'crampon1923','Ne leur ressemblez pas, car votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez.'),
('mt',6,9,'crampon1923','Vous prierez donc ainsi: Notre Père qui êtes aux cieux, que votre nom soit sanctifié.'),
('mt',6,10,'crampon1923','Que votre règne arrive; que votre volonté soit faite sur la terre comme au ciel.'),
('mt',6,11,'crampon1923','Donnez-nous aujourd''hui le pain nécessaire à notre subsistance.'),
('mt',6,12,'crampon1923','Remettez-nous nos dettes, comme nous remettons les leurs à ceux qui nous doivent.'),
('mt',6,13,'crampon1923','Et ne nous induisez point en tentation, mais délivrez-nous du mal.'),
('mt',6,14,'crampon1923','Car si vous pardonnez aux hommes leurs offenses, votre Père céleste vous pardonnera aussi.'),
('mt',6,15,'crampon1923','Mais si vous ne pardonnez pas aux hommes, votre Père ne pardonnera pas non plus vos offenses.'),
('mt',6,16,'crampon1923','Lorsque vous jeûnez, ne prenez pas un air sombre, comme font les hypocrites, qui exténuent leur visage, pour faire paraître aux hommes qu''ils jeûnent. En vérité, je vous le dis, ils ont reçu leur récompense.'),
('mt',6,17,'crampon1923','Pour toi, quand tu jeûnes, parfume ta tête et lave ton visage,'),
('mt',6,18,'crampon1923','afin qu''il ne paraisse pas aux hommes que tu jeûnes, mais à ton Père qui est présent dans le secret; et ton Père, qui voit dans le secret, te le rendra.'),
('mt',6,19,'crampon1923','Ne vous amassez pas des trésors sur la terre, où la rouille et les vers rongent, et où les voleurs percent les murs et dérobent.'),
('mt',6,20,'crampon1923','Mais amassez-vous des trésors dans le ciel, où ni les vers ni la rouille ne rongent, et où les voleurs ne percent pas les murs ni ne dérobent.'),
('mt',6,21,'crampon1923','Car là où est votre trésor, là aussi sera votre cœur.'),
('mt',6,22,'crampon1923','La lampe du corps, c''est l''œil. Si ton œil est sain, tout ton corps sera dans la lumière;'),
('mt',6,23,'crampon1923','mais si ton œil est mauvais, tout ton corps sera dans les ténèbres. Si donc la lumière qui est en toi est ténèbres, combien grandes seront les ténèbres!'),
('mt',6,24,'crampon1923','Nul ne peut servir deux maîtres: car ou il haïra l''un et aimera l''autre, ou il s''attachera à l''un et méprisera l''autre. Vous ne pouvez servir Dieu et la Richesse.'),
('mt',6,25,'crampon1923','C''est pourquoi je vous dis: Ne vous inquiétez pas pour votre vie, de ce que vous mangerez ou boirez; ni pour votre corps, de quoi vous le vêtirez. La vie n''est-elle pas plus que la nourriture, et le corps plus que le vêtement?'),
('mt',6,26,'crampon1923','Regardez les oiseaux du ciel: ils ne sèment ni ne moissonnent, ils n''amassent rien dans des greniers, et votre Père céleste les nourrit. Ne valez-vous pas beaucoup plus qu''eux?'),
('mt',6,27,'crampon1923','Qui de vous, à force de soucis, pourrait ajouter une coudée à la longueur de sa vie?'),
('mt',6,28,'crampon1923','Et pourquoi vous inquiétez-vous pour le vêtement? Considérez les lis des champs, comment ils croissent: ils ne travaillent, ni ne filent.'),
('mt',6,29,'crampon1923','Et cependant je vous dis que Salomon même, dans toute sa gloire, n''a pas été vêtu comme l''un d''eux.'),
('mt',6,30,'crampon1923','Que si Dieu revêt ainsi l''herbe des champs, qui est aujourd''hui et demain sera jetée au four, ne le fera-t-il pas bien plus pour vous, gens de peu de foi?'),
('mt',6,31,'crampon1923','Ne vous mettez donc point en peine, disant: Que mangerons-nous, ou que boirons-nous, ou de quoi nous vêtirons-nous?'),
('mt',6,32,'crampon1923','Car ce sont les Gentils qui recherchent toutes ces choses, et votre Père céleste sait que vous en avez besoin.'),
('mt',6,33,'crampon1923','Cherchez premièrement le royaume de Dieu et sa justice, et tout cela vous sera donné par-dessus.'),
('mt',6,34,'crampon1923','N''ayez donc point de souci du lendemain, le lendemain aura souci de lui-même. A chaque jour suffit sa peine.'),
('mt',7,1,'crampon1923','Ne jugez point, afin que vous ne soyez point jugés.'),
('mt',7,2,'crampon1923','Car selon ce que vous aurez jugé, on vous jugera, et de la même mesure dont vous aurez mesuré, on vous mesurera.'),
('mt',7,3,'crampon1923','Pourquoi regardes-tu la paille qui est dans l''œil de ton frère, et ne remarques-tu pas la poutre qui est dans ton œil?'),
('mt',7,4,'crampon1923','Ou comment peux-tu dire à ton frère: Laisse-moi ôter la paille de ton œil, lorsqu''il y a une poutre dans le tien?'),
('mt',7,5,'crampon1923','Hypocrite, ôte d''abord la poutre de ton œil, et alors tu verras à ôter la paille de l''œil de ton frère.'),
('mt',7,6,'crampon1923','Ne donnez pas aux chiens ce qui est saint, et ne jetez pas vos perles devant les pourceaux, de peur qu''ils ne les foulent aux pieds, et que, se tournant contre vous, ils ne vous déchirent.'),
('mt',7,7,'crampon1923','Demandez, et l''on vous donnera; cherchez et vous trouverez; frappez et l''on vous ouvrira.'),
('mt',7,8,'crampon1923','Car quiconque demande reçoit, qui cherche trouve, et l''on ouvrira à celui qui frappe.'),
('mt',7,9,'crampon1923','Qui de vous, si son fils lui demande du pain, lui donnera une pierre?'),
('mt',7,10,'crampon1923','Ou, s''il lui demande un poisson, lui donnera un serpent?'),
('mt',7,11,'crampon1923','Si donc vous, tout méchants que vous êtes, vous savez donner de bonnes choses à vos enfants, combien plus votre Père qui est dans les cieux donnera-t-il ce qui est bon à ceux qui le prient?'),
('mt',7,12,'crampon1923','Ainsi donc tout ce que vous voulez que les hommes vous fassent, faites-le aussi pour eux; car c''est la Loi et les Prophètes.'),
('mt',7,13,'crampon1923','Entrez par la porte étroite; car la porte large et la voie spacieuse conduisent à la perdition, et nombreux sont ceux qui y passent;'),
('mt',7,14,'crampon1923','car elle est étroite la porte et resserrée la voie qui conduit à la vie, et il en est peu qui la trouvent!'),
('mt',7,15,'crampon1923','Gardez-vous des faux prophètes. Ils viennent à vous sous des vêtements de brebis, mais au dedans ce sont des loups ravissants.'),
('mt',7,16,'crampon1923','Vous les reconnaîtrez à leurs fruits: cueille-t-on des raisins sur des épines, ou des figues sur des ronces?'),
('mt',7,17,'crampon1923','Ainsi tout bon arbre porte de bons fruits, et tout arbre mauvais de mauvais fruits.'),
('mt',7,18,'crampon1923','Un bon arbre ne peut porter de mauvais fruits, ni un arbre mauvais porter de bons fruits.'),
('mt',7,19,'crampon1923','Tout arbre qui ne porte pas de bons fruits sera coupé et jeté au feu.'),
('mt',7,20,'crampon1923','Vous les reconnaîtrez donc à leurs fruits.'),
('mt',7,21,'crampon1923','Ce ne sont pas tous ceux qui me disent: Seigneur, Seigneur, qui entreront dans le royaume des cieux, mais bien celui qui fait la volonté de mon Père qui est dans les cieux.'),
('mt',7,22,'crampon1923','Plusieurs me diront en ce jour-là: Seigneur, Seigneur, n''est-ce pas en votre nom que nous avons prophétisé? n''est-ce pas en votre nom que nous avons chassé les démons? et n''avons-nous pas, en votre nom, fait beaucoup de miracles?'),
('mt',7,23,'crampon1923','Alors je leur dirai hautement: Je ne vous ai jamais connus. Retirez-vous de moi, ouvriers d''iniquité.'),
('mt',7,24,'crampon1923','Tout homme donc qui entend ces paroles que je viens de dire, et les met en pratique, sera comparé à un homme sage, qui a bâti sa maison sur la pierre.'),
('mt',7,25,'crampon1923','La pluie est tombée, les torrents sont venus, les vents ont soufflé et se sont déchaînés contre cette maison, et elle n''a pas été renversée, car elle était fondée sur la pierre.'),
('mt',7,26,'crampon1923','Mais quiconque entend ces paroles que je dis, et ne les met pas en pratique, sera semblable à un insensé qui a bâti sa maison sur le sable.'),
('mt',7,27,'crampon1923','La pluie est tombée, les torrents sont venus, les vents ont soufflé et ont battu cette maison, et elle a été renversée, et grande a été sa ruine. "'),
('mt',7,28,'crampon1923','Jésus ayant achevé ce discours, le peuple était dans l''admiration de sa doctrine.'),
('mt',7,29,'crampon1923','Car il les enseignait comme ayant autorité, et non comme leurs Scribes.'),
('mt',8,1,'crampon1923','Jésus étant descendu de la montagne, une grande multitude le suivit.'),
('mt',8,2,'crampon1923','Et un lépreux s''étant approché, se prosterna devant lui, en disant: " Seigneur, si vous voulez, vous pouvez me guérir. "'),
('mt',8,3,'crampon1923','Jésus étendit la main, le toucha et dit: " Je le veux, sois guéri. " Et à l''instant sa lèpre fut guérie.'),
('mt',8,4,'crampon1923','Alors Jésus lui dit: " Garde-toi d''en parler à personne; mais va te montrer au prêtre, et offre le don prescrit par Moïse pour attester au peuple ta guérison. "'),
('mt',8,5,'crampon1923','Comme Jésus entrait dans Capharnaüm, un centurion l''aborda'),
('mt',8,6,'crampon1923','et lui fit cette prière: " Seigneur, mon serviteur est couché dans ma maison, frappé de paralysie, et il souffre cruellement. "'),
('mt',8,7,'crampon1923','Jésus lui dit: " J''irai et je le guérirai. —'),
('mt',8,8,'crampon1923','Seigneur, répondit le centurion, je ne suis pas digne que vous entriez sous mon toit; mais dites seulement une parole, et mon serviteur sera guéri.'),
('mt',8,9,'crampon1923','Car moi qui suis soumis à des supérieurs, j''ai des soldats sous mes ordres, et je dis à l''un: Va, et il va; et à un autre: Viens, et il vient; et à mon serviteur: Fais cela, et il le fait. "'),
('mt',8,10,'crampon1923','En entendant ces paroles, Jésus fut dans l''admiration, et dit à ceux qui le suivaient: " Je vous le dis en vérité, dans Israël même, je n''ai pas trouvé une si grande foi.'),
('mt',8,11,'crampon1923','C''est pourquoi je vous dis que beaucoup viendront de l''Orient et de l''Occident, et auront place au festin avec Abraham, Isaac et Jacob, dans le royaume des cieux,'),
('mt',8,12,'crampon1923','tandis que les fils du royaume seront jetés dans les ténèbres extérieures: c''est là qu''il y aura des pleurs et des grincements de dents. "'),
('mt',8,13,'crampon1923','Alors Jésus dit au centurion: " Va, et qu''il te soit fait selon ta foi; " et à l''heure même son serviteur fut guéri.'),
('mt',8,14,'crampon1923','Et Jésus étant venu dans la maison de Pierre, y trouva sa belle-mère qui était au lit, tourmentée par la fièvre.'),
('mt',8,15,'crampon1923','Il lui toucha la main, et la fièvre la quitta; aussitôt elle se leva, et se mit à les servir.'),
('mt',8,16,'crampon1923','Sur le soir, on lui présenta plusieurs démoniaques, et d''un mot il chassa les esprits et guérit tous les malades:'),
('mt',8,17,'crampon1923','accomplissant ainsi cette parole du prophète Isaïe: " Il a pris nos infirmités, et s''est chargé de nos maladies. "'),
('mt',8,18,'crampon1923','Jésus, voyant une grande multitude autour de lui, donna l''ordre de passer à l''autre bord du lac.'),
('mt',8,19,'crampon1923','Alors un Scribe s''approcha et lui dit: " Maître, je vous suivrai partout où vous irez. "'),
('mt',8,20,'crampon1923','Jésus lui répondit: " Les renards ont leurs tanières, et les oiseaux du ciel leurs nids; mais le Fils de l''homme n''a pas où reposer sa tête. "'),
('mt',8,21,'crampon1923','Un autre, du nombre des disciples, lui dit: " Seigneur, permettez-moi d''aller auparavant ensevelir mon père. "'),
('mt',8,22,'crampon1923','Mais Jésus lui répondit: " Suis-moi, et laisse les morts ensevelir leurs morts. "'),
('mt',8,23,'crampon1923','Il entra alors dans la barque, suivi de ses disciples.'),
('mt',8,24,'crampon1923','Et voilà qu''une grande agitation se fit dans la mer, de sorte que les flots couvraient la barque: lui, cependant, dormait.'),
('mt',8,25,'crampon1923','Ses disciples venant à lui l''éveillèrent et lui dirent: " Seigneur, sauvez-nous, nous périssons! "'),
('mt',8,26,'crampon1923','Jésus leur dit: " Pourquoi craignez-vous, hommes de peu de foi? " Alors il se leva, commanda aux vents et à la mer, et il se fit un grand calme.'),
('mt',8,27,'crampon1923','Et saisis d''admiration, tous disaient: " Quel est celui-ci, que les vents même et la mer lui obéissent? "'),
('mt',8,28,'crampon1923','Jésus ayant abordé de l''autre côté du lac, dans le pays des Géraséniens, deux démoniaques sortirent des sépulcres et s''avancèrent vers lui; ils étaient si furieux, que personne n''osait passer par ce chemin.'),
('mt',8,29,'crampon1923','Et ils se mirent à crier: " Qu''avons-nous à faire avec vous, Jésus, Fils de Dieu? Êtes-vous venu ici pour nous tourmenter avant le temps? "'),
('mt',8,30,'crampon1923','Or il y avait, à quelque distance, un nombreux troupeau de porcs qui paissaient.'),
('mt',8,31,'crampon1923','Et les démons firent à Jésus cette prière: " Si vous nous chassez d''ici, envoyez-nous dans ce troupeau de porcs. "'),
('mt',8,32,'crampon1923','Il leur dit: " Allez. " Ils sortirent du corps des possédés, et entrèrent dans les pourceaux. Au même instant, tout le troupeau prenant sa course se précipita par les pentes escarpées dans la mer, et ils périrent dans les eaux.'),
('mt',8,33,'crampon1923','Les gardiens s''enfuirent, et ils vinrent dans la ville, où ils racontèrent toutes ces choses et ce qui était arrivé aux démoniaques.'),
('mt',8,34,'crampon1923','Aussitôt toute la ville sortit au-devant de Jésus, et dès qu''ils le virent, ils le supplièrent de quitter leur territoire.'),
('mt',9,1,'crampon1923','Jésus étant donc monté dans la barque, repassa le lac et vint dans sa ville.'),
('mt',9,2,'crampon1923','Et voilà qu''on lui présenta un paralytique, étendu sur un lit. Jésus, voyant leur foi, dit au paralytique: " Mon fils, aie confiance, tes péchés te sont remis. "'),
('mt',9,3,'crampon1923','Aussitôt quelques Scribes dirent en eux-mêmes: " Cet homme blasphème. "'),
('mt',9,4,'crampon1923','Jésus, connaissant leurs pensées, leur dit: " Pourquoi pensez-vous le mal dans vos cœurs?'),
('mt',9,5,'crampon1923','Lequel est le plus aisé de dire: Tes péchés te sont remis; ou de dire: Lève-toi et marche?'),
('mt',9,6,'crampon1923','Or, afin que vous sachiez que le Fils de l''homme a sur la terre le pouvoir de remettre les péchés: Lève-toi, dit-il au paralytique, prends ton lit, et va dans ta maison. "'),
('mt',9,7,'crampon1923','Et il se leva, et s''en alla dans sa maison.'),
('mt',9,8,'crampon1923','La multitude voyant ce prodige fut saisie de crainte, et rendit gloire à Dieu, qui avait donné une telle puissance aux hommes.'),
('mt',9,9,'crampon1923','Étant parti de là, Jésus vit un homme, nommé Matthieu, assis au bureau de péage, et il lui dit: " Suis-moi. " Celui-ci se leva, et le suivit.'),
('mt',9,10,'crampon1923','Or il arriva que Jésus étant à table dans la maison de Matthieu, un grand nombre de publicains et de pécheurs vinrent prendre place avec lui et ses disciples.'),
('mt',9,11,'crampon1923','Ce que voyant, les Pharisiens dirent à ses disciples: " Pourquoi votre maître mange-t-il avec les publicains et les pécheurs? "'),
('mt',9,12,'crampon1923','Jésus, entendant cela, leur dit: " Ce ne sont point les bien portants qui ont besoin de médecin, mais les malades.'),
('mt',9,13,'crampon1923','Allez apprendre ce que signifie cette parole: Je veux la miséricorde et non le sacrifice. Car je ne suis pas venu appeler les justes, mais les pécheurs. "'),
('mt',9,14,'crampon1923','Alors les disciples de Jean vinrent le trouver, et lui dirent: " Pourquoi, tandis que les Pharisiens et nous, nous jeûnons souvent, vos disciples ne jeûnent-ils pas? "'),
('mt',9,15,'crampon1923','Jésus leur répondit: " Les amis de l''époux peuvent-ils s''attrister pendant que l''époux est avec eux? Mais viendront des jours où l''époux leur sera enlevé, et alors ils jeûneront.'),
('mt',9,16,'crampon1923','Personne ne met une pièce d''étoffe neuve à un vieux vêtement; car elle emporte quelque chose du vêtement, et la déchirure en est pire.'),
('mt',9,17,'crampon1923','On ne met pas non plus du vin nouveau dans des outres vieilles; autrement, les outres se rompent, le vin se répand et les outres sont perdues. Mais on met le vin nouveau dans des outres neuves, et tous les deux se conservent. "'),
('mt',9,18,'crampon1923','Comme il leur parlait ainsi, un chef de la synagogue entra, et se prosternant devant lui, il lui dit: " Ma fille vient de mourir; mais venez, imposez votre main sur elle, et elle vivra. "'),
('mt',9,19,'crampon1923','Jésus se leva et le suivit avec ses disciples.'),
('mt',9,20,'crampon1923','Et voilà qu''une femme, affligée d''un flux de sang depuis douze années, s''approcha par derrière et toucha la houppe de son manteau.'),
('mt',9,21,'crampon1923','Car elle disait en elle-même: " Si je touche seulement son manteau, je serai guérie. "'),
('mt',9,22,'crampon1923','Jésus se retourna, et la voyant, il lui dit: " Ayez confiance, ma fille, votre foi vous a guérie. " Et cette femme fut guérie à l''heure même.'),
('mt',9,23,'crampon1923','Lorsque Jésus fut arrivé à la maison du chef de la synagogue, voyant les joueurs de flûte et une foule qui faisait grand bruit, il leur dit:'),
('mt',9,24,'crampon1923','" Retirez-vous; car la jeune fille n''est pas morte, mais elle dort "; et ils se riaient de lui.'),
('mt',9,25,'crampon1923','Lorsqu''on eut fait sortir cette foule, il entra, prit la main de la jeune fille, et elle se leva.'),
('mt',9,26,'crampon1923','Et le bruit s''en répandit dans tout le pays.'),
('mt',9,27,'crampon1923','Comme Jésus poursuivait sa route, deux aveugles se mirent à le suivre, en disant à haute voix: " Fils de David, ayez pitié de nous. "'),
('mt',9,28,'crampon1923','Lorsqu''il fut entré dans la maison, les aveugles s''approchèrent de lui, et Jésus leur dit: " Croyez-vous que je puisse faire cela? " Ils lui dirent: " Oui, Seigneur. "'),
('mt',9,29,'crampon1923','Alors il toucha leurs yeux en disant: " Qu''il vous soit fait selon votre foi. "'),
('mt',9,30,'crampon1923','Aussitôt leurs yeux furent ouverts, et Jésus leur dit d''un ton sévère: " Prenez garde que personne ne le sache. "'),
('mt',9,31,'crampon1923','Mais, s''en étant allés, ils publièrent ses louanges dans tout le pays.'),
('mt',9,32,'crampon1923','Après leur départ, on lui présenta un homme muet, possédé du démon.'),
('mt',9,33,'crampon1923','Le démon ayant été chassé, le muet parla, et la multitude, saisie d''admiration, disait: " Jamais rien de semblable ne s''est vu en Israël. "'),
('mt',9,34,'crampon1923','Mais les Pharisiens disaient: " C''est par le prince des démons qu''il chasse les démons. "'),
('mt',9,35,'crampon1923','Et Jésus parcourait toutes les villes et les bourgades, enseignant dans les synagogues, prêchant l''Évangile du royaume, et guérissant toute maladie et toute infirmité.'),
('mt',9,36,'crampon1923','Or, en voyant cette multitude d''hommes, il fut ému de compassion pour eux, parce qu''ils étaient harassés et abattus, comme des brebis sans pasteur.'),
('mt',9,37,'crampon1923','Alors il dit à ses disciples: " La moisson est grande, mais les ouvriers sont en petit nombre.'),
('mt',9,38,'crampon1923','Priez donc le maître de la moisson d''envoyer des ouvriers à sa moisson. "'),
('mt',10,1,'crampon1923','Puis, ayant appelé ses douze disciples, il leur donna pouvoir sur les esprits impurs, afin de les chasser et de guérir toute maladie et toute infirmité.'),
('mt',10,2,'crampon1923','Or voici les noms des douze Apôtres: le premier est Simon, appelé Pierre, puis André son frère; Jacques fils de Zébédée, et Jean son frère;'),
('mt',10,3,'crampon1923','Philippe et Barthélemy; Thomas et Matthieu le publicain; Jacques, fils d''Alphée et Thaddée;'),
('mt',10,4,'crampon1923','Simon le Zélé, et Judas Iscariote, qui le trahit.'),
('mt',10,5,'crampon1923','Tels sont les douze que Jésus envoya, après leur avoir donné ses instructions: " N''allez point, leur dit-il, vers les Gentils, et n''entrez point dans les villes des Samaritains;'),
('mt',10,6,'crampon1923','allez plutôt aux brebis perdues de la maison d''Israël.'),
('mt',10,7,'crampon1923','Partout, sur votre chemin, annoncez que le royaume des cieux est proche.'),
('mt',10,8,'crampon1923','Guérissez les malades, ressuscitez les morts, purifiez les lépreux, chassez les démons: vous avez reçu gratuitement, donnez gratuitement.'),
('mt',10,9,'crampon1923','Ne prenez ni or, ni argent, ni aucune monnaie dans vos ceintures,'),
('mt',10,10,'crampon1923','ni sac pour la route, ni deux tuniques, ni chaussure, ni bâton; car l''ouvrier mérite sa nourriture.'),
('mt',10,11,'crampon1923','En quelque ville ou village que vous entriez, informez-vous qui y est digne, et demeurez chez lui jusqu''à votre départ.'),
('mt',10,12,'crampon1923','En entrant dans la maison, saluez-la [en disant: Paix à cette maison].'),
('mt',10,13,'crampon1923','Et si cette maison en est digne, que votre paix vienne sur elle; mais si elle ne l''est pas, que votre paix revienne à vous.'),
('mt',10,14,'crampon1923','Si l''on refuse de vous recevoir et d''écouter votre parole, sortez de cette maison ou de cette ville en secouant la poussière de vos pieds.'),
('mt',10,15,'crampon1923','Je vous le dis en vérité, il y aura moins de rigueur, au jour du jugement, pour la terre de Sodome et de Gomorrhe que pour cette ville.'),
('mt',10,16,'crampon1923','Voyez, je vous envoie comme des brebis au milieu des loups. Soyez donc prudents comme les serpents, et simples comme les colombes.'),
('mt',10,17,'crampon1923','Tenez-vous en garde contre les hommes; car ils vous livreront à leurs tribunaux, et vous flagelleront dans leurs synagogues.'),
('mt',10,18,'crampon1923','Vous serez menés à cause de moi devant les gouverneurs et les rois, pour me rendre témoignage devant eux et devant les Gentils.'),
('mt',10,19,'crampon1923','Lorsqu''on vous livrera, ne pensez ni à la manière dont vous parlerez, ni à ce que vous devrez dire: ce que vous aurez à dire vous sera donné à l''heure même.'),
('mt',10,20,'crampon1923','Car ce n''est pas vous qui parlerez; mais c''est l''Esprit de votre Père qui parlera en vous.'),
('mt',10,21,'crampon1923','Le frère livrera son frère à la mort, et le père son enfant, et les enfants s''élèveront contre leurs parents et les feront mourir.'),
('mt',10,22,'crampon1923','Vous serez en haine à tous à cause de mon nom; mais celui qui persévérera jusqu''à la fin, celui-là sera sauvé.'),
('mt',10,23,'crampon1923','Lorsqu''on vous poursuivra dans une ville, fuyez dans une autre. En vérité, je vous le dis, vous n''aurez pas achevé de parcourir les villes d''Israël, que le Fils de l''homme sera venu.'),
('mt',10,24,'crampon1923','Le disciple n''est pas au-dessus du maître, ni le serviteur au-dessus de son seigneur.'),
('mt',10,25,'crampon1923','Il suffit au disciple d''être comme son maître, et au serviteur comme son seigneur. S''ils ont appelé le père de famille Béelzébub, combien plus ceux de sa maison?'),
('mt',10,26,'crampon1923','Ne les craignez donc point. Car il n''y a rien de caché qui ne se découvre, rien de secret qui ne finisse par être connu.'),
('mt',10,27,'crampon1923','Ce que je vous dis dans les ténèbres, dites-le au grand jour, et ce qui vous est dit à l''oreille, publiez-le sur les toits.'),
('mt',10,28,'crampon1923','Ne craignez pas ceux qui tuent le corps, et ne peuvent tuer l''âme; craignez plutôt celui qui peut perdre l''âme et le corps dans la géhenne.'),
('mt',10,29,'crampon1923','Deux passereaux ne se vendent-ils pas un as? Et il n''en tombe pas un sur la terre, sans la permission de votre Père.'),
('mt',10,30,'crampon1923','Les cheveux mêmes de votre tête sont tous comptés.'),
('mt',10,31,'crampon1923','Ne craignez donc point: vous êtes de plus de prix que beaucoup de passereaux.'),
('mt',10,32,'crampon1923','Celui donc qui m''aura confessé devant les hommes, moi aussi je le confesserai devant mon Père qui est dans les cieux;'),
('mt',10,33,'crampon1923','et celui qui m''aura renié devant les hommes, moi aussi je le renierai devant mon Père qui est dans les cieux.'),
('mt',10,34,'crampon1923','Ne pensez pas que je sois venu apporter la paix sur la terre; je suis venu apporter, non la paix, mais le glaive.'),
('mt',10,35,'crampon1923','Je suis venu mettre en lutte le fils avec son père, la fille avec sa mère, et la belle-fille avec sa belle-mère.'),
('mt',10,36,'crampon1923','On aura pour ennemis les gens de sa propre maison.'),
('mt',10,37,'crampon1923','Celui qui aime son père ou sa mère plus que moi, n''est pas digne de moi; et celui qui aime son fils ou sa fille plus que moi, n''est pas digne de moi.'),
('mt',10,38,'crampon1923','Celui qui ne prend pas sa croix et ne me suit pas, n''est pas digne de moi.'),
('mt',10,39,'crampon1923','Celui qui sauvera sa vie, la perdra; et celui qui perdra sa vie à cause de moi, la sauvera.'),
('mt',10,40,'crampon1923','Celui qui vous reçoit, me reçoit, et celui qui me reçoit, reçoit celui qui m''a envoyé.'),
('mt',10,41,'crampon1923','Celui qui reçoit un prophète en qualité de prophète, recevra une récompense de prophète; et celui qui reçoit un juste en qualité de juste, recevra une récompense de juste.'),
('mt',10,42,'crampon1923','Et quiconque donnera seulement un verre d''eau fraîche à l''un de ces petits parce qu''il est de mes disciples, je vous le dis en vérité, il ne perdra point sa récompense. "'),
('mt',11,1,'crampon1923','Quand Jésus eut achevé de donner ses instructions à ses douze disciples, il partit de là pour enseigner et prêcher dans leurs villes.'),
('mt',11,2,'crampon1923','Jean, dans sa prison, ayant entendu parler des œuvres du Christ, envoya deux de ses disciples lui dire:'),
('mt',11,3,'crampon1923','" Êtes-vous celui qui doit venir, ou devons-nous en attendre un autre? "'),
('mt',11,4,'crampon1923','Jésus leur répondit: " Allez, rapportez à Jean ce que vous entendez et ce que vous voyez:'),
('mt',11,5,'crampon1923','Les aveugles voient, les boiteux marchent, les lépreux sont guéris, les sourds entendent, les morts ressuscitent, les pauvres sont évangélisés.'),
('mt',11,6,'crampon1923','Heureux celui pour qui je ne serai pas une occasion de chute! "'),
('mt',11,7,'crampon1923','Comme ils s''en allaient, Jésus se mit à parler de Jean à la foule:'),
('mt',11,8,'crampon1923','" Qu''êtes-vous allés voir au désert? Un roseau agité par le vent? Qu''êtes-vous donc aller voir? Un homme vêtu d''habits somptueux? Mais ceux qui portent des habits somptueux se trouvent dans les maisons des rois.'),
('mt',11,9,'crampon1923','Mais qu''êtes-vous allés voir? Un prophète? Oui, vous dis-je, et plus qu''un prophète.'),
('mt',11,10,'crampon1923','Car c''est celui dont il est écrit: Voici que j''envoie mon messager devant vous, pour vous précéder et vous préparer la voie.'),
('mt',11,11,'crampon1923','En vérité, je vous le dis, parmi les enfants des femmes, il n''en a point paru de plus grand que Jean-Baptiste; toutefois le plus petit dans le royaume des cieux est plus grand que lui.'),
('mt',11,12,'crampon1923','Depuis les jours de Jean-Baptiste jusqu''à présent, le royaume des cieux est emporté de force, et les violents s''en emparent.'),
('mt',11,13,'crampon1923','Car tous les Prophètes et la Loi ont prophétisé jusqu''à Jean.'),
('mt',11,14,'crampon1923','Et si vous voulez le comprendre, lui-même est Elie qui doit venir.'),
('mt',11,15,'crampon1923','Que celui qui a des oreilles entende! "'),
('mt',11,16,'crampon1923','" A qui comparerai-je cette génération? Elle ressemble à des enfants assis dans la place publique, et qui crient à leurs compagnons:'),
('mt',11,17,'crampon1923','Nous avons joué de la flûte, et vous n''avez point dansé; nous avons chanté une lamentation, et vous n''avez point frappé votre poitrine.'),
('mt',11,18,'crampon1923','Jean est venu ne mangeant ni ne buvant, et ils disent: Il est possédé du démon;'),
('mt',11,19,'crampon1923','le Fils de l''homme est venu mangeant et buvant, et ils disent: C''est un homme de bonne chère et un buveur de vin, un ami des publicains et des gens de mauvaise vie. Mais la Sagesse a été justifiée par ses enfants. "'),
('mt',11,20,'crampon1923','Alors Jésus se mit à reprocher aux villes où il avait opéré le plus grand nombre de ses miracles, de n''avoir pas fait pénitence.'),
('mt',11,21,'crampon1923','" Malheur à toi, Corozaïn! Malheur à toi, Bethsaïde! Car si les miracles qui ont été faits au milieu de vous, avaient été faits dans Tyr et dans Sidon, il y a longtemps qu''elles auraient fait pénitence sous le cilice et la cendre.'),
('mt',11,22,'crampon1923','Oui, je vous le dis, il y aura, au jour du jugement, moins de rigueur pour Tyr et pour Sidon, que pour vous.'),
('mt',11,23,'crampon1923','Et toi, Capharnaüm, qui t''élèves jusqu''au ciel, tu seras abaissée jusqu''aux enfers; car si les miracles qui ont été faits dans tes murs, avaient été faits dans Sodome, elle serait restée debout jusqu''à ce jour.'),
('mt',11,24,'crampon1923','Oui, je te le dis, il y aura, au jour du jugement, moins de rigueur pour le pays de Sodome que pour toi. "'),
('mt',11,25,'crampon1923','En ce même temps, Jésus dit encore: " Je vous bénis, Père, Seigneur du ciel et de la terre, de ce que vous avez caché ces choses aux sages et aux prudents, et les avez révélées aux petits.'),
('mt',11,26,'crampon1923','Oui, Père, je vous bénis de ce qu''il vous a plu ainsi.'),
('mt',11,27,'crampon1923','Toutes choses m''ont été données par mon Père; personne ne connaît le Fils, si ce n''est le Père, et personne ne connaît le Père, si ce n''est le Fils, et celui à qui le Fils a voulu le révéler.'),
('mt',11,28,'crampon1923','Venez à moi, vous tous qui êtes fatigués et ployez sous le fardeau, et je vous soulagerai.'),
('mt',11,29,'crampon1923','Prenez sur vous mon joug, et recevez mes leçons, car je suis doux et humble de cœur; et vous trouverez le repos de vos âmes.'),
('mt',11,30,'crampon1923','Car mon joug est doux et mon fardeau léger. "'),
('mt',12,1,'crampon1923','En ce temps-là, Jésus traversait des champs de blé un jour de sabbat, et ses disciples, ayant faim, se mirent à cueillir des épis et à les manger.'),
('mt',12,2,'crampon1923','Les Pharisiens, voyant cela, lui dirent: " Vos disciples font une chose qu''il n''est pas permis de faire pendant le sabbat. "'),
('mt',12,3,'crampon1923','Mais il leur répondit: " N''avez-vous pas lu ce que fit David, lorsqu''il eut faim, lui et ceux qui étaient avec lui:'),
('mt',12,4,'crampon1923','comment il entra dans la maison de Dieu et mangea les pains de proposition, qu''il ne lui était pas permis de manger, non plus qu''à ceux qui étaient avec lui, mais aux prêtres seuls?')
